INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('Nm', 13, 'pt', '[{"numero": 1, "texto": "E o SENHOR falou a Moisés, dizendo:"}, {"numero": 2, "texto": "“Envia homens que reconheçam a terra de Canaã, a qual eu dou aos filhos de Israel; de cada tribo de seus pais enviareis um homem, cada um líder entre eles.”"}, {"numero": 3, "texto": "E Moisés os enviou desde o deserto de Parã, conforme a palavra do SENHOR; e todos aqueles homens eram líderes dos filhos de Israel."}, {"numero": 4, "texto": "Os nomes dos quais são estes: da tribo de Rúben, Samua, filho de Zacur."}, {"numero": 5, "texto": "Da tribo de Simeão, Safate, filho de Hori."}, {"numero": 6, "texto": "Da tribo de Judá, Calebe, filho de Jefoné."}, {"numero": 7, "texto": "Da tribo de Issacar, Jigeal, filho de José."}, {"numero": 8, "texto": "Da tribo de Efraim, Oseias, filho de Num."}, {"numero": 9, "texto": "Da tribo de Benjamim, Palti, filho de Rafu."}, {"numero": 10, "texto": "Da tribo de Zebulom, Gadiel, filho de Sodi."}, {"numero": 11, "texto": "Da tribo de José: pela tribo de Manassés, Gadi, filho de Susi."}, {"numero": 12, "texto": "Da tribo de Dã, Amiel, filho de Gemali."}, {"numero": 13, "texto": "Da tribo de Aser, Setur, filho de Micael."}, {"numero": 14, "texto": "Da tribo de Naftali, Nabi, filho de Vofsi."}, {"numero": 15, "texto": "Da tribo de Gade, Guel, filho de Maqui."}, {"numero": 16, "texto": "Estes são os nomes dos homens que Moisés enviou para reconhecer a terra; e a Oseias, filho de Num, Moisés lhe pôs o nome de Josué."}, {"numero": 17, "texto": "Então Moisés os enviou para reconhecer a terra de Canaã, dizendo-lhes: “Subi por aqui, pelo sul, e subi ao monte:"}, {"numero": 18, "texto": "e observai a terra que tal é; e o povo que a habita, se é forte ou débil, se pouco ou numeroso;"}, {"numero": 19, "texto": "qual é a terra habitada, se é boa ou má; e quais são as cidades habitadas, se de tendas ou de fortalezas;"}, {"numero": 20, "texto": "e qual é o terreno, se é fértil ou fraco, se nele há ou não árvores; esforçai-vos, e colhei do fruto daquela terra.” E o tempo era o tempo das primeiras uvas."}, {"numero": 21, "texto": "E eles subiram, e reconheceram a terra desde o deserto de Zim até Reobe, entrando em Hamate."}, {"numero": 22, "texto": "E subiram pelo sul, e vieram até Hebrom: e ali estavam Aimã, e Sesai, e Talmai, filhos de Anaque. Hebrom foi edificada sete anos antes de Zoã, a do Egito."}, {"numero": 23, "texto": "E chegaram até o ribeiro de Escol, e dali cortaram um ramo com um cacho de uvas, o qual trouxeram dois em uma vara, e das romãs e dos figos."}, {"numero": 24, "texto": "E chamou-se aquele lugar vale de Escol pelo cacho que cortaram dali os filhos de Israel."}, {"numero": 25, "texto": "E voltaram de reconhecer a terra ao fim de quarenta dias."}, {"numero": 26, "texto": "E andaram e vieram a Moisés e a Arão, e a toda a congregação dos filhos de Israel, no deserto de Parã, em Cades, e deram-lhes a resposta, e a toda a congregação, e lhes mostraram o fruto da terra."}, {"numero": 27, "texto": "E lhe contaram, e disseram: Nós chegamos à terra à qual nos enviaste, a que certamente flui leite e mel; e este é o fruto dela."}, {"numero": 28, "texto": "Mas o povo que habita aquela terra é forte, e as cidades muito grandes e fortes; e também vimos ali os filhos de Anaque."}, {"numero": 29, "texto": "Amaleque habita a terra do sul; e os heteus, e os jebuseus, e os amorreus, habitam no monte; e os cananeus habitam junto ao mar, e à beira do Jordão."}, {"numero": 30, "texto": "Então Calebe fez calar o povo diante de Moisés, e disse: Subamos logo, e passemos a ela; que mais poderemos que ela."}, {"numero": 31, "texto": "Mas os homens que subiram com ele, disseram: Não poderemos subir contra aquele povo; porque é mais forte que nós."}, {"numero": 32, "texto": "E falaram mal entre os filhos de Israel da terra que haviam reconhecido, dizendo: A terra por de onde passamos para reconhecê-la, é terra que consome a seus moradores; e todo o povo que vimos em meio dela, são homens de grande estatura."}, {"numero": 33, "texto": "Também vimos ali gigantes, filhos de Anaque, raça dos gigantes: e éramos nós, à nossa aparência, como gafanhotos; e assim lhes parecíamos a eles."}]'::jsonb, 'Almeida Livre'),
  ('Nm', 13, 'en', '[{"numero": 1, "texto": "And the Lord spake unto Moses, saying,"}, {"numero": 2, "texto": "Send thou men, that they may search the land of Canaan, which I give unto the children of Israel: of every tribe of their fathers shall ye send a man, every one a ruler among them."}, {"numero": 3, "texto": "And Moses by the commandment of the Lord sent them from the wilderness of Paran: all those men were heads of the children of Israel."}, {"numero": 4, "texto": "And these were their names: of the tribe of Reuben, Shammua the son of Zaccur."}, {"numero": 5, "texto": "Of the tribe of Simeon, Shaphat the son of Hori."}, {"numero": 6, "texto": "Of the tribe of Judah, Caleb the son of Jephunneh."}, {"numero": 7, "texto": "Of the tribe of Issachar, Igal the son of Joseph."}, {"numero": 8, "texto": "Of the tribe of Ephraim, Oshea the son of Nun."}, {"numero": 9, "texto": "Of the tribe of Benjamin, Palti the son of Raphu."}, {"numero": 10, "texto": "Of the tribe of Zebulun, Gaddiel the son of Sodi."}, {"numero": 11, "texto": "Of the tribe of Joseph, namely, of the tribe of Manasseh, Gaddi the son of Susi."}, {"numero": 12, "texto": "Of the tribe of Dan, Ammiel the son of Gemalli."}, {"numero": 13, "texto": "Of the tribe of Asher, Sethur the son of Michael."}, {"numero": 14, "texto": "Of the tribe of Naphtali, Nahbi the son of Vophsi."}, {"numero": 15, "texto": "Of the tribe of Gad, Geuel the son of Machi."}, {"numero": 16, "texto": "These are the names of the men which Moses sent to spy out the land. And Moses called Oshea the son of Nun Jehoshua."}, {"numero": 17, "texto": "And Moses sent them to spy out the land of Canaan, and said unto them, Get you up this way southward, and go up into the mountain:"}, {"numero": 18, "texto": "And see the land, what it is, and the people that dwelleth therein, whether they be strong or weak, few or many;"}, {"numero": 19, "texto": "And what the land is that they dwell in, whether it be good or bad; and what cities they be that they dwell in, whether in tents, or in strong holds;"}, {"numero": 20, "texto": "And what the land is, whether it be fat or lean, whether there be wood therein, or not. And be ye of good courage, and bring of the fruit of the land. Now the time was the time of the firstripe grapes."}, {"numero": 21, "texto": "So they went up, and searched the land from the wilderness of Zin unto Rehob, as men come to Hamath."}, {"numero": 22, "texto": "And they ascended by the south, and came unto Hebron; where Ahiman, Sheshai, and Talmai, the children of Anak, were. (Now Hebron was built seven years before Zoan in Egypt.)"}, {"numero": 23, "texto": "And they came unto the brook of Eshcol, and cut down from thence a branch with one cluster of grapes, and they bare it between two upon a staff; and they brought of the pomegranates, and of the figs."}, {"numero": 24, "texto": "The place was called the brook Eshcol, because of the cluster of grapes which the children of Israel cut down from thence."}, {"numero": 25, "texto": "And they returned from searching of the land after forty days."}, {"numero": 26, "texto": "And they went and came to Moses, and to Aaron, and to all the congregation of the children of Israel, unto the wilderness of Paran, to Kadesh; and brought back word unto them, and unto all the congregation, and shewed them the fruit of the land."}, {"numero": 27, "texto": "And they told him, and said, We came unto the land whither thou sentest us, and surely it floweth with milk and honey; and this is the fruit of it."}, {"numero": 28, "texto": "Nevertheless the people be strong that dwell in the land, and the cities are walled, and very great: and moreover we saw the children of Anak there."}, {"numero": 29, "texto": "The Amalekites dwell in the land of the south: and the Hittites, and the Jebusites, and the Amorites, dwell in the mountains: and the Canaanites dwell by the sea, and by the coast of Jordan."}, {"numero": 30, "texto": "And Caleb stilled the people before Moses, and said, Let us go up at once, and possess it; for we are well able to overcome it."}, {"numero": 31, "texto": "But the men that went up with him said, We be not able to go up against the people; for they are stronger than we."}, {"numero": 32, "texto": "And they brought up an evil report of the land which they had searched unto the children of Israel, saying, The land, through which we have gone to search it, is a land that eateth up the inhabitants thereof; and all the people that we saw in it are men of a great stature."}, {"numero": 33, "texto": "And there we saw the giants, the sons of Anak, which come of the giants: and we were in our own sight as grasshoppers, and so we were in their sight."}]'::jsonb, 'King James Version'),
  ('Nm', 13, 'fr', '[{"numero": 1, "texto": "L''''Eternel parla à Moïse, et dit:"}, {"numero": 2, "texto": "Envoie des hommes pour explorer le pays de Canaan, que je donne aux enfants d''''Israël. Tu enverras un homme de chacune des tribus de leurs pères; tous seront des principaux d''''entre eux."}, {"numero": 3, "texto": "Moïse les envoya du désert de Paran, d''''après l''''ordre de l''''Eternel; tous ces hommes étaient chefs des enfants d''''Israël."}, {"numero": 4, "texto": "Voici leurs noms. Pour la tribu de Ruben: Schammua, fils de Zaccur;"}, {"numero": 5, "texto": "pour la tribu de Siméon: Schaphath, fils de Hori;"}, {"numero": 6, "texto": "pour la tribu de Juda: Caleb, fils de Jephunné;"}, {"numero": 7, "texto": "pour la tribu d''''Issacar: Jigual, fils de Joseph;"}, {"numero": 8, "texto": "pour la tribu d''''Ephraïm: Hosée, fils de Nun;"}, {"numero": 9, "texto": "pour la tribu de Benjamin: Palthi, fils de Raphu;"}, {"numero": 10, "texto": "pour la tribu de Zabulon: Gaddiel, fils de Sodi;"}, {"numero": 11, "texto": "pour la tribu de Joseph, la tribu de Manassé: Gaddi, fils de Susi;"}, {"numero": 12, "texto": "pour la tribu de Dan: Ammiel, fils de Guemalli;"}, {"numero": 13, "texto": "pour la tribu d''''Aser: Sethur, fils de Micaël;"}, {"numero": 14, "texto": "pour la tribu de Nephthali: Nachbi, fils de Vophsi;"}, {"numero": 15, "texto": "pour la tribu de Gad: Guéuel, fils de Maki."}, {"numero": 16, "texto": "Tels sont les noms des hommes que Moïse envoya pour explorer le pays. Moïse donna à Hosée, fils de Nun, le nom de Josué."}, {"numero": 17, "texto": "Moïse les envoya pour explorer le pays de Canaan. Il leur dit: Montez ici, par le midi; et vous monterez sur la montagne."}, {"numero": 18, "texto": "Vous verrez le pays, ce qu''''il est, et le peuple qui l''''habite, s''''il est fort ou faible, s''''il est en petit ou en grand nombre;"}, {"numero": 19, "texto": "ce qu''''est le pays où il habite, s''''il est bon ou mauvais; ce que sont les villes où il habite, si elles sont ouvertes ou fortifiées;"}, {"numero": 20, "texto": "ce qu''''est le terrain, s''''il est gras ou maigre, s''''il y a des arbres ou s''''il n''''y en a point. Ayez bon courage, et prenez des fruits du pays. C''''était le temps des premiers raisins."}, {"numero": 21, "texto": "Ils montèrent, et ils explorèrent le pays, depuis le désert de Tsin jusqu''''à Rehob, sur le chemin de Hamath."}, {"numero": 22, "texto": "Ils montèrent, par le midi, et ils allèrent jusqu''''à Hébron, où étaient Ahiman, Schéschaï et Talmaï, enfants d''''Anak. Hébron avait été bâtie sept ans avant Tsoan en Egypte."}, {"numero": 23, "texto": "Ils arrivèrent jusqu''''à la vallée d''''Eschcol, où ils coupèrent une branche de vigne avec une grappe de raisin, qu''''ils portèrent à deux au moyen d''''une perche; ils prirent aussi des grenades et des figues."}, {"numero": 24, "texto": "On donna à ce lieu le nom de vallée d''''Eschcol, à cause de la grappe que les enfants d''''Israël y coupèrent."}, {"numero": 25, "texto": "Ils furent de retour de l''''exploration du pays au bout de quarante jours."}, {"numero": 26, "texto": "A leur arrivée, ils se rendirent auprès de Moïse et d''''Aaron, et de toute l''''assemblée des enfants d''''Israël, à Kadès dans le désert de Paran. Ils leur firent un rapport, ainsi qu''''à toute l''''assemblée, et ils leur montrèrent les fruits du pays."}, {"numero": 27, "texto": "Voici ce qu''''ils racontèrent à Moïse: Nous sommes allés dans le pays où tu nous as envoyés. A la vérité, c''''est un pays où coulent le lait et le miel, et en voici les fruits."}, {"numero": 28, "texto": "Mais le peuple qui habite ce pays est puissant, les villes sont fortifiées, très grandes; nous y avons vu des enfants d''''Anak."}, {"numero": 29, "texto": "Les Amalécites habitent la contrée du midi; les Héthiens, les Jébusiens et les Amoréens habitent la montagne; et les Cananéens habitent près de la mer et le long du Jourdain."}, {"numero": 30, "texto": "Caleb fit taire le peuple, qui murmurait contre Moïse. Il dit: Montons, emparons-nous du pays, nous y serons vainqueurs!"}, {"numero": 31, "texto": "Mais les hommes qui y étaient allés avec lui dirent: Nous ne pouvons pas monter contre ce peuple, car il est plus fort que nous."}, {"numero": 32, "texto": "Et ils décrièrent devant les enfants d''''Israël le pays qu''''ils avaient exploré. Ils dirent: Le pays que nous avons parcouru, pour l''''explorer, est un pays qui dévore ses habitants; tous ceux que nous y avons vus sont des hommes d''''une haute taille;"}, {"numero": 33, "texto": "et nous y avons vu les géants, enfants d''''Anak, de la race des géants: nous étions à nos yeux et aux leurs comme des sauterelles."}]'::jsonb, 'Louis Segond 1910'),
  ('Nm', 13, 'es', '[{"numero": 1, "texto": "Y DESPUÉS movió el pueblo de Haseroth, y asentaron el campo en el desierto de Parán."}, {"numero": 2, "texto": "Y Jehová habló á Moisés, diciendo:"}, {"numero": 3, "texto": "Envía tú hombres que reconozcan la tierra de Canaán, la cual yo doy á los hijos de Israel: de cada tribu de sus padres enviaréis un varón, cada uno príncipe entre ellos."}, {"numero": 4, "texto": "Y Moisés los envió desde el desierto de Parán, conforme á la palabra de Jehová: y todos aquellos varones eran príncipes de los hijos de Israel."}, {"numero": 5, "texto": "Los nombres de los cuales son éstos: De la tribu de Rubén, Sammua hijo de Zaccur."}, {"numero": 6, "texto": "De la tribu de Simeón, Saphat hijo de Hurí."}, {"numero": 7, "texto": "De la tribu de Judá, Caleb hijo de Jephone."}, {"numero": 8, "texto": "De la tribu de Issachâr, Igal hijo de Joseph."}, {"numero": 9, "texto": "De la tribu de Ephraim, Oseas hijo de Nun."}, {"numero": 10, "texto": "De la tribu de Benjamín, Palti hijo de Raphu."}, {"numero": 11, "texto": "De la tribu de Zabulón, Gaddiel hijo de Sodi."}, {"numero": 12, "texto": "De la tribu de José, de la tribu de Manasés, Gaddi hijo de Susi."}, {"numero": 13, "texto": "De la tribu de Dan, Ammiel hijo de Gemalli."}, {"numero": 14, "texto": "De la tribu de Aser, Sethur hijo de Michâel."}, {"numero": 15, "texto": "De la tribu de Nephtalí, Nahabí hijo de Vapsi."}, {"numero": 16, "texto": "De la tribu de Gad, Geuel hijo de Machî."}, {"numero": 17, "texto": "Estos son los nombres de los varones que Moisés envió á reconocer la tierra: y á Oseas hijo de Nun, le puso Moisés el nombre de Josué."}, {"numero": 18, "texto": "Enviólos, pues, Moisés á reconocer la tierra de Canaán, diciéndoles: Subid por aquí, por el mediodía, y subid al monte:"}, {"numero": 19, "texto": "Y observad la tierra qué tal es; y el pueblo que la habita, si es fuerte ó débil, si poco ó numeroso;"}, {"numero": 20, "texto": "Qué tal la tierra habitada, si es buena ó mala; y qué tales son las ciudades habitadas, si de tiendas ó de fortalezas;"}, {"numero": 21, "texto": "Y cuál sea el terreno, si es pingüe ó flaco, si en él hay ó no árboles: y esforzaos, y coged del fruto del país. Y el tiempo era el tiempo de las primeras uvas."}, {"numero": 22, "texto": "Y ellos subieron, y reconocieron la tierra desde el desierto de Zin hasta Rehob, entrando en Emath."}, {"numero": 23, "texto": "Y subieron por el mediodía, y vinieron hasta Hebrón: y allí estaban Aimán, y Sesai, y Talmai, hijos de Anac. Hebrón fué edificada siete años antes de Zoán, la de Egipto."}, {"numero": 24, "texto": "Y llegaron hasta el arroyo de Escol, y de allí cortaron un sarmiento con un racimo de uvas, el cual trajeron dos en un palo, y de las granadas y de los higos."}, {"numero": 25, "texto": "Y llamóse aquel lugar Nahal-escol, por el racimo que cortaron de allí los hijos de Israel."}, {"numero": 26, "texto": "Y volvieron de reconocer la tierra al cabo de cuarenta días."}, {"numero": 27, "texto": "Y anduvieron y vinieron á Moisés y á Aarón, y á toda la congregación de los hijos de Israel, en el desierto de Parán, en Cades, y diéronles la respuesta, y á toda la congregación, y les mostraron el fruto de la tierra."}, {"numero": 28, "texto": "Y le contaron, y dijeron: Nosotros llegamos á la tierra á la cual nos enviaste, la que ciertamente fluye leche y miel; y este es el fruto de ella."}, {"numero": 29, "texto": "Mas el pueblo que habita aquella tierra es fuerte, y las ciudades muy grandes y fuertes; y también vimos allí los hijos de Anac."}, {"numero": 30, "texto": "Amalec habita la tierra del mediodía; y el Hetheo, y el Jebuseo, y el Amorrheo, habitan en el monte; y el Cananeo habita junto á la mar, y á la ribera del Jordán."}, {"numero": 31, "texto": "Entonces Caleb hizo callar el pueblo delante de Moisés, y dijo: Subamos luego, y poseámosla; que más podremos que ella."}, {"numero": 32, "texto": "Mas los varones que subieron con él, dijeron: No podremos subir contra aquel pueblo; porque es más fuerte que nosotros."}, {"numero": 33, "texto": "Y vituperaron entre los hijos de Israel la tierra que habían reconocido, diciendo: La tierra por donde pasamos para reconocerla, es tierra que traga á sus moradores; y todo el pueblo que vimos en medio de ella, son hombres de grande estatura. También vimos allí gigantes, hijos de Anac, raza de los gigantes: y éramos nosotros, á nuestro parecer, como langostas; y así les parecíamos á ellos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Nm', 14, 'pt', '[{"numero": 1, "texto": "Então toda a congregação levantaram grito, e deram vozes: e o povo chorou aquela noite."}, {"numero": 2, "texto": "E queixaram-se contra Moisés e contra Arão todos os filhos de Israel; e disse-lhes toda a multidão: Melhor seria se tivéssemos morrido na terra do Egito; ou melhor seria se tivéssemos morrido neste deserto!"}, {"numero": 3, "texto": "E por que nos traze o SENHOR a esta terra para cair à espada e que nossas mulheres e nossos meninos sejam por presa? não nos seria melhor voltarmos ao Egito?"}, {"numero": 4, "texto": "E diziam um ao outro: Façamos um capitão, e voltemos ao Egito."}, {"numero": 5, "texto": "Então Moisés e Arão caíram sobre seus rostos diante de toda a multidão da congregação dos filhos de Israel."}, {"numero": 6, "texto": "E Josué filho de Num, e Calebe filho de Jefoné, que eram dos que haviam reconhecido a terra, rasgaram suas roupas;"}, {"numero": 7, "texto": "E falaram a toda a congregação dos filhos de Israel, dizendo: A terra por de onde passamos para reconhecê-la, é terra em grande maneira boa."}, {"numero": 8, "texto": "Se o SENHOR se agradar de nós, ele nos porá nesta terra, e a entregará a nós; terra que flui leite e mel."}, {"numero": 9, "texto": "Portanto, não sejais rebeldes contra o SENHOR, nem temais ao povo desta terra, porque nosso pão são: seu amparo se afastou deles, e conosco está o SENHOR: não os temais."}, {"numero": 10, "texto": "Então toda a multidão falou de apedrejá-los com pedras. Mas a glória do SENHOR se mostrou no tabernáculo do testemunho a todos os filhos de Israel."}, {"numero": 11, "texto": "E o SENHOR disse a Moisés: Até quando me há de irritar este povo? até quando não me há de crer com todos os sinais que fiz em meio deles?."}, {"numero": 12, "texto": "Eu lhe ferirei de mortandade, e o destruirei, e a ti te porei sobre gente grande e mais forte que eles."}, {"numero": 13, "texto": "E Moisés respondeu ao SENHOR: Logo os egípcios o ouvirão, porque do meio deles tiraste a este povo com tua força:"}, {"numero": 14, "texto": "E o dirão aos habitantes desta terra; os quais ouviram que tu, ó SENHOR, estavas em meio deste povo, que olho a olho aparecias tu, ó SENHOR, e que tua nuvem estava sobre eles, e que de dia ias diante deles em coluna de nuvem, e de noite em coluna de fogo."}, {"numero": 15, "texto": "E que fizeste morrer a este povo como a um homem: e as nações que houverem ouvido tua fama falarão, dizendo:"}, {"numero": 16, "texto": "Porque não pôde o SENHOR meter este povo na terra da qual lhes havia jurado, os matou no deserto."}, {"numero": 17, "texto": "Agora, pois, eu te rogo que seja engrandecida a força do Senhor, como o falaste, dizendo:"}, {"numero": 18, "texto": "O SENHOR, tardio de ira e grande em misericórdia, que perdoa a iniquidade e a rebelião, e deixa impune o culpado; que visita a maldade dos pais sobre os filhos até a terceira geração e até a quarta."}, {"numero": 19, "texto": "Perdoa agora a iniquidade deste povo segundo a grandeza de tua misericórdia, e como perdoaste a este povo desde Egito até aqui."}, {"numero": 20, "texto": "Então o SENHOR disse: Eu o perdoei conforme tu dito:"}, {"numero": 21, "texto": "Mas, certamente vivo eu e minha glória inche toda a terra,"}, {"numero": 22, "texto": "Que todos os que viram minha glória e meus sinais que fiz no Egito e no deserto, e me tentaram já dez vezes, e não ouviram minha voz,"}, {"numero": 23, "texto": "Não verão a terra da qual jurei a seus pais: não, nenhum dos que me irritaram a verá."}, {"numero": 24, "texto": "Porém meu servo Calebe, porquanto houve nele outro espírito, e cumpriu de ir após mim, eu o porei na terra onde entrou e sua descendência a receberá em herança."}, {"numero": 25, "texto": "Agora bem, os amalequitas e os cananeus habitam no vale; voltai-vos amanhã, e parti-vos ao deserto, caminho do mar Vermelho."}, {"numero": 26, "texto": "E o SENHOR falou a Moisés e a Arão, dizendo:"}, {"numero": 27, "texto": "Até quando ouvirei esta depravada multidão que murmura contra mim, as queixas dos filhos de Israel, que de mim se queixam?"}, {"numero": 28, "texto": "Dize-lhes: Vivo eu, diz o SENHOR, que segundo falastes a meus ouvidos, assim farei eu convosco:"}, {"numero": 29, "texto": "Neste deserto cairão vossos corpos; todos vossos contados segundo toda vossa contagem, de vinte anos acima, os quais murmurastes contra mim;"}, {"numero": 30, "texto": "Vós à verdade não entrareis na terra, pela qual levantei minha mão de fazer-vos habitar nela; exceto a Calebe filho de Jefoné, e a Josué filho de Num."}, {"numero": 31, "texto": "Mas vossos meninos, dos quais dissestes que seriam por presa, eu os introduzirei, e eles conhecerão a terra que vós desprezastes."}, {"numero": 32, "texto": "E quanto a vós, vossos corpos cairão neste deserto."}, {"numero": 33, "texto": "E vossos filhos andarão pastoreando no deserto quarenta anos, e eles levarão vossas prostituições, até que vossos corpos sejam consumidos no deserto."}, {"numero": 34, "texto": "Conforme o número dos dias, dos quarenta dias em que reconhecestes a terra, levareis vossas iniquidades quarenta anos, ano por cada dia; e conhecereis meu castigo."}, {"numero": 35, "texto": "Eu sou o SENHOR falei; assim farei a toda esta multidão perversa que se juntou contra mim; neste deserto serão consumidos, e ali morrerão."}, {"numero": 36, "texto": "E os homens que Moisés enviou para reconhecer a terra, e depois de voltarem, fizeram toda a congregação murmurar contra ele, trazendo um mau relato daquela terra,"}, {"numero": 37, "texto": "aqueles homens que haviam falado mal da terra, morreram de praga diante do SENHOR."}, {"numero": 38, "texto": "Mas Josué filho de Num, e Calebe filho de Jefoné, restaram com vida dentre aqueles homens que haviam ido a reconhecer a terra."}, {"numero": 39, "texto": "E Moisés disse estas coisas a todos os filhos de Israel, e o povo ficou em muito luto."}, {"numero": 40, "texto": "E levantaram-se pela manhã, e subiram ao cume do monte, dizendo: Eis-nos aqui para subir ao lugar do qual falou o SENHOR; porque pecamos."}, {"numero": 41, "texto": "E disse Moisés: Por que quebrantais o dito do SENHOR? Isto tampouco vos sucederá bem."}, {"numero": 42, "texto": "Não subais, porque o SENHOR não está em meio de vós, não sejais feridos diante de vossos inimigos."}, {"numero": 43, "texto": "Porque os amalequitas e os cananeus estão ali diante de vós, e caireis à espada: pois porquanto vos desviastes de seguir ao SENHOR, por isso não será o SENHOR convosco."}, {"numero": 44, "texto": "Todavia, se insistiram em subir por cima do monte: mas a arca da aliança do SENHOR, e Moisés, não se apartaram do meio do acampamento."}, {"numero": 45, "texto": "E desceram os amalequitas e os cananeus, que habitavam naquele monte, e os feriram e os derrotaram, perseguindo-os até Hormá."}]'::jsonb, 'Almeida Livre'),
  ('Nm', 14, 'en', '[{"numero": 1, "texto": "And all the congregation lifted up their voice, and cried; and the people wept that night."}, {"numero": 2, "texto": "And all the children of Israel murmured against Moses and against Aaron: and the whole congregation said unto them, Would God that we had died in the land of Egypt! or would God we had died in this wilderness!"}, {"numero": 3, "texto": "And wherefore hath the Lord brought us unto this land, to fall by the sword, that our wives and our children should be a prey? were it not better for us to return into Egypt?"}, {"numero": 4, "texto": "And they said one to another, Let us make a captain, and let us return into Egypt."}, {"numero": 5, "texto": "Then Moses and Aaron fell on their faces before all the assembly of the congregation of the children of Israel."}, {"numero": 6, "texto": "And Joshua the son of Nun, and Caleb the son of Jephunneh, which were of them that searched the land, rent their clothes:"}, {"numero": 7, "texto": "And they spake unto all the company of the children of Israel, saying, The land, which we passed through to search it, is an exceeding good land."}, {"numero": 8, "texto": "If the Lord delight in us, then he will bring us into this land, and give it us; a land which floweth with milk and honey."}, {"numero": 9, "texto": "Only rebel not ye against the Lord, neither fear ye the people of the land; for they are bread for us: their defence is departed from them, and the Lord is with us: fear them not."}, {"numero": 10, "texto": "But all the congregation bade stone them with stones. And the glory of the Lord appeared in the tabernacle of the congregation before all the children of Israel."}, {"numero": 11, "texto": "And the Lord said unto Moses, How long will this people provoke me? and how long will it be ere they believe me, for all the signs which I have shewed among them?"}, {"numero": 12, "texto": "I will smite them with the pestilence, and disinherit them, and will make of thee a greater nation and mightier than they."}, {"numero": 13, "texto": "And Moses said unto the Lord, Then the Egyptians shall hear it, (for thou broughtest up this people in thy might from among them;)"}, {"numero": 14, "texto": "And they will tell it to the inhabitants of this land: for they have heard that thou Lord art among this people, that thou Lord art seen face to face, and that thy cloud standeth over them, and that thou goest before them, by day time in a pillar of a cloud, and in a pillar of fire by night."}, {"numero": 15, "texto": "Now if thou shalt kill all this people as one man, then the nations which have heard the fame of thee will speak, saying,"}, {"numero": 16, "texto": "Because the Lord was not able to bring this people into the land which he sware unto them, therefore he hath slain them in the wilderness."}, {"numero": 17, "texto": "And now, I beseech thee, let the power of my lord be great, according as thou hast spoken, saying,"}, {"numero": 18, "texto": "The Lord is longsuffering, and of great mercy, forgiving iniquity and transgression, and by no means clearing the guilty, visiting the iniquity of the fathers upon the children unto the third and fourth generation."}, {"numero": 19, "texto": "Pardon, I beseech thee, the iniquity of this people according unto the greatness of thy mercy, and as thou hast forgiven this people, from Egypt even until now."}, {"numero": 20, "texto": "And the Lord said, I have pardoned according to thy word:"}, {"numero": 21, "texto": "But as truly as I live, all the earth shall be filled with the glory of the Lord."}, {"numero": 22, "texto": "Because all those men which have seen my glory, and my miracles, which I did in Egypt and in the wilderness, and have tempted me now these ten times, and have not hearkened to my voice;"}, {"numero": 23, "texto": "Surely they shall not see the land which I sware unto their fathers, neither shall any of them that provoked me see it:"}, {"numero": 24, "texto": "But my servant Caleb, because he had another spirit with him, and hath followed me fully, him will I bring into the land whereinto he went; and his seed shall possess it."}, {"numero": 25, "texto": "(Now the Amalekites and the Canaanites dwelt in the valley.) Tomorrow turn you, and get you into the wilderness by the way of the Red sea."}, {"numero": 26, "texto": "And the Lord spake unto Moses and unto Aaron, saying,"}, {"numero": 27, "texto": "How long shall I bear with this evil congregation, which murmur against me? I have heard the murmurings of the children of Israel, which they murmur against me."}, {"numero": 28, "texto": "Say unto them, As truly as I live, saith the Lord, as ye have spoken in mine ears, so will I do to you:"}, {"numero": 29, "texto": "Your carcases shall fall in this wilderness; and all that were numbered of you, according to your whole number, from twenty years old and upward which have murmured against me."}, {"numero": 30, "texto": "Doubtless ye shall not come into the land, concerning which I sware to make you dwell therein, save Caleb the son of Jephunneh, and Joshua the son of Nun."}, {"numero": 31, "texto": "But your little ones, which ye said should be a prey, them will I bring in, and they shall know the land which ye have despised."}, {"numero": 32, "texto": "But as for you, your carcases, they shall fall in this wilderness."}, {"numero": 33, "texto": "And your children shall wander in the wilderness forty years, and bear your whoredoms, until your carcases be wasted in the wilderness."}, {"numero": 34, "texto": "After the number of the days in which ye searched the land, even forty days, each day for a year, shall ye bear your iniquities, even forty years, and ye shall know my breach of promise."}, {"numero": 35, "texto": "I the Lord have said, I will surely do it unto all this evil congregation, that are gathered together against me: in this wilderness they shall be consumed, and there they shall die."}, {"numero": 36, "texto": "And the men, which Moses sent to search the land, who returned, and made all the congregation to murmur against him, by bringing up a slander upon the land,"}, {"numero": 37, "texto": "Even those men that did bring up the evil report upon the land, died by the plague before the Lord."}, {"numero": 38, "texto": "But Joshua the son of Nun, and Caleb the son of Jephunneh, which were of the men that went to search the land, lived still."}, {"numero": 39, "texto": "And Moses told these sayings unto all the children of Israel: and the people mourned greatly."}, {"numero": 40, "texto": "And they rose up early in the morning, and gat them up into the top of the mountain, saying, Lo, we be here, and will go up unto the place which the Lord hath promised: for we have sinned."}, {"numero": 41, "texto": "And Moses said, Wherefore now do ye transgress the commandment of the Lord? but it shall not prosper."}, {"numero": 42, "texto": "Go not up, for the Lord is not among you; that ye be not smitten before your enemies."}, {"numero": 43, "texto": "For the Amalekites and the Canaanites are there before you, and ye shall fall by the sword: because ye are turned away from the Lord, therefore the Lord will not be with you."}, {"numero": 44, "texto": "But they presumed to go up unto the hill top: nevertheless the ark of the covenant of the Lord, and Moses, departed not out of the camp."}, {"numero": 45, "texto": "Then the Amalekites came down, and the Canaanites which dwelt in that hill, and smote them, and discomfited them, even unto Hormah."}]'::jsonb, 'King James Version'),
  ('Nm', 14, 'fr', '[{"numero": 1, "texto": "Toute l''''assemblée éleva la voix et poussa des cris, et le peuple pleura pendant la nuit."}, {"numero": 2, "texto": "Tous les enfants d''''Israël murmurèrent contre Moïse et Aaron, et toute l''''assemblée leur dit: Que ne sommes-nous morts dans le pays d''''Egypte, ou que ne sommes-nous morts dans ce désert!"}, {"numero": 3, "texto": "Pourquoi l''''Eternel nous fait-il aller dans ce pays, où nous tomberons par l''''épée, où nos femmes et nos petits enfants deviendront une proie? Ne vaut-il pas mieux pour nous retourner en Egypte?"}, {"numero": 4, "texto": "Et ils se dirent l''''un à l''''autre: Nommons un chef, et retournons en Egypte."}, {"numero": 5, "texto": "Moïse et Aaron tombèrent sur leur visage, en présence de toute l''''assemblée réunie des enfants d''''Israël."}, {"numero": 6, "texto": "Et, parmi ceux qui avaient exploré le pays, Josué, fils de Nun, et Caleb, fils de Jephunné, déchirèrent leurs vêtements,"}, {"numero": 7, "texto": "et parlèrent ainsi à toute l''''assemblée des enfants d''''Israël: Le pays que nous avons parcouru, pour l''''explorer, est un pays très bon, excellent."}, {"numero": 8, "texto": "Si l''''Eternel nous est favorable, il nous mènera dans ce pays, et nous le donnera: c''''est un pays où coulent le lait et le miel."}, {"numero": 9, "texto": "Seulement, ne soyez point rebelles contre l''''Eternel, et ne craignez point les gens de ce pays, car ils nous serviront de pâture, ils n''''ont plus d''''ombrage pour les couvrir, l''''Eternel est avec nous, ne les craignez point!"}, {"numero": 10, "texto": "Toute l''''assemblée parlait de les lapider, lorsque la gloire de l''''Eternel apparut sur la tente d''''assignation, devant tous les enfants d''''Israël."}, {"numero": 11, "texto": "Et l''''Eternel dit à Moïse: Jusqu''''à quand ce peuple me méprisera-t-il? Jusqu''''à quand ne croira-t-il pas en moi, malgré tous les prodiges que j''''ai faits au milieu de lui?"}, {"numero": 12, "texto": "Je le frapperai par la peste, et je le détruirai; mais je ferai de toi une nation plus grande et plus puissante que lui."}, {"numero": 13, "texto": "Moïse dit à l''''Eternel: Les Egyptiens l''''apprendront, eux du milieu desquels tu as fait monter ce peuple par ta puissance,"}, {"numero": 14, "texto": "et ils le diront aux habitants de ce pays. Ils savaient que toi, l''''Eternel, tu es au milieu de ce peuple; que tu apparais visiblement, toi, l''''Eternel; que ta nuée se tient sur lui; que tu marches devant lui le jour dans une colonne de nuée, et la nuit dans une colonne de feu."}, {"numero": 15, "texto": "Si tu fais mourir ce peuple comme un seul homme, les nations qui ont entendu parler de toi diront:"}, {"numero": 16, "texto": "L''''Eternel n''''avait pas le pouvoir de mener ce peuple dans le pays qu''''il avait juré de lui donner: c''''est pour cela qu''''il l''''a égorgé dans le désert."}, {"numero": 17, "texto": "Maintenant, que la puissance du Seigneur se montre dans sa grandeur, comme tu l''''as déclaré en disant:"}, {"numero": 18, "texto": "L''''Eternel est lent à la colère et riche en bonté, il pardonne l''''iniquité et la rébellion; mais il ne tient point le coupable pour innocent, et il punit l''''iniquité des pères sur les enfants jusqu''''à la troisième et la quatrième génération."}, {"numero": 19, "texto": "Pardonne l''''iniquité de ce peuple, selon la grandeur de ta miséricorde, comme tu as pardonné à ce peuple depuis l''''Egypte jusqu''''ici."}, {"numero": 20, "texto": "Et l''''Eternel dit: Je pardonne, comme tu l''''as demandé."}, {"numero": 21, "texto": "Mais, je suis vivant! et la gloire de l''''Eternel remplira toute la terre."}, {"numero": 22, "texto": "Tous ceux qui ont vu ma gloire, et les prodiges que j''''ai faits en Egypte et dans le désert, qui m''''ont tenté déjà dix fois, et qui n''''ont point écouté ma voix,"}, {"numero": 23, "texto": "tous ceux-là ne verront point le pays que j''''ai juré à leurs pères de leur donner, tous ceux qui m''''ont méprisé ne le verront point."}, {"numero": 24, "texto": "Et parce que mon serviteur Caleb a été animé d''''un autre esprit, et qu''''il a pleinement suivi ma voie, je le ferai entrer dans le pays où il est allé, et ses descendants le posséderont."}, {"numero": 25, "texto": "Les Amalécites et les Cananéens habitent la vallée: demain, tournez-vous, et partez pour le désert, dans la direction de la mer Rouge."}, {"numero": 26, "texto": "L''''Eternel parla à Moïse et à Aaron, et dit:"}, {"numero": 27, "texto": "Jusqu''''à quand laisserai-je cette méchante assemblée murmurer contre moi? J''''ai entendu les murmures des enfants d''''Israël qui murmuraient contre moi."}, {"numero": 28, "texto": "Dis-leur: Je suis vivant! dit l''''Eternel, je vous ferai ainsi que vous avez parlé à mes oreilles."}, {"numero": 29, "texto": "Vos cadavres tomberont dans ce désert. Vous tous, dont on a fait le dénombrement, en vous comptant depuis l''''âge de vingt ans et au-dessus, et qui avez murmuré contre moi,"}, {"numero": 30, "texto": "vous n''''entrerez point dans le pays que j''''avais juré de vous faire habiter, excepté Caleb, fils de Jephunné, et Josué, fils de Nun."}, {"numero": 31, "texto": "Et vos petits enfants, dont vous avez dit: Ils deviendront une proie! je les y ferai entrer, et ils connaîtront le pays que vous avez dédaigné."}, {"numero": 32, "texto": "Vos cadavres, à vous, tomberont dans le désert;"}, {"numero": 33, "texto": "et vos enfants paîtront quarante années dans le désert, et porteront la peine de vos infidélités, jusqu''''à ce que vos cadavres soient tous tombés dans le désert."}, {"numero": 34, "texto": "De même que vous avez mis quarante jours à explorer le pays, vous porterez la peine de vos iniquités quarante années, une année pour chaque jour; et vous saurez ce que c''''est que d''''être privé de ma présence."}, {"numero": 35, "texto": "Moi, l''''Eternel, j''''ai parlé! et c''''est ainsi que je traiterai cette méchante assemblée qui s''''est réunie contre moi; ils seront consumés dans ce désert, ils y mourront."}, {"numero": 36, "texto": "Les hommes que Moïse avait envoyés pour explorer le pays, et qui, à leur retour, avaient fait murmurer contre lui toute l''''assemblée, en décriant le pays;"}, {"numero": 37, "texto": "ces hommes, qui avaient décrié le pays, moururent frappés d''''une plaie devant l''''Eternel."}, {"numero": 38, "texto": "Josué, fils de Nun, et Caleb, fils de Jephunné, restèrent seuls vivants parmi ces hommes qui étaient allés pour explorer le pays."}, {"numero": 39, "texto": "Moïse rapporta ces choses à tous les enfants d''''Israël, et le peuple fut dans une grande désolation."}, {"numero": 40, "texto": "Ils se levèrent de bon matin, et montèrent au sommet de la montagne, en disant: Nous voici! nous monterons au lieu dont a parlé l''''Eternel, car nous avons péché."}, {"numero": 41, "texto": "Moïse dit: Pourquoi transgressez-vous l''''ordre de l''''Eternel? Cela ne réussira point."}, {"numero": 42, "texto": "Ne montez pas! car l''''Eternel n''''est pas au milieu de vous. Ne vous faites pas battre par vos ennemis."}, {"numero": 43, "texto": "Car les Amalécites et les Cananéens sont là devant vous, et vous tomberiez par l''''épée. Parce que vous vous êtes détournés de l''''Eternel, l''''Eternel ne sera point avec vous."}, {"numero": 44, "texto": "Ils s''''obstinèrent à monter au sommet de la montagne; mais l''''arche de l''''alliance et Moïse ne sortirent point du milieu du camp."}, {"numero": 45, "texto": "Alors descendirent les Amalécites et les Cananéens qui habitaient cette montagne; ils les battirent, et les taillèrent en pièces jusqu''''à Horma."}]'::jsonb, 'Louis Segond 1910'),
  ('Nm', 14, 'es', '[{"numero": 1, "texto": "ENTONCES toda la congregación alzaron grita, y dieron voces: y el pueblo lloró aquella noche."}, {"numero": 2, "texto": "Y quejáronse contra Moisés y contra Aarón todos los hijos de Israel; y díjoles toda la multitud: ¡Ojalá muriéramos en la tierra de Egipto; ó en este desierto ojalá muriéramos!"}, {"numero": 3, "texto": "¿Y por qué nos trae Jehová á esta tierra para caer á cuchillo, y que nuestras mujeres y nuestros chiquitos sean por presa? ¿no nos sería mejor volvernos á Egipto?"}, {"numero": 4, "texto": "Y decían el uno al otro: Hagamos un capitán, y volvámonos á Egipto."}, {"numero": 5, "texto": "Entonces Moisés y Aarón cayeron sobre sus rostros delante de toda la multitud de la congregación de los hijos de Israel."}, {"numero": 6, "texto": "Y Josué hijo de Nun, y Caleb hijo de Jephone, que eran de los que habían reconocido la tierra, rompieron sus vestidos;"}, {"numero": 7, "texto": "Y hablaron á toda la congregación de los hijos de Israel, diciendo: La tierra por donde pasamos para reconocerla, es tierra en gran manera buena."}, {"numero": 8, "texto": "Si Jehová se agradare de nosotros, él nos meterá en esta tierra, y nos la entregará; tierra que fluye leche y miel."}, {"numero": 9, "texto": "Por tanto, no seáis rebeldes contra Jehová, ni temáis al pueblo de aquesta tierra, porque nuestro pan son: su amparo se ha apartado de ellos, y con nosotros está Jehová: no los temáis."}, {"numero": 10, "texto": "Entonces toda la multitud habló de apedrearlos con piedras. Mas la gloria de Jehová se mostró en el tabernáculo del testimonio á todos los hijos de Israel."}, {"numero": 11, "texto": "Y Jehová dijo á Moisés: ¿Hasta cuándo me ha de irritar este pueblo? ¿hasta cuándo no me ha de creer con todas las señales que he hecho en medio de ellos?"}, {"numero": 12, "texto": "Yo le heriré de mortandad, y lo destruiré, y á ti te pondré sobre gente grande y más fuerte que ellos."}, {"numero": 13, "texto": "Y Moisés respondió á Jehová: Oiránlo luego los Egipcios, porque de en medio de ellos sacaste á este pueblo con tu fortaleza:"}, {"numero": 14, "texto": "Y lo dirán á los habitadores de esta tierra; los cuales han oído que tú, oh Jehová, estabas en medio de este pueblo, que ojo á ojo aparecías tú, oh Jehová, y que tu nube estaba sobre ellos, y que de día ibas delante de ellos en columna de nube, y de noche en columna de fuego:"}, {"numero": 15, "texto": "Y que has hecho morir á este pueblo como á un hombre: y las gentes que hubieren oído tu fama hablarán, diciendo:"}, {"numero": 16, "texto": "Porque no pudo Jehová meter este pueblo en la tierra de la cual les había jurado, los mató en el desierto."}, {"numero": 17, "texto": "Ahora, pues, yo te ruego que sea magnificada la fortaleza del Señor, como lo hablaste, diciendo:"}, {"numero": 18, "texto": "Jehová, tardo de ira y grande en misericordia, que perdona la iniquidad y la rebelión, y absolviendo no absolverá al culpado; que visita la maldad de los padres sobre los hijos hasta los terceros y hasta los cuartos."}, {"numero": 19, "texto": "Perdona ahora la iniquidad de este pueblo según la grandeza de tu misericordia, y como has perdonado á este pueblo desde Egipto hasta aquí."}, {"numero": 20, "texto": "Entonces Jehová dijo: yo lo he perdonado conforme á tu dicho:"}, {"numero": 21, "texto": "Mas, ciertamente vivo yo y mi gloria hinche toda la tierra,"}, {"numero": 22, "texto": "Que todos los que vieron mi gloria y mis señales que he hecho en Egipto y en el desierto, y me han tentado ya diez veces, y no han oído mi voz,"}, {"numero": 23, "texto": "No verán la tierra de la cual juré á sus padres: no, ninguno de los que me han irritado la verá."}, {"numero": 24, "texto": "Empero mi siervo Caleb, por cuanto hubo en él otro espíritu, y cumplió de ir en pos de mí, yo le meteré en la tierra donde entró, y su simiente la recibirá en heredad."}, {"numero": 25, "texto": "Ahora bien, el Amalecita y el Cananeo habitan en el valle; volveos mañana, y partíos al desierto, camino del mar Bermejo."}, {"numero": 26, "texto": "Y Jehová habló á Moisés y á Aarón, diciendo:"}, {"numero": 27, "texto": "¿Hasta cuándo oiré esta depravada multitud que murmura contra mí, las querellas de los hijos de Israel, que de mí se quejan?"}, {"numero": 28, "texto": "Diles: Vivo yo, dice Jehová, que según habéis hablado á mis oídos, así haré yo con vosotros:"}, {"numero": 29, "texto": "En este desierto caerán vuestros cuerpos; todos vuestros contados según toda vuestra cuenta, de veinte años arriba, los cuales habéis murmurado contra mí;"}, {"numero": 30, "texto": "Vosotros á la verdad no entraréis en la tierra, por la cual alcé mi mano de haceros habitar en ella; exceptuando á Caleb hijo de Jephone, y á Josué hijo de Nun."}, {"numero": 31, "texto": "Mas vuestros chiquitos, de los cuales dijisteis que serían por presa, yo los introduciré, y ellos conocerán la tierra que vosotros despreciasteis."}, {"numero": 32, "texto": "Y en cuanto á vosotros, vuestros cuerpos caerán en este desierto."}, {"numero": 33, "texto": "Y vuestros hijos andarán pastoreando en el desierto cuarenta años, y ellos llevarán vuestras fornicaciones, hasta que vuestros cuerpos sean consumidos en el desierto."}, {"numero": 34, "texto": "Conforme al número de los días, de los cuarenta días en que reconocisteis la tierra, llevaréis vuestras iniquidades cuarenta años, un año por cada día; y conoceréis mi castigo."}, {"numero": 35, "texto": "Yo Jehová he hablado; así haré á toda esta multitud perversa que se ha juntado contra mí; en este desierto serán consumidos, y ahí morirán."}, {"numero": 36, "texto": "Y los varones que Moisés envió á reconocer la tierra, y vueltos habían hecho murmurar contra él á toda la congregación, desacreditando aquel país,"}, {"numero": 37, "texto": "Aquellos varones que habían hablado mal de la tierra, murieron de plaga delante de Jehová."}, {"numero": 38, "texto": "Mas Josué hijo de Nun, y Caleb hijo de Jephone, quedaron con vida de entre aquellos hombres que habían ido á reconocer la tierra."}, {"numero": 39, "texto": "Y Moisés dijo estas cosas á todos los hijos de Israel, y el pueblo se enlutó mucho."}, {"numero": 40, "texto": "Y levantáronse por la mañana, y subieron á la cumbre del monte, diciendo: Henos aquí para subir al lugar del cual ha hablado Jehová; porque hemos pecado."}, {"numero": 41, "texto": "Y dijo Moisés: ¿Por qué quebrantáis el dicho de Jehová? Esto tampoco os sucederá bien."}, {"numero": 42, "texto": "No subáis, porque Jehová no está en medio de vosotros, no seáis heridos delante de vuestros enemigos."}, {"numero": 43, "texto": "Porque el Amalecita y el Cananeo están allí delante de vosotros, y caeréis á cuchillo: pues por cuanto os habéis retraído de seguir á Jehová, por eso no será Jehová con vosotros."}, {"numero": 44, "texto": "Sin embargo, se obstinaron en subir á la cima del monte: mas el arca de la alianza de Jehová, y Moisés, no se apartaron de en medio del campo."}, {"numero": 45, "texto": "Y descendieron el Amalecita y el Cananeo, que habitaban en aquel monte, é hiriéronlos y derrotáronlos, persiguiéndolos hasta Horma."}]'::jsonb, 'Reina-Valera 1909'),
  ('Nm', 16, 'pt', '[{"numero": 1, "texto": "E Coré, filho de Izar, filho de Coate, filho de Levi; e Datã e Abirão, filhos de Eliabe; e Om, filho de Pelete, dos filhos de Rúben, tomaram gente,"}, {"numero": 2, "texto": "E levantaram-se contra Moisés com duzentos e cinquenta homens dos filhos de Israel, príncipes da congregação, dos do conselho, homens de renome;"}, {"numero": 3, "texto": "E se juntaram contra Moisés e Arão, e lhes disseram: Basta-vos, porque toda a congregação, todos eles são santos, e em meio deles está o SENHOR: por que, pois, vos levantais vós sobre a congregação do SENHOR?"}, {"numero": 4, "texto": "E quando o ouviu Moisés, lançou-se sobre seu rosto;"}, {"numero": 5, "texto": "E falou a Coré e a todo o seu grupo, dizendo: Amanhã mostrará o SENHOR quem é seu, e ao santo o fará chegar a si; e ao que ele escolher, ele o achegará a si."}, {"numero": 6, "texto": "Fazei isto: tomai incensários, Coré e todo o seu grupo:"}, {"numero": 7, "texto": "E ponde fogo neles, e ponde neles incenso diante do SENHOR amanhã; e será que o homem a quem o SENHOR escolher, aquele será o santo: basta-vos isto, filhos de Levi."}, {"numero": 8, "texto": "Disse mais Moisés a Coré: Ouvi agora, filhos de Levi:"}, {"numero": 9, "texto": "Vos é pouco que o Deus de Israel vos haja apartado da congregação de Israel, fazendo-vos achegar a si para que ministrasses no serviço do tabernáculo do SENHOR, e estivésseis diante da congregação para ministrar-lhes?"}, {"numero": 10, "texto": "E que te fez aproximar a ti, e a todos os teus irmãos os filhos de Levi contigo; para que procureis também o sacerdócio?"}, {"numero": 11, "texto": "Portanto, tu e todo o teu grupo sois os que vos juntais contra o SENHOR: pois Arão, que é para que contra ele murmureis?"}, {"numero": 12, "texto": "E enviou Moisés a chamar a Datã e Abirão, filhos de Eliabe; mas eles responderam: Não iremos lá:"}, {"numero": 13, "texto": "É pouco que nos tenhas feito vir de uma terra que destila leite e mel, para fazer-nos morrer no deserto, mas que também te faças senhor de nós autoritariamente?"}, {"numero": 14, "texto": "Nem tampouco nos puseste tu em terra que flua leite e mel, nem nos deste propriedades de terras e vinhas: hás de arrancar os olhos destes homens? Não subiremos."}, {"numero": 15, "texto": "Então Moisés se irou em grande maneira, e disse ao SENHOR: Não olhes a sua oferta: nem ainda um asno tomei deles, nem a nenhum deles fiz mal."}, {"numero": 16, "texto": "Depois disse Moisés a Coré: Tu e todo o teu grupo, ponde-vos amanhã diante do SENHOR; tu, e eles, e Arão:"}, {"numero": 17, "texto": "E tomai cada um seu incensário, e ponde incenso neles, e achegai diante do SENHOR cada um seu incensário: duzentos e cinquenta incensários: tu também, e Arão, cada um com seu incensário."}, {"numero": 18, "texto": "E tomaram cada um seu incensário, e puseram neles fogo, e lançaram neles incenso, e puseram-se à porta do tabernáculo do testemunho com Moisés e Arão."}, {"numero": 19, "texto": "Já Coré havia feito juntar contra eles toda a congregação à porta do tabernáculo do testemunho: então a glória do SENHOR apareceu a toda a congregação."}, {"numero": 20, "texto": "E o SENHOR falou a Moisés e a Arão, dizendo:"}, {"numero": 21, "texto": "Apartai-vos dentre esta congregação, e os consumirei em um momento."}, {"numero": 22, "texto": "E eles se lançaram sobre seus rostos, e disseram: Deus, Deus dos espíritos de toda carne, não é um homem o que pecou? E te irarás tu contra toda a congregação?"}, {"numero": 23, "texto": "Então o SENHOR falou a Moisés, dizendo:"}, {"numero": 24, "texto": "Fala à congregação, dizendo: Apartai-vos de em derredor da tenda de Coré, Datã, e Abirão."}, {"numero": 25, "texto": "E Moisés se levantou, e foi a Datã e Abirão; e os anciãos de Israel foram atrás dele."}, {"numero": 26, "texto": "E ele falou à congregação, dizendo: Apartai-vos agora das tendas destes ímpios homens, e não toqueis nenhuma coisa sua, porque não pereçais em todos os seus pecados."}, {"numero": 27, "texto": "E apartaram-se das tendas de Coré, de Datã, e de Abirão em derredor: e Datã e Abirão saíram e puseram-se às portas de suas tendas, com suas mulheres, e seus filhos, e suas crianças."}, {"numero": 28, "texto": "E disse Moisés: Em isto conhecereis que o SENHOR me enviou para que fizesse todas estas coisas: que não de meu coração as fiz."}, {"numero": 29, "texto": "Se como morrem todos os homens morrerem estes, ou se forem eles visitados à maneira de todos os homens, o SENHOR não me enviou."}, {"numero": 30, "texto": "Mas se o SENHOR fizer uma nova coisa, e a terra abrir sua boca, e os tragar com todas suas coisas, e descerem vivos ao Xeol, então conhecereis que estes homens irritaram ao SENHOR."}, {"numero": 31, "texto": "E aconteceu, que em acabando ele de falar todas estas palavras, rompeu-se a terra que estava debaixo deles:"}, {"numero": 32, "texto": "E abriu a terra sua boca, e tragou-os a eles, e a suas casas, e a todos os homens de Coré, e a todos os seus pertences."}, {"numero": 33, "texto": "E eles, com tudo o que tinham, desceram vivos ao Xeol, a a terra os cobriu, e pereceram do meio da congregação."}, {"numero": 34, "texto": "E todo Israel, os que estavam em derredor deles, fugiram ao grito deles; porque diziam: Não nos trague também a terra."}, {"numero": 35, "texto": "E saiu fogo do SENHOR, e consumiu os duzentos e cinquenta homens que ofereciam o incenso."}, {"numero": 36, "texto": "Então o SENHOR falou a Moisés, dizendo:"}, {"numero": 37, "texto": "Dize a Eleazar, filho de Arão sacerdote, que tome os incensários do meio do incêndio, e derrame mais ali o fogo; porque são santificados:"}, {"numero": 38, "texto": "Os incensários destes pecadores contra suas almas: e farão deles placas estendidas para cobrir o altar: porquanto ofereceram com eles diante do SENHOR, são santificados; e serão por sinal aos filhos de Israel."}, {"numero": 39, "texto": "E o sacerdote Eleazar tomou os incensários de bronze com que os queimados haviam oferecido; e estenderam-nos para cobrir o altar,"}, {"numero": 40, "texto": "Em memorial aos filhos de Israel que nenhum estranho que não seja da descendência de Arão, chegue a oferecer incenso diante do SENHOR, para que não seja como Coré, e como seu grupo; segundo se o disse o SENHOR por meio de Moisés."}, {"numero": 41, "texto": "No dia seguinte toda a congregação dos filhos de Israel murmurou contra Moisés e Arão, dizendo: Vós haveis matado ao povo do SENHOR."}, {"numero": 42, "texto": "E aconteceu que, quando se juntou a congregação contra Moisés e Arão, olharam até o tabernáculo do testemunho, e eis que a nuvem o havia coberto, e apareceu a glória do SENHOR."}, {"numero": 43, "texto": "E vieram Moisés e Arão diante do tabernáculo do testemunho."}, {"numero": 44, "texto": "E o SENHOR falou a Moisés, dizendo:"}, {"numero": 45, "texto": "Apartai-vos do meio desta congregação, e os consumirei em um momento. E eles se lançaram sobre seus rostos."}, {"numero": 46, "texto": "E disse Moisés A Arão: Toma o incensário, e põe nele fogo do altar, e sobre ele põe incenso, e vai logo à congregação, e faze expiação por eles; porque o furor saiu de diante da face do SENHOR: a mortandade começou."}, {"numero": 47, "texto": "Então tomou Arão o incensário, como Moisés disse, e correu em meio da congregação: e eis que a mortandade havia começado no povo: e ele pôs incenso, e fez expiação pelo povo."}, {"numero": 48, "texto": "E pôs-se entre os mortos e os vivos, e cessou a mortandade."}, {"numero": 49, "texto": "E os que morreram naquela mortandade foram catorze mil e setecentos, sem os mortos pelo negócio de Coré."}, {"numero": 50, "texto": "Depois se voltou Arão a Moisés à porta do tabernáculo do testemunho, quando a mortandade havia cessado."}]'::jsonb, 'Almeida Livre'),
  ('Nm', 16, 'en', '[{"numero": 1, "texto": "Now Korah, the son of Izhar, the son of Kohath, the son of Levi, and Dathan and Abiram, the sons of Eliab, and On, the son of Peleth, sons of Reuben, took men:"}, {"numero": 2, "texto": "And they rose up before Moses, with certain of the children of Israel, two hundred and fifty princes of the assembly, famous in the congregation, men of renown:"}, {"numero": 3, "texto": "And they gathered themselves together against Moses and against Aaron, and said unto them, Ye take too much upon you, seeing all the congregation are holy, every one of them, and the Lord is among them: wherefore then lift ye up yourselves above the congregation of the Lord?"}, {"numero": 4, "texto": "And when Moses heard it, he fell upon his face:"}, {"numero": 5, "texto": "And he spake unto Korah and unto all his company, saying, Even to morrow the Lord will shew who are his, and who is holy; and will cause him to come near unto him: even him whom he hath chosen will he cause to come near unto him."}, {"numero": 6, "texto": "This do; Take you censers, Korah, and all his company;"}, {"numero": 7, "texto": "And put fire therein, and put incense in them before the Lord to morrow: and it shall be that the man whom the Lord doth choose, he shall be holy: ye take too much upon you, ye sons of Levi."}, {"numero": 8, "texto": "And Moses said unto Korah, Hear, I pray you, ye sons of Levi:"}, {"numero": 9, "texto": "Seemeth it but a small thing unto you, that the God of Israel hath separated you from the congregation of Israel, to bring you near to himself to do the service of the tabernacle of the Lord, and to stand before the congregation to minister unto them?"}, {"numero": 10, "texto": "And he hath brought thee near to him, and all thy brethren the sons of Levi with thee: and seek ye the priesthood also?"}, {"numero": 11, "texto": "For which cause both thou and all thy company are gathered together against the Lord: and what is Aaron, that ye murmur against him?"}, {"numero": 12, "texto": "And Moses sent to call Dathan and Abiram, the sons of Eliab: which said, We will not come up:"}, {"numero": 13, "texto": "Is it a small thing that thou hast brought us up out of a land that floweth with milk and honey, to kill us in the wilderness, except thou make thyself altogether a prince over us?"}, {"numero": 14, "texto": "Moreover thou hast not brought us into a land that floweth with milk and honey, or given us inheritance of fields and vineyards: wilt thou put out the eyes of these men? we will not come up."}, {"numero": 15, "texto": "And Moses was very wroth, and said unto the Lord, Respect not thou their offering: I have not taken one ass from them, neither have I hurt one of them."}, {"numero": 16, "texto": "And Moses said unto Korah, Be thou and all thy company before the Lord, thou, and they, and Aaron, to morrow:"}, {"numero": 17, "texto": "And take every man his censer, and put incense in them, and bring ye before the Lord every man his censer, two hundred and fifty censers; thou also, and Aaron, each of you his censer."}, {"numero": 18, "texto": "And they took every man his censer, and put fire in them, and laid incense thereon, and stood in the door of the tabernacle of the congregation with Moses and Aaron."}, {"numero": 19, "texto": "And Korah gathered all the congregation against them unto the door of the tabernacle of the congregation: and the glory of the Lord appeared unto all the congregation."}, {"numero": 20, "texto": "And the Lord spake unto Moses and unto Aaron, saying,"}, {"numero": 21, "texto": "Separate yourselves from among this congregation, that I may consume them in a moment."}, {"numero": 22, "texto": "And they fell upon their faces, and said, O God, the God of the spirits of all flesh, shall one man sin, and wilt thou be wroth with all the congregation?"}, {"numero": 23, "texto": "And the Lord spake unto Moses, saying,"}, {"numero": 24, "texto": "Speak unto the congregation, saying, Get you up from about the tabernacle of Korah, Dathan, and Abiram."}, {"numero": 25, "texto": "And Moses rose up and went unto Dathan and Abiram; and the elders of Israel followed him."}, {"numero": 26, "texto": "And he spake unto the congregation, saying, Depart, I pray you, from the tents of these wicked men, and touch nothing of their''s, lest ye be consumed in all their sins."}, {"numero": 27, "texto": "So they gat up from the tabernacle of Korah, Dathan, and Abiram, on every side: and Dathan and Abiram came out, and stood in the door of their tents, and their wives, and their sons, and their little children."}, {"numero": 28, "texto": "And Moses said, Hereby ye shall know that the Lord hath sent me to do all these works; for I have not done them of mine own mind."}, {"numero": 29, "texto": "If these men die the common death of all men, or if they be visited after the visitation of all men; then the Lord hath not sent me."}, {"numero": 30, "texto": "But if the Lord make a new thing, and the earth open her mouth, and swallow them up, with all that appertain unto them, and they go down quick into the pit; then ye shall understand that these men have provoked the Lord."}, {"numero": 31, "texto": "And it came to pass, as he had made an end of speaking all these words, that the ground clave asunder that was under them:"}, {"numero": 32, "texto": "And the earth opened her mouth, and swallowed them up, and their houses, and all the men that appertained unto Korah, and all their goods."}, {"numero": 33, "texto": "They, and all that appertained to them, went down alive into the pit, and the earth closed upon them: and they perished from among the congregation."}, {"numero": 34, "texto": "And all Israel that were round about them fled at the cry of them: for they said, Lest the earth swallow us up also."}, {"numero": 35, "texto": "And there came out a fire from the Lord, and consumed the two hundred and fifty men that offered incense."}, {"numero": 36, "texto": "And the Lord spake unto Moses, saying,"}, {"numero": 37, "texto": "Speak unto Eleazar the son of Aaron the priest, that he take up the censers out of the burning, and scatter thou the fire yonder; for they are hallowed."}, {"numero": 38, "texto": "The censers of these sinners against their own souls, let them make them broad plates for a covering of the altar: for they offered them before the Lord, therefore they are hallowed: and they shall be a sign unto the children of Israel."}, {"numero": 39, "texto": "And Eleazar the priest took the brasen censers, wherewith they that were burnt had offered; and they were made broad plates for a covering of the altar:"}, {"numero": 40, "texto": "To be a memorial unto the children of Israel, that no stranger, which is not of the seed of Aaron, come near to offer incense before the Lord; that he be not as Korah, and as his company: as the Lord said to him by the hand of Moses."}, {"numero": 41, "texto": "But on the morrow all the congregation of the children of Israel murmured against Moses and against Aaron, saying, Ye have killed the people of the Lord."}, {"numero": 42, "texto": "And it came to pass, when the congregation was gathered against Moses and against Aaron, that they looked toward the tabernacle of the congregation: and, behold, the cloud covered it, and the glory of the Lord appeared."}, {"numero": 43, "texto": "And Moses and Aaron came before the tabernacle of the congregation."}, {"numero": 44, "texto": "And the Lord spake unto Moses, saying,"}, {"numero": 45, "texto": "Get you up from among this congregation, that I may consume them as in a moment. And they fell upon their faces."}, {"numero": 46, "texto": "And Moses said unto Aaron, Take a censer, and put fire therein from off the altar, and put on incense, and go quickly unto the congregation, and make an atonement for them: for there is wrath gone out from the Lord; the plague is begun."}, {"numero": 47, "texto": "And Aaron took as Moses commanded, and ran into the midst of the congregation; and, behold, the plague was begun among the people: and he put on incense, and made an atonement for the people."}, {"numero": 48, "texto": "And he stood between the dead and the living; and the plague was stayed."}, {"numero": 49, "texto": "Now they that died in the plague were fourteen thousand and seven hundred, beside them that died about the matter of Korah."}, {"numero": 50, "texto": "And Aaron returned unto Moses unto the door of the tabernacle of the congregation: and the plague was stayed."}]'::jsonb, 'King James Version'),
  ('Nm', 16, 'fr', '[{"numero": 1, "texto": "Koré, fils de Jitsehar, fils de Kehath, fils de Lévi, se révolta avec Dathan et Abiram, fils d''''Eliab, et On, fils de Péleth, tous trois fils de Ruben."}, {"numero": 2, "texto": "Ils se soulevèrent contre Moïse, avec deux cent cinquante hommes des enfants d''''Israël, des principaux de l''''assemblée, de ceux que l''''on convoquait à l''''assemblée, et qui étaient des gens de renom."}, {"numero": 3, "texto": "Ils s''''assemblèrent contre Moïse et Aaron, et leur dirent: C''''en est assez! car toute l''''assemblée, tous sont saints, et l''''Eternel est au milieu d''''eux. Pourquoi vous élevez-vous au-dessus de l''''assemblée de l''''Eternel?"}, {"numero": 4, "texto": "Quand Moïse eut entendu cela, il tomba sur son visage."}, {"numero": 5, "texto": "Il parla à Koré et à toute sa troupe, en disant: Demain, l''''Eternel fera connaître qui est à lui et qui est saint, et il le fera approcher de lui; il fera approcher de lui celui qu''''il choisira."}, {"numero": 6, "texto": "Faites ceci. Prenez des brasiers, Koré et toute sa troupe."}, {"numero": 7, "texto": "Demain, mettez-y du feu, et posez-y du parfum devant l''''Eternel; celui que l''''Eternel choisira, c''''est celui-là qui sera saint. C''''en est assez, enfants de Lévi!"}, {"numero": 8, "texto": "Moïse dit à Koré: Ecoutez donc, enfants de Lévi:"}, {"numero": 9, "texto": "Est-ce trop peu pour vous que le Dieu d''''Israël vous ait choisis dans l''''assemblée d''''Israël, en vous faisant approcher de lui, afin que vous soyez employés au service du tabernacle de l''''Eternel, et que vous vous présentiez devant l''''assemblée pour la servir?"}, {"numero": 10, "texto": "Il vous a fait approcher de lui, toi, et tous tes frères, les enfants de Lévi, et vous voulez encore le sacerdoce!"}, {"numero": 11, "texto": "C''''est à cause de cela que toi et toute ta troupe, vous vous assemblez contre l''''Eternel! car qui est Aaron, pour que vous murmuriez contre lui?"}, {"numero": 12, "texto": "Moïse envoya appeler Dathan et Abiram, fils d''''Eliab. Mais ils dirent: Nous ne monterons pas."}, {"numero": 13, "texto": "N''''est-ce pas assez que tu nous aies fait sortir d''''un pays où coulent le lait et le miel pour nous faire mourir au désert, sans que tu continues à dominer sur nous?"}, {"numero": 14, "texto": "Et ce n''''est pas dans un pays où coulent le lait et le miel que tu nous as menés, ce ne sont pas des champs et des vignes que tu nous as donnés en possession. Penses-tu crever les yeux de ces gens? Nous ne monterons pas."}, {"numero": 15, "texto": "Moïse fut très irrité, et il dit à l''''Eternel: N''''aie point égard à leur offrande. Je ne leur ai pas même pris un âne, et je n''''ai fait de mal à aucun d''''eux."}, {"numero": 16, "texto": "Moïse dit à Koré: Toi et toute ta troupe, trouvez-vous demain devant l''''Eternel, toi et eux, avec Aaron."}, {"numero": 17, "texto": "Prenez chacun votre brasier, mettez-y du parfum, et présentez devant l''''Eternel chacun votre brasier: il y aura deux cent cinquante brasiers; toi et Aaron, vous prendrez aussi chacun votre brasier."}, {"numero": 18, "texto": "Ils prirent chacun leur brasier, y mirent du feu et y posèrent du parfum, et ils se tinrent à l''''entrée de la tente d''''assignation, avec Moïse et Aaron."}, {"numero": 19, "texto": "Et Koré convoqua toute l''''assemblée contre Moïse et Aaron, à l''''entrée de la tente d''''assignation. Alors la gloire de l''''Eternel apparut à toute l''''assemblée."}, {"numero": 20, "texto": "Et l''''Eternel parla à Moïse et à Aaron, et dit:"}, {"numero": 21, "texto": "Séparez-vous du milieu de cette assemblée, et je les consumerai en un seul instant."}, {"numero": 22, "texto": "Ils tombèrent sur leur visage, et dirent: O Dieu, Dieu des esprits de toute chair! un seul homme a péché, et tu t''''irriterais contre toute l''''assemblée?"}, {"numero": 23, "texto": "L''''Eternel parla à Moïse, et dit:"}, {"numero": 24, "texto": "Parle à l''''assemblée, et dis: Retirez-vous de toutes parts loin de la demeure de Koré, de Dathan et d''''Abiram."}, {"numero": 25, "texto": "Moïse se leva, et alla vers Dathan et Abiram; et les anciens d''''Israël le suivirent."}, {"numero": 26, "texto": "Il parla à l''''assemblée, et dit: Eloignez-vous des tentes de ces méchants hommes, et ne touchez à rien de ce qui leur appartient, de peur que vous ne périssiez en même temps qu''''ils seront punis pour tous leurs péchés."}, {"numero": 27, "texto": "Ils se retirèrent de toutes parts loin de la demeure de Koré, de Dathan et d''''Abiram. Dathan et Abiram sortirent, et se tinrent à l''''entrée de leurs tentes, avec leurs femmes, leurs fils et leurs petits-enfants."}, {"numero": 28, "texto": "Moïse dit: A ceci vous connaîtrez que l''''Eternel m''''a envoyé pour faire toutes ces choses, et que je n''''agis pas de moi-même."}, {"numero": 29, "texto": "Si ces gens meurent comme tous les hommes meurent, s''''ils subissent le sort commun à tous les hommes, ce n''''est pas l''''Eternel qui m''''a envoyé;"}, {"numero": 30, "texto": "mais si l''''Eternel fait une chose inouïe, si la terre ouvre sa bouche pour les engloutir avec tout ce qui leur appartient, et qu''''ils descendent vivants dans le séjour des morts, vous saurez alors que ces gens ont méprisé l''''Eternel."}, {"numero": 31, "texto": "Comme il achevait de prononcer toutes ces paroles, la terre qui était sous eux se fendit."}, {"numero": 32, "texto": "La terre ouvrit sa bouche, et les engloutit, eux et leurs maisons, avec tous les gens de Koré et tous leurs biens."}, {"numero": 33, "texto": "Ils descendirent vivants dans le séjour des morts, eux et tout ce qui leur appartenait; la terre les recouvrit, et ils disparurent au milieu de l''''assemblée."}, {"numero": 34, "texto": "Tout Israël, qui était autour d''''eux, s''''enfuit à leur cri; car ils disaient: Fuyons, de peur que la terre ne nous engloutisse!"}, {"numero": 35, "texto": "Un feu sortit d''''auprès de l''''Eternel, et consuma les deux cent cinquante hommes qui offraient le parfum."}, {"numero": 36, "texto": "L''''Eternel parla à Moïse, et dit:"}, {"numero": 37, "texto": "Dis à Eléazar, fils du sacrificateur Aaron, de retirer de l''''incendie les brasiers et d''''en répandre au loin le feu, car ils sont sanctifiés."}, {"numero": 38, "texto": "Avec les brasiers de ces gens qui ont péché au péril de leur vie, que l''''on fasse des lames étendues dont on couvrira l''''autel. Puisqu''''ils ont été présentés devant l''''Eternel et qu''''ils sont sanctifiés, ils serviront de souvenir aux enfants d''''Israël."}, {"numero": 39, "texto": "Le sacrificateur Eléazar prit les brasiers d''''airain qu''''avaient présentés les victimes de l''''incendie, et il en fit des lames pour couvrir l''''autel."}, {"numero": 40, "texto": "C''''est un souvenir pour les enfants d''''Israël, afin qu''''aucun étranger à la race d''''Aaron ne s''''approche pour offrir du parfum devant l''''Eternel et ne soit comme Koré et comme sa troupe, selon ce que l''''Eternel avait déclaré par Moïse."}, {"numero": 41, "texto": "Dès le lendemain, toute l''''assemblée des enfants d''''Israël murmura contre Moïse et Aaron, en disant: Vous avez fait mourir le peuple de l''''Eternel."}, {"numero": 42, "texto": "Comme l''''assemblée se formait contre Moïse et Aaron, et comme ils tournaient les regards vers la tente d''''assignation, voici, la nuée la couvrit, et la gloire de l''''Eternel apparut."}, {"numero": 43, "texto": "Moïse et Aaron arrivèrent devant la tente d''''assignation."}, {"numero": 44, "texto": "Et l''''Eternel parla à Moïse, et dit:"}, {"numero": 45, "texto": "Retirez-vous du milieu de cette assemblée, et je les consumerai en un instant. Ils tombèrent sur leur visage;"}, {"numero": 46, "texto": "et Moïse dit à Aaron: Prends le brasier, mets-y du feu de dessus l''''autel, poses-y du parfum, va promptement vers l''''assemblée, et fais pour eux l''''expiation; car la colère de l''''Eternel a éclaté, la plaie a commencé."}, {"numero": 47, "texto": "Aaron prit le brasier, comme Moïse avait dit, et courut au milieu de l''''assemblée; et voici, la plaie avait commencé parmi le peuple. Il offrit le parfum, et il fit l''''expiation pour le peuple."}, {"numero": 48, "texto": "Il se plaça entre les morts et les vivants, et la plaie fut arrêtée."}, {"numero": 49, "texto": "Il y eut quatorze mille sept cents personnes qui moururent de cette plaie, outre ceux qui étaient morts à cause de Koré."}, {"numero": 50, "texto": "Aaron retourna auprès de Moïse, à l''''entrée de la tente d''''assignation. La plaie était arrêtée."}]'::jsonb, 'Louis Segond 1910'),
  ('Nm', 16, 'es', '[{"numero": 1, "texto": "Y CORÉ, hijo de Ishar, hijo de Coath, hijo de Leví; y Dathán y Abiram, hijos de Eliab; y Hon, hijo de Peleth, de los hijos de Rubén, tomaron gente,"}, {"numero": 2, "texto": "Y levantáronse contra Moisés con doscientos y cincuenta varones de los hijos de Israel, príncipes de la congregación, de los del consejo, varones de nombre;"}, {"numero": 3, "texto": "Y se juntaron contra Moisés y Aarón, y les dijeron: Básteos, porque toda la congregación, todos ellos son santos, y en medio de ellos está Jehová: ¿por qué, pues, os levantáis vosotros sobre la congregación de Jehová?"}, {"numero": 4, "texto": "Y como lo oyó Moisés, echóse sobre su rostro;"}, {"numero": 5, "texto": "Y habló á Coré y á todo su séquito, diciendo: Mañana mostrará Jehová quién es suyo, y al santo harálo llegar á sí; y al que él escogiere, él lo allegará á sí."}, {"numero": 6, "texto": "Haced esto: tomaos incensarios, Coré y todo su séquito:"}, {"numero": 7, "texto": "Y poned fuego en ellos, y poned en ellos sahumerio delante de Jehová mañana; y será que el varón á quien Jehová escogiere, aquél será el santo: básteos esto, hijos de Leví."}, {"numero": 8, "texto": "Dijo más Moisés á Coré: Oid ahora, hijos de Leví:"}, {"numero": 9, "texto": "¿Os es poco que el Dios de Israel os haya apartado de la congregación de Israel, haciéndoos allegar á sí para que ministraseis en el servicio del tabernáculo de Jehová, y estuvieseis delante de la congregación para ministrarles?"}, {"numero": 10, "texto": "¿Y que te hizo acercar á ti, y á todos tus hermanos los hijos de Leví contigo; para que procuréis también el sacerdocio?"}, {"numero": 11, "texto": "Por tanto, tú y todo tu séquito sois los que os juntáis contra Jehová: pues Aarón, ¿qué es para que contra él murmuréis?"}, {"numero": 12, "texto": "Y envió Moisés á llamar á Dathán y Abiram, hijos de Eliab; mas ellos respondieron: No iremos allá:"}, {"numero": 13, "texto": "¿Es poco que nos hayas hecho venir de una tierra que destila leche y miel, para hacernos morir en el desierto, sino que también te enseñorees de nosotros imperiosamente?"}, {"numero": 14, "texto": "Ni tampoco nos has metido tú en tierra que fluya leche y miel, ni nos has dado heredades de tierras y viñas: ¿has de arrancar los ojos de estos hombres? No subiremos."}, {"numero": 15, "texto": "Entonces Moisés se enojó en gran manera, y dijo á Jehová: No mires á su presente: ni aun un asno he tomado de ellos, ni á ninguno de ellos he hecho mal."}, {"numero": 16, "texto": "Después dijo Moisés á Coré: Tú y todo tu séquito, poneos mañana delante de Jehová; tú, y ellos, y Aarón:"}, {"numero": 17, "texto": "Y tomad cada uno su incensario, y poned sahumerio en ellos, y allegad delante de Jehová cada uno su incensario: doscientos y cincuenta incensarios: tú también, y Aarón, cada uno con su incensario."}, {"numero": 18, "texto": "Y tomaron cada uno su incensario, y pusieron en ellos fuego, y echaron en ellos sahumerio, y pusiéronse á la puerta del tabernáculo del testimonio con Moisés y Aarón."}, {"numero": 19, "texto": "Ya Coré había hecho juntar contra ellos toda la congregación á la puerta del tabernáculo del testimonio: entonces la gloria de Jehová apareció á toda la congregación."}, {"numero": 20, "texto": "Y Jehová habló á Moisés y á Aarón, diciendo:"}, {"numero": 21, "texto": "Apartaos de entre esta congregación, y consumirlos he en un momento."}, {"numero": 22, "texto": "Y ellos se echaron sobre sus rostros, y dijeron: Dios, Dios de los espíritus de toda carne, ¿no es un hombre el que pecó? ¿y airarte has tú contra toda la congregación?"}, {"numero": 23, "texto": "Entonces Jehová habló á Moisés, diciendo:"}, {"numero": 24, "texto": "Habla á la congregación, diciendo: Apartaos de en derredor de la tienda de Coré, Dathán, y Abiram."}, {"numero": 25, "texto": "Y Moisés se levantó, y fué á Dathán y á Abiram; y los ancianos de Israel fueron en pos de él."}, {"numero": 26, "texto": "Y él habló á la congregación, diciendo: Apartaos ahora de las tiendas de estos impíos hombres, y no toquéis ninguna cosa suya, por que no perezcáis en todos sus pecados."}, {"numero": 27, "texto": "Y apartáronse de las tiendas de Coré, de Dathán, y de Abiram en derredor: y Dathán y Abiram salieron y pusiéronse á las puertas de sus tiendas, con sus mujeres, y sus hijos, y sus chiquitos."}, {"numero": 28, "texto": "Y dijo Moisés: En esto conoceréis que Jehová me ha enviado para que hiciese todas estas cosas; que no de mi corazón las hice."}, {"numero": 29, "texto": "Si como mueren todos los hombres murieren éstos, ó si fueren ellos visitados á la manera de todos los hombres, Jehová no me envió."}, {"numero": 30, "texto": "Mas si Jehová hiciere una nueva cosa, y la tierra abriere su boca, y los tragare con todas sus cosas, y descendieren vivos al abismo, entonces conoceréis que estos hombres irritaron á Jehová."}, {"numero": 31, "texto": "Y aconteció, que en acabando él de hablar todas estas palabras, rompióse la tierra que estaba debajo de ellos:"}, {"numero": 32, "texto": "Y abrió la tierra su boca, y tragólos á ellos, y á sus casas, y á todos los hombres de Coré, y á toda su hacienda."}, {"numero": 33, "texto": "Y ellos, con todo lo que tenían, descendieron vivos al abismo, y cubriólos la tierra, y perecieron de en medio de la congregación."}, {"numero": 34, "texto": "Y todo Israel, los que estaban en derredor de ellos, huyeron al grito de ellos; porque decían: No nos trague también la tierra."}, {"numero": 35, "texto": "Y salió fuego de Jehová, y consumió los doscientos y cincuenta hombres que ofrecían el sahumerio."}, {"numero": 36, "texto": "Entonces Jehová habló á Moisés, diciendo:"}, {"numero": 37, "texto": "Di á Eleazar, hijo de Aarón sacerdote, que tome los incensarios de en medio del incendio, y derrame más allá el fuego; porque son santificados:"}, {"numero": 38, "texto": "Los incensarios de estos pecadores contra sus almas: y harán de ellos planchas extendidas para cubrir el altar: por cuanto ofrecieron con ellos delante de Jehová, son santificados; y serán por señal á los hijos de Israel."}, {"numero": 39, "texto": "Y el sacerdote Eleazar tomó los incensarios de metal con que los quemados habían ofrecido; y extendiéronlos para cubrir el altar,"}, {"numero": 40, "texto": "En recuerdo á los hijos de Israel que ningún extraño que no sea de la simiente de Aarón, llegue á ofrecer sahumerio delante de Jehová, porque no sea como Coré, y como su séquito; según se lo dijo Jehová por mano de Moisés."}, {"numero": 41, "texto": "El día siguiente toda la congregación de los hijos de Israel murmuró contra Moisés y Aarón, diciendo: Vosotros habéis muerto al pueblo de Jehová."}, {"numero": 42, "texto": "Y aconteció que, como se juntó la congregación contra Moisés y Aarón, miraron hacia el tabernáculo del testimonio, y he aquí la nube lo había cubierto, y apareció la gloria de Jehová."}, {"numero": 43, "texto": "Y vinieron Moisés y Aarón delante del tabernáculo del testimonio."}, {"numero": 44, "texto": "Y Jehová habló á Moisés, diciendo:"}, {"numero": 45, "texto": "Apartaos de en medio de esta congregación, y consumirélos en un momento. Y ellos se echaron sobre sus rostros."}, {"numero": 46, "texto": "Y dijo Moisés á Aarón: Toma el incensario, y pon en él fuego del altar, y sobre él pon perfume, y ve presto á la congregación, y haz expiación por ellos; porque el furor ha salido de delante de la faz de Jehová: la mortandad ha comenzado."}, {"numero": 47, "texto": "Entonces tomó Aarón el incensario, como Moisés dijo, y corrió en medio de la congregación: y he aquí que la mortandad había comenzado en el pueblo: y él puso perfume, é hizo expiación por el pueblo."}, {"numero": 48, "texto": "Y púsose entre los muertos y los vivos; y cesó la mortandad."}, {"numero": 49, "texto": "Y los que murieron en aquella mortandad fueron catorce mil y setecientos, sin los muertos por el negocio de Coré."}, {"numero": 50, "texto": "Después se volvió Aarón á Moisés á la puerta del tabernáculo del testimonio, cuando la mortandad había cesado."}]'::jsonb, 'Reina-Valera 1909'),
  ('Nm', 17, 'pt', '[{"numero": 1, "texto": "E falou o SENHOR a Moisés, dizendo:"}, {"numero": 2, "texto": "Fala aos filhos de Israel, e toma deles uma vara por cada casa dos pais, de todos os príncipes deles, doze varas conforme as casas de seus pais; e escreverás o nome de cada um sobre sua vara."}, {"numero": 3, "texto": "E escreverás o nome de Arão sobre a vara de Levi; porque cada cabeça de família de seus pais terá uma vara."}, {"numero": 4, "texto": "E as porás no tabernáculo do testemunho diante do testemunho, onde eu me declararei a vós."}, {"numero": 5, "texto": "E será, que o homem que eu escolher, sua vara florescerá: e farei cessar de sobre mim as queixas dos filhos de Israel, com que murmuram contra vós."}, {"numero": 6, "texto": "E Moisés falou aos filhos de Israel, e todos os príncipes deles lhe deram varas; cada príncipe pelas casas de seus pais uma vara, em todas doze varas; e a vara de Arão estava entre as varas deles."}, {"numero": 7, "texto": "E Moisés pôs as varas diante do SENHOR no tabernáculo do testemunho."}, {"numero": 8, "texto": "E aconteceu que no dia seguinte veio Moisés ao tabernáculo do testemunho; e eis que a vara de Arão da casa de Levi havia brotado, e produzido flores, e lançado renovos, e produzido amêndoas."}, {"numero": 9, "texto": "Então tirou Moisés todas as varas de diante do SENHOR a todos os filhos de Israel; e eles o viram, e tomaram cada um sua vara."}, {"numero": 10, "texto": "E o SENHOR disse a Moisés: Volta a vara de Arão diante do testemunho, para que se guarde por sinal aos filhos rebeldes; e farás cessar suas queixas de sobre mim, para que não morram."}, {"numero": 11, "texto": "E o fez Moisés: como lhe mandou o SENHOR, assim fez."}, {"numero": 12, "texto": "Então os filhos de Israel falaram a Moisés, dizendo: Eis que nós somos mortos, perdidos somos, todos nós somos perdidos."}, {"numero": 13, "texto": "Qualquer um que se chegar, o que se aproximar ao tabernáculo do SENHOR morrerá: Acabaremos de perecer todos?"}]'::jsonb, 'Almeida Livre'),
  ('Nm', 17, 'en', '[{"numero": 1, "texto": "And the Lord spake unto Moses, saying,"}, {"numero": 2, "texto": "Speak unto the children of Israel, and take of every one of them a rod according to the house of their fathers, of all their princes according to the house of their fathers twelve rods: write thou every man''s name upon his rod."}, {"numero": 3, "texto": "And thou shalt write Aaron''s name upon the rod of Levi: for one rod shall be for the head of the house of their fathers."}, {"numero": 4, "texto": "And thou shalt lay them up in the tabernacle of the congregation before the testimony, where I will meet with you."}, {"numero": 5, "texto": "And it shall come to pass, that the man''s rod, whom I shall choose, shall blossom: and I will make to cease from me the murmurings of the children of Israel, whereby they murmur against you."}, {"numero": 6, "texto": "And Moses spake unto the children of Israel, and every one of their princes gave him a rod apiece, for each prince one, according to their fathers'' houses, even twelve rods: and the rod of Aaron was among their rods."}, {"numero": 7, "texto": "And Moses laid up the rods before the Lord in the tabernacle of witness."}, {"numero": 8, "texto": "And it came to pass, that on the morrow Moses went into the tabernacle of witness; and, behold, the rod of Aaron for the house of Levi was budded, and brought forth buds, and bloomed blossoms, and yielded almonds."}, {"numero": 9, "texto": "And Moses brought out all the rods from before the Lord unto all the children of Israel: and they looked, and took every man his rod."}, {"numero": 10, "texto": "And the Lord said unto Moses, Bring Aaron''s rod again before the testimony, to be kept for a token against the rebels; and thou shalt quite take away their murmurings from me, that they die not."}, {"numero": 11, "texto": "And Moses did so: as the Lord commanded him, so did he."}, {"numero": 12, "texto": "And the children of Israel spake unto Moses, saying, Behold, we die, we perish, we all perish."}, {"numero": 13, "texto": "Whosoever cometh any thing near unto the tabernacle of the Lord shall die: shall we be consumed with dying?"}]'::jsonb, 'King James Version'),
  ('Nm', 17, 'fr', '[{"numero": 1, "texto": "L''''Eternel parla à Moïse, et dit:"}, {"numero": 2, "texto": "Parle aux enfants d''''Israël, et prends d''''eux une verge selon les maisons de leurs pères, soit douze verges de la part de tous leurs princes selon les maisons de leurs pères. Tu écriras le nom de chacun sur sa verge,"}, {"numero": 3, "texto": "et tu écriras le nom d''''Aaron sur la verge de Lévi; car il y aura une verge pour chaque chef des maisons de leurs pères."}, {"numero": 4, "texto": "Tu les déposeras dans la tente d''''assignation, devant le témoignage, où je me rencontre avec vous."}, {"numero": 5, "texto": "L''''homme que je choisirai sera celui dont la verge fleurira, et je ferai cesser de devant moi les murmures que profèrent contre vous les enfants d''''Israël."}, {"numero": 6, "texto": "Moïse parla aux enfants d''''Israël; et tous leurs princes lui donnèrent une verge, chaque prince une verge, selon les maisons de leurs pères, soit douze verges; la verge d''''Aaron était au milieu des leurs."}, {"numero": 7, "texto": "Moïse déposa les verges devant l''''Eternel, dans la tente du témoignage."}, {"numero": 8, "texto": "Le lendemain, lorsque Moïse entra dans la tente du témoignage, voici, la verge d''''Aaron, pour la maison de Lévi, avait fleuri, elle avait poussé des boutons, produit des fleurs, et mûri des amandes."}, {"numero": 9, "texto": "Moïse ôta de devant l''''Eternel toutes les verges, et les porta à tous les enfants d''''Israël, afin qu''''ils les vissent et qu''''ils prissent chacun leur verge."}, {"numero": 10, "texto": "L''''Eternel dit à Moïse: Reporte la verge d''''Aaron devant le témoignage, pour être conservée comme un signe pour les enfants de rébellion, afin que tu fasses cesser de devant moi leurs murmures et qu''''ils ne meurent point."}, {"numero": 11, "texto": "Moïse fit ainsi; il se conforma à l''''ordre que l''''Eternel lui avait donné."}, {"numero": 12, "texto": "Les enfants d''''Israël dirent à Moïse: Voici, nous expirons, nous périssons, nous périssons tous!"}, {"numero": 13, "texto": "Quiconque s''''approche du tabernacle de l''''Eternel, meurt. Nous faudra-t-il tous expirer?"}]'::jsonb, 'Louis Segond 1910'),
  ('Nm', 17, 'es', '[{"numero": 1, "texto": "Y HABLÓ Jehová á Moisés, diciendo:"}, {"numero": 2, "texto": "Habla á los hijos de Israel, y toma de ellos una vara por cada casa de los padres, de todos los príncipes de ellos, doce varas conforme á las casas de sus padres; y escribirás el nombre de cada uno sobre su vara."}, {"numero": 3, "texto": "Y escribirás el nombre de Aarón sobre la vara de Leví; porque cada cabeza de familia de sus padres tendrá una vara."}, {"numero": 4, "texto": "Y las pondrás en el tabernáculo del testimonio delante del testimonio, donde yo me declararé á vosotros."}, {"numero": 5, "texto": "Y será, que el varón que yo escogiere, su vara florecerá: y haré cesar de sobre mí las quejas de los hijos de Israel, con que murmuran contra vosotros."}, {"numero": 6, "texto": "Y Moisés habló á los hijos de Israel, y todos los príncipes de ellos le dieron varas; cada príncipe por las casas de sus padres una vara, en todas doce varas; y la vara de Aarón estaba entre las varas de ellos."}, {"numero": 7, "texto": "Y Moisés puso las varas delante de Jehová en el tabernáculo del testimonio."}, {"numero": 8, "texto": "Y aconteció que el día siguiente vino Moisés al tabernáculo del testimonio; y he aquí que la vara de Aarón de la casa de Leví había brotado, y echado flores, y arrojado renuevos, y producido almendras."}, {"numero": 9, "texto": "Entonces sacó Moisés todas las varas de delante de Jehová á todos los hijos de Israel; y ellos lo vieron, y tomaron cada uno su vara."}, {"numero": 10, "texto": "Y Jehová dijo á Moisés: Vuelve la vara de Aarón delante del testimonio, para que se guarde por señal á los hijos rebeldes; y harás cesar sus quejas de sobre mí, porque no mueran."}, {"numero": 11, "texto": "E hízolo Moisés: como le mandó Jehová, así hizo."}, {"numero": 12, "texto": "Entonces los hijos de Israel hablaron á Moisés, diciendo: He aquí nosotros somos muertos, perdidos somos, todos nosotros somos perdidos."}, {"numero": 13, "texto": "Cualquiera que se llegare, el que se acercare al tabernáculo de Jehová morirá: ¿acabaremos de perecer todos?"}]'::jsonb, 'Reina-Valera 1909'),
  ('Nm', 20, 'pt', '[{"numero": 1, "texto": "E chegaram os filhos de Israel, toda a congregação, ao deserto de Zim, no mês primeiro, e assentou o povo em Cades; e ali morreu Miriã, e foi ali sepultada."}, {"numero": 2, "texto": "E como não havia água para a congregação, juntaram-se contra Moisés e Arão."}, {"numero": 3, "texto": "E brigou o povo com Moisés, e falaram dizendo: Antes que nós tivéssemos morrido quando pereceram nossos irmãos diante do SENHOR!"}, {"numero": 4, "texto": "E por que fizeste vir a congregação do SENHOR a este deserto, para que morramos aqui nós e nossos animais?"}, {"numero": 5, "texto": "E por que nos fizeste subir do Egito, para trazer-nos a este mal lugar? Não é lugar de sementeira, de figueiras, de vinhas, nem romãs: nem ainda de água para beber."}, {"numero": 6, "texto": "E foram-se Moisés e Arão de diante da congregação à porta do tabernáculo do testemunho, e lançaram-se sobre seus rostos; e a glória do SENHOR apareceu sobre eles."}, {"numero": 7, "texto": "E falou o SENHOR a Moisés, dizendo:"}, {"numero": 8, "texto": "Toma a vara e reúne a congregação, tu e Arão teu irmão, e falai à rocha em olhos deles; e ela dará sua água, e lhes tirarás águas da rocha, e darás de beber à congregação, e a seus animais."}, {"numero": 9, "texto": "Então Moisés tomou a vara de diante do SENHOR, como ele lhe mandou."}, {"numero": 10, "texto": "E juntaram Moisés e Arão a congregação diante da rocha, e disse-lhes: Ouvi agora, rebeldes: Faremos para vós sair águas desta rocha?"}, {"numero": 11, "texto": "Então levantou Moisés sua mão, e feriu a rocha com sua vara duas vezes: e saíram muitas águas, e bebeu a congregação, e seus animais."}, {"numero": 12, "texto": "E o SENHOR disse a Moisés e a Arão: Porquanto não crestes em mim, para santificar-me aos olhos dos filhos de Israel, portanto, não poreis esta congregação na terra que lhes dei."}, {"numero": 13, "texto": "Estas são as águas da briga, pelas quais contenderam os filhos de Israel com o SENHOR, e ele se santificou neles."}, {"numero": 14, "texto": "E enviou Moisés embaixadores ao rei de Edom desde Cades: Assim diz Israel teu irmão: Tu soubeste todo o trabalho que nos veio:"}, {"numero": 15, "texto": "Como nossos pais desceram ao Egito, e estivemos no Egito longo tempo, e os egípcios nos maltrataram, e a nossos pais;"}, {"numero": 16, "texto": "E clamamos ao SENHOR, o qual ouviu nossa voz, e enviou anjo, e tirou-nos do Egito; e eis que estamos em Cades, cidade ao extremo de teus confins:"}, {"numero": 17, "texto": "Rogamo-te que passemos por tua terra; não passaremos por lavoura, nem por vinha, nem beberemos água de poços: pelo caminho real iremos, sem apartar-nos à direita nem à esquerda, até que havemos passado teu termo."}, {"numero": 18, "texto": "E Edom lhe respondeu: Não passarás por minha terra, de outra maneira sairei contra ti armado."}, {"numero": 19, "texto": "E os filhos de Israel disseram: Pelo caminho seguido iremos; e se bebermos tuas águas eu e meus gados, darei o preço delas: certamente sem fazer outra coisa, passarei de seguida."}, {"numero": 20, "texto": "E ele respondeu: Não passarás. E saiu Edom contra ele com muito povo, e mão forte."}, {"numero": 21, "texto": "Não quis, pois, Edom deixar passar a Israel por seu termo, e apartou-se Israel dele."}, {"numero": 22, "texto": "E partidos de Cades os filhos de Israel, toda aquela congregação, vieram ao monte de Hor."}, {"numero": 23, "texto": "E o SENHOR falou a Moisés e Arão no monte de Hor, nos confins da terra de Edom, dizendo:"}, {"numero": 24, "texto": "Arão será reunido a seus povos; pois não entrará na terra que eu dize aos filhos de Israel, porquanto fostes rebeldes a meu mandamento nas águas da briga."}, {"numero": 25, "texto": "Toma a Arão e a Eleazar seu filho, e faze-os subir ao monte de Hor;"}, {"numero": 26, "texto": "E faze desnudar a Arão suas roupas, e viste delas a Eleazar seu filho; porque Arão será reunido a seus povos, e ali morrerá."}, {"numero": 27, "texto": "E Moisés fez como o SENHOR lhe mandou: e subiram ao monte de Hor à vista de toda a congregação."}, {"numero": 28, "texto": "E Moisés fez desnudar a Arão de suas roupas e vestiu-as a Eleazar seu filho: e Arão morreu ali no cume do monte: e Moisés e Eleazar desceram do monte."}, {"numero": 29, "texto": "E vendo toda a congregação que Arão era morto, fizeram-lhe luto por trinta dias todas as famílias de Israel."}]'::jsonb, 'Almeida Livre'),
  ('Nm', 20, 'en', '[{"numero": 1, "texto": "Then came the children of Israel, even the whole congregation, into the desert of Zin in the first month: and the people abode in Kadesh; and Miriam died there, and was buried there."}, {"numero": 2, "texto": "And there was no water for the congregation: and they gathered themselves together against Moses and against Aaron."}, {"numero": 3, "texto": "And the people chode with Moses, and spake, saying, Would God that we had died when our brethren died before the Lord!"}, {"numero": 4, "texto": "And why have ye brought up the congregation of the Lord into this wilderness, that we and our cattle should die there?"}, {"numero": 5, "texto": "And wherefore have ye made us to come up out of Egypt, to bring us in unto this evil place? it is no place of seed, or of figs, or of vines, or of pomegranates; neither is there any water to drink."}, {"numero": 6, "texto": "And Moses and Aaron went from the presence of the assembly unto the door of the tabernacle of the congregation, and they fell upon their faces: and the glory of the Lord appeared unto them."}, {"numero": 7, "texto": "And the Lord spake unto Moses, saying,"}, {"numero": 8, "texto": "Take the rod, and gather thou the assembly together, thou, and Aaron thy brother, and speak ye unto the rock before their eyes; and it shall give forth his water, and thou shalt bring forth to them water out of the rock: so thou shalt give the congregation and their beasts drink."}, {"numero": 9, "texto": "And Moses took the rod from before the Lord, as he commanded him."}, {"numero": 10, "texto": "And Moses and Aaron gathered the congregation together before the rock, and he said unto them, Hear now, ye rebels; must we fetch you water out of this rock?"}, {"numero": 11, "texto": "And Moses lifted up his hand, and with his rod he smote the rock twice: and the water came out abundantly, and the congregation drank, and their beasts also."}, {"numero": 12, "texto": "And the Lord spake unto Moses and Aaron, Because ye believed me not, to sanctify me in the eyes of the children of Israel, therefore ye shall not bring this congregation into the land which I have given them."}, {"numero": 13, "texto": "This is the water of Meribah; because the children of Israel strove with the Lord, and he was sanctified in them."}, {"numero": 14, "texto": "And Moses sent messengers from Kadesh unto the king of Edom, Thus saith thy brother Israel, Thou knowest all the travail that hath befallen us:"}, {"numero": 15, "texto": "How our fathers went down into Egypt, and we have dwelt in Egypt a long time; and the Egyptians vexed us, and our fathers:"}, {"numero": 16, "texto": "And when we cried unto the Lord, he heard our voice, and sent an angel, and hath brought us forth out of Egypt: and, behold, we are in Kadesh, a city in the uttermost of thy border:"}, {"numero": 17, "texto": "Let us pass, I pray thee, through thy country: we will not pass through the fields, or through the vineyards, neither will we drink of the water of the wells: we will go by the king''s high way, we will not turn to the right hand nor to the left, until we have passed thy borders."}, {"numero": 18, "texto": "And Edom said unto him, Thou shalt not pass by me, lest I come out against thee with the sword."}, {"numero": 19, "texto": "And the children of Israel said unto him, We will go by the high way: and if I and my cattle drink of thy water, then I will pay for it: I will only, without doing anything else, go through on my feet."}, {"numero": 20, "texto": "And he said, Thou shalt not go through. And Edom came out against him with much people, and with a strong hand."}, {"numero": 21, "texto": "Thus Edom refused to give Israel passage through his border: wherefore Israel turned away from him."}, {"numero": 22, "texto": "And the children of Israel, even the whole congregation, journeyed from Kadesh, and came unto mount Hor."}, {"numero": 23, "texto": "And the Lord spake unto Moses and Aaron in mount Hor, by the coast of the land of Edom, saying,"}, {"numero": 24, "texto": "Aaron shall be gathered unto his people: for he shall not enter into the land which I have given unto the children of Israel, because ye rebelled against my word at the water of Meribah."}, {"numero": 25, "texto": "Take Aaron and Eleazar his son, and bring them up unto mount Hor:"}, {"numero": 26, "texto": "And strip Aaron of his garments, and put them upon Eleazar his son: and Aaron shall be gathered unto his people, and shall die there."}, {"numero": 27, "texto": "And Moses did as the Lord commanded: and they went up into mount Hor in the sight of all the congregation."}, {"numero": 28, "texto": "And Moses stripped Aaron of his garments, and put them upon Eleazar his son; and Aaron died there in the top of the mount: and Moses and Eleazar came down from the mount."}, {"numero": 29, "texto": "And when all the congregation saw that Aaron was dead, they mourned for Aaron thirty days, even all the house of Israel."}]'::jsonb, 'King James Version'),
  ('Nm', 20, 'fr', '[{"numero": 1, "texto": "Toute l''''assemblée des enfants d''''Israël arriva dans le désert de Tsin le premier mois, et le peuple s''''arrêta à Kadès. C''''est là que mourut Marie, et qu''''elle fut enterrée."}, {"numero": 2, "texto": "Il n''''y avait point d''''eau pour l''''assemblée; et l''''on se souleva contre Moïse et Aaron."}, {"numero": 3, "texto": "Le peuple chercha querelle à Moïse. Ils dirent: Que n''''avons-nous expiré, quand nos frères expirèrent devant l''''Eternel?"}, {"numero": 4, "texto": "Pourquoi avez-vous fait venir l''''assemblée de l''''Eternel dans ce désert, pour que nous y mourions, nous et notre bétail?"}, {"numero": 5, "texto": "Pourquoi nous avez-vous fait monter hors d''''Egypte, pour nous amener dans ce méchant lieu? Ce n''''est pas un lieu où l''''on puisse semer, et il n''''y a ni figuier, ni vigne, ni grenadier, ni d''''eau à boire."}, {"numero": 6, "texto": "Moïse et Aaron s''''éloignèrent de l''''assemblée pour aller à l''''entrée de la tente d''''assignation. Ils tombèrent sur leur visage; et la gloire de l''''Eternel leur apparut."}, {"numero": 7, "texto": "L''''Eternel parla à Moïse, et dit:"}, {"numero": 8, "texto": "Prends la verge, et convoque l''''assemblée, toi et ton frère Aaron. Vous parlerez en leur présence au rocher, et il donnera ses eaux; tu feras sortir pour eux de l''''eau du rocher, et tu abreuveras l''''assemblée et leur bétail."}, {"numero": 9, "texto": "Moïse prit la verge qui était devant l''''Eternel, comme l''''Eternel le lui avait ordonné."}, {"numero": 10, "texto": "Moïse et Aaron convoquèrent l''''assemblée en face du rocher. Et Moïse leur dit: Ecoutez donc, rebelles! Est-ce de ce rocher que nous vous ferons sortir de l''''eau?"}, {"numero": 11, "texto": "Puis Moïse leva la main et frappa deux fois le rocher avec sa verge. Il sortit de l''''eau en abondance. L''''assemblée but, et le bétail aussi."}, {"numero": 12, "texto": "Alors l''''Eternel dit à Moïse et à Aaron: Parce que vous n''''avez pas cru en moi, pour me sanctifier aux yeux des enfants d''''Israël, vous ne ferez point entrer cette assemblée dans le pays que je lui donne."}, {"numero": 13, "texto": "Ce sont les eaux de Meriba, où les enfants d''''Israël contestèrent avec l''''Eternel, qui fut sanctifié en eux."}, {"numero": 14, "texto": "De Kadès, Moïse envoya des messagers au roi d''''Edom, pour lui dire: Ainsi parle ton frère Israël: Tu sais toutes les souffrances que nous avons éprouvées."}, {"numero": 15, "texto": "Nos pères descendirent en Egypte, et nous y demeurâmes longtemps. Mais les Egyptiens nous ont maltraités, nous et nos pères."}, {"numero": 16, "texto": "Nous avons crié à l''''Eternel, et il a entendu notre voix. Il a envoyé un ange, et nous a fait sortir de l''''Egypte. Et voici, nous sommes à Kadès, ville à l''''extrémité de ton territoire."}, {"numero": 17, "texto": "Laisse-nous passer par ton pays; nous ne traverserons ni les champs, ni les vignes, et nous ne boirons pas l''''eau des puits; nous suivrons la route royale, sans nous détourner à droite ou à gauche, jusqu''''à ce que nous ayons franchi ton territoire."}, {"numero": 18, "texto": "Edom lui dit: Tu ne passeras point chez moi, sinon je sortirai à ta rencontre avec l''''épée."}, {"numero": 19, "texto": "Les enfants d''''Israël lui dirent: Nous monterons par la grande route; et, si nous buvons de ton eau, moi et mes troupeaux, j''''en paierai le prix; je ne ferai que passer avec mes pieds, pas autre chose."}, {"numero": 20, "texto": "Il répondit: Tu ne passeras pas! Et Edom sortit à sa rencontre avec un peuple nombreux et à main forte."}, {"numero": 21, "texto": "Ainsi Edom refusa de donner passage à Israël par son territoire. Et Israël se détourna de lui."}, {"numero": 22, "texto": "Toute l''''assemblée des enfants d''''Israël partit de Kadès, et arriva à la montagne de Hor."}, {"numero": 23, "texto": "L''''Eternel dit à Moïse et à Aaron, vers la montagne de Hor, sur la frontière du pays d''''Edom:"}, {"numero": 24, "texto": "Aaron va être recueilli auprès de son peuple; car il n''''entrera point dans le pays que je donne aux enfants d''''Israël, parce que vous avez été rebelles à mon ordre, aux eaux de Meriba."}, {"numero": 25, "texto": "Prends Aaron et son fils Eléazar, et fais-les monter sur la montagne de Hor."}, {"numero": 26, "texto": "Dépouille Aaron de ses vêtements, et fais-les revêtir à Eléazar, son fils. C''''est là qu''''Aaron sera recueilli et qu''''il mourra."}, {"numero": 27, "texto": "Moïse fit ce que l''''Eternel avait ordonné. Ils montèrent sur la montagne de Hor, aux yeux de toute l''''assemblée."}, {"numero": 28, "texto": "Moïse dépouilla Aaron de ses vêtements, et les fit revêtir à Eléazar, son fils. Aaron mourut là, au sommet de la montagne. Moïse et Eléazar descendirent de la montagne."}, {"numero": 29, "texto": "Toute l''''assemblée vit qu''''Aaron avait expiré, et toute la maison d''''Israël pleura Aaron pendant trente jours."}]'::jsonb, 'Louis Segond 1910'),
  ('Nm', 20, 'es', '[{"numero": 1, "texto": "Y LLEGARON los hijos de Israel, toda la congregación, al desierto de Zin, en el mes primero, y asentó el pueblo en Cades; y allí murió María, y fué allí sepultada."}, {"numero": 2, "texto": "Y como no hubiese agua para la congregación, juntáronse contra Moisés y Aarón."}, {"numero": 3, "texto": "Y regañó el pueblo con Moisés, y hablaron diciendo: ¡Ojalá que nosotros hubiéramos muerto cuando perecieron nuestros hermanos delante de Jehová!"}, {"numero": 4, "texto": "¿Y por qué hiciste venir la congregación de Jehová á este desierto, para que muramos aquí nosotros y nuestras bestias?"}, {"numero": 5, "texto": "¿Y por qué nos has hecho subir de Egipto, para traernos á este mal lugar? No es lugar de sementera, de higueras, de viñas, ni granadas: ni aun de agua para beber."}, {"numero": 6, "texto": "Y fuéronse Moisés y Aarón de delante de la congregación á la puerta del tabernáculo del testimonio, y echáronse sobre sus rostros; y la gloria de Jehová apareció sobre ellos."}, {"numero": 7, "texto": "Y habló Jehová á Moisés, diciendo:"}, {"numero": 8, "texto": "Toma la vara, y reune la congregación, tú y Aarón tu hermano, y hablad á la peña en ojos de ellos; y ella dará su agua, y les sacarás aguas de la peña, y darás de beber á la congregación, y á sus bestias."}, {"numero": 9, "texto": "Entonces Moisés tomó la vara de delante de Jehová, como él le mandó."}, {"numero": 10, "texto": "Y juntaron Moisés y Aarón la congregación delante de la peña, y díjoles: Oid ahora, rebeldes: ¿os hemos de hacer salir aguas de esta peña?"}, {"numero": 11, "texto": "Entonces alzó Moisés su mano, é hirió la peña con su vara dos veces: y salieron muchas aguas, y bebió la congregación, y sus bestias."}, {"numero": 12, "texto": "Y Jehová dijo á Moisés y á Aarón: Por cuanto no creísteis en mí, para santificarme en ojos de los hijos de Israel, por tanto, no meteréis esta congregación en la tierra que les he dado."}, {"numero": 13, "texto": "Estas son las aguas de la rencilla, por las cuales contendieron los hijos de Israel con Jehová, y él se santificó en ellos."}, {"numero": 14, "texto": "Y envió Moisés embajadores al rey de Edom desde Cades: Así dice Israel tu hermano: Tú has sabido todo el trabajo que nos ha venido:"}, {"numero": 15, "texto": "Cómo nuestros padres descendieron á Egipto, y estuvimos en Egipto largo tiempo, y los Egipcios nos maltrataron, y á nuestros padres;"}, {"numero": 16, "texto": "Y clamamos á Jehová, el cual oyó nuestra voz, y envió ángel, y sacónos de Egipto; y he aquí estamos en Cades, ciudad al extremo de tus confines:"}, {"numero": 17, "texto": "Rogámoste que pasemos por tu tierra; no pasaremos por labranza, ni por viña, ni beberemos agua de pozos: por el camino real iremos, sin apartarnos á la diestra ni á la siniestra, hasta que hayamos pasado tu término."}, {"numero": 18, "texto": "Y Edom le respondió: No pasarás por mi país, de otra manera saldré contra ti armado."}, {"numero": 19, "texto": "Y los hijos de Israel dijeron: Por el camino seguido iremos; y si bebiéremos tus aguas yo y mis ganados, daré el precio de ellas: ciertamente sin hacer otra cosa, pasaré de seguida."}, {"numero": 20, "texto": "Y él respondió: No pasarás. Y salió Edom contra él con mucho pueblo, y mano fuerte."}, {"numero": 21, "texto": "No quiso, pues, Edom dejar pasar á Israel por su término, y apartóse Israel de él."}, {"numero": 22, "texto": "Y partidos de Cades los hijos de Israel, toda aquella congregación, vinieron al monte de Hor."}, {"numero": 23, "texto": "Y Jehová habló á Moisés y Aarón en el monte de Hor, en los confines de la tierra de Edom, diciendo:"}, {"numero": 24, "texto": "Aarón será reunido á sus pueblos; pues no entrará en la tierra que yo di á los hijos de Israel, por cuanto fuisteis rebeldes á mi mandamiento en las aguas de la rencilla."}, {"numero": 25, "texto": "Toma á Aarón y á Eleazar su hijo, y hazlos subir al monte de Hor;"}, {"numero": 26, "texto": "Y haz desnudar á Aarón sus vestidos, y viste de ellos á Eleazar su hijo; porque Aarón será reunido á sus pueblos, y allí morirá."}, {"numero": 27, "texto": "Y Moisés hizo como Jehová le mandó: y subieron al monte de Hor á ojos de toda la congregación."}, {"numero": 28, "texto": "Y Moisés hizo desnudar á Aarón de sus vestidos y vistiólos á Eleazar su hijo: y Aarón murió allí en la cumbre del monte: y Moisés y Eleazar descendieron del monte."}, {"numero": 29, "texto": "Y viendo toda la congregación que Aarón era muerto, hiciéronle duelo por treinta días todas las familias de Israel."}]'::jsonb, 'Reina-Valera 1909'),
  ('Nm', 21, 'pt', '[{"numero": 1, "texto": "E quando o cananeu, o rei de Arade, que habitava ao sul, ouviu falar que Israel vinha pelo caminho de Atarim, lutou contra Israel, e dele levou alguns como prisioneiros."}, {"numero": 2, "texto": "Então Israel fez voto ao SENHOR, e disse: Se com efeito entregares a este povo em minha mão, eu destruirei suas cidades."}, {"numero": 3, "texto": "E o SENHOR escutou a voz de Israel, e entregou aos cananeus, e destruiu-os a eles e a suas cidades; e chamou o nome daquele lugar Hormá."}, {"numero": 4, "texto": "E partiram do monte de Hor, caminho do mar Vermelho, para rodear a terra de Edom; e abateu-se o ânimo do povo pelo caminho."}, {"numero": 5, "texto": "E falou o povo contra Deus e Moisés: Por que nos fizeste subir do Egito para que morrêssemos neste deserto? que nem há pão, nem água, e nossa alma tem ódio deste pão tão miserável."}, {"numero": 6, "texto": "E o SENHOR enviou entre o povo serpentes ardentes, que mordiam ao povo: e morreu muito povo de Israel."}, {"numero": 7, "texto": "Então o povo veio a Moisés, e disseram: Pecado temos por haver falado contra o SENHOR, e contra ti: roga ao SENHOR que tire de nós estas serpentes. E Moisés orou pelo povo."}, {"numero": 8, "texto": "E o SENHOR disse a Moisés: Faze-te uma serpente ardente, e põe-a sobre a haste: e será que qualquer um que for mordido e olhar a ela, viverá."}, {"numero": 9, "texto": "E Moisés fez uma serpente de bronze, e a pôs sobre a haste, e foi, que quando alguma serpente mordia a algum, olhava à serpente de bronze, e vivia."}, {"numero": 10, "texto": "E partiram os filhos de Israel, e assentaram acampamento em Obote."}, {"numero": 11, "texto": "E partidos de Obote, assentaram em Ijé-Abarim, no deserto que está diante de Moabe, ao oriente."}, {"numero": 12, "texto": "Partidos dali, assentaram no vale de Zerede."}, {"numero": 13, "texto": "De ali moveram, e assentaram da outra parte de Arnom, que está no deserto, e que sai do termo dos amorreus; porque Arnom é termo de Moabe, entre Moabe e os amorreus."}, {"numero": 14, "texto": "Por isso se diz no livro das batalhas do SENHOR: Vaebe em Sufa, e nos ribeiros de Arnom:"}, {"numero": 15, "texto": "E à corrente dos ribeiros que vai a parar em Ar, e descansa no termo de Moabe."}, {"numero": 16, "texto": "E dali vieram a Beer: este é o poço do qual o SENHOR disse a Moisés: Junta ao povo, e lhes darei água."}, {"numero": 17, "texto": "Então cantou Israel esta canção: Sobe, ó poço; a ele cantai:"}, {"numero": 18, "texto": "Poço, o qual cavaram os senhores; Cavaram-no os príncipes do povo, E o legislador, com seus bordões. E do deserto [partiram] para Matana."}, {"numero": 19, "texto": "E de Mataná a Naaliel: e de Naaliel a Bamote:"}, {"numero": 20, "texto": "E de Bamote ao vale que está nos campos de Moabe, e ao cume de Pisga, que está voltado a Jesimom."}, {"numero": 21, "texto": "E enviou Israel embaixadores a Seom, rei dos amorreus, dizendo:"}, {"numero": 22, "texto": "Deixa-me passar por tua terra: não nos desviaremos pelos campos, nem pelas vinhas; não beberemos as águas dos poços; pelo caminho real iremos, até que passemos os teus termos."}, {"numero": 23, "texto": "Mas Seom não deixou passar a Israel por seus termos: antes juntou Seom todo seu povo, e saiu contra Israel no deserto: e veio a Jaza, e lutou contra Israel."}, {"numero": 24, "texto": "Mas Israel o feriu a fio de espada, e tomou sua terra desde Arnom até Jaboque, até os filhos de Amom: porque o termo dos filhos de Amom era forte."}, {"numero": 25, "texto": "E tomou Israel todas estas cidades: e habitou Israel em todas as cidades dos amorreus, em Hesbom e em todas suas aldeias."}, {"numero": 26, "texto": "Porque Hesbom era a cidade de Seom, rei dos amorreus; o qual havia tido guerra antes com o rei de Moabe, e tomado de seu poder toda a sua terra até Arnom."}, {"numero": 27, "texto": "Portanto, dizem os proverbistas: Vinde a Hesbom, Edifique-se e repare-se a cidade de Seom:"}, {"numero": 28, "texto": "Que fogo saiu de Hesbom, E chama da cidade de Seom, E consumiu a Ar de Moabe, aos senhores dos altos de Arnom."}, {"numero": 29, "texto": "Ai de ti, Moabe! Pereceste, povo de Camos: Pôs seus filhos em fuga, E suas filhas em cativeiro, por Seom rei dos amorreus."}, {"numero": 30, "texto": "Mas devastamos o reino deles; pereceu Hesbom até Dibom, E destruímos até Nofá e Medeba."}, {"numero": 31, "texto": "Assim habitou Israel na terra dos amorreus."}, {"numero": 32, "texto": "E enviou Moisés a reconhecer a Jazer; e tomaram suas aldeias, e expulsaram aos amorreus que estavam ali."}, {"numero": 33, "texto": "E voltaram, e subiram caminho de Basã. E Ogue, rei de Basã, ele e todo o seu povo, saíram contra eles, para lutar em Edrei."}, {"numero": 34, "texto": "Então o SENHOR disse a Moisés: Não tenhas medo dele, que em tua mão o dei, a o e a todo seu povo, e a sua terra; e farás dele como fizeste de Seom, rei dos amorreus, que habitava em Hesbom."}, {"numero": 35, "texto": "E feriram a ele, e a seus filhos, e a toda sua gente, sem que lhe restasse um, e possuíram sua terra."}]'::jsonb, 'Almeida Livre'),
  ('Nm', 21, 'en', '[{"numero": 1, "texto": "And when king Arad the Canaanite, which dwelt in the south, heard tell that Israel came by the way of the spies; then he fought against Israel, and took some of them prisoners."}, {"numero": 2, "texto": "And Israel vowed a vow unto the Lord, and said, If thou wilt indeed deliver this people into my hand, then I will utterly destroy their cities."}, {"numero": 3, "texto": "And the Lord hearkened to the voice of Israel, and delivered up the Canaanites; and they utterly destroyed them and their cities: and he called the name of the place Hormah."}, {"numero": 4, "texto": "And they journeyed from mount Hor by the way of the Red sea, to compass the land of Edom: and the soul of the people was much discouraged because of the way."}, {"numero": 5, "texto": "And the people spake against God, and against Moses, Wherefore have ye brought us up out of Egypt to die in the wilderness? for there is no bread, neither is there any water; and our soul loatheth this light bread."}, {"numero": 6, "texto": "And the Lord sent fiery serpents among the people, and they bit the people; and much people of Israel died."}, {"numero": 7, "texto": "Therefore the people came to Moses, and said, We have sinned, for we have spoken against the Lord, and against thee; pray unto the Lord, that he take away the serpents from us. And Moses prayed for the people."}, {"numero": 8, "texto": "And the Lord said unto Moses, Make thee a fiery serpent, and set it upon a pole: and it shall come to pass, that every one that is bitten, when he looketh upon it, shall live."}, {"numero": 9, "texto": "And Moses made a serpent of brass, and put it upon a pole, and it came to pass, that if a serpent had bitten any man, when he beheld the serpent of brass, he lived."}, {"numero": 10, "texto": "And the children of Israel set forward, and pitched in Oboth."}, {"numero": 11, "texto": "And they journeyed from Oboth, and pitched at Ijeabarim, in the wilderness which is before Moab, toward the sunrising."}, {"numero": 12, "texto": "From thence they removed, and pitched in the valley of Zared."}, {"numero": 13, "texto": "From thence they removed, and pitched on the other side of Arnon, which is in the wilderness that cometh out of the coasts of the Amorites: for Arnon is the border of Moab, between Moab and the Amorites."}, {"numero": 14, "texto": "Wherefore it is said in the book of the wars of the Lord, What he did in the Red sea, and in the brooks of Arnon,"}, {"numero": 15, "texto": "And at the stream of the brooks that goeth down to the dwelling of Ar, and lieth upon the border of Moab."}, {"numero": 16, "texto": "And from thence they went to Beer: that is the well whereof the Lord spake unto Moses, Gather the people together, and I will give them water."}, {"numero": 17, "texto": "Then Israel sang this song, Spring up, O well; sing ye unto it:"}, {"numero": 18, "texto": "The princes digged the well, the nobles of the people digged it, by the direction of the lawgiver, with their staves. And from the wilderness they went to Mattanah:"}, {"numero": 19, "texto": "And from Mattanah to Nahaliel: and from Nahaliel to Bamoth:"}, {"numero": 20, "texto": "And from Bamoth in the valley, that is in the country of Moab, to the top of Pisgah, which looketh toward Jeshimon."}, {"numero": 21, "texto": "And Israel sent messengers unto Sihon king of the Amorites, saying,"}, {"numero": 22, "texto": "Let me pass through thy land: we will not turn into the fields, or into the vineyards; we will not drink of the waters of the well: but we will go along by the king''s high way, until we be past thy borders."}, {"numero": 23, "texto": "And Sihon would not suffer Israel to pass through his border: but Sihon gathered all his people together, and went out against Israel into the wilderness: and he came to Jahaz, and fought against Israel."}, {"numero": 24, "texto": "And Israel smote him with the edge of the sword, and possessed his land from Arnon unto Jabbok, even unto the children of Ammon: for the border of the children of Ammon was strong."}, {"numero": 25, "texto": "And Israel took all these cities: and Israel dwelt in all the cities of the Amorites, in Heshbon, and in all the villages thereof."}, {"numero": 26, "texto": "For Heshbon was the city of Sihon the king of the Amorites, who had fought against the former king of Moab, and taken all his land out of his hand, even unto Arnon."}, {"numero": 27, "texto": "Wherefore they that speak in proverbs say, Come into Heshbon, let the city of Sihon be built and prepared:"}, {"numero": 28, "texto": "For there is a fire gone out of Heshbon, a flame from the city of Sihon: it hath consumed ar of Moab, and the lords of the high places of Arnon."}, {"numero": 29, "texto": "Woe to thee, Moab! thou art undone, O people of Chemosh: he hath given his sons that escaped, and his daughters, into captivity unto Sihon king of the Amorites."}, {"numero": 30, "texto": "We have shot at them; Heshbon is perished even unto Dibon, and we have laid them waste even unto Nophah, which reacheth unto Medeba."}, {"numero": 31, "texto": "Thus Israel dwelt in the land of the Amorites."}, {"numero": 32, "texto": "And Moses sent to spy out Jaazer, and they took the villages thereof, and drove out the Amorites that were there."}, {"numero": 33, "texto": "And they turned and went up by the way of Bashan: and og the king of bashan went out against them, he, and all his people, to the battle at edrei."}, {"numero": 34, "texto": "And the Lord said unto Moses, Fear him not: for I have delivered him into thy hand, and all his people, and his land; and thou shalt do to him as thou didst unto Sihon king of the Amorites, which dwelt at Heshbon."}, {"numero": 35, "texto": "So they smote him, and his sons, and all his people, until there was none left him alive: and they possessed his land."}]'::jsonb, 'King James Version'),
  ('Nm', 21, 'fr', '[{"numero": 1, "texto": "Le roi d''''Arad, Cananéen, qui habitait le midi, apprit qu''''Israël venait par le chemin d''''Atharim. Il combattit Israël, et emmena des prisonniers."}, {"numero": 2, "texto": "Alors Israël fit un voeu à l''''Eternel, et dit: Si tu livres ce peuple entre mes mains, je dévouerai ses villes par interdit."}, {"numero": 3, "texto": "L''''Eternel entendit la voix d''''Israël, et livra les Cananéens. On les dévoua par interdit, eux et leurs villes; et l''''on nomma ce lieu Horma."}, {"numero": 4, "texto": "Ils partirent de la montagne de Hor par le chemin de la mer Rouge, pour contourner le pays d''''Edom. Le peuple s''''impatienta en route,"}, {"numero": 5, "texto": "et parla contre Dieu et contre Moïse: Pourquoi nous avez-vous fait monter hors d''''Egypte, pour que nous mourions dans le désert? car il n''''y a point de pain, et il n''''y a point d''''eau, et notre âme est dégoûtée de cette misérable nourriture."}, {"numero": 6, "texto": "Alors l''''Eternel envoya contre le peuple des serpents brûlants; ils mordirent le peuple, et il mourut beaucoup de gens en Israël."}, {"numero": 7, "texto": "Le peuple vint à Moïse, et dit: Nous avons péché, car nous avons parlé contre l''''Eternel et contre toi. Prie l''''Eternel, afin qu''''il éloigne de nous ces serpents. Moïse pria pour le peuple."}, {"numero": 8, "texto": "L''''Eternel dit à Moïse: Fais-toi un serpent brûlant, et place-le sur une perche; quiconque aura été mordu, et le regardera, conservera la vie."}, {"numero": 9, "texto": "Moïse fit un serpent d''''airain, et le plaça sur une perche; et quiconque avait été mordu par un serpent, et regardait le serpent d''''airain, conservait la vie."}, {"numero": 10, "texto": "Les enfants d''''Israël partirent, et ils campèrent à Oboth."}, {"numero": 11, "texto": "Ils partirent d''''Oboth et ils campèrent à Ijjé-Abarim, dans le désert qui est vis-à-vis de Moab, vers le soleil levant."}, {"numero": 12, "texto": "De là ils partirent, et ils campèrent dans la vallée de Zéred."}, {"numero": 13, "texto": "De là ils partirent, et ils campèrent de l''''autre côté de l''''Arnon, qui coule dans le désert en sortant du territoire des Amoréens; car l''''Arnon est la frontière de Moab, entre Moab et les Amoréens."}, {"numero": 14, "texto": "C''''est pourquoi il est dit dans le livre des Guerres de l''''Eternel: ...Vaheb en Supha, et les torrents de l''''Arnon,"}, {"numero": 15, "texto": "et le cours des torrents, qui s''''étend du côté d''''Ar et touche à la frontière de Moab."}, {"numero": 16, "texto": "De là ils allèrent à Beer. C''''est ce Beer, où l''''Eternel dit à Moïse: Rassemble le peuple, et je leur donnerai de l''''eau."}, {"numero": 17, "texto": "Alors Israël chanta ce cantique: Monte, puits! Chantez en son honneur!"}, {"numero": 18, "texto": "Puits, que des princes ont creusé, Que les grands du peuple ont creusé, Avec le sceptre, avec leurs bâtons! Du désert ils allèrent à Matthana;"}, {"numero": 19, "texto": "de Matthana, à Nahaliel; de Nahaliel, à Bamoth;"}, {"numero": 20, "texto": "de Bamoth, à la vallée qui est dans le territoire de Moab, au sommet du Pisga, en regard du désert."}, {"numero": 21, "texto": "Israël envoya des messagers à Sihon, roi des Amoréens, pour lui dire:"}, {"numero": 22, "texto": "Laisse-moi passer par ton pays; nous n''''entrerons ni dans les champs, ni dans les vignes, et nous ne boirons pas l''''eau des puits; nous suivrons la route royale, jusqu''''à ce que nous ayons franchi ton territoire."}, {"numero": 23, "texto": "Sihon n''''accorda point à Israël le passage sur son territoire; il rassembla tout son peuple, et sortit à la rencontre d''''Israël, dans le désert; il vint à Jahats, et combattit Israël."}, {"numero": 24, "texto": "Israël le frappa du tranchant de l''''épée et s''''empara de son pays depuis l''''Arnon jusqu''''au Jabbok, jusqu''''à la frontière des enfants d''''Ammon; car la frontière des enfants d''''Ammon était fortifiée."}, {"numero": 25, "texto": "Israël prit toutes les villes, et s''''établit dans toutes les villes des Amoréens, à Hesbon et dans toutes les villes de son ressort."}, {"numero": 26, "texto": "Car Hesbon était la ville de Sihon, roi des Amoréens; il avait fait la guerre au précédent roi de Moab, et lui avait enlevé tout son pays jusqu''''à l''''Arnon."}, {"numero": 27, "texto": "C''''est pourquoi les poètes disent: Venez à Hesbon! Que la ville de Sihon soit rebâtie et fortifiée!"}, {"numero": 28, "texto": "Car il est sorti un feu de Hesbon, Une flamme de la ville de Sihon; Elle a dévoré Ar-Moab, Les habitants des hauteurs de l''''Arnon."}, {"numero": 29, "texto": "Malheur à toi, Moab! Tu es perdu, peuple de Kemosch! Il a fait de ses fils des fuyards, Et il a livré ses filles captives A Sihon, roi des Amoréens."}, {"numero": 30, "texto": "Nous avons lancé sur eux nos traits: De Hesbon à Dibon tout est détruit; Nous avons étendu nos ravages jusqu''''à Nophach, Jusqu''''à Médeba."}, {"numero": 31, "texto": "Israël s''''établit dans le pays des Amoréens."}, {"numero": 32, "texto": "Moïse envoya reconnaître Jaezer; et ils prirent les villes de son ressort, et chassèrent les Amoréens qui y étaient."}, {"numero": 33, "texto": "Ils changèrent ensuite de direction, et montèrent par le chemin de Basan. Og, roi de Basan, sortit à leur rencontre, avec tout son peuple, pour les combattre à Edréi."}, {"numero": 34, "texto": "L''''Eternel dit à Moïse: Ne le crains point; car je le livre entre tes mains, lui et tout son peuple, et son pays; tu le traiteras comme tu as traité Sihon, roi des Amoréens, qui habitait à Hesbon."}, {"numero": 35, "texto": "Et ils le battirent, lui et ses fils, et tout son peuple, sans en laisser échapper un seul, et ils s''''emparèrent de son pays."}]'::jsonb, 'Louis Segond 1910'),
  ('Nm', 21, 'es', '[{"numero": 1, "texto": "Y OYENDO el Cananeo, el rey de Arad, el cual habitaba al mediodía, que venía Israel por el camino de los centinelas, peleó con Israel, y tomó de él presa."}, {"numero": 2, "texto": "Entonces Israel hizo voto á Jehová, y dijo: Si en efecto entregares á este pueblo en mi mano, yo destruiré sus ciudades."}, {"numero": 3, "texto": "Y Jehová escuchó la voz de Israel, y entregó al Cananeo, y destruyólos á ellos y á sus ciudades; y llamó el nombre de aquel lugar Horma."}, {"numero": 4, "texto": "Y partieron del monte de Hor, camino del mar Bermejo, para rodear la tierra de Edom; y abatióse el ánimo del pueblo por el camino."}, {"numero": 5, "texto": "Y habló el pueblo contra Dios y Moisés: ¿Por qué nos hiciste subir de Egipto para que muramos en este desierto? que ni hay pan, ni agua, y nuestra alma tiene fastidio de este pan tan liviano."}, {"numero": 6, "texto": "Y Jehová envió entre el pueblo serpientes ardientes, que mordían al pueblo: y murió mucho pueblo de Israel."}, {"numero": 7, "texto": "Entonces el pueblo vino á Moisés, y dijeron: Pecado hemos por haber hablado contra Jehová, y contra ti: ruega á Jehová que quite de nosotros estas serpientes. Y Moisés oró por el pueblo."}, {"numero": 8, "texto": "Y Jehová dijo á Moisés: Hazte una serpiente ardiente, y ponla sobre la bandera: y será que cualquiera que fuere mordido y mirare á ella, vivirá."}, {"numero": 9, "texto": "Y Moisés hizo una serpiente de metal, y púsola sobre la bandera: y fué, que cuando alguna serpiente mordía á alguno, miraba á la serpiente de metal, y vivía."}, {"numero": 10, "texto": "Y partieron los hijos de Israel, y asentaron campo en Oboth."}, {"numero": 11, "texto": "Y partidos de Oboth, asentaron en Ije-abarim, en el desierto que está delante de Moab, al nacimiento del sol."}, {"numero": 12, "texto": "Partidos de allí, asentaron en la arroyada de Zared."}, {"numero": 13, "texto": "De allí movieron, y asentaron de la otra parte de Arnón, que está en el desierto, y que sale del término del Amorrheo; porque Arnón es término de Moab, entre Moab y el Amorrheo."}, {"numero": 14, "texto": "Por tanto se dice en el libro de las batallas de Jehová: Lo que hizo en el mar Bermejo, y en los arroyos de Arnón:"}, {"numero": 15, "texto": "Y á la corriente de los arroyos que va á parar en Ar, y descansa en el término de Moab."}, {"numero": 16, "texto": "Y de allí vinieron á Beer: este es el pozo del cual Jehová dijo á Moisés: Junta el pueblo, y les daré agua."}, {"numero": 17, "texto": "Entonces cantó Israel esta canción: Sube, oh pozo; á él cantad:"}, {"numero": 18, "texto": "Pozo, el cual cavaron los señores; caváronlo los príncipes del pueblo, y el legislador, con sus bordones. Y del desierto vinieron á Mathana:"}, {"numero": 19, "texto": "Y de Mathana á Nahaliel: y de Nahaliel á Bamoth:"}, {"numero": 20, "texto": "Y de Bamoth al valle que está en los campos de Moab, y á la cumbre de Pisga, que mira á Jesimón."}, {"numero": 21, "texto": "Y envió Israel embajadores á Sehón, rey de los Amorrheos, diciendo:"}, {"numero": 22, "texto": "Pasaré por tu tierra: no nos apartaremos por los labrados, ni por las viñas; no beberemos las aguas de los pozos: por el camino real iremos, hasta que pasemos tu término."}, {"numero": 23, "texto": "Mas Sehón no dejó pasar á Israel por su término: antes juntó Sehón todo su pueblo, y salió contra Israel en el desierto: y vino á Jahaz, y peleó contra Israel."}, {"numero": 24, "texto": "E hirióle Israel á filo de espada, y tomó su tierra desde Arnón hasta Jaboc, hasta los hijos de Ammón: porque el término de los hijos de Ammón era fuerte."}, {"numero": 25, "texto": "Y tomó Israel todas estas ciudades: y habitó Israel en todas las ciudades del Amorrheo, en Hesbón y en todas sus aldeas."}, {"numero": 26, "texto": "Porque Hesbón era la ciudad de Sehón, rey de los Amorrheos; el cual había tenido guerra antes con el rey de Moab, y tomado de su poder toda su tierra hasta Arnón."}, {"numero": 27, "texto": "Por tanto, dicen los proverbistas: Venid á Hesbón, edifíquese y repárese la ciudad de Sehón:"}, {"numero": 28, "texto": "Que fuego salió de Hesbón, y llama de la ciudad de Sehón, y consumió á Ar de Moab, á los señores de los altos de Arnón."}, {"numero": 29, "texto": "¡Ay de ti, Moab! Perecido has, pueblo de Chêmos: puso sus hijos en huída, y sus hijas en cautividad, por Sehón rey de los Amorrheos."}, {"numero": 30, "texto": "Mas devastamos el reino de ellos; pereció Hesbón hasta Dibón, y destruimos hasta Nopha y Medeba."}, {"numero": 31, "texto": "Así habitó Israel en la tierra del Amorrheo."}, {"numero": 32, "texto": "Y envió Moisés á reconocer á Jazer; y tomaron sus aldeas, y echaron al Amorrheo que estaba allí."}, {"numero": 33, "texto": "Y volvieron, y subieron camino de Basán, y salió contra ellos Og rey de Basán, él y todo su pueblo, para pelear en Edrei."}, {"numero": 34, "texto": "Entonces Jehová dijo á Moisés: No le tengas miedo, que en tu mano lo he dado, á él y á todo su pueblo, y á su tierra; y harás de él como hiciste de Sehón, rey de los Amorrheos, que habitaba en Hesbón."}, {"numero": 35, "texto": "E hirieron á él, y á sus hijos, y á toda su gente, sin que le quedara uno, y poseyeron su tierra."}]'::jsonb, 'Reina-Valera 1909'),
  ('Nm', 22, 'pt', '[{"numero": 1, "texto": "Depois os filhos de Israel partiram, e se assentaram nos campos de Moabe, desta parte do Jordão de Jericó."}, {"numero": 2, "texto": "E viu Balaque, filho de Zipor, tudo o que Israel havia feito aos amorreus."}, {"numero": 3, "texto": "E Moabe temeu muito por causa do povo que era muito; e angustiou-se Moabe por causa dos filhos de Israel."}, {"numero": 4, "texto": "E disse Moabe aos anciãos de Midiã: Agora lamberá esta gente todos nossos entornos, como lambe o boi a grama do campo. E Balaque, filho de Zipor, era então rei de Moabe."}, {"numero": 5, "texto": "Portanto enviou mensageiros a Balaão filho de Beor, a Petor, que está junto ao rio na terra dos filhos de seu povo, para que o chamassem, dizendo: Um povo saiu do Egito, e eis que cobre a face da terra, e habita diante de mim:"}, {"numero": 6, "texto": "Vem pois agora, te rogo, amaldiçoa para mim este povo, porque é mais forte que eu: talvez poderei eu feri-lo, e lançá-lo da terra: que eu sei que o que tu abençoares, será bendito, e o que tu amaldiçoares, será maldito."}, {"numero": 7, "texto": "E foram os anciãos de Moabe e os anciãos de Midiã, com o [pagamento pela] adivinhação em sua mão, e chegaram a Balaão, e lhe disseram as palavras de Balaque."}, {"numero": 8, "texto": "E ele lhes disse: Repousai aqui esta noite, e eu vos referirei as palavras, como o SENHOR me falar. Assim os príncipes de Moabe se restaram com Balaão."}, {"numero": 9, "texto": "E veio Deus a Balaão, e disse-lhe: Que homens são estes que estão contigo?"}, {"numero": 10, "texto": "E Balaão respondeu a Deus: Balaque filho de Zipor, rei de Moabe, enviou a mim dizendo:"}, {"numero": 11, "texto": "Eis que este povo que saiu do Egito, cobre a face da terra: vem pois agora, e amaldiçoa-o para mim; talvez poderei lutar com ele, e expulsá-lo."}, {"numero": 12, "texto": "Então disse Deus a Balaão: Não vás com eles, nem amaldiçoes ao povo; porque é bendito."}, {"numero": 13, "texto": "Assim Balaão se levantou pela manhã, e disse aos príncipes de Balaque: Voltai-vos à vossa terra, porque o SENHOR não me quer deixar ir convosco."}, {"numero": 14, "texto": "E os príncipes de Moabe se levantaram, e vieram a Balaque, e disseram: Balaão não quis vir conosco."}, {"numero": 15, "texto": "E voltou Balaque a enviar outra vez mais príncipes, e mais nobres que os outros."}, {"numero": 16, "texto": "Os quais vieram a Balaão, e disseram-lhe: Assim diz Balaque, filho de Zipor: Rogo-te que não deixes de vir a mim:"}, {"numero": 17, "texto": "Porque sem dúvida te honrarei muito, e farei tudo o que me disseres: vem pois agora, almaldiçoa para mim a este povo."}, {"numero": 18, "texto": "E Balaão respondeu, e disse aos servos de Balaque: Ainda que Balaque me desse sua casa cheia de prata e ouro, não posso transgredir a palavra do SENHOR meu Deus, para fazer coisa pequena nem grande."}, {"numero": 19, "texto": "Rogo-vos, portanto, agora, que repouseis aqui esta noite, para que eu saiba que me volta a dizer o SENHOR."}, {"numero": 20, "texto": "E veio Deus a Balaão de noite, e disse-lhe: Se homens vierem a te chamar, levanta-te e vai com eles: porém farás o que eu te disser."}, {"numero": 21, "texto": "Assim Balaão se levantou pela manhã, e preparou sua jumenta, e foi com os príncipes de Moabe."}, {"numero": 22, "texto": "E o furor de Deus se acendeu porque ele ia; e o anjo do SENHOR se pôs no caminho por adversário seu. Ia, pois, ele montado sobre sua jumenta, e com ele dois servos seus."}, {"numero": 23, "texto": "E a jumenta viu o anjo do SENHOR, que estava no caminho com sua espada exposta em sua mão; então a jumenta desviou-se do caminho, e foi pelo campo. Em seguida, Balaão espancou a jumenta para fazê-la voltar ao caminho."}, {"numero": 24, "texto": "Mas o anjo do SENHOR se pôs em uma vereda de vinhas que tinha parede de uma parte e parede de outra."}, {"numero": 25, "texto": "E quando a jumenta viu o anjo do SENHOR, apegou-se à parede, e apertou contra a parede o pé de Balaão: e ele voltou a espancá-la."}, {"numero": 26, "texto": "E o anjo do SENHOR passou mais ali, e pôs-se em um lugar estreito, onde não havia caminho para desviar-se nem à direita nem à esquerda."}, {"numero": 27, "texto": "E vendo a jumenta ao anjo do SENHOR, lançou-se debaixo de Balaão: e irou-se Balaão, e feriu à jumenta com um bordão."}, {"numero": 28, "texto": "Então o SENHOR abriu a boca da jumenta, a qual disse a Balaão: Que te fiz, que me feriste estas três vezes?"}, {"numero": 29, "texto": "E Balaão respondeu à jumenta: Porque te zombaste de mim: bom seria se eu tivesse espada em minha mão, que agora te mataria!"}, {"numero": 30, "texto": "E a jumenta disse a Balaão: Não sou eu tua jumenta? Sobre mim montaste desde que tu me tens até hoje; costumei a fazê-lo assim contigo? E ele respondeu: Não."}, {"numero": 31, "texto": "Então o SENHOR abriu os olhos a Balaão, e viu ao anjo do SENHOR que estava no caminho, e tinha sua espada nua em sua mão. E Balaão fez reverência, e inclinou-se sobre seu rosto."}, {"numero": 32, "texto": "E o anjo do SENHOR lhe disse: Por que feriste tua jumenta estas três vezes? eis que eu saí para me opor a ti, porque teu caminho é perverso diante de mim:"}, {"numero": 33, "texto": "A jumenta me viu, e afastou-se logo de diante de mim estas três vezes: e se de mim não se houvesse afastado, eu também agora mataria a ti, e a ela deixaria viva."}, {"numero": 34, "texto": "Então Balaão disse ao anjo do SENHOR: Pequei, que não sabia que tu te punhas diante de mim no caminho: mas agora, se te parece mal, eu me voltarei."}, {"numero": 35, "texto": "E o anjo do SENHOR disse a Balaão: Vai com esses homens: porém a palavra que eu te disser, essa falarás. Assim Balaão foi com os príncipes de Balaque."}, {"numero": 36, "texto": "E ouvindo Balaque que Balaão vinha, saiu a recebê-lo à cidade de Moabe, que está junto ao termo de Arnom, que é a extremidade das fronteiras."}, {"numero": 37, "texto": "E Balaque disse a Balaão: Não enviei eu a ti a chamar-te? por que não vieste a mim? não posso eu te honrar?"}, {"numero": 38, "texto": "E Balaão respondeu a Balaque: Eis que eu vim a ti: mas poderei agora falar alguma coisa? A palavra que Deus puser em minha boca, essa falarei."}, {"numero": 39, "texto": "E foi Balaão com Balaque, e vieram à Quiriate-Huzote."}, {"numero": 40, "texto": "E Balaque fez matar bois e ovelhas, e enviou a Balaão, e aos príncipes que estavam com ele."}, {"numero": 41, "texto": "E no dia seguinte Balaque tomou a Balaão, e o fez subir aos lugares altos de Baal, e desde ali viu a extremidade do povo."}]'::jsonb, 'Almeida Livre'),
  ('Nm', 22, 'en', '[{"numero": 1, "texto": "And the children of Israel set forward, and pitched in the plains of Moab on this side Jordan by Jericho."}, {"numero": 2, "texto": "And Balak the son of Zippor saw all that Israel had done to the Amorites."}, {"numero": 3, "texto": "And Moab was sore afraid of the people, because they were many: and Moab was distressed because of the children of Israel."}, {"numero": 4, "texto": "And Moab said unto the elders of Midian, Now shall this company lick up all that are round about us, as the ox licketh up the grass of the field. And Balak the son of Zippor was king of the Moabites at that time."}, {"numero": 5, "texto": "He sent messengers therefore unto Balaam the son of Beor to Pethor, which is by the river of the land of the children of his people, to call him, saying, Behold, there is a people come out from Egypt: behold, they cover the face of the earth, and they abide over against me:"}, {"numero": 6, "texto": "Come now therefore, I pray thee, curse me this people; for they are too mighty for me: peradventure I shall prevail, that we may smite them, and that I may drive them out of the land: for I wot that he whom thou blessest is blessed, and he whom thou cursest is cursed."}, {"numero": 7, "texto": "And the elders of Moab and the elders of Midian departed with the rewards of divination in their hand; and they came unto Balaam, and spake unto him the words of Balak."}, {"numero": 8, "texto": "And he said unto them, Lodge here this night, and I will bring you word again, as the Lord shall speak unto me: and the princes of Moab abode with Balaam."}, {"numero": 9, "texto": "And God came unto Balaam, and said, What men are these with thee?"}, {"numero": 10, "texto": "And Balaam said unto God, Balak the son of Zippor, king of Moab, hath sent unto me, saying,"}, {"numero": 11, "texto": "Behold, there is a people come out of Egypt, which covereth the face of the earth: come now, curse me them; peradventure I shall be able to overcome them, and drive them out."}, {"numero": 12, "texto": "And God said unto Balaam, Thou shalt not go with them; thou shalt not curse the people: for they are blessed."}, {"numero": 13, "texto": "And Balaam rose up in the morning, and said unto the princes of Balak, Get you into your land: for the Lord refuseth to give me leave to go with you."}, {"numero": 14, "texto": "And the princes of Moab rose up, and they went unto Balak, and said, Balaam refuseth to come with us."}, {"numero": 15, "texto": "And Balak sent yet again princes, more, and more honourable than they."}, {"numero": 16, "texto": "And they came to Balaam, and said to him, Thus saith Balak the son of Zippor, Let nothing, I pray thee, hinder thee from coming unto me:"}, {"numero": 17, "texto": "For I will promote thee unto very great honour, and I will do whatsoever thou sayest unto me: come therefore, I pray thee, curse me this people."}, {"numero": 18, "texto": "And Balaam answered and said unto the servants of Balak, If Balak would give me his house full of silver and gold, I cannot go beyond the word of the Lord my God, to do less or more."}, {"numero": 19, "texto": "Now therefore, I pray you, tarry ye also here this night, that I may know what the Lord will say unto me more."}, {"numero": 20, "texto": "And God came unto Balaam at night, and said unto him, If the men come to call thee, rise up, and go with them; but yet the word which I shall say unto thee, that shalt thou do."}, {"numero": 21, "texto": "And Balaam rose up in the morning, and saddled his ass, and went with the princes of Moab."}, {"numero": 22, "texto": "And God''s anger was kindled because he went: and the angel of the Lord stood in the way for an adversary against him. Now he was riding upon his ass, and his two servants were with him."}, {"numero": 23, "texto": "And the ass saw the angel of the Lord standing in the way, and his sword drawn in his hand: and the ass turned aside out of the way, and went into the field: and Balaam smote the ass, to turn her into the way."}, {"numero": 24, "texto": "But the angel of the Lord stood in a path of the vineyards, a wall being on this side, and a wall on that side."}, {"numero": 25, "texto": "And when the ass saw the angel of the Lord, she thrust herself unto the wall, and crushed Balaam''s foot against the wall: and he smote her again."}, {"numero": 26, "texto": "And the angel of the Lord went further, and stood in a narrow place, where was no way to turn either to the right hand or to the left."}, {"numero": 27, "texto": "And when the ass saw the angel of the Lord, she fell down under Balaam: and Balaam''s anger was kindled, and he smote the ass with a staff."}, {"numero": 28, "texto": "And the Lord opened the mouth of the ass, and she said unto Balaam, What have I done unto thee, that thou hast smitten me these three times?"}, {"numero": 29, "texto": "And Balaam said unto the ass, Because thou hast mocked me: I would there were a sword in mine hand, for now would I kill thee."}, {"numero": 30, "texto": "And the ass said unto Balaam, Am not I thine ass, upon which thou hast ridden ever since I was thine unto this day? was I ever wont to do so unto thee? and he said, Nay."}, {"numero": 31, "texto": "Then the Lord opened the eyes of Balaam, and he saw the angel of the Lord standing in the way, and his sword drawn in his hand: and he bowed down his head, and fell flat on his face."}, {"numero": 32, "texto": "And the angel of the Lord said unto him, Wherefore hast thou smitten thine ass these three times? behold, I went out to withstand thee, because thy way is perverse before me:"}, {"numero": 33, "texto": "And the ass saw me, and turned from me these three times: unless she had turned from me, surely now also I had slain thee, and saved her alive."}, {"numero": 34, "texto": "And Balaam said unto the angel of the Lord, I have sinned; for I knew not that thou stoodest in the way against me: now therefore, if it displease thee, I will get me back again."}, {"numero": 35, "texto": "And the angel of the Lord said unto Balaam, Go with the men: but only the word that I shall speak unto thee, that thou shalt speak. So Balaam went with the princes of Balak."}, {"numero": 36, "texto": "And when Balak heard that Balaam was come, he went out to meet him unto a city of Moab, which is in the border of Arnon, which is in the utmost coast."}, {"numero": 37, "texto": "And Balak said unto Balaam, Did I not earnestly send unto thee to call thee? wherefore camest thou not unto me? am I not able indeed to promote thee to honour?"}, {"numero": 38, "texto": "And Balaam said unto Balak, Lo, I am come unto thee: have I now any power at all to say any thing? the word that God putteth in my mouth, that shall I speak."}, {"numero": 39, "texto": "And Balaam went with Balak, and they came unto Kirjathhuzoth."}, {"numero": 40, "texto": "And Balak offered oxen and sheep, and sent to Balaam, and to the princes that were with him."}, {"numero": 41, "texto": "And it came to pass on the morrow, that Balak took Balaam, and brought him up into the high places of Baal, that thence he might see the utmost part of the people."}]'::jsonb, 'King James Version'),
  ('Nm', 22, 'fr', '[{"numero": 1, "texto": "Les enfants d''''Israël partirent, et ils campèrent dans les plaines de Moab, au delà du Jourdain, vis-à-vis de Jéricho."}, {"numero": 2, "texto": "Balak, fils de Tsippor, vit tout ce qu''''Israël avait fait aux Amoréens."}, {"numero": 3, "texto": "Et Moab fut très effrayé en face d''''un peuple aussi nombreux, il fut saisi de terreur en face des enfants d''''Israël."}, {"numero": 4, "texto": "Moab dit aux anciens de Madian: Cette multitude va dévorer tout ce qui nous entoure, comme le boeuf broute la verdure des champs. Balak, fils de Tsippor, était alors roi de Moab."}, {"numero": 5, "texto": "Il envoya des messagers auprès de Balaam, fils de Beor, à Pethor sur le fleuve, dans le pays des fils de son peuple, afin de l''''appeler et de lui dire: Voici, un peuple est sorti d''''Egypte, il couvre la surface de la terre, et il habite vis-à-vis de moi."}, {"numero": 6, "texto": "Viens, je te prie, maudis-moi ce peuple, car il est plus puissant que moi; peut-être ainsi pourrai-je le battre et le chasserai-je du pays, car je sais que celui que tu bénis est béni, et que celui que tu maudis est maudit."}, {"numero": 7, "texto": "Les anciens de Moab et les anciens de Madian partirent, ayant avec eux des présents pour le devin. Ils arrivèrent auprès de Balaam, et lui rapportèrent les paroles de Balak."}, {"numero": 8, "texto": "Balaam leur dit: Passez ici la nuit, et je vous donnerai réponse, d''''après ce que l''''Eternel me dira. Et les chefs de Moab restèrent chez Balaam."}, {"numero": 9, "texto": "Dieu vint à Balaam, et dit: Qui sont ces hommes que tu as chez toi?"}, {"numero": 10, "texto": "Balaam répondit à Dieu: Balak, fils de Tsippor, roi de Moab, les a envoyés pour me dire:"}, {"numero": 11, "texto": "Voici, un peuple est sorti d''''Egypte, et il couvre la surface de la terre; viens donc, maudis-le; peut-être ainsi pourrai-je le combattre, et le chasserai-je."}, {"numero": 12, "texto": "Dieu dit à Balaam: Tu n''''iras point avec eux; tu ne maudiras point ce peuple, car il est béni."}, {"numero": 13, "texto": "Balaam se leva le matin, et il dit aux chefs de Balak: Allez dans votre pays, car l''''Eternel refuse de me laisser aller avec vous."}, {"numero": 14, "texto": "Et les princes de Moab se levèrent, retournèrent auprès de Balak, et dirent: Balaam a refusé de venir avec nous."}, {"numero": 15, "texto": "Balak envoya de nouveau des chefs en plus grand nombre et plus considérés que les précédents."}, {"numero": 16, "texto": "Ils arrivèrent auprès de Balaam, et lui dirent: Ainsi parle Balak, fils de Tsippor: Que l''''on ne t''''empêche donc pas de venir vers moi;"}, {"numero": 17, "texto": "car je te rendrai beaucoup d''''honneurs, et je ferai tout ce que tu me diras; viens, je te prie, maudis-moi ce peuple."}, {"numero": 18, "texto": "Balaam répondit et dit aux serviteurs de Balak: Quand Balak me donnerait sa maison pleine d''''argent et d''''or, je ne pourrais faire aucune chose, ni petite ni grande, contre l''''ordre de l''''Eternel, mon Dieu."}, {"numero": 19, "texto": "Maintenant, je vous prie, restez ici cette nuit, et je saurai ce que l''''Eternel me dira encore."}, {"numero": 20, "texto": "Dieu vint à Balaam pendant la nuit, et lui dit: Puisque ces hommes sont venus pour t''''appeler, lève-toi, va avec eux; mais tu feras ce que je te dirai."}, {"numero": 21, "texto": "Balaam se leva le matin, sella son ânesse, et partit avec les chefs de Moab."}, {"numero": 22, "texto": "La colère de Dieu s''''enflamma, parce qu''''il était parti; et l''''ange de l''''Eternel se plaça sur le chemin, pour lui résister. Balaam était monté sur son ânesse, et ses deux serviteurs étaient avec lui."}, {"numero": 23, "texto": "L''''ânesse vit l''''ange de l''''Eternel qui se tenait sur le chemin, son épée nue dans la main; elle se détourna du chemin et alla dans les champs. Balaam frappa l''''ânesse pour la ramener dans le chemin."}, {"numero": 24, "texto": "L''''ange de l''''Eternel se plaça dans un sentier entre les vignes; il y avait un mur de chaque côté."}, {"numero": 25, "texto": "L''''ânesse vit l''''ange de l''''Eternel; elle se serra contre le mur, et pressa le pied de Balaam contre le mur. Balaam la frappa de nouveau."}, {"numero": 26, "texto": "L''''ange de l''''Eternel passa plus loin, et se plaça dans un lieu où il n''''y avait point d''''espace pour se détourner à droite ou à gauche."}, {"numero": 27, "texto": "L''''ânesse vit l''''ange de l''''Eternel, et elle s''''abattit sous Balaam. La colère de Balaam s''''enflamma, et il frappa l''''ânesse avec un bâton."}, {"numero": 28, "texto": "L''''Eternel ouvrit la bouche de l''''ânesse, et elle dit à Balaam: Que t''''ai je fait, pour que tu m''''aies frappée déjà trois fois?"}, {"numero": 29, "texto": "Balaam répondit à l''''ânesse: C''''est parce que tu t''''es moquée de moi; si j''''avais une épée dans la main, je te tuerais à l''''instant."}, {"numero": 30, "texto": "L''''ânesse dit à Balaam: Ne suis-je pas ton ânesse, que tu as de tout temps montée jusqu''''à ce jour? Ai-je l''''habitude de te faire ainsi? Et il répondit: Non."}, {"numero": 31, "texto": "L''''Eternel ouvrit les yeux de Balaam, et Balaam vit l''''ange de l''''Eternel qui se tenait sur le chemin, son épée nue dans la main; et il s''''inclina, et se prosterna sur son visage."}, {"numero": 32, "texto": "L''''ange de l''''Eternel lui dit: Pourquoi as-tu frappé ton ânesse déjà trois fois? Voici, je suis sorti pour te résister, car c''''est un chemin de perdition qui est devant moi."}, {"numero": 33, "texto": "L''''ânesse m''''a vu, et elle s''''est détournée devant moi déjà trois fois; si elle ne se fût pas détournée de moi, je t''''aurais même tué, et je lui aurais laissé la vie."}, {"numero": 34, "texto": "Balaam dit à l''''ange de l''''Eternel: J''''ai péché, car je ne savais pas que tu te fusses placé au-devant de moi sur le chemin; et maintenant, si tu me désapprouves, je m''''en retournerai."}, {"numero": 35, "texto": "L''''ange de l''''Eternel dit à Balaam: Va avec ces hommes; mais tu ne feras que répéter les paroles que je te dirai. Et Balaam alla avec les chefs de Balak."}, {"numero": 36, "texto": "Balak apprit que Balaam arrivait, et il sortit à sa rencontre jusqu''''à la ville de Moab qui est sur la limite de l''''Arnon, à l''''extrême frontière."}, {"numero": 37, "texto": "Balak dit à Balaam: N''''ai-je pas envoyé auprès de toi pour t''''appeler? Pourquoi n''''es-tu pas venu vers moi? Ne puis-je donc pas te traiter avec honneur?"}, {"numero": 38, "texto": "Balaam dit à Balak: Voici, je suis venu vers toi; maintenant, me sera-t-il permis de dire quoi que ce soit? Je dirai les paroles que Dieu mettra dans ma bouche."}, {"numero": 39, "texto": "Balaam alla avec Balak, et ils arrivèrent à Kirjath-Hutsoth."}, {"numero": 40, "texto": "Balak sacrifia des boeufs et des brebis, et il en envoya à Balaam et aux chefs qui étaient avec lui."}, {"numero": 41, "texto": "Le matin, Balak prit Balaam, et le fit monter à Bamoth-Baal, d''''où Balaam vit une partie du peuple."}]'::jsonb, 'Louis Segond 1910'),
  ('Nm', 22, 'es', '[{"numero": 1, "texto": "Y MOVIERON los hijos de Israel, y asentaron en los campos de Moab, de esta parte del Jordán de Jericó."}, {"numero": 2, "texto": "Y vió Balac, hijo de Zippor, todo lo que Israel había hecho al Amorrheo."}, {"numero": 3, "texto": "Y Moab temió mucho á causa del pueblo que era mucho; y angustióse Moab á causa de los hijos de Israel."}, {"numero": 4, "texto": "Y dijo Moab á los ancianos de Madián: Ahora lamerá esta gente todos nuestros contornos, como lame el buey la grama del campo. Y Balac, hijo de Zippor, era entonces rey de Moab."}, {"numero": 5, "texto": "Por tanto envió mensajeros á Balaam hijo de Beor, á Pethor, que está junto al río en la tierra de los hijos de su pueblo, para que lo llamasen, diciendo: Un pueblo ha salido de Egipto, y he aquí cubre la haz de la tierra, y habita delante de mí:"}, {"numero": 6, "texto": "Ven pues ahora, te ruego, maldíceme este pueblo, porque es más fuerte que yo: quizá podré yo herirlo, y echarlo de la tierra: que yo sé que el que tú bendijeres, será bendito, y el que tú maldijeres, será maldito."}, {"numero": 7, "texto": "Y fueron los ancianos de Moab, y los ancianos de Madián, con las dádivas de adivinación en su mano, y llegaron á Balaam, y le dijeron las palabras de Balac."}, {"numero": 8, "texto": "Y él les dijo: Reposad aquí esta noche, y yo os referiré las palabras, como Jehová me hablare. Así los príncipes de Moab se quedaron con Balaam."}, {"numero": 9, "texto": "Y vino Dios á Balaam, y díjole: ¿Qué varones son estos que están contigo?"}, {"numero": 10, "texto": "Y Balaam respondió á Dios: Balac hijo de Zippor, rey de Moab, ha enviado á mí diciendo:"}, {"numero": 11, "texto": "He aquí este pueblo que ha salido de Egipto, cubre la haz de la tierra: ven pues ahora, y maldícemelo; quizá podré pelear con él, y echarlo."}, {"numero": 12, "texto": "Entonces dijo Dios á Balaam: No vayas con ellos, ni maldigas al pueblo; porque es bendito."}, {"numero": 13, "texto": "Así Balaam se levantó por la mañana, y dijo á los príncipes de Balac: Volveos á vuestra tierra, porque Jehová no me quiere dejar ir con vosotros."}, {"numero": 14, "texto": "Y los príncipes de Moab se levantaron, y vinieron á Balac, y dijeron: Balaam no quiso venir con nosotros."}, {"numero": 15, "texto": "Y tornó Balac á enviar otra vez más príncipes, y más honorables que los otros."}, {"numero": 16, "texto": "Los cuales vinieron á Balaam, y dijéronle: Así dice Balac, hijo de Zippor: Ruégote que no dejes de venir á mí:"}, {"numero": 17, "texto": "Porque sin duda te honraré mucho, y haré todo lo que me dijeres: ven pues ahora, maldíceme á este pueblo."}, {"numero": 18, "texto": "Y Balaam respondió, y dijo á los siervos de Balac: Aunque Balac me diese su casa llena de plata y oro, no puedo traspasar la palabra de Jehová mi Dios, para hacer cosa chica ni grande."}, {"numero": 19, "texto": "Ruégoos por tanto ahora, que reposéis aquí esta noche, para que yo sepa qué me vuelve á decir Jehová."}, {"numero": 20, "texto": "Y vino Dios á Balaam de noche, y díjole: Si vinieren á llamarte hombres, levántate y ve con ellos: empero harás lo que yo te dijere."}, {"numero": 21, "texto": "Así Balaam se levantó por la mañana, y cinchó su asna, y fué con los príncipes de Moab."}, {"numero": 22, "texto": "Y el furor de Dios se encendió porque él iba; y el ángel de Jehová se puso en el camino por adversario suyo. Iba, pues, él montado sobre su asna, y con él dos mozos suyos."}, {"numero": 23, "texto": "Y el asna vió al ángel de Jehová, que estaba en el camino con su espada desnuda en su mano; y apartóse el asna del camino, é iba por el campo. Entonces hirió Balaam al asna para hacerla volver al camino."}, {"numero": 24, "texto": "Mas el ángel de Jehová se puso en una senda de viñas que tenía pared de una parte y pared de otra."}, {"numero": 25, "texto": "Y viendo el asna al ángel de Jehová, pegóse á la pared, y apretó contra la pared el pie de Balaam: y él volvió á herirla."}, {"numero": 26, "texto": "Y el ángel de Jehová pasó más allá, y púsose en una angostura, donde no había camino para apartarse ni á diestra ni á siniestra."}, {"numero": 27, "texto": "Y viendo el asna al ángel de Jehová, echóse debajo de Balaam: y enojóse Balaam, é hirió al asna con el palo."}, {"numero": 28, "texto": "Entonces Jehová abrió la boca al asna, la cual dijo á Balaam: ¿Qué te he hecho, que me has herido estas tres veces?"}, {"numero": 29, "texto": "Y Balaam respondió al asna: Porque te has burlado de mí: ¡ojalá tuviera espada en mi mano, que ahora te mataría!"}, {"numero": 30, "texto": "Y el asna dijo á Balaam: ¿No soy yo tu asna? sobre mí has cabalgado desde que tú me tienes hasta este día; ¿he acostumbrado á hacerlo así contigo? Y él respondió: No."}, {"numero": 31, "texto": "Entonces Jehová abrió los ojos á Balaam, y vió al ángel de Jehová que estaba en el camino, y tenía su espada desnuda en su mano. Y Balaam hizo reverencia, é inclinóse sobre su rostro."}, {"numero": 32, "texto": "Y el ángel de Jehová le dijo: ¿Por qué has herido tu asna estas tres veces? he aquí yo he salido para contrarrestarte, porque tu camino es perverso delante de mí:"}, {"numero": 33, "texto": "El asna me ha visto, y hase apartado luego de delante de mí estas tres veces: y si de mí no se hubiera apartado, yo también ahora te mataría á ti, y á ella dejaría viva."}, {"numero": 34, "texto": "Entonces Balaam dijo al ángel de Jehová: He pecado, que no sabía que tú te ponías delante de mí en el camino: mas ahora, si te parece mal, yo me volveré."}, {"numero": 35, "texto": "Y el ángel de Jehová dijo á Balaam: Ve con esos hombres: empero la palabra que yo te dijere, esa hablarás. Así Balaam fué con los príncipes de Balac."}, {"numero": 36, "texto": "Y oyendo Balac que Balaam venía, salió á recibirlo á la ciudad de Moab, que está junto al término de Arnón, que es el cabo de los confines."}, {"numero": 37, "texto": "Y Balac dijo á Balaam: ¿No envié yo á ti á llamarte? ¿por qué no has venido á mí? ¿no puedo yo honrarte?"}, {"numero": 38, "texto": "Y Balaam respondió á Balac: He aquí yo he venido á ti: mas ¿podré ahora hablar alguna cosa? La palabra que Dios pusiere en mi boca, esa hablaré."}, {"numero": 39, "texto": "Y fué Balaam con Balac, y vinieron á la ciudad de Husoth."}, {"numero": 40, "texto": "Y Balac hizo matar bueyes y ovejas, y envió á Balaam, y á los príncipes que estaban con él."}, {"numero": 41, "texto": "Y el día siguiente Balac tomó á Balaam, é hízolo subir á los altos de Baal, y desde allí vió la extremidad del pueblo."}]'::jsonb, 'Reina-Valera 1909'),
  ('Nm', 23, 'pt', '[{"numero": 1, "texto": "E Balaão disse a Balaque: Edifica para mim aqui sete altares, e prepara-me aqui sete bezerros e sete carneiros."}, {"numero": 2, "texto": "E Balaque fez como lhe disse Balaão: e ofereceram Balaque e Balaão um bezerro e um carneiro em cada altar."}, {"numero": 3, "texto": "E Balaão disse a Balaque: Põe-te junto a teu holocausto, e eu irei: talvez o SENHOR me virá ao encontro, e qualquer um coisa que me mostrar, eu a contarei a ti. E assim se foi só."}, {"numero": 4, "texto": "E veio Deus ao encontro de Balaão, e este lhe disse: Sete altares ordenei, e em cada altar ofereci um bezerro e um carneiro."}, {"numero": 5, "texto": "E o SENHOR pôs palavra na boca de Balaão, e disse-lhe: Volta a Balaque, e hás de falar assim."}, {"numero": 6, "texto": "E voltou a ele, e eis que estava ele junto a seu holocausto, ele e todos os príncipes de Moabe."}, {"numero": 7, "texto": "E ele tomou sua parábola, e disse: De Arã me trouxe Balaque, rei de Moabe, dos montes do oriente: Vem, amaldiçoa para mim a Jacó; E vem, condena a Israel."}, {"numero": 8, "texto": "Por que amaldiçoarei eu ao que Deus não amaldiçoou? E por que condenarei ao que o SENHOR não condenou?"}, {"numero": 9, "texto": "Porque do cume das penhas o verei, E desde as colinas o olharei: Eis aqui um povo que habitará confiante, e não será contado entre as nações."}, {"numero": 10, "texto": "Quem contará o pó de Jacó, Ou o número da quarta parte de Israel? Morra minha pessoa da morte dos corretos, E meu fim seja como o seu."}, {"numero": 11, "texto": "Então Balaque disse a Balaão: Que me fizeste? Tomei-te para que amaldiçoes a meus inimigos, e eis que proferiste bênçãos."}, {"numero": 12, "texto": "E ele respondeu, e disse: Não observarei eu o que o SENHOR puser em minha boca para dizê-lo?"}, {"numero": 13, "texto": "E disse Balaque: Rogo-te que venhas comigo a outro lugar desde o qual o vejas; sua extremidade somente verás, que não o verás todo; e desde ali me o amaldiçoarás."}, {"numero": 14, "texto": "E levou-o ao campo de Zofim, ao cume de Pisga, e edificou sete altares, e ofereceu um bezerro e um carneiro em cada altar."}, {"numero": 15, "texto": "Então ele disse a Balaque: Põe-te aqui junto a teu holocausto, e eu irei a encontrar a Deus ali."}, {"numero": 16, "texto": "E o SENHOR saiu ao encontro de Balaão, e pôs palavra em sua boca, e disse-lhe: Volta a Balaque, e assim dirás."}, {"numero": 17, "texto": "E veio a ele, e eis que ele estava junto a seu holocausto, e com ele os príncipes de Moabe: e disse-lhe Balaque: Que disse o SENHOR?"}, {"numero": 18, "texto": "Então ele tomou sua parábola, e disse: Balaque, levanta-te e ouve; Escuta minhas palavras, filho de Zipor:"}, {"numero": 19, "texto": "Deus não é homem, para que minta; nem filho de homem para que se arrependa: ele disse, e não fará?; Falou, e não o executará?"}, {"numero": 20, "texto": "Eis que, eu tomei bênção: E ele abençoou, e não poderei revogá-la."}, {"numero": 21, "texto": "Não notou iniquidade em Jacó, nem viu perversidade em Israel: o SENHOR seu Deus é com ele, E júbilo de rei nele."}, {"numero": 22, "texto": "Deus os tirou do Egito; Tem forças como de boi selvagem."}, {"numero": 23, "texto": "Porque em Jacó não há agouro, nem adivinhação em Israel: Como agora, será dito de Jacó e de Israel: O que fez Deus!"}, {"numero": 24, "texto": "Eis que o povo, que como leão se levantará, E como leão se erguerá: Não se deitará até que coma a presa, E beba o sangue dos mortos."}, {"numero": 25, "texto": "Então Balaque disse a Balaão: Já que não o amaldiçoas, nem tampouco o abençoes."}, {"numero": 26, "texto": "E Balaão respondeu, e disse a Balaque: Não te disse que tudo o que o SENHOR me disser, aquilo tenho de fazer?"}, {"numero": 27, "texto": "E disse Balaque a Balaão: Rogo-te que venhas, te levarei a outro lugar; porventura comparecerá bem a Deus que desde ali me o amaldiçoes."}, {"numero": 28, "texto": "E Balaque levou a Balaão ao cume de Peor, que está voltado até Jesimom."}, {"numero": 29, "texto": "Então Balaão disse a Balaque: Edifica para mim aqui sete altares, e prepara-me aqui sete bezerros e sete carneiros."}, {"numero": 30, "texto": "E Balaque fez como Balaão lhe disse; e ofereceu um bezerro e um carneiro em cada altar."}]'::jsonb, 'Almeida Livre'),
  ('Nm', 23, 'en', '[{"numero": 1, "texto": "And Balaam said unto Balak, Build me here seven altars, and prepare me here seven oxen and seven rams."}, {"numero": 2, "texto": "And Balak did as Balaam had spoken; and Balak and Balaam offered on every altar a bullock and a ram."}, {"numero": 3, "texto": "And Balaam said unto Balak, Stand by thy burnt offering, and I will go: peradventure the Lord will come to meet me: and whatsoever he sheweth me I will tell thee. And he went to an high place."}, {"numero": 4, "texto": "And God met Balaam: and he said unto him, I have prepared seven altars, and I have offered upon every altar a bullock and a ram."}, {"numero": 5, "texto": "And the Lord put a word in Balaam''s mouth, and said, Return unto Balak, and thus thou shalt speak."}, {"numero": 6, "texto": "And he returned unto him, and, lo, he stood by his burnt sacrifice, he, and all the princes of Moab."}, {"numero": 7, "texto": "And he took up his parable, and said, Balak the king of Moab hath brought me from Aram, out of the mountains of the east, saying, Come, curse me Jacob, and come, defy Israel."}, {"numero": 8, "texto": "How shall I curse, whom God hath not cursed? or how shall I defy, whom the Lord hath not defied?"}, {"numero": 9, "texto": "For from the top of the rocks I see him, and from the hills I behold him: lo, the people shall dwell alone, and shall not be reckoned among the nations."}, {"numero": 10, "texto": "Who can count the dust of Jacob, and the number of the fourth part of Israel? Let me die the death of the righteous, and let my last end be like his!"}, {"numero": 11, "texto": "And Balak said unto Balaam, What hast thou done unto me? I took thee to curse mine enemies, and, behold, thou hast blessed them altogether."}, {"numero": 12, "texto": "And he answered and said, Must I not take heed to speak that which the Lord hath put in my mouth?"}, {"numero": 13, "texto": "And Balak said unto him, Come, I pray thee, with me unto another place, from whence thou mayest see them: thou shalt see but the utmost part of them, and shalt not see them all: and curse me them from thence."}, {"numero": 14, "texto": "And he brought him into the field of Zophim, to the top of Pisgah, and built seven altars, and offered a bullock and a ram on every altar."}, {"numero": 15, "texto": "And he said unto Balak, Stand here by thy burnt offering, while I meet the Lord yonder."}, {"numero": 16, "texto": "And the Lord met Balaam, and put a word in his mouth, and said, Go again unto Balak, and say thus."}, {"numero": 17, "texto": "And when he came to him, behold, he stood by his burnt offering, and the princes of Moab with him. And Balak said unto him, What hath the Lord spoken?"}, {"numero": 18, "texto": "And he took up his parable, and said, Rise up, Balak, and hear; hearken unto me, thou son of Zippor:"}, {"numero": 19, "texto": "God is not a man, that he should lie; neither the son of man, that he should repent: hath he said, and shall he not do it? or hath he spoken, and shall he not make it good?"}, {"numero": 20, "texto": "Behold, I have received commandment to bless: and he hath blessed; and I cannot reverse it."}, {"numero": 21, "texto": "He hath not beheld iniquity in Jacob, neither hath he seen perverseness in Israel: the Lord his God is with him, and the shout of a king is among them."}, {"numero": 22, "texto": "God brought them out of Egypt; he hath as it were the strength of an unicorn."}, {"numero": 23, "texto": "Surely there is no enchantment against Jacob, neither is there any divination against Israel: according to this time it shall be said of Jacob and of Israel, What hath God wrought!"}, {"numero": 24, "texto": "Behold, the people shall rise up as a great lion, and lift up himself as a young lion: he shall not lie down until he eat of the prey, and drink the blood of the slain."}, {"numero": 25, "texto": "And Balak said unto Balaam, Neither curse them at all, nor bless them at all."}, {"numero": 26, "texto": "But Balaam answered and said unto Balak, Told not I thee, saying, All that the Lord speaketh, that I must do?"}, {"numero": 27, "texto": "And Balak said unto Balaam, Come, I pray thee, I will bring thee unto another place; peradventure it will please God that thou mayest curse me them from thence."}, {"numero": 28, "texto": "And Balak brought Balaam unto the top of Peor, that looketh toward jeshimon."}, {"numero": 29, "texto": "And Balaam said unto Balak, Build me here seven altars, and prepare me here seven bullocks and seven rams."}, {"numero": 30, "texto": "And Balak did as Balaam had said, and offered a bullock and a ram on every altar."}]'::jsonb, 'King James Version'),
  ('Nm', 23, 'fr', '[{"numero": 1, "texto": "Balaam dit à Balak: Bâtis-moi ici sept autels, et prépare-moi ici sept taureaux et sept béliers."}, {"numero": 2, "texto": "Balak fit ce que Balaam avait dit; et Balak et Balaam offrirent un taureau et un bélier sur chaque autel."}, {"numero": 3, "texto": "Balaam dit à Balak: Tiens-toi près de ton holocauste, et je m''''éloignerai; peut-être que l''''Eternel viendra à ma rencontre, et je te dirai ce qu''''il me révélera. Et il alla sur un lieu élevé."}, {"numero": 4, "texto": "Dieu vint au-devant de Balaam, et Balaam lui dit: J''''ai dressé sept autels, et j''''ai offert un taureau et un bélier sur chaque autel."}, {"numero": 5, "texto": "L''''Eternel mit des paroles dans la bouche de Balaam, et dit: Retourne vers Balak, et tu parleras ainsi."}, {"numero": 6, "texto": "Il retourna vers lui; et voici, Balak se tenait près de son holocauste, lui et tous les chefs de Moab."}, {"numero": 7, "texto": "Balaam prononça son oracle, et dit: Balak m''''a fait descendre d''''Aram, Le roi de Moab m''''a fait descendre des montagnes de l''''Orient. -Viens, maudis-moi Jacob! Viens, sois irrité contre Israël!"}, {"numero": 8, "texto": "Comment maudirais-je celui que Dieu n''''a point maudit? Comment serais-je irrité quand l''''Eternel n''''est point irrité?"}, {"numero": 9, "texto": "Je le vois du sommet des rochers, Je le contemple du haut des collines: C''''est un peuple qui a sa demeure à part, Et qui ne fait point partie des nations."}, {"numero": 10, "texto": "Qui peut compter la poussière de Jacob, Et dire le nombre du quart d''''Israël? Que je meure de la mort des justes, Et que ma fin soit semblable à la leur!"}, {"numero": 11, "texto": "Balak dit à Balaam: Que m''''as-tu fait? Je t''''ai pris pour maudire mon ennemi, et voici, tu le bénis!"}, {"numero": 12, "texto": "Il répondit, et dit: N''''aurai-je pas soin de dire ce que l''''Eternel met dans ma bouche?"}, {"numero": 13, "texto": "Balak lui dit: Viens donc avec moi dans un autre lieu, d''''où tu le verras; tu n''''en verras qu''''une partie, tu n''''en verras pas la totalité. Et de là maudis-le-moi."}, {"numero": 14, "texto": "Il le mena au champ de Tsophim, sur le sommet du Pisga; il bâtit sept autels, et offrit un taureau et un bélier sur chaque autel."}, {"numero": 15, "texto": "Balaam dit à Balak: Tiens-toi ici, près de ton holocauste, et j''''irai à la rencontre de Dieu."}, {"numero": 16, "texto": "L''''Eternel vint au-devant de Balaam; il mit des paroles dans sa bouche, et dit: Retourne vers Balak, et tu parleras ainsi."}, {"numero": 17, "texto": "Il retourna vers lui; et voici, Balak se tenait près de son holocauste, avec les chefs de Moab. Balak lui dit: Qu''''est-ce que l''''Eternel a dit?"}, {"numero": 18, "texto": "Balaam prononça son oracle, et dit: Lève-toi, Balak, écoute! Prête-moi l''''oreille, fils de Tsippor!"}, {"numero": 19, "texto": "Dieu n''''est point un homme pour mentir, Ni fils d''''un homme pour se repentir. Ce qu''''il a dit, ne le fera-t-il pas? Ce qu''''il a déclaré, ne l''''exécutera-t il pas?"}, {"numero": 20, "texto": "Voici, j''''ai reçu l''''ordre de bénir: Il a béni, je ne le révoquerai point."}, {"numero": 21, "texto": "Il n''''aperçoit point d''''iniquité en Jacob, Il ne voit point d''''injustice en Israël; L''''Eternel, son Dieu, est avec lui, Il est son roi, l''''objet de son allégresse."}, {"numero": 22, "texto": "Dieu les a fait sortir d''''Egypte, Il est pour eux comme la vigueur du buffle."}, {"numero": 23, "texto": "L''''enchantement ne peut rien contre Jacob, Ni la divination contre Israël; Au temps marqué, il sera dit à Jacob et à Israël: Quelle est l''''oeuvre de Dieu."}, {"numero": 24, "texto": "C''''est un peuple qui se lève comme une lionne, Et qui se dresse comme un lion; Il ne se couche point jusqu''''à ce qu''''il ait dévoré la proie, Et qu''''il ait bu le sang des blessés."}, {"numero": 25, "texto": "Balak dit à Balaam: Ne le maudis pas, mais du moins ne le bénis pas."}, {"numero": 26, "texto": "Balaam répondit, et dit à Balak: Ne t''''ai-je pas parlé ainsi: Je ferai tout ce que l''''Eternel dira?"}, {"numero": 27, "texto": "Balak dit à Balaam: Viens donc, je te mènerai dans un autre lieu; peut être Dieu trouvera-t-il bon que de là tu me maudisses ce peuple."}, {"numero": 28, "texto": "Balak mena Balaam sur le sommet du Peor, en regard du désert."}, {"numero": 29, "texto": "Balaam dit à Balak: Bâtis-moi ici sept autels, et prépare-moi ici sept taureaux et sept béliers."}, {"numero": 30, "texto": "Balak fit ce que Balaam avait dit, et il offrit un taureau et un bélier sur chaque autel."}]'::jsonb, 'Louis Segond 1910'),
  ('Nm', 23, 'es', '[{"numero": 1, "texto": "Y BALAAM dijo á Balac: Edifícame aquí siete altares, y prepárame aquí siete becerros y siete carneros."}, {"numero": 2, "texto": "Y Balac hizo como le dijo Balaam: y ofrecieron Balac y Balaam un becerro y un carnero en cada altar."}, {"numero": 3, "texto": "Y Balaam dijo á Balac: Ponte junto á tu holocausto, y yo iré: quizá Jehová me vendrá al encuentro, y cualquiera cosa que me mostrare, te la noticiaré. Y así se fué solo."}, {"numero": 4, "texto": "Y vino Dios al encuentro de Balaam, y éste le dijo: Siete altares he ordenado, y en cada altar he ofrecido un becerro y un carnero."}, {"numero": 5, "texto": "Y Jehová puso palabra en la boca de Balaam, y díjole: Vuelve á Balac, y has de hablar así."}, {"numero": 6, "texto": "Y volvió á él, y he aquí estaba él junto á su holocausto, él y todos los príncipes de Moab."}, {"numero": 7, "texto": "Y él tomó su parábola, y dijo: De Aram me trajo Balac, rey de Moab, de los montes del oriente: ven, maldíceme á Jacob; y ven, execra á Israel."}, {"numero": 8, "texto": "¿Por qué maldeciré yo al que Dios no maldijo? ¿y por qué he de execrar al que Jehová no ha execrado?"}, {"numero": 9, "texto": "Porque de la cumbre de las peñas lo veré, y desde los collados lo miraré: he aquí un pueblo que habitará confiado, y no será contado entre las gentes."}, {"numero": 10, "texto": "¿Quién contará el polvo de Jacob, o el número de la cuarta parte de Israel? Muera mi persona de la muerte de los rectos, y mi postrimería sea como la suya."}, {"numero": 11, "texto": "Entonces Balac dijo á Balaam: ¿Qué me has hecho? hete tomado para que maldigas á mis enemigos, y he aquí has proferido bendiciones."}, {"numero": 12, "texto": "Y él respondió, y dijo: ¿No observaré yo lo que Jehová pusiere en mi boca para decirlo?"}, {"numero": 13, "texto": "Y dijo Balac: Ruégote que vengas conmigo á otro lugar desde el cual lo veas; su extremidad solamente verás, que no lo verás todo; y desde allí me lo maldecirás."}, {"numero": 14, "texto": "Y llevólo al campo de Sophim, á la cumbre de Pisga, y edificó siete altares, y ofreció un becerro y un carnero en cada altar."}, {"numero": 15, "texto": "Entonces él dijo á Balac: Ponte aquí junto á tu holocausto, y yo iré á encontrar á Dios allí."}, {"numero": 16, "texto": "Y Jehová salió al encuentro de Balaam, y puso palabra en su boca, y díjole: Vuelve á Balac, y así has de decir."}, {"numero": 17, "texto": "Y vino á él, y he aquí que él estaba junto á su holocausto, y con él los príncipes de Moab: y díjole Balac: ¿Qué ha dicho Jehová?"}, {"numero": 18, "texto": "Entonces él tomó su parábola, y dijo: Balac, levántate y oye; escucha mis palabras, hijo de Zippor:"}, {"numero": 19, "texto": "Dios no es hombre, para que mienta; ni hijo de hombre para que se arrepienta: el dijo, ¿y no hará?; habló, ¿y no lo ejecutará?"}, {"numero": 20, "texto": "He aquí, yo he tomado bendición: y él bendijo, y no podré revocarla."}, {"numero": 21, "texto": "No ha notado iniquidad en Jacob, ni ha visto perversidad en Israel: Jehová su Dios es con él, y júbilo de rey en él."}, {"numero": 22, "texto": "Dios los ha sacado de Egipto; tiene fuerzas como de unicornio."}, {"numero": 23, "texto": "Porque en Jacob no hay agüero, ni adivinación en Israel: como ahora, será dicho de Jacob y de Israel: ¡Lo que ha hecho Dios!"}, {"numero": 24, "texto": "He aquí el pueblo, que como león se levantará, y como león se erguirá: no se echará hasta que coma la presa, y beba la sangre de los muertos."}, {"numero": 25, "texto": "Entonces Balac dijo á Balaam: Ya que no lo maldices, ni tampoco lo bendigas."}, {"numero": 26, "texto": "Y Balaam respondió, y dijo á Balac: ¿No te he dicho que todo lo que Jehová me dijere, aquello tengo de hacer?"}, {"numero": 27, "texto": "Y dijo Balac á Balaam: Ruégote que vengas, te llevaré á otro lugar; por ventura parecerá bien á Dios que desde allí me lo maldigas."}, {"numero": 28, "texto": "Y Balac llevó á Balaam á la cumbre de Peor, que mira hacia Jesimón."}, {"numero": 29, "texto": "Entonces Balaam dijo á Balac: Edifícame aquí siete altares, y prepárame aquí siete becerros y siete carneros."}, {"numero": 30, "texto": "Y Balac hizo como Balaam le dijo; y ofreció un becerro y un carnero en cada altar."}]'::jsonb, 'Reina-Valera 1909'),
  ('Nm', 24, 'pt', '[{"numero": 1, "texto": "E quando viu Balaão que parecia bem ao SENHOR que o abençoasse a Israel, não foi, como a primeira e segunda vez, a encontro de agouros, mas sim que pôs seu rosto até o deserto;"}, {"numero": 2, "texto": "E levantando seus olhos, viu a Israel alojado por suas tribos; e o espírito de Deus veio sobre ele."}, {"numero": 3, "texto": "Então tomou sua parábola, e disse: Disse Balaão filho de Beor, E disse o homem de olhos abertos:"}, {"numero": 4, "texto": "Disse o que ouviu os ditos de Deus, O que viu a visão do Todo-Poderoso; caído, mas abertos os olhos:"}, {"numero": 5, "texto": "Quão belas são tuas tendas, ó Jacó, Tuas habitações, ó Israel!"}, {"numero": 6, "texto": "Como ribeiros estão estendidas, Como jardins junto ao rio, Como aloés plantados pelo SENHOR, Como cedros junto às águas."}, {"numero": 7, "texto": "De suas mãos destilarão águas, E sua descendência será em muitas águas: E se levantará seu rei mais que Agague, E seu reino será exaltado."}, {"numero": 8, "texto": "Deus o tirou do Egito; Tem forças como de boi selvagem: Comerá às nações suas inimigas, E esmiuçará seus ossos, E perfurará com suas flechas."}, {"numero": 9, "texto": "Se encurvará para deitar-se como leão, E como leoa; quem o despertará? Benditos os que te abençoarem, E malditos os que te amaldiçoarem."}, {"numero": 10, "texto": "Então se acendeu a ira de Balaque contra Balaão, e batendo suas palmas lhe disse: Para amaldiçoar a meus inimigos te chamei, e eis que os abençoaste insistentemente já três vezes."}, {"numero": 11, "texto": "Foge-te, portanto, agora a teu lugar: eu disse que te honraria, mas eis que o SENHOR te privou de honra."}, {"numero": 12, "texto": "E Balaão lhe respondeu: Não o declarei eu também a teus mensageiros que me enviaste, dizendo:"}, {"numero": 13, "texto": "Se Balaque me desse sua casa cheia de prata e ouro, eu não poderei transgredir o dito do SENHOR para fazer coisa boa nem má de minha vontade; mas o que o SENHOR falar, isso direi eu?"}, {"numero": 14, "texto": "Eis que eu me vou agora a meu povo: portanto, vem, te indicarei o que este povo há de fazer a teu povo nos últimos dias."}, {"numero": 15, "texto": "E tomou sua parábola, e disse: Disse Balaão filho de Beor, Disse o homem de olhos abertos:"}, {"numero": 16, "texto": "Disse o que ouviu os ditos do SENHOR, E o que sabe o conhecimento do Altíssimo, o que viu a visão do Todo-Poderoso; caído, mas abertos os olhos:"}, {"numero": 17, "texto": "Verei, mas não agora: O olharei, mas não de perto: Sairá estrela de Jacó, E se levantará cetro de Israel, E ferirá os cantos de Moabe, E destruirá a todos os filhos de Sete."}, {"numero": 18, "texto": "E será tomada Edom, Será também tomada Seir por seus inimigos, E Israel se portará corajosamente."}, {"numero": 19, "texto": "E o de Jacó será dominador, E destruirá da cidade o que restar."}, {"numero": 20, "texto": "E vendo a Amaleque, tomou sua parábola, e disse: Amaleque, cabeça de nações; Mas seu fim perecerá para sempre."}, {"numero": 21, "texto": "E vendo aos queneus, tomou sua parábola, e disse: Forte é tua habitação, Põe na rocha tua ninho:"}, {"numero": 22, "texto": "Que os queneus serão expulsos, Quando Assur te levará cativo."}, {"numero": 23, "texto": "Todavia tomou sua parábola, e disse: Ai! quem viverá quando fizer Deus estas coisas?"}, {"numero": 24, "texto": "E virão navios da costa de Quitim, E afligirão a Assur, afligirão também a Éber: Mas ele também perecerá para sempre."}, {"numero": 25, "texto": "Então se levantou Balaão, e se foi, e voltou-se a seu lugar: e também Balaque se foi por seu caminho."}]'::jsonb, 'Almeida Livre'),
  ('Nm', 24, 'en', '[{"numero": 1, "texto": "And when Balaam saw that it pleased the Lord to bless Israel, he went not, as at other times, to seek for enchantments, but he set his face toward the wilderness."}, {"numero": 2, "texto": "And Balaam lifted up his eyes, and he saw Israel abiding in his tents according to their tribes; and the spirit of God came upon him."}, {"numero": 3, "texto": "And he took up his parable, and said, Balaam the son of Beor hath said, and the man whose eyes are open hath said:"}, {"numero": 4, "texto": "He hath said, which heard the words of God, which saw the vision of the Almighty, falling into a trance, but having his eyes open:"}, {"numero": 5, "texto": "How goodly are thy tents, O Jacob, and thy tabernacles, O Israel!"}, {"numero": 6, "texto": "As the valleys are they spread forth, as gardens by the river''s side, as the trees of lign aloes which the Lord hath planted, and as cedar trees beside the waters."}, {"numero": 7, "texto": "He shall pour the water out of his buckets, and his seed shall be in many waters, and his king shall be higher than Agag, and his kingdom shall be exalted."}, {"numero": 8, "texto": "God brought him forth out of Egypt; he hath as it were the strength of an unicorn: he shall eat up the nations his enemies, and shall break their bones, and pierce them through with his arrows."}, {"numero": 9, "texto": "He couched, he lay down as a lion, and as a great lion: who shall stir him up? Blessed is he that blesseth thee, and cursed is he that curseth thee."}, {"numero": 10, "texto": "And Balak''s anger was kindled against Balaam, and he smote his hands together: and Balak said unto Balaam, I called thee to curse mine enemies, and, behold, thou hast altogether blessed them these three times."}, {"numero": 11, "texto": "Therefore now flee thou to thy place: I thought to promote thee unto great honour; but, lo, the Lord hath kept thee back from honour."}, {"numero": 12, "texto": "And Balaam said unto Balak, Spake I not also to thy messengers which thou sentest unto me, saying,"}, {"numero": 13, "texto": "If Balak would give me his house full of silver and gold, I cannot go beyond the commandment of the Lord, to do either good or bad of mine own mind; but what the Lord saith, that will I speak?"}, {"numero": 14, "texto": "And now, behold, I go unto my people: come therefore, and I will advertise thee what this people shall do to thy people in the latter days."}, {"numero": 15, "texto": "And he took up his parable, and said, Balaam the son of Beor hath said, and the man whose eyes are open hath said:"}, {"numero": 16, "texto": "He hath said, which heard the words of God, and knew the knowledge of the most High, which saw the vision of the Almighty, falling into a trance, but having his eyes open:"}, {"numero": 17, "texto": "I shall see him, but not now: I shall behold him, but not nigh: there shall come a Star out of Jacob, and a Sceptre shall rise out of Israel, and shall smite the corners of Moab, and destroy all the children of Sheth."}, {"numero": 18, "texto": "And Edom shall be a possession, Seir also shall be a possession for his enemies; and Israel shall do valiantly."}, {"numero": 19, "texto": "Out of Jacob shall come he that shall have dominion, and shall destroy him that remaineth of the city."}, {"numero": 20, "texto": "And when he looked on Amalek, he took up his parable, and said, Amalek was the first of the nations; but his latter end shall be that he perish for ever."}, {"numero": 21, "texto": "And he looked on the Kenites, and took up his parable, and said, Strong is thy dwellingplace, and thou puttest thy nest in a rock."}, {"numero": 22, "texto": "Nevertheless the Kenite shall be wasted, until Asshur shall carry thee away captive."}, {"numero": 23, "texto": "And he took up his parable, and said, Alas, who shall live when God doeth this!"}, {"numero": 24, "texto": "And ships shall come from the coast of Chittim, and shall afflict Asshur, and shall afflict Eber, and he also shall perish for ever."}, {"numero": 25, "texto": "And Balaam rose up, and went and returned to his place: and Balak also went his way."}]'::jsonb, 'King James Version'),
  ('Nm', 24, 'fr', '[{"numero": 1, "texto": "Balaam vit que l''''Eternel trouvait bon de bénir Israël, et il n''''alla point comme les autres fois, à la rencontre des enchantements; mais il tourna son visage du côté du désert."}, {"numero": 2, "texto": "Balaam leva les yeux, et vit Israël campé selon ses tribus. Alors l''''esprit de Dieu fut sur lui."}, {"numero": 3, "texto": "Balaam prononça son oracle, et dit: Parole de Balaam, fils de Beor, Parole de l''''homme qui a l''''oeil ouvert,"}, {"numero": 4, "texto": "Parole de celui qui entend les paroles de Dieu, De celui qui voit la vision du Tout-Puissant, De celui qui se prosterne et dont les yeux s''''ouvrent."}, {"numero": 5, "texto": "Qu''''elles sont belles, tes tentes, ô Jacob! Tes demeures, ô Israël!"}, {"numero": 6, "texto": "Elles s''''étendent comme des vallées, Comme des jardins près d''''un fleuve, Comme des aloès que l''''Eternel a plantés, Comme des cèdres le long des eaux."}, {"numero": 7, "texto": "L''''eau coule de ses seaux, Et sa semence est fécondée par d''''abondantes eaux. Son roi s''''élève au-dessus d''''Agag, Et son royaume devient puissant."}, {"numero": 8, "texto": "Dieu l''''a fait sortir d''''Egypte, Il est pour lui comme la vigueur du buffle. Il dévore les nations qui s''''élèvent contre lui, Il brise leurs os, et les abat de ses flèches."}, {"numero": 9, "texto": "Il ploie les genoux, il se couche comme un lion, comme une lionne: Qui le fera lever? Béni soit quiconque te bénira, Et maudit soit quiconque te maudira!"}, {"numero": 10, "texto": "La colère de Balak s''''enflamma contre Balaam; il frappa des mains, et dit à Balaam: C''''est pour maudire mes ennemis que je t''''ai appelé, et voici, tu les as bénis déjà trois fois."}, {"numero": 11, "texto": "Fuis maintenant, va-t''''en chez toi! J''''avais dit que je te rendrais des honneurs, mais l''''Eternel t''''empêche de les recevoir."}, {"numero": 12, "texto": "Balaam répondit à Balak: Eh! n''''ai-je pas dit aux messagers que tu m''''as envoyés:"}, {"numero": 13, "texto": "Quand Balak me donnerait sa maison pleine d''''argent et d''''or, je ne pourrais faire de moi-même ni bien ni mal contre l''''ordre de l''''Eternel; je répéterai ce que dira l''''Eternel?"}, {"numero": 14, "texto": "Et maintenant voici, je m''''en vais vers mon peuple. Viens, je t''''annoncerai ce que ce peuple fera à ton peuple dans la suite des temps."}, {"numero": 15, "texto": "Balaam prononça son oracle, et dit: Parole de Balaam, fils de Beor, Parole de l''''homme qui a l''''oeil ouvert,"}, {"numero": 16, "texto": "Parole de celui qui entend les paroles de Dieu, De celui qui connaît les desseins du Très-Haut, De celui qui voit la vision du Tout-Puissant, De celui qui se prosterne et dont les yeux s''''ouvrent."}, {"numero": 17, "texto": "Je le vois, mais non maintenant, Je le contemple, mais non de près. Un astre sort de Jacob, Un sceptre s''''élève d''''Israël. Il perce les flancs de Moab, Et il abat tous les enfants de Seth."}, {"numero": 18, "texto": "Il se rend maître d''''Edom, Il se rend maître de Séir, ses ennemis. Israël manifeste sa force."}, {"numero": 19, "texto": "Celui qui sort de Jacob règne en souverain, Il fait périr ceux qui s''''échappent des villes."}, {"numero": 20, "texto": "Balaam vit Amalek. Il prononça son oracle, et dit: Amalek est la première des nations, Mais un jour il sera détruit."}, {"numero": 21, "texto": "Balaam vit les Kéniens. Il prononça son oracle, et dit: Ta demeure est solide, Et ton nid posé sur le roc."}, {"numero": 22, "texto": "Mais le Kénien sera chassé, Quand l''''Assyrien t''''emmènera captif."}, {"numero": 23, "texto": "Balaam prononça son oracle, et dit: Hélas! qui vivra après que Dieu l''''aura établi?"}, {"numero": 24, "texto": "Mais des navires viendront de Kittim, Ils humilieront l''''Assyrien, ils humilieront l''''Hébreu; Et lui aussi sera détruit."}, {"numero": 25, "texto": "Balaam se leva, partit, et retourna chez lui. Balak s''''en alla aussi de son côté."}]'::jsonb, 'Louis Segond 1910'),
  ('Nm', 24, 'es', '[{"numero": 1, "texto": "Y COMO vió Balaam que parecía bien á Jehová que él bendijese á Israel, no fué, como la primera y segunda vez, á encuentro de agüeros, sino que puso su rostro hacia el desierto;"}, {"numero": 2, "texto": "Y alzando sus ojos, vió á Israel alojado por sus tribus; y el espíritu de Dios vino sobre él."}, {"numero": 3, "texto": "Entonces tomó su parábola, y dijo: Dijo Balaam hijo de Beor, y dijo el varón de ojos abiertos:"}, {"numero": 4, "texto": "Dijo el que oyó los dichos de Dios, el que vió la visión del Omnipotente; caído, mas abiertos los ojos:"}, {"numero": 5, "texto": "¡Cuán hermosas son tus tiendas, oh Jacob, tus habitaciones, oh Israel!"}, {"numero": 6, "texto": "Como arroyos están extendidas, como huertos junto al río, como lináloes plantados por Jehová, como cedros junto á las aguas."}, {"numero": 7, "texto": "De sus manos destilarán aguas, y su simiente será en muchas aguas: y ensalzarse ha su rey más que Agag, y su reino será ensalzado."}, {"numero": 8, "texto": "Dios lo sacó de Egipto; tiene fuerzas como de unicornio: comerá á las gentes sus enemigas, y desmenuzará sus huesos, y asaeteará con sus saetas."}, {"numero": 9, "texto": "Se encorvará para echarse como león, y como leona; ¿quién lo despertará? Benditos los que te bendijeren, y malditos los que te maldijeren."}, {"numero": 10, "texto": "Entonces se encendió la ira de Balac contra Balaam, y batiendo sus palmas le dijo: Para maldecir á mis enemigos te he llamado, y he aquí los has resueltamente bendecido ya tres veces."}, {"numero": 11, "texto": "Húyete, por tanto, ahora á tu lugar: yo dije que te honraría, mas he aquí que Jehová te ha privado de honra."}, {"numero": 12, "texto": "Y Balaam le respondió: ¿No lo declaré yo también á tus mensajeros que me enviaste, diciendo:"}, {"numero": 13, "texto": "Si Balac me diese su casa llena de plata y oro, yo no podré traspasar el dicho de Jehová para hacer cosa buena ni mala de mi arbitrio; mas lo que Jehová hablare, eso diré yo?"}, {"numero": 14, "texto": "He aquí yo me voy ahora á mi pueblo: por tanto, ven, te indicaré lo que este pueblo ha de hacer á tu pueblo en los postrimeros días."}, {"numero": 15, "texto": "Y tomó su parábola, y dijo: Dijo Balaam hijo de Beor, dijo el varón de ojos abiertos:"}, {"numero": 16, "texto": "Dijo el que oyó los dichos de Jehová, y el que sabe la ciencia del Altísimo, el que vió la visión del Omnipotente; caído, mas abiertos los ojos:"}, {"numero": 17, "texto": "Verélo, mas no ahora: lo miraré, mas no de cerca: saldrá ESTRELLA de Jacob, y levantaráse cetro de Israel, y herirá los cantones de Moab, y destruirá á todos los hijos de Seth."}, {"numero": 18, "texto": "Y será tomada Edom, será también tomada Seir por sus enemigos, e Israel se portará varonilmente."}, {"numero": 19, "texto": "Y el de Jacob se enseñoreará, y destruirá de la ciudad lo que quedare."}, {"numero": 20, "texto": "Y viendo á Amalec, tomó su parábola, y dijo: Amalec, cabeza de gentes; mas su postrimería perecerá para siempre."}, {"numero": 21, "texto": "Y viendo al Cineo, tomó su parábola, y dijo: Fuerte es tu habitación, pon en la peña tu nido:"}, {"numero": 22, "texto": "Que el Cineo será echado, cuando Assur te llevará cautivo."}, {"numero": 23, "texto": "Todavía tomó su parábola, y dijo: ¡Ay! ¿quién vivirá cuando hiciere Dios estas cosas?"}, {"numero": 24, "texto": "Y vendrán navíos de la costa de Cittim, y afligirán á Assur, afligirán también á Eber: mas él también perecerá para siempre."}, {"numero": 25, "texto": "Entonces se levantó Balaam, y se fué, y volvióse á su lugar: y también Balac se fué por su camino."}]'::jsonb, 'Reina-Valera 1909'),
  ('Nm', 35, 'pt', '[{"numero": 1, "texto": "E falou o SENHOR a Moisés nos campos de Moabe, junto ao Jordão de Jericó, dizendo:"}, {"numero": 2, "texto": "Manda aos filhos de Israel, que deem aos levitas da possessão de sua herança cidades em que habitem: Também dareis aos levitas campos de essas cidades ao redor delas."}, {"numero": 3, "texto": "E terão eles as cidades para habitar, e os campos delas serão para seus animais, e para seus gados, e para todos seus animais."}, {"numero": 4, "texto": "E os campos das cidades que dareis aos levitas, serão mil côvados ao redor, desde o muro da cidade para fora."}, {"numero": 5, "texto": "Logo medireis fora da cidade à parte do oriente dois mil côvados, e à parte do sul dois mil côvados, e à parte do ocidente dois mil côvados, e à parte do norte dois mil côvados, e a cidade em meio: isto terão pelos campos das cidades."}, {"numero": 6, "texto": "E das cidades que dareis aos levitas, seis cidades serão de refúgio, as quais dareis para que o homicida se acolha ali: e também destas dareis quarenta e duas cidades."}, {"numero": 7, "texto": "Todas as cidades que dareis aos levitas serão quarenta e oito cidades; elas com seus campos."}, {"numero": 8, "texto": "E as cidades que deres da herança dos filhos de Israel, do que muito tomareis muito, e do que pouco tomareis pouco: cada um dará de suas cidades aos levitas segundo a possessão que herdará."}, {"numero": 9, "texto": "E falou o SENHOR a Moisés, dizendo:"}, {"numero": 10, "texto": "Fala aos filhos de Israel, e dize-lhes: Quando houverdes passado o Jordão à terra de Canaã,"}, {"numero": 11, "texto": "Assinalareis para vós cidades, tereis cidades de refúgio, para onde fuja o homicida que ferir a algum de morte por acidente."}, {"numero": 12, "texto": "E vos serão aquelas cidades por refúgio do parente, e não morrerá o homicida até que esteja a juízo diante da congregação."}, {"numero": 13, "texto": "Das cidades, pois, que dareis, tereis seis cidades de refúgio."}, {"numero": 14, "texto": "Três cidades dareis desta parte do Jordão, e três cidades dareis na terra de Canaã; as quais serão cidades de refúgio."}, {"numero": 15, "texto": "Estas seis cidades serão para refúgio aos filhos de Israel, e ao peregrino, e ao que morar entre eles, para que fuja ali qualquer um que ferir de morte a outro por acidente."}, {"numero": 16, "texto": "E se com instrumento de ferro o ferir e morrer, homicida é; o homicida morrerá:"}, {"numero": 17, "texto": "E se com pedra da mão, de que podia morrer, o ferir, e morrer, homicida é; o homicida morrerá."}, {"numero": 18, "texto": "E se com instrumento de madeira da mão, de que podia morrer, o ferir, e morrer, homicida é; o homicida morrerá."}, {"numero": 19, "texto": "O parente do morto, ele matará ao homicida: quando o encontrar, ele lhe matará."}, {"numero": 20, "texto": "E se por ódio o empurrou, ou lançou sobre ele alguma coisa por ciladas, e morre;"}, {"numero": 21, "texto": "Ou por inimizade o feriu com sua mão, e morreu: o feridor morrerá; é homicida; o parente do morto matará ao homicida, quando o encontrar."}, {"numero": 22, "texto": "Mas se casualmente o empurrou sem inimizades, ou lançou sobre ele qualquer instrumento sem más intenções,"}, {"numero": 23, "texto": "Ou bem, sem vê-lo, fez cair sobre ele alguma pedra, de que possa morrer, e morrer, e ele não era seu inimigo, nem procurava seu mal;"}, {"numero": 24, "texto": "Então a congregação julgará entre o feridor e o parente do morto conforme estas leis:"}, {"numero": 25, "texto": "E a congregação livrará ao homicida da mão do parente do morto, e a congregação o fará voltar à seu cidade de refúgio, à qual se havia acolhido; e morará nela até que morra o sumo sacerdote, o qual foi ungido com o azeite santo."}, {"numero": 26, "texto": "E se o homicida sair fora do termo de sua cidade de refúgio, à qual se refugiou,"}, {"numero": 27, "texto": "E o parente do morto lhe achar fora do termo da cidade de sua acolhida, e o parente do morto ao homicida matar, não se lhe culpará por isso:"}, {"numero": 28, "texto": "Pois em sua cidade de refúgio deverá aquele habitar até que morra o sumo sacerdote: e depois que morrer o sumo sacerdote, o homicida voltará à terra de sua possessão."}, {"numero": 29, "texto": "E estas coisas vos serão por ordenança de regulamento por vossas gerações, em todas as vossas habitações."}, {"numero": 30, "texto": "Qualquer um que ferir a alguém, por dito de testemunhas, morrerá o homicida: mas uma só testemunha não fará fé contra alguma pessoa para que morra."}, {"numero": 31, "texto": "E não tomareis preço pela vida do homicida; porque está condenado a morte: mas inevitavelmente morrerá."}, {"numero": 32, "texto": "Nem tampouco tomareis preço do que fugiu à sua cidade de refúgio, para que volte a viver em sua terra, até que morra o sacerdote."}, {"numero": 33, "texto": "E não contaminareis a terra onde estiverdes: porque este sangue profanará a terra: e a terra não será expiada do sangue que foi derramado nela, a não ser pelo sangue do que a derramou."}, {"numero": 34, "texto": "Não contamineis, pois, a terra onde habitais, em meio da qual eu habito; porque eu o SENHOR habito em meio dos filhos de Israel."}]'::jsonb, 'Almeida Livre'),
  ('Nm', 35, 'en', '[{"numero": 1, "texto": "And the Lord spake unto Moses in the plains of Moab by Jordan near Jericho, saying,"}, {"numero": 2, "texto": "Command the children of Israel, that they give unto the Levites of the inheritance of their possession cities to dwell in; and ye shall give also unto the Levites suburbs for the cities round about them."}, {"numero": 3, "texto": "And the cities shall they have to dwell in; and the suburbs of them shall be for their cattle, and for their goods, and for all their beasts."}, {"numero": 4, "texto": "And the suburbs of the cities, which ye shall give unto the Levites, shall reach from the wall of the city and outward a thousand cubits round about."}, {"numero": 5, "texto": "And ye shall measure from without the city on the east side two thousand cubits, and on the south side two thousand cubits, and on the west side two thousand cubits, and on the north side two thousand cubits; and the city shall be in the midst: this shall be to them the suburbs of the cities."}, {"numero": 6, "texto": "And among the cities which ye shall give unto the Levites there shall be six cities for refuge, which ye shall appoint for the manslayer, that he may flee thither: and to them ye shall add forty and two cities."}, {"numero": 7, "texto": "So all the cities which ye shall give to the Levites shall be forty and eight cities: them shall ye give with their suburbs."}, {"numero": 8, "texto": "And the cities which ye shall give shall be of the possession of the children of Israel: from them that have many ye shall give many; but from them that have few ye shall give few: every one shall give of his cities unto the Levites according to his inheritance which he inheriteth."}, {"numero": 9, "texto": "And the Lord spake unto Moses, saying,"}, {"numero": 10, "texto": "Speak unto the children of Israel, and say unto them, When ye be come over Jordan into the land of Canaan;"}, {"numero": 11, "texto": "Then ye shall appoint you cities to be cities of refuge for you; that the slayer may flee thither, which killeth any person at unawares."}, {"numero": 12, "texto": "And they shall be unto you cities for refuge from the avenger; that the manslayer die not, until he stand before the congregation in judgment."}, {"numero": 13, "texto": "And of these cities which ye shall give six cities shall ye have for refuge."}, {"numero": 14, "texto": "Ye shall give three cities on this side Jordan, and three cities shall ye give in the land of Canaan, which shall be cities of refuge."}, {"numero": 15, "texto": "These six cities shall be a refuge, both for the children of Israel, and for the stranger, and for the sojourner among them: that every one that killeth any person unawares may flee thither."}, {"numero": 16, "texto": "And if he smite him with an instrument of iron, so that he die, he is a murderer: the murderer shall surely be put to death."}, {"numero": 17, "texto": "And if he smite him with throwing a stone, wherewith he may die, and he die, he is a murderer: the murderer shall surely be put to death."}, {"numero": 18, "texto": "Or if he smite him with an hand weapon of wood, wherewith he may die, and he die, he is a murderer: the murderer shall surely be put to death."}, {"numero": 19, "texto": "The revenger of blood himself shall slay the murderer: when he meeteth him, he shall slay him."}, {"numero": 20, "texto": "But if he thrust him of hatred, or hurl at him by laying of wait, that he die;"}, {"numero": 21, "texto": "Or in enmity smite him with his hand, that he die: he that smote him shall surely be put to death; for he is a murderer: the revenger of blood shall slay the murderer, when he meeteth him."}, {"numero": 22, "texto": "But if he thrust him suddenly without enmity, or have cast upon him any thing without laying of wait,"}, {"numero": 23, "texto": "Or with any stone, wherewith a man may die, seeing him not, and cast it upon him, that he die, and was not his enemy, neither sought his harm:"}, {"numero": 24, "texto": "Then the congregation shall judge between the slayer and the revenger of blood according to these judgments:"}, {"numero": 25, "texto": "And the congregation shall deliver the slayer out of the hand of the revenger of blood, and the congregation shall restore him to the city of his refuge, whither he was fled: and he shall abide in it unto the death of the high priest, which was anointed with the holy oil."}, {"numero": 26, "texto": "But if the slayer shall at any time come without the border of the city of his refuge, whither he was fled;"}, {"numero": 27, "texto": "And the revenger of blood find him without the borders of the city of his refuge, and the revenger of blood kill the slayer; he shall not be guilty of blood:"}, {"numero": 28, "texto": "Because he should have remained in the city of his refuge until the death of the high priest: but after the death of the high priest the slayer shall return into the land of his possession."}, {"numero": 29, "texto": "So these things shall be for a statute of judgment unto you throughout your generations in all your dwellings."}, {"numero": 30, "texto": "Whoso killeth any person, the murderer shall be put to death by the mouth of witnesses: but one witness shall not testify against any person to cause him to die."}, {"numero": 31, "texto": "Moreover ye shall take no satisfaction for the life of a murderer, which is guilty of death: but he shall be surely put to death."}, {"numero": 32, "texto": "And ye shall take no satisfaction for him that is fled to the city of his refuge, that he should come again to dwell in the land, until the death of the priest."}, {"numero": 33, "texto": "So ye shall not pollute the land wherein ye are: for blood it defileth the land: and the land cannot be cleansed of the blood that is shed therein, but by the blood of him that shed it."}, {"numero": 34, "texto": "Defile not therefore the land which ye shall inhabit, wherein I dwell: for I the Lord dwell among the children of Israel."}]'::jsonb, 'King James Version'),
  ('Nm', 35, 'fr', '[{"numero": 1, "texto": "L''''Eternel parla à Moïse, dans les plaines de Moab, près du Jourdain, vis-à-vis de Jéricho. Il dit:"}, {"numero": 2, "texto": "Ordonne aux enfants d''''Israël d''''accorder aux Lévites, sur l''''héritage qu''''ils posséderont, des villes où ils puissent habiter. Vous donnerez aussi aux Lévites une banlieue autour de ces villes."}, {"numero": 3, "texto": "Ils auront les villes pour y habiter; et les banlieues seront pour leur bétail, pour leurs biens et pour tous leurs animaux."}, {"numero": 4, "texto": "Les banlieues des villes que vous donnerez aux Lévites auront, à partir du mur de la ville et au dehors, mille coudées tout autour."}, {"numero": 5, "texto": "Vous mesurerez, en dehors de la ville, deux mille coudées pour le côté oriental, deux mille coudées pour le côté méridional, deux mille coudées pour le côté occidental, et deux mille coudées pour le côté septentrional. La ville sera au milieu. Telles seront les banlieues de leurs villes."}, {"numero": 6, "texto": "Parmi les villes que vous donnerez aux Lévites, il y aura six villes de refuge où pourra s''''enfuir le meurtrier, et quarante-deux autres villes."}, {"numero": 7, "texto": "Total des villes que vous donnerez aux Lévites: quarante-huit villes, avec leurs banlieues."}, {"numero": 8, "texto": "Les villes que vous donnerez sur les propriétés des enfants d''''Israël seront livrées en plus grand nombre par ceux qui en ont le plus, et en plus petit nombre par ceux qui en ont moins; chacun donnera de ses villes aux Lévites à proportion de l''''héritage qu''''il possédera."}, {"numero": 9, "texto": "L''''Eternel parla à Moïse, et dit:"}, {"numero": 10, "texto": "Parle aux enfants d''''Israël, et dis-leur: Lorsque vous aurez passé le Jourdain et que vous serez entrés dans le pays de Canaan,"}, {"numero": 11, "texto": "vous vous établirez des villes qui soient pour vous des villes de refuge, où pourra s''''enfuir le meurtrier qui aura tué quelqu''''un involontairement."}, {"numero": 12, "texto": "Ces villes vous serviront de refuge contre le vengeur du sang, afin que le meurtrier ne soit point mis à mort avant d''''avoir comparu devant l''''assemblée pour être jugé."}, {"numero": 13, "texto": "Des villes que vous donnerez, six seront pour vous des villes de refuge."}, {"numero": 14, "texto": "Vous donnerez trois villes au delà du Jourdain, et vous donnerez trois villes dans le pays de Canaan: ce seront des villes de refuge."}, {"numero": 15, "texto": "Ces six villes serviront de refuge aux enfants d''''Israël, à l''''étranger et à celui qui demeure au milieu de vous: là pourra s''''enfuir tout homme qui aura tué quelqu''''un involontairement."}, {"numero": 16, "texto": "Si un homme frappe son prochain avec un instrument de fer, et que la mort en soit la suite, c''''est un meurtrier: le meurtrier sera puni de mort."}, {"numero": 17, "texto": "S''''il le frappe, tenant à la main une pierre qui puisse causer la mort, et que la mort en soit la suite, c''''est un meurtrier: le meurtrier sera puni de mort."}, {"numero": 18, "texto": "S''''il le frappe, tenant à la main un instrument de bois qui puisse causer la mort, et que la mort en soit la suite, c''''est un meurtrier: le meurtrier sera puni de mort."}, {"numero": 19, "texto": "Le vengeur du sang fera mourir le meurtrier; quand il le rencontrera, il le tuera."}, {"numero": 20, "texto": "Si un homme pousse son prochain par un mouvement de haine, ou s''''il jette quelque chose sur lui avec préméditation, et que la mort en soit la suite,"}, {"numero": 21, "texto": "ou s''''il le frappe de sa main par inimitié, et que la mort en soit la suite, celui qui a frappé sera puni de mort, c''''est un meurtrier: le vengeur du sang tuera le meurtrier, quand il le rencontrera."}, {"numero": 22, "texto": "Mais si un homme pousse son prochain subitement et non par inimitié, ou s''''il jette quelque chose sur lui sans préméditation,"}, {"numero": 23, "texto": "ou s''''il fait tomber sur lui par mégarde une pierre qui puisse causer la mort, et que la mort en soit la suite, sans qu''''il ait de la haine contre lui et qu''''il lui cherche du mal,"}, {"numero": 24, "texto": "voici les lois d''''après lesquelles l''''assemblée jugera entre celui qui a frappé et le vengeur du sang."}, {"numero": 25, "texto": "L''''assemblée délivrera le meurtrier de la main du vengeur du sang, et le fera retourner dans la ville de refuge où il s''''était enfui. Il y demeurera jusqu''''à la mort du souverain sacrificateur qu''''on a oint de l''''huile sainte."}, {"numero": 26, "texto": "Si le meurtrier sort du territoire de la ville de refuge où il s''''est enfui,"}, {"numero": 27, "texto": "et si le vengeur du sang le rencontre hors du territoire de la ville de refuge et qu''''il tue le meurtrier, il ne sera point coupable de meurtre."}, {"numero": 28, "texto": "Car le meurtrier doit demeurer dans sa ville de refuge jusqu''''à la mort du souverain sacrificateur; et après la mort du souverain sacrificateur, il pourra retourner dans sa propriété."}, {"numero": 29, "texto": "Voici des ordonnances de droit pour vous et pour vos descendants, dans tous les lieux où vous habiterez."}, {"numero": 30, "texto": "Si un homme tue quelqu''''un, on ôtera la vie au meurtrier, sur la déposition de témoins. Un seul témoin ne suffira pas pour faire condamner une personne à mort."}, {"numero": 31, "texto": "Vous n''''accepterez point de rançon pour la vie d''''un meurtrier qui mérite la mort, car il sera puni de mort."}, {"numero": 32, "texto": "Vous n''''accepterez point de rançon, qui lui permette de s''''enfuir dans sa ville de refuge, et de retourner habiter dans le pays après la mort du sacrificateur."}, {"numero": 33, "texto": "Vous ne souillerez point le pays où vous serez, car le sang souille le pays; et il ne sera fait pour le pays aucune expiation du sang qui y sera répandu que par le sang de celui qui l''''aura répandu."}, {"numero": 34, "texto": "Vous ne souillerez point le pays où vous allez demeurer, et au milieu duquel j''''habiterai; car je suis l''''Eternel, qui habite au milieu des enfants d''''Israël."}]'::jsonb, 'Louis Segond 1910'),
  ('Nm', 35, 'es', '[{"numero": 1, "texto": "Y HABLÓ Jehová á Moisés en los campos de Moab, junto al Jordán de Jericó, diciendo:"}, {"numero": 2, "texto": "Manda á los hijos de Israel, que den á los Levitas de la posesión de su heredad ciudades en que habiten: también daréis á los Levitas los ejidos de esas ciudades alrededor de ellas."}, {"numero": 3, "texto": "Y tendrán ellos las ciudades para habitar, y los ejidos de ellas serán para sus animales, y para sus ganados, y para todas sus bestias."}, {"numero": 4, "texto": "Y los ejidos de las ciudades que daréis á los Levitas, serán mil codos alrededor, desde el muro de la ciudad para afuera."}, {"numero": 5, "texto": "Luego mediréis fuera de la ciudad á la parte del oriente dos mil codos, y á la parte del mediodía dos mil codos, y á la parte del occidente dos mil codos, y á la parte del norte dos mil codos, y la ciudad en medio: esto tendrán por los ejidos de las ciudades."}, {"numero": 6, "texto": "Y de las ciudades que daréis á los Levitas, seis ciudades serán de acogimiento, las cuales daréis para que el homicida se acoja allá: y además de éstas daréis cuarenta y dos ciudades."}, {"numero": 7, "texto": "Todas las ciudades que daréis á los Levitas serán cuarenta y ocho ciudades; ellas con sus ejidos."}, {"numero": 8, "texto": "Y las ciudades que diereis de la heredad de los hijos de Israel, del que mucho tomaréis mucho, y del que poco tomaréis poco: cada uno dará de sus ciudades á los Levitas según la posesión que heredará."}, {"numero": 9, "texto": "Y habló Jehová á Moisés, diciendo:"}, {"numero": 10, "texto": "Habla á los hijos de Israel, y diles: Cuando hubiereis pasado el Jordán á la tierra de Canaán,"}, {"numero": 11, "texto": "Os señalaréis ciudades, ciudades de acogimiento tendréis, donde huya el homicida que hiriere á alguno de muerte por yerro."}, {"numero": 12, "texto": "Y os serán aquellas ciudades por acogimiento del pariente, y no morirá el homicida hasta que esté á juicio delante de la congregación."}, {"numero": 13, "texto": "De las ciudades, pues, que daréis, tendréis seis ciudades de acogimiento."}, {"numero": 14, "texto": "Tres ciudades daréis de esta parte del Jordán, y tres ciudades daréis en la tierra de Canaán; las cuales serán ciudades de acogimiento."}, {"numero": 15, "texto": "Estas seis ciudades serán para acogimiento á los hijos de Israel, y al peregrino, y al que morare entre ellos, para que huya allá cualquiera que hiriere de muerte á otro por yerro."}, {"numero": 16, "texto": "Y si con instrumento de hierro lo hiriere y muriere, homicida es; el homicida morirá:"}, {"numero": 17, "texto": "Y si con piedra de mano, de que pueda morir, lo hiriere, y muriere, homicida es; el homicida morirá."}, {"numero": 18, "texto": "Y si con instrumento de palo de mano, de que pueda morir, lo hiriere, y muriere, homicida es; el homicida morirá."}, {"numero": 19, "texto": "El pariente del muerto, él matará al homicida: cuando lo encontrare, él le matará."}, {"numero": 20, "texto": "Y si por odio lo empujó, ó echó sobre él alguna cosa por asechanzas, y muere;"}, {"numero": 21, "texto": "O por enemistad lo hirió con su mano, y murió: el heridor morirá; es homicida; el pariente del muerto matará al homicida, cuando lo encontrare."}, {"numero": 22, "texto": "Mas si casualmente lo empujó sin enemistades, ó echó sobre él cualquier instrumento sin asechanzas,"}, {"numero": 23, "texto": "O bien, sin verlo, hizo caer sobre él alguna piedra, de que pudo morir, y muriere, y él no era su enemigo, ni procuraba su mal;"}, {"numero": 24, "texto": "Entonces la congregación juzgará entre el heridor y el pariente del muerto conforme á estas leyes:"}, {"numero": 25, "texto": "Y la congregación librará al homicida de mano del pariente del muerto, y la congregación lo hará volver á su ciudad de acogimiento, á la cual se había acogido; y morará en ella hasta que muera el gran sacerdote, el cual fué ungido con el aceite santo."}, {"numero": 26, "texto": "Y si el homicida saliere fuera del término de su ciudad de refugio, á la cual se acogió,"}, {"numero": 27, "texto": "Y el pariente del muerto le hallare fuera del término de la ciudad de su acogida, y el pariente del muerto al homicida matare, no se le culpará por ello:"}, {"numero": 28, "texto": "Pues en su ciudad de refugio deberá aquél habitar hasta que muera el gran sacerdote: y después que muriere el gran sacerdote, el homicida volverá á la tierra de su posesión."}, {"numero": 29, "texto": "Y estas cosas os serán por ordenanza de derecho por vuestras edades, en todas vuestras habitaciones."}, {"numero": 30, "texto": "Cualquiera que hiriere á alguno, por dicho de testigos, morirá el homicida: mas un solo testigo no hará fe contra alguna persona para que muera."}, {"numero": 31, "texto": "Y no tomaréis precio por la vida del homicida; porque está condenado á muerte: mas indefectiblemente morirá."}, {"numero": 32, "texto": "Ni tampoco tomaréis precio del que huyó á su ciudad de refugio, para que vuelva á vivir en su tierra, hasta que muera el sacerdote."}, {"numero": 33, "texto": "Y no contaminaréis la tierra donde estuviereis: porque esta sangre amancillará la tierra: y la tierra no será expiada de la sangre que fué derramada en ella, sino por la sangre del que la derramó."}, {"numero": 34, "texto": "No contaminéis, pues, la tierra donde habitáis, en medio de la cual yo habito; porque yo Jehová habito en medio de los hijos de Israel."}]'::jsonb, 'Reina-Valera 1909'),
  ('Pv', 1, 'pt', '[{"numero": 1, "texto": "Provérbios de Salomão, filho de Davi, rei de Israel."}, {"numero": 2, "texto": "Para conhecer a sabedoria e a instrução; para entender as palavras da prudência;"}, {"numero": 3, "texto": "Para obter a instrução do entendimento; justiça, juízo e equidades;"}, {"numero": 4, "texto": "Para dar inteligência aos simples, conhecimento e bom senso aos jovens."}, {"numero": 5, "texto": "O sábio ouvirá, e crescerá em conhecimento; o bom entendedor obterá sábios conselhos."}, {"numero": 6, "texto": "Para entender provérbios e [sua] interpretação; as palavras dos sábios, e seus enigmas."}, {"numero": 7, "texto": "O temor ao SENHOR [é] o principio do conhecimento; os tolos desprezam a sabedoria e a instrução."}, {"numero": 8, "texto": "Filho meu, ouve a instrução de teu pai; e não abandones a doutrina de tua mãe."}, {"numero": 9, "texto": "Porque [serão] um ornamento gracioso para tua cabeça; e colares para teu pescoço."}, {"numero": 10, "texto": "Filho meu, se os pecadores tentarem te convencer, não te deixes influenciar."}, {"numero": 11, "texto": "Se disserem: Vem conosco, vamos espiar [derramamento] de sangue; preparemos uma emboscada ao inocente sem razão."}, {"numero": 12, "texto": "Vamos tragá-los vivos, como o Xeol; e inteiros, como os que descem à cova."}, {"numero": 13, "texto": "Acharemos toda espécie de coisas valiosas, encheremos nossas casas de despojos."}, {"numero": 14, "texto": "Lança tua sorte entre nós, compartilharemos todos de uma [só] bolsa."}, {"numero": 15, "texto": "Filho meu, não sigas teu caminho com eles; desvia teu pé [para longe] de onde eles passarem;"}, {"numero": 16, "texto": "Porque os pés deles correm para o mal, e se apressam para derramar sangue."}, {"numero": 17, "texto": "Certamente [é] inútil se estender a rede diante da vista de todas as aves;"}, {"numero": 18, "texto": "Porém estes estão esperando [o derramamento] de seu [próprio] sangue; e preparam emboscada para suas [próprias] almas."}, {"numero": 19, "texto": "Assim [são] os caminhos de todo aquele que tem ganância pelo lucro desonesto; ela tomará a alma daqueles que a tem."}, {"numero": 20, "texto": "A sabedoria grita pelas ruas; nas praças ela levanta sua voz."}, {"numero": 21, "texto": "Ela clama nas encruzilhadas, onde [passam] muita gente; às entradas das portas, nas cidades ela diz suas mensagens:"}, {"numero": 22, "texto": "Até quando, ó tolos, amareis a tolice? E vós zombadores, desejareis a zombaria? E [vós] loucos, odiareis o conhecimento?"}, {"numero": 23, "texto": "Convertei-vos à minha repreensão; eis que vos derramarei meu espírito, [e] vos farei saber minhas palavras."}, {"numero": 24, "texto": "[Mas] porque eu clamei, e recusastes; estendi minha mão, e não houve quem desse atenção,"}, {"numero": 25, "texto": "E rejeitastes todo o meu conselho, e não quisestes minha repreensão,"}, {"numero": 26, "texto": "Também eu rirei em vosso sofrimento, [e] zombarei, quando vier vosso medo."}, {"numero": 27, "texto": "Quando vier vosso temor como tempestade, e a causa de vosso sofrimento como ventania, quando vier sobre vós a opressão e a angústia,"}, {"numero": 28, "texto": "Então clamarão a mim; porém eu não responderei; de madrugada me buscarão, porém não me acharão."}, {"numero": 29, "texto": "Porque odiaram o conhecimento; e escolheram não temer ao SENHOR."}, {"numero": 30, "texto": "Não concordaram com meu conselho, [e] desprezaram toda a minha repreensão."}, {"numero": 31, "texto": "Por isso comerão do fruto do seu [próprio] caminho, e se fartarão de seus [próprios] conselhos."}, {"numero": 32, "texto": "Pois o desvio dos tolos os matará, e a confiança dos loucos os destruirá."}, {"numero": 33, "texto": "Porém aquele que me ouvir habitará em segurança, e estará tranquilo do temor do mal."}]'::jsonb, 'Almeida Livre'),
  ('Pv', 1, 'en', '[{"numero": 1, "texto": "The proverbs of Solomon the son of David, king of Israel;"}, {"numero": 2, "texto": "To know wisdom and instruction; to perceive the words of understanding;"}, {"numero": 3, "texto": "To receive the instruction of wisdom, justice, and judgment, and equity;"}, {"numero": 4, "texto": "To give subtilty to the simple, to the young man knowledge and discretion."}, {"numero": 5, "texto": "A wise man will hear, and will increase learning; and a man of understanding shall attain unto wise counsels:"}, {"numero": 6, "texto": "To understand a proverb, and the interpretation; the words of the wise, and their dark sayings."}, {"numero": 7, "texto": "The fear of the Lord is the beginning of knowledge: but fools despise wisdom and instruction."}, {"numero": 8, "texto": "My son, hear the instruction of thy father, and forsake not the law of thy mother:"}, {"numero": 9, "texto": "For they shall be an ornament of grace unto thy head, and chains about thy neck."}, {"numero": 10, "texto": "My son, if sinners entice thee, consent thou not."}, {"numero": 11, "texto": "If they say, Come with us, let us lay wait for blood, let us lurk privily for the innocent without cause:"}, {"numero": 12, "texto": "Let us swallow them up alive as the grave; and whole, as those that go down into the pit:"}, {"numero": 13, "texto": "We shall find all precious substance, we shall fill our houses with spoil:"}, {"numero": 14, "texto": "Cast in thy lot among us; let us all have one purse:"}, {"numero": 15, "texto": "My son, walk not thou in the way with them; refrain thy foot from their path:"}, {"numero": 16, "texto": "For their feet run to evil, and make haste to shed blood."}, {"numero": 17, "texto": "Surely in vain the net is spread in the sight of any bird."}, {"numero": 18, "texto": "And they lay wait for their own blood; they lurk privily for their own lives."}, {"numero": 19, "texto": "So are the ways of every one that is greedy of gain; which taketh away the life of the owners thereof."}, {"numero": 20, "texto": "Wisdom crieth without; she uttereth her voice in the streets:"}, {"numero": 21, "texto": "She crieth in the chief place of concourse, in the openings of the gates: in the city she uttereth her words, saying,"}, {"numero": 22, "texto": "How long, ye simple ones, will ye love simplicity? and the scorners delight in their scorning, and fools hate knowledge?"}, {"numero": 23, "texto": "Turn you at my reproof: behold, I will pour out my spirit unto you, I will make known my words unto you."}, {"numero": 24, "texto": "Because I have called, and ye refused; I have stretched out my hand, and no man regarded;"}, {"numero": 25, "texto": "But ye have set at nought all my counsel, and would none of my reproof:"}, {"numero": 26, "texto": "I also will laugh at your calamity; I will mock when your fear cometh;"}, {"numero": 27, "texto": "When your fear cometh as desolation, and your destruction cometh as a whirlwind; when distress and anguish cometh upon you."}, {"numero": 28, "texto": "Then shall they call upon me, but I will not answer; they shall seek me early, but they shall not find me:"}, {"numero": 29, "texto": "For that they hated knowledge, and did not choose the fear of the Lord:"}, {"numero": 30, "texto": "They would none of my counsel: they despised all my reproof."}, {"numero": 31, "texto": "Therefore shall they eat of the fruit of their own way, and be filled with their own devices."}, {"numero": 32, "texto": "For the turning away of the simple shall slay them, and the prosperity of fools shall destroy them."}, {"numero": 33, "texto": "But whoso hearkeneth unto me shall dwell safely, and shall be quiet from fear of evil."}]'::jsonb, 'King James Version'),
  ('Pv', 1, 'fr', '[{"numero": 1, "texto": "Proverbes de Salomon, fils de David, roi d''''Israël,"}, {"numero": 2, "texto": "Pour connaître la sagesse et l''''instruction, Pour comprendre les paroles de l''''intelligence;"}, {"numero": 3, "texto": "Pour recevoir des leçons de bon sens, De justice, d''''équité et de droiture;"}, {"numero": 4, "texto": "Pour donner aux simples du discernement, Au jeune homme de la connaissance et de la réflexion."}, {"numero": 5, "texto": "Que le sage écoute, et il augmentera son savoir, Et celui qui est intelligent acquerra de l''''habileté,"}, {"numero": 6, "texto": "Pour saisir le sens d''''un proverbe ou d''''une énigme, Des paroles des sages et de leurs sentences."}, {"numero": 7, "texto": "La crainte de l''''Eternel est le commencement de la science; Les insensés méprisent la sagesse et l''''instruction."}, {"numero": 8, "texto": "Ecoute, mon fils, l''''instruction de ton père, Et ne rejette pas l''''enseignement de ta mère;"}, {"numero": 9, "texto": "Car c''''est une couronne de grâce pour ta tête, Et une parure pour ton cou."}, {"numero": 10, "texto": "Mon fils, si des pécheurs veulent te séduire, Ne te laisse pas gagner."}, {"numero": 11, "texto": "S''''ils disent: Viens avec nous! dressons des embûches, versons du sang, Tendons des pièges à celui qui se repose en vain sur son innocence,"}, {"numero": 12, "texto": "Engloutissons-les tout vifs, comme le séjour des morts, Et tout entiers, comme ceux qui descendent dans la fosse;"}, {"numero": 13, "texto": "Nous trouverons toute sorte de biens précieux, Nous remplirons de butin nos maisons;"}, {"numero": 14, "texto": "Tu auras ta part avec nous, Il n''''y aura qu''''une bourse pour nous tous!"}, {"numero": 15, "texto": "Mon fils, ne te mets pas en chemin avec eux, Détourne ton pied de leur sentier;"}, {"numero": 16, "texto": "Car leurs pieds courent au mal, Et ils ont hâte de répandre le sang."}, {"numero": 17, "texto": "Mais en vain jette-t-on le filet Devant les yeux de tout ce qui a des ailes;"}, {"numero": 18, "texto": "Et eux, c''''est contre leur propre sang qu''''ils dressent des embûches, C''''est à leur âme qu''''ils tendent des pièges."}, {"numero": 19, "texto": "Ainsi arrive-t-il à tout homme avide de gain; La cupidité cause la perte de ceux qui s''''y livrent."}, {"numero": 20, "texto": "La sagesse crie dans les rues, Elle élève sa voix dans les places:"}, {"numero": 21, "texto": "Elle crie à l''''entrée des lieux bruyants; Aux portes, dans la ville, elle fait entendre ses paroles:"}, {"numero": 22, "texto": "Jusqu''''à quand, stupides, aimerez-vous la stupidité? Jusqu''''à quand les moqueurs se plairont-ils à la moquerie, Et les insensés haïront-ils la science?"}, {"numero": 23, "texto": "Tournez-vous pour écouter mes réprimandes! Voici, je répandrai sur vous mon esprit, Je vous ferai connaître mes paroles..."}, {"numero": 24, "texto": "Puisque j''''appelle et que vous résistez, Puisque j''''étends ma main et que personne n''''y prend garde,"}, {"numero": 25, "texto": "Puisque vous rejetez tous mes conseils, Et que vous n''''aimez pas mes réprimandes,"}, {"numero": 26, "texto": "Moi aussi, je rirai quand vous serez dans le malheur, Je me moquerai quand la terreur vous saisira,"}, {"numero": 27, "texto": "Quand la terreur vous saisira comme une tempête, Et que le malheur vous enveloppera comme un tourbillon, Quand la détresse et l''''angoisse fondront sur vous."}, {"numero": 28, "texto": "Alors ils m''''appelleront, et je ne répondrai pas; Ils me chercheront, et ils ne me trouveront pas."}, {"numero": 29, "texto": "Parce qu''''ils ont haï la science, Et qu''''ils n''''ont pas choisi la crainte de l''''Eternel,"}, {"numero": 30, "texto": "Parce qu''''ils n''''ont point aimé mes conseils, Et qu''''ils ont dédaigné toutes mes réprimandes,"}, {"numero": 31, "texto": "Ils se nourriront du fruit de leur voie, Et ils se rassasieront de leurs propres conseils,"}, {"numero": 32, "texto": "Car la résistance des stupides les tue, Et la sécurité des insensés les perd;"}, {"numero": 33, "texto": "Mais celui qui m''''écoute reposera avec assurance, Il vivra tranquille et sans craindre aucun mal."}]'::jsonb, 'Louis Segond 1910'),
  ('Pv', 1, 'es', '[{"numero": 1, "texto": "LOS proverbios de Salomón, hijo de David, rey de Israel:"}, {"numero": 2, "texto": "Para entender sabiduría y doctrina; para conocer las razones prudentes;"}, {"numero": 3, "texto": "Para recibir el consejo de prudencia, justicia, y juicio y equidad;"}, {"numero": 4, "texto": "Para dar sagacidad á los simples, y á los jóvenes inteligencia y cordura."}, {"numero": 5, "texto": "Oirá el sabio, y aumentará el saber; y el entendido adquirirá consejo;"}, {"numero": 6, "texto": "Para entender parábola y declaración; palabras de sabios, y sus dichos oscuros."}, {"numero": 7, "texto": "El principio de la sabiduría es el temor de Jehová: los insensatos desprecian la sabiduría y la enseñanza."}, {"numero": 8, "texto": "Oye, hijo mío, la doctrina de tu padre, y no desprecies la dirección de tu madre:"}, {"numero": 9, "texto": "Porque adorno de gracia serán á tu cabeza, y collares á tu cuello."}, {"numero": 10, "texto": "Hijo mío, si los pecadores te quisieren engañar, no consientas."}, {"numero": 11, "texto": "Si dijeren: Ven con nosotros, pongamos asechanzas á la sangre, acechemos sin motivo al inocente;"}, {"numero": 12, "texto": "Los tragaremos vivos como el sepulcro, y enteros, como los que caen en sima;"}, {"numero": 13, "texto": "Hallaremos riquezas de todas suertes, henchiremos nuestras casas de despojos;"}, {"numero": 14, "texto": "Echa tu suerte entre nosotros; tengamos todos una bolsa:"}, {"numero": 15, "texto": "Hijo mío, no andes en camino con ellos; aparta tu pie de sus veredas:"}, {"numero": 16, "texto": "Porque sus pies correrán al mal, é irán presurosos á derramar sangre."}, {"numero": 17, "texto": "Porque en vano se tenderá la red ante los ojos de toda ave;"}, {"numero": 18, "texto": "Mas ellos á su propia sangre ponen asechanzas, y á sus almas tienden lazo."}, {"numero": 19, "texto": "Tales son las sendas de todo el que es dado á la codicia, la cual prenderá el alma de sus poseedores."}, {"numero": 20, "texto": "La sabiduría clama de fuera, da su voz en las plazas:"}, {"numero": 21, "texto": "Clama en los principales lugares de concurso; en las entradas de las puertas de la ciudad dice sus razones:"}, {"numero": 22, "texto": "¿Hasta cuándo, oh simples, amaréis la simpleza, y los burladores desearán el burlar, y los insensatos aborrecerán la ciencia?"}, {"numero": 23, "texto": "Volveos á mi reprensión: he aquí yo os derramaré mi espíritu, y os haré saber mis palabras."}, {"numero": 24, "texto": "Por cuanto llamé, y no quisisteis; extendí mi mano, y no hubo quien escuchase;"}, {"numero": 25, "texto": "Antes desechasteis todo consejo mío, y mi reprensión no quisisteis:"}, {"numero": 26, "texto": "También yo me reiré en vuestra calamidad, y me burlaré cuando os viniere lo que teméis;"}, {"numero": 27, "texto": "Cuando viniere como una destrucción lo que teméis, y vuestra calamidad llegare como un torbellino; cuando sobre vosotros viniere tribulación y angustia."}, {"numero": 28, "texto": "Entonces me llamarán, y no responderé; buscarme han de mañana, y no me hallarán:"}, {"numero": 29, "texto": "Por cuanto aborrecieron la sabiduría, y no escogieron el temor de Jehová,"}, {"numero": 30, "texto": "Ni quisieron mi consejo, y menospreciaron toda reprensión mía:"}, {"numero": 31, "texto": "Comerán pues del fruto de su camino, y se hartarán de sus consejos."}, {"numero": 32, "texto": "Porque el reposo de los ignorantes los matará, y la prosperidad de los necios los echará á perder."}, {"numero": 33, "texto": "Mas el que me oyere, habitará confiadamente, y vivirá reposado, sin temor de mal."}]'::jsonb, 'Reina-Valera 1909'),
  ('Pv', 3, 'pt', '[{"numero": 1, "texto": "Filho meu, não te esqueças de minha lei; e que teu coração guarde meus mandamentos."}, {"numero": 2, "texto": "Porque te acrescentarão extensão de dias, e anos de vida e paz."}, {"numero": 3, "texto": "Que a bondade e a fidelidade não te desamparem; amarra-as junto ao teu pescoço; escreve-as na tábua de teu coração."}, {"numero": 4, "texto": "Então tu acharás graça e bom entendimento, aos olhos de Deus e dos homens."}, {"numero": 5, "texto": "Confia no SENHOR com todo o teu coração; e não te apoies em teu [próprio] entendimento."}, {"numero": 6, "texto": "Dá reconhecimento a ele em todas os teus caminhos; e ele endireitará tuas veredas."}, {"numero": 7, "texto": "Não sejas sábio aos teus [próprios] olhos; teme ao SENHOR, e afasta-te do mal."}, {"numero": 8, "texto": "Isto será remédio para teu corpo, e alívio para teus ossos."}, {"numero": 9, "texto": "Honra ao SENHOR com teus bens, e com a primeira parte de toda a tua renda."}, {"numero": 10, "texto": "E teus celeiros se encherão de fartura, e tuas prensas de uvas transbordarão de vinho novo."}, {"numero": 11, "texto": "Filho meu, não rejeites a correção do SENHOR, nem te desagrades de sua repreensão;"}, {"numero": 12, "texto": "Porque o SENHOR repreende a quem ele ama, assim como o pai ao filho, [a quem] ele quer bem."}, {"numero": 13, "texto": "Bem-aventurado o homem que encontra sabedoria, e o homem que ganha conhecimento."}, {"numero": 14, "texto": "Porque seu produto é melhor que o produto da prata; e seu valor, mais do que o do ouro fino."}, {"numero": 15, "texto": "Ela é mais preciosa do que rubis; e tudo o que podes desejar não se pode comparar a ela."}, {"numero": 16, "texto": "Extensão de dias [há] em sua mão direita; em sua esquerda riquezas e honra."}, {"numero": 17, "texto": "Seus caminhos são caminhos agradáveis; e todas as suas veredas são paz."}, {"numero": 18, "texto": "Ela é uma árvore de vida para os que dela pegam; e bem-aventurados são todos os que a retêm."}, {"numero": 19, "texto": "O SENHOR com sabedoria fundou a terra; ele preparou os céus com a inteligência."}, {"numero": 20, "texto": "Com seu conhecimento se fenderam os abismos, e as nuvens gotejam orvalho."}, {"numero": 21, "texto": "Filho meu, que [estes] não se afastem de teus olhos; guarda a sabedoria e o bom-senso."}, {"numero": 22, "texto": "Porque serão vida para tua alma, e graça para teu pescoço."}, {"numero": 23, "texto": "Então andarás por teu caminho em segurança; e com teus pés não tropeçarás."}, {"numero": 24, "texto": "Quando te deitares, não terás medo; tu deitarás, e teu sono será suave."}, {"numero": 25, "texto": "Não temas o pavor repentino; nem da assolação dos perversos, quando vier."}, {"numero": 26, "texto": "Porque o SENHOR será tua esperança; e ele guardará teus pés para que não sejam presos."}, {"numero": 27, "texto": "Não detenhas o bem daqueles que possuem o direito, se tiveres em tuas mãos poder para o fazeres."}, {"numero": 28, "texto": "Não digas a teu próximo: Vai, e volta [depois] , que amanhã te darei; se tu tiveres contigo [o que ele te pede] ."}, {"numero": 29, "texto": "Não planejes o mal contra teu próximo, pois ele mora tendo confiança em ti."}, {"numero": 30, "texto": "Não brigues contra alguém sem motivo, se ele não fez mal contra ti."}, {"numero": 31, "texto": "Não tenhas inveja do homem violento, nem escolhas [seguir] algum dos caminhos dele."}, {"numero": 32, "texto": "Porque o SENHOR abomina os perversos; mas ele [guarda] o seu segredo com os justos."}, {"numero": 33, "texto": "A maldição do SENHOR [está] na casa do perverso; porém ele abençoa a morada dos justos."}, {"numero": 34, "texto": "Certamente ele zombará dos zombadores; mas dará graça aos humildes."}, {"numero": 35, "texto": "Os sábios herdarão honra; porém os loucos terão sobre si confusão."}]'::jsonb, 'Almeida Livre'),
  ('Pv', 3, 'en', '[{"numero": 1, "texto": "My son, forget not my law; but let thine heart keep my commandments:"}, {"numero": 2, "texto": "For length of days, and long life, and peace, shall they add to thee."}, {"numero": 3, "texto": "Let not mercy and truth forsake thee: bind them about thy neck; write them upon the table of thine heart:"}, {"numero": 4, "texto": "So shalt thou find favour and good understanding in the sight of God and man."}, {"numero": 5, "texto": "Trust in the Lord with all thine heart; and lean not unto thine own understanding."}, {"numero": 6, "texto": "In all thy ways acknowledge him, and he shall direct thy paths."}, {"numero": 7, "texto": "Be not wise in thine own eyes: fear the Lord, and depart from evil."}, {"numero": 8, "texto": "It shall be health to thy navel, and marrow to thy bones."}, {"numero": 9, "texto": "Honour the Lord with thy substance, and with the firstfruits of all thine increase:"}, {"numero": 10, "texto": "So shall thy barns be filled with plenty, and thy presses shall burst out with new wine."}, {"numero": 11, "texto": "My son, despise not the chastening of the Lord; neither be weary of his correction:"}, {"numero": 12, "texto": "For whom the Lord loveth he correcteth; even as a father the son in whom he delighteth."}, {"numero": 13, "texto": "Happy is the man that findeth wisdom, and the man that getteth understanding."}, {"numero": 14, "texto": "For the merchandise of it is better than the merchandise of silver, and the gain thereof than fine gold."}, {"numero": 15, "texto": "She is more precious than rubies: and all the things thou canst desire are not to be compared unto her."}, {"numero": 16, "texto": "Length of days is in her right hand; and in her left hand riches and honour."}, {"numero": 17, "texto": "Her ways are ways of pleasantness, and all her paths are peace."}, {"numero": 18, "texto": "She is a tree of life to them that lay hold upon her: and happy is every one that retaineth her."}, {"numero": 19, "texto": "The Lord by wisdom hath founded the earth; by understanding hath he established the heavens."}, {"numero": 20, "texto": "By his knowledge the depths are broken up, and the clouds drop down the dew."}, {"numero": 21, "texto": "My son, let not them depart from thine eyes: keep sound wisdom and discretion:"}, {"numero": 22, "texto": "So shall they be life unto thy soul, and grace to thy neck."}, {"numero": 23, "texto": "Then shalt thou walk in thy way safely, and thy foot shall not stumble."}, {"numero": 24, "texto": "When thou liest down, thou shalt not be afraid: yea, thou shalt lie down, and thy sleep shall be sweet."}, {"numero": 25, "texto": "Be not afraid of sudden fear, neither of the desolation of the wicked, when it cometh."}, {"numero": 26, "texto": "For the Lord shall be thy confidence, and shall keep thy foot from being taken."}, {"numero": 27, "texto": "Withhold not good from them to whom it is due, when it is in the power of thine hand to do it."}, {"numero": 28, "texto": "Say not unto thy neighbour, Go, and come again, and to morrow I will give; when thou hast it by thee."}, {"numero": 29, "texto": "Devise not evil against thy neighbour, seeing he dwelleth securely by thee."}, {"numero": 30, "texto": "Strive not with a man without cause, if he have done thee no harm."}, {"numero": 31, "texto": "Envy thou not the oppressor, and choose none of his ways."}, {"numero": 32, "texto": "For the froward is abomination to the Lord: but his secret is with the righteous."}, {"numero": 33, "texto": "The curse of the Lord is in the house of the wicked: but he blesseth the habitation of the just."}, {"numero": 34, "texto": "Surely he scorneth the scorners: but he giveth grace unto the lowly."}, {"numero": 35, "texto": "The wise shall inherit glory: but shame shall be the promotion of fools."}]'::jsonb, 'King James Version'),
  ('Pv', 3, 'fr', '[{"numero": 1, "texto": "Mon fils, n''''oublie pas mes enseignements, Et que ton coeur garde mes préceptes;"}, {"numero": 2, "texto": "Car ils prolongeront les jours et les années de ta vie, Et ils augmenteront ta paix."}, {"numero": 3, "texto": "Que la bonté et la fidélité ne t''''abandonnent pas; Lie-les à ton cou, écris-les sur la table de ton coeur."}, {"numero": 4, "texto": "Tu acquerras ainsi de la grâce et une raison saine, Aux yeux de Dieu et des hommes."}, {"numero": 5, "texto": "Confie-toi en l''''Eternel de tout ton coeur, Et ne t''''appuie pas sur ta sagesse;"}, {"numero": 6, "texto": "Reconnais-le dans toutes tes voies, Et il aplanira tes sentiers."}, {"numero": 7, "texto": "Ne sois point sage à tes propres yeux, Crains l''''Eternel, et détourne-toi du mal:"}, {"numero": 8, "texto": "Ce sera la santé pour tes muscles, Et un rafraîchissement pour tes os."}, {"numero": 9, "texto": "Honore l''''Eternel avec tes biens, Et avec les prémices de tout ton revenu:"}, {"numero": 10, "texto": "Alors tes greniers seront remplis d''''abondance, Et tes cuves regorgeront de moût."}, {"numero": 11, "texto": "Mon fils, ne méprise pas la correction de l''''Eternel, Et ne t''''effraie point de ses châtiments;"}, {"numero": 12, "texto": "Car l''''Eternel châtie celui qu''''il aime, Comme un père l''''enfant qu''''il chérit."}, {"numero": 13, "texto": "Heureux l''''homme qui a trouvé la sagesse, Et l''''homme qui possède l''''intelligence!"}, {"numero": 14, "texto": "Car le gain qu''''elle procure est préférable à celui de l''''argent, Et le profit qu''''on en tire vaut mieux que l''''or;"}, {"numero": 15, "texto": "Elle est plus précieuse que les perles, Elle a plus de valeur que tous les objets de prix."}, {"numero": 16, "texto": "Dans sa droite est une longue vie; Dans sa gauche, la richesse et la gloire."}, {"numero": 17, "texto": "Ses voies sont des voies agréables, Et tous ses sentiers sont paisibles."}, {"numero": 18, "texto": "Elle est un arbre de vie pour ceux qui la saisissent, Et ceux qui la possèdent sont heureux."}, {"numero": 19, "texto": "C''''est par la sagesse que l''''Eternel a fondé la terre, C''''est par l''''intelligence qu''''il a affermi les cieux;"}, {"numero": 20, "texto": "C''''est par sa science que les abîmes se sont ouverts, Et que les nuages distillent la rosée."}, {"numero": 21, "texto": "Mon fils, que ces enseignements ne s''''éloignent pas de tes yeux, Garde la sagesse et la réflexion:"}, {"numero": 22, "texto": "Elles seront la vie de ton âme, Et l''''ornement de ton cou."}, {"numero": 23, "texto": "Alors tu marcheras avec assurance dans ton chemin, Et ton pied ne heurtera pas."}, {"numero": 24, "texto": "Si tu te couches, tu seras sans crainte; Et quand tu seras couché, ton sommeil sera doux."}, {"numero": 25, "texto": "Ne redoute ni une terreur soudaine, Ni une attaque de la part des méchants;"}, {"numero": 26, "texto": "Car l''''Eternel sera ton assurance, Et il préservera ton pied de toute embûche."}, {"numero": 27, "texto": "Ne refuse pas un bienfait à celui qui y a droit, Quand tu as le pouvoir de l''''accorder."}, {"numero": 28, "texto": "Ne dis pas à ton prochain: Va et reviens, Demain je donnerai! quand tu as de quoi donner."}, {"numero": 29, "texto": "Ne médite pas le mal contre ton prochain, Lorsqu''''il demeure tranquillement près de toi."}, {"numero": 30, "texto": "Ne conteste pas sans motif avec quelqu''''un, Lorsqu''''il ne t''''a point fait de mal."}, {"numero": 31, "texto": "Ne porte pas envie à l''''homme violent, Et ne choisis aucune de ses voies."}, {"numero": 32, "texto": "Car l''''Eternel a en horreur les hommes pervers, Mais il est un ami pour les hommes droits;"}, {"numero": 33, "texto": "La malédiction de l''''Eternel est dans la maison du méchant, Mais il bénit la demeure des justes;"}, {"numero": 34, "texto": "Il se moque des moqueurs, Mais il fait grâce aux humbles;"}, {"numero": 35, "texto": "Les sages hériteront la gloire, Mais les insensés ont la honte en partage."}]'::jsonb, 'Louis Segond 1910'),
  ('Pv', 3, 'es', '[{"numero": 1, "texto": "HIJO mío, no te olvides de mi ley; y tu corazón guarde mis mandamientos:"}, {"numero": 2, "texto": "Porque largura de días, y años de vida y paz te aumentarán."}, {"numero": 3, "texto": "Misericordia y verdad no te desamparen; átalas á tu cuello, escríbelas en la tabla de tu corazón:"}, {"numero": 4, "texto": "Y hallarás gracia y buena opinión en los ojos de Dios y de los hombres."}, {"numero": 5, "texto": "Fíate de Jehová de todo tu corazón, y no estribes en tu prudencia."}, {"numero": 6, "texto": "Reconócelo en todos tus caminos, y él enderezará tus veredas."}, {"numero": 7, "texto": "No seas sabio en tu opinión: teme á Jehová, y apártate del mal;"}, {"numero": 8, "texto": "Porque será medicina á tu ombligo, y tuétano á tus huesos."}, {"numero": 9, "texto": "Honra á Jehová de tu sustancia, y de las primicias de todos tus frutos;"}, {"numero": 10, "texto": "Y serán llenas tus trojes con abundancia, y tus lagares rebosarán de mosto."}, {"numero": 11, "texto": "No deseches, hijo mío, el castigo de Jehová; ni te fatigues de su corrección:"}, {"numero": 12, "texto": "Porque al que ama castiga, como el padre al hijo á quien quiere."}, {"numero": 13, "texto": "Bienaventurado el hombre que halla la sabiduría, y que obtiene la inteligencia:"}, {"numero": 14, "texto": "Porque su mercadería es mejor que la mercadería de la plata, y sus frutos más que el oro fino."}, {"numero": 15, "texto": "Más preciosa es que las piedras preciosas; y todo lo que puedes desear, no se puede comparar á ella."}, {"numero": 16, "texto": "Largura de días está en su mano derecha; en su izquierda riquezas y honra."}, {"numero": 17, "texto": "Sus caminos son caminos deleitosos, y todas sus veredas paz."}, {"numero": 18, "texto": "Ella es árbol de vida á los que de ella asen: y bienaventurados son los que la mantienen."}, {"numero": 19, "texto": "Jehová con sabiduría fundó la tierra; afirmó los cielos con inteligencia."}, {"numero": 20, "texto": "Con su ciencia se partieron los abismos, y destilan el rocío los cielos."}, {"numero": 21, "texto": "Hijo mío, no se aparten estas cosas de tus ojos; guarda la ley y el consejo;"}, {"numero": 22, "texto": "Y serán vida á tu alma, y gracia á tu cuello."}, {"numero": 23, "texto": "Entonces andarás por tu camino confiadamente, y tu pie no tropezará."}, {"numero": 24, "texto": "Cuando te acostares, no tendrás temor; antes te acostarás, y tu sueño será suave."}, {"numero": 25, "texto": "No tendrás temor de pavor repentino, ni de la ruina de los impíos cuando viniere:"}, {"numero": 26, "texto": "Porque Jehová será tu confianza, y él preservará tu pie de ser preso."}, {"numero": 27, "texto": "No detengas el bien de sus dueños, cuando tuvieres poder para hacerlo."}, {"numero": 28, "texto": "No digas á tu prójimo: Ve, y vuelve, y mañana te daré; cuando tienes contigo qué darle."}, {"numero": 29, "texto": "No intentes mal contra tu prójimo, estando él confiado de ti."}, {"numero": 30, "texto": "No pleitees con alguno sin razón, si él no te ha hecho agravio."}, {"numero": 31, "texto": "No envidies al hombre injusto, ni escojas alguno de sus caminos."}, {"numero": 32, "texto": "Porque el perverso es abominado de Jehová: mas su secreto es con los rectos."}, {"numero": 33, "texto": "La maldición de Jehová está en la casa del impío; mas él bendecirá la morada de los justos."}, {"numero": 34, "texto": "Ciertamente él escarnecerá á los escarnecedores, y á los humildes dará gracia."}, {"numero": 35, "texto": "Los sabios heredarán honra: mas los necios sostendrán ignominia."}]'::jsonb, 'Reina-Valera 1909'),
  ('Pv', 4, 'pt', '[{"numero": 1, "texto": "Ouvi, filhos, a correção do pai; e prestai atenção, para que conheçais o entendimento."}, {"numero": 2, "texto": "Pois eu vos dou boa doutrina; não deixeis a minha lei."}, {"numero": 3, "texto": "Porque eu era filho do meu pai; tenro, e único perante a face de minha mãe."}, {"numero": 4, "texto": "E ele me ensinava, e me dizia: Que teu coração retenha minhas palavras; guarda meus mandamentos, e vive."}, {"numero": 5, "texto": "Adquire sabedoria, adquire entendimento; [e] não te esqueças nem te desvies das palavras de minha boca."}, {"numero": 6, "texto": "Não a abandones, e ela te guardará; ama-a, e ela te conservará."}, {"numero": 7, "texto": "O principal é a sabedoria; adquire sabedoria, e acima de tudo o que adquirires, adquire entendimento."}, {"numero": 8, "texto": "Exalta-a, e ela te exaltará; quando tu a abraçares, ela te honrará."}, {"numero": 9, "texto": "Ela dará a tua cabeça um ornamento gracioso; ela te entregará uma bela coroa."}, {"numero": 10, "texto": "Ouve, filho meu, e recebe minhas palavras; e elas te acrescentarão anos de vida."}, {"numero": 11, "texto": "Eu te ensino no caminho da sabedoria; [e] te faço andar pelos percursos direitos."}, {"numero": 12, "texto": "Quando tu andares, teus passos não se estreitarão; e se tu correres, não tropeçarás."}, {"numero": 13, "texto": "Toma a correção para si, e não [a] largues; guarda-a, porque ela [é] tua vida."}, {"numero": 14, "texto": "Não entres pela vereda dos perversos, nem andes pelo caminho dos maus."}, {"numero": 15, "texto": "Rejeita-o! Não passes por ele; desvia-te dele, e passa longe."}, {"numero": 16, "texto": "Pois eles não dormem se não fizerem o mal; e ficam sem sono, se não fizerem tropeçar [a alguém] ."}, {"numero": 17, "texto": "Porque comem pão da maldade, e bebem vinho de violências."}, {"numero": 18, "texto": "Mas o caminho dos justos é como a luz brilhante, que vai, e ilumina até o dia [ficar claro] por completo."}, {"numero": 19, "texto": "O caminho dos perversos é como a escuridão; não sabem nem em que tropeçam."}, {"numero": 20, "texto": "Filho meu, presta atenção às minhas palavras; e ouve as minhas instruções."}, {"numero": 21, "texto": "Não as deixes ficarem longe de teus olhos; guarda-as no meio de teu coração."}, {"numero": 22, "texto": "Porque são vida para aqueles que as encontram; e saúde para todo o seu corpo."}, {"numero": 23, "texto": "Acima de tudo o que se deve guardar, guarda o teu coração; porque dele [procedem] as saídas da vida."}, {"numero": 24, "texto": "Afasta de ti a perversidade da boca; e põe longe de ti a corrupção dos lábios."}, {"numero": 25, "texto": "Teus olhos olhem direito; tuas pálpebras estejam corretas diante de ti."}, {"numero": 26, "texto": "Pondera o curso de teus pés; e todos os teus caminhos sejam bem ordenados."}, {"numero": 27, "texto": "Não te desvies nem para a direita, nem para a esquerda; afasta teus pés do mal."}]'::jsonb, 'Almeida Livre'),
  ('Pv', 4, 'en', '[{"numero": 1, "texto": "Hear, ye children, the instruction of a father, and attend to know understanding."}, {"numero": 2, "texto": "For I give you good doctrine, forsake ye not my law."}, {"numero": 3, "texto": "For I was my father''s son, tender and only beloved in the sight of my mother."}, {"numero": 4, "texto": "He taught me also, and said unto me, Let thine heart retain my words: keep my commandments, and live."}, {"numero": 5, "texto": "Get wisdom, get understanding: forget it not; neither decline from the words of my mouth."}, {"numero": 6, "texto": "Forsake her not, and she shall preserve thee: love her, and she shall keep thee."}, {"numero": 7, "texto": "Wisdom is the principal thing; therefore get wisdom: and with all thy getting get understanding."}, {"numero": 8, "texto": "Exalt her, and she shall promote thee: she shall bring thee to honour, when thou dost embrace her."}, {"numero": 9, "texto": "She shall give to thine head an ornament of grace: a crown of glory shall she deliver to thee."}, {"numero": 10, "texto": "Hear, O my son, and receive my sayings; and the years of thy life shall be many."}, {"numero": 11, "texto": "I have taught thee in the way of wisdom; I have led thee in right paths."}, {"numero": 12, "texto": "When thou goest, thy steps shall not be straitened; and when thou runnest, thou shalt not stumble."}, {"numero": 13, "texto": "Take fast hold of instruction; let her not go: keep her; for she is thy life."}, {"numero": 14, "texto": "Enter not into the path of the wicked, and go not in the way of evil men."}, {"numero": 15, "texto": "Avoid it, pass not by it, turn from it, and pass away."}, {"numero": 16, "texto": "For they sleep not, except they have done mischief; and their sleep is taken away, unless they cause some to fall."}, {"numero": 17, "texto": "For they eat the bread of wickedness, and drink the wine of violence."}, {"numero": 18, "texto": "But the path of the just is as the shining light, that shineth more and more unto the perfect day."}, {"numero": 19, "texto": "The way of the wicked is as darkness: they know not at what they stumble."}, {"numero": 20, "texto": "My son, attend to my words; incline thine ear unto my sayings."}, {"numero": 21, "texto": "Let them not depart from thine eyes; keep them in the midst of thine heart."}, {"numero": 22, "texto": "For they are life unto those that find them, and health to all their flesh."}, {"numero": 23, "texto": "Keep thy heart with all diligence; for out of it are the issues of life."}, {"numero": 24, "texto": "Put away from thee a froward mouth, and perverse lips put far from thee."}, {"numero": 25, "texto": "Let thine eyes look right on, and let thine eyelids look straight before thee."}, {"numero": 26, "texto": "Ponder the path of thy feet, and let all thy ways be established."}, {"numero": 27, "texto": "Turn not to the right hand nor to the left: remove thy foot from evil."}]'::jsonb, 'King James Version'),
  ('Pv', 4, 'fr', '[{"numero": 1, "texto": "Ecoutez, mes fils, l''''instruction d''''un père, Et soyez attentifs, pour connaître la sagesse;"}, {"numero": 2, "texto": "Car je vous donne de bons conseils: Ne rejetez pas mon enseignement."}, {"numero": 3, "texto": "J''''étais un fils pour mon père, Un fils tendre et unique auprès de ma mère."}, {"numero": 4, "texto": "Il m''''instruisait alors, et il me disait: Que ton coeur retienne mes paroles; Observe mes préceptes, et tu vivras."}, {"numero": 5, "texto": "Acquiers la sagesse, acquiers l''''intelligence; N''''oublie pas les paroles de ma bouche, et ne t''''en détourne pas."}, {"numero": 6, "texto": "Ne l''''abandonne pas, et elle te gardera; Aime-la, et elle te protégera."}, {"numero": 7, "texto": "Voici le commencement de la sagesse: Acquiers la sagesse, Et avec tout ce que tu possèdes acquiers l''''intelligence."}, {"numero": 8, "texto": "Exalte-la, et elle t''''élèvera; Elle fera ta gloire, si tu l''''embrasses;"}, {"numero": 9, "texto": "Elle mettra sur ta tête une couronne de grâce, Elle t''''ornera d''''un magnifique diadème."}, {"numero": 10, "texto": "Ecoute, mon fils, et reçois mes paroles; Et les années de ta vie se multiplieront."}, {"numero": 11, "texto": "Je te montre la voie de la sagesse, Je te conduis dans les sentiers de la droiture."}, {"numero": 12, "texto": "Si tu marches, ton pas ne sera point gêné; Et si tu cours, tu ne chancelleras point."}, {"numero": 13, "texto": "Retiens l''''instruction, ne t''''en dessaisis pas; Garde-la, car elle est ta vie."}, {"numero": 14, "texto": "N''''entre pas dans le sentier des méchants, Et ne marche pas dans la voie des hommes mauvais."}, {"numero": 15, "texto": "Evite-la, n''''y passe point; Détourne-t''''en, et passe outre."}, {"numero": 16, "texto": "Car ils ne dormiraient pas s''''ils n''''avaient fait le mal, Le sommeil leur serait ravi s''''ils n''''avaient fait tomber personne;"}, {"numero": 17, "texto": "Car c''''est le pain de la méchanceté qu''''ils mangent, C''''est le vin de la violence qu''''ils boivent."}, {"numero": 18, "texto": "Le sentier des justes est comme la lumière resplendissante, Dont l''''éclat va croissant jusqu''''au milieu du jour."}, {"numero": 19, "texto": "La voie des méchants est comme les ténèbres; Ils n''''aperçoivent pas ce qui les fera tomber."}, {"numero": 20, "texto": "Mon fils, sois attentif à mes paroles, Prête l''''oreille à mes discours."}, {"numero": 21, "texto": "Qu''''ils ne s''''éloignent pas de tes yeux; Garde-les dans le fond de ton coeur;"}, {"numero": 22, "texto": "Car c''''est la vie pour ceux qui les trouvent, C''''est la santé pour tout leur corps."}, {"numero": 23, "texto": "Garde ton coeur plus que toute autre chose, Car de lui viennent les sources de la vie."}, {"numero": 24, "texto": "Ecarte de ta bouche la fausseté, Eloigne de tes lèvres les détours."}, {"numero": 25, "texto": "Que tes yeux regardent en face, Et que tes paupières se dirigent devant toi."}, {"numero": 26, "texto": "Considère le chemin par où tu passes, Et que toutes tes voies soient bien réglées;"}, {"numero": 27, "texto": "N''''incline ni à droite ni à gauche, Et détourne ton pied du mal."}]'::jsonb, 'Louis Segond 1910'),
  ('Pv', 4, 'es', '[{"numero": 1, "texto": "OID, hijos, la doctrina de un padre, y estad atentos para que conozcáis cordura."}, {"numero": 2, "texto": "Porque os doy buena enseñanza; no desamparéis mi ley."}, {"numero": 3, "texto": "Porque yo fuí hijo de mi padre, delicado y único delante de mi madre."}, {"numero": 4, "texto": "Y él me enseñaba, y me decía: Mantenga tu corazón mis razones, guarda mis mandamientos, y vivirás:"}, {"numero": 5, "texto": "Adquiere sabiduría, adquiere inteligencia; no te olvides ni te apartes de las razones de mi boca;"}, {"numero": 6, "texto": "No la dejes, y ella te guardará; ámala, y te conservará."}, {"numero": 7, "texto": "Sabiduría ante todo: adquiere sabiduría: y ante toda tu posesión adquiere inteligencia."}, {"numero": 8, "texto": "Engrandécela, y ella te engrandecerá: ella te honrará, cuando tú la hubieres abrazado."}, {"numero": 9, "texto": "Adorno de gracia dará á tu cabeza: corona de hermosura te entregará."}, {"numero": 10, "texto": "Oye, hijo mío, y recibe mis razones; y se te multiplicarán años de vida."}, {"numero": 11, "texto": "Por el camino de la sabiduría te he encaminado, y por veredas derechas te he hecho andar."}, {"numero": 12, "texto": "Cuando anduvieres no se estrecharán tus pasos; y si corrieres, no tropezarás."}, {"numero": 13, "texto": "Ten el consejo, no lo dejes; guárdalo, porque eso es tu vida."}, {"numero": 14, "texto": "No entres por la vereda de los impíos, ni vayas por el camino de los malos."}, {"numero": 15, "texto": "Desampárala, no pases por ella; apártate de ella, pasa."}, {"numero": 16, "texto": "Porque no duermen ellos, si no hicieren mal; y pierden su sueño, si no han hecho caer."}, {"numero": 17, "texto": "Porque comen pan de maldad, y beben vino de robos."}, {"numero": 18, "texto": "Mas la senda de los justos es como la luz de la aurora, que va en aumento hasta que el día es perfecto."}, {"numero": 19, "texto": "El camino de los impíos es como la oscuridad: no saben en qué tropiezan."}, {"numero": 20, "texto": "Hijo mío, está atento á mis palabras; inclina tu oído á mis razones."}, {"numero": 21, "texto": "No se aparten de tus ojos; guárdalas en medio de tu corazón."}, {"numero": 22, "texto": "Porque son vida á los que las hallan, y medicina á toda su carne."}, {"numero": 23, "texto": "Sobre toda cosa guardada guarda tu corazón; porque de él mana la vida."}, {"numero": 24, "texto": "Aparta de ti la perversidad de la boca, y aleja de ti la iniquidad de labios."}, {"numero": 25, "texto": "Tus ojos miren lo recto, y tus párpados en derechura delante de ti."}, {"numero": 26, "texto": "Examina la senda de tus pies, y todos tus caminos sean ordenados."}, {"numero": 27, "texto": "No te apartes á diestra, ni á siniestra: aparta tu pie del mal."}]'::jsonb, 'Reina-Valera 1909'),
  ('Pv', 10, 'pt', '[{"numero": 1, "texto": "Provérbios de Salomão:O filho sábio alegra ao pai; mas o filho tolo é tristeza para sua mãe."}, {"numero": 2, "texto": "Tesouros da perversidade para nada aproveitam; porém a justiça livra da morte."}, {"numero": 3, "texto": "O SENHOR não permite a alma do justo passar fome, porém arruína o interesse dos perversos."}, {"numero": 4, "texto": "Aquele que trabalha com mão preguiçosa empobrece; mas a mão de quem trabalha com empenho enriquece."}, {"numero": 5, "texto": "Aquele que ajunta no verão é filho prudente; [mas] o que dorme na ceifa é filho causador de vergonha."}, {"numero": 6, "texto": "Há bênçãos sobre a cabeça dos justos; mas a violência cobre a boca dos perversos."}, {"numero": 7, "texto": "A lembrança do justo [será] uma bênção; mas o nome dos perversos apodrecerá."}, {"numero": 8, "texto": "O sábio de coração aceita os mandamentos; mas o louco de lábios será derrubado."}, {"numero": 9, "texto": "Aquele que anda em sinceridade anda seguro; mas o que perverte seus caminhos será conhecido."}, {"numero": 10, "texto": "Aquele que pisca os olhos maliciosamente gera dores; e o louco de lábios será derrubado."}, {"numero": 11, "texto": "A boca do justo é um manancial de vida; mas a boca dos perversos está coberta de violência."}, {"numero": 12, "texto": "O ódio desperta brigas; mas o amor cobre todas as transgressões."}, {"numero": 13, "texto": "Nos lábios do bom entendedor se acha sabedoria, mas uma vara está às costas daquele que não tem entendimento."}, {"numero": 14, "texto": "Os sábios guardam consigo sabedoria; mas a boca do tolo [está] perto da perturbação."}, {"numero": 15, "texto": "A prosperidade do rico é a sua cidade fortificada; a pobreza dos necessitados é sua perturbação."}, {"numero": 16, "texto": "A obra do justo é para a vida; os frutos do perverso, para o pecado."}, {"numero": 17, "texto": "O caminho para a vida [é d] aquele que guarda a correção; mas aquele que abandona a repreensão anda sem rumo."}, {"numero": 18, "texto": "Aquele que esconde o ódio [tem] lábios mentirosos; e o que produz má fama é tolo."}, {"numero": 19, "texto": "Na abundância de palavras não há falta de transgressão; mas aquele que refreia seus lábios é prudente."}, {"numero": 20, "texto": "A língua do justo [é como] prata escolhida; o coração dos perversos [vale] pouco."}, {"numero": 21, "texto": "Os lábios dos justo apascentam a muitos; mas os tolos, por falta de entendimento, morrem."}, {"numero": 22, "texto": "É a bênção do SENHOR que enriquece; e ele não lhe acrescenta dores."}, {"numero": 23, "texto": "Para o tolo, fazer o mal é uma diversão; mas para o homem bom entendedor, [divertida é] a sabedoria."}, {"numero": 24, "texto": "O temor do perverso virá sobre ele, mas o desejo dos justos será concedido."}, {"numero": 25, "texto": "Assim como o vento passa, assim também o perverso não [mais] existirá; mas o justo [tem] um alicerce eterno."}, {"numero": 26, "texto": "Assim como vinagre para os dentes, e como fumaça para os olhos, assim também é o preguiçoso para aqueles que o mandam."}, {"numero": 27, "texto": "O temor ao SENHOR faz aumentar os dias; mas os anos dos perversos serão encurtados."}, {"numero": 28, "texto": "A esperança dos justos [é] alegria; mas a expectativa dos perversos perecerá."}, {"numero": 29, "texto": "O caminho do SENHOR é fortaleza para os corretos, mas ruína para os que praticam maldade."}, {"numero": 30, "texto": "O justo nunca será removido, mas os perversos não habitarão a terra."}, {"numero": 31, "texto": "A boca do justo produz sabedoria, mas a língua perversa será cortada fora."}, {"numero": 32, "texto": "Os lábios do justo sabem o que é agradável; mas a boca dos perversos [é cheia] de perversidades."}]'::jsonb, 'Almeida Livre'),
  ('Pv', 10, 'en', '[{"numero": 1, "texto": "The proverbs of Solomon. A wise son maketh a glad father: but a foolish son is the heaviness of his mother."}, {"numero": 2, "texto": "Treasures of wickedness profit nothing: but righteousness delivereth from death."}, {"numero": 3, "texto": "The Lord will not suffer the soul of the righteous to famish: but he casteth away the substance of the wicked."}, {"numero": 4, "texto": "He becometh poor that dealeth with a slack hand: but the hand of the diligent maketh rich."}, {"numero": 5, "texto": "He that gathereth in summer is a wise son: but he that sleepeth in harvest is a son that causeth shame."}, {"numero": 6, "texto": "Blessings are upon the head of the just: but violence covereth the mouth of the wicked."}, {"numero": 7, "texto": "The memory of the just is blessed: but the name of the wicked shall rot."}, {"numero": 8, "texto": "The wise in heart will receive commandments: but a prating fool shall fall."}, {"numero": 9, "texto": "He that walketh uprightly walketh surely: but he that perverteth his ways shall be known."}, {"numero": 10, "texto": "He that winketh with the eye causeth sorrow: but a prating fool shall fall."}, {"numero": 11, "texto": "The mouth of a righteous man is a well of life: but violence covereth the mouth of the wicked."}, {"numero": 12, "texto": "Hatred stirreth up strifes: but love covereth all sins."}, {"numero": 13, "texto": "In the lips of him that hath understanding wisdom is found: but a rod is for the back of him that is void of understanding."}, {"numero": 14, "texto": "Wise men lay up knowledge: but the mouth of the foolish is near destruction."}, {"numero": 15, "texto": "The rich man''s wealth is his strong city: the destruction of the poor is their poverty."}, {"numero": 16, "texto": "The labour of the righteous tendeth to life: the fruit of the wicked to sin."}, {"numero": 17, "texto": "He is in the way of life that keepeth instruction: but he that refuseth reproof erreth."}, {"numero": 18, "texto": "He that hideth hatred with lying lips, and he that uttereth a slander, is a fool."}, {"numero": 19, "texto": "In the multitude of words there wanteth not sin: but he that refraineth his lips is wise."}, {"numero": 20, "texto": "The tongue of the just is as choice silver: the heart of the wicked is little worth."}, {"numero": 21, "texto": "The lips of the righteous feed many: but fools die for want of wisdom."}, {"numero": 22, "texto": "The blessing of the Lord, it maketh rich, and he addeth no sorrow with it."}, {"numero": 23, "texto": "It is as sport to a fool to do mischief: but a man of understanding hath wisdom."}, {"numero": 24, "texto": "The fear of the wicked, it shall come upon him: but the desire of the righteous shall be granted."}, {"numero": 25, "texto": "As the whirlwind passeth, so is the wicked no more: but the righteous is an everlasting foundation."}, {"numero": 26, "texto": "As vinegar to the teeth, and as smoke to the eyes, so is the sluggard to them that send him."}, {"numero": 27, "texto": "The fear of the Lord prolongeth days: but the years of the wicked shall be shortened."}, {"numero": 28, "texto": "The hope of the righteous shall be gladness: but the expectation of the wicked shall perish."}, {"numero": 29, "texto": "The way of the Lord is strength to the upright: but destruction shall be to the workers of iniquity."}, {"numero": 30, "texto": "The righteous shall never be removed: but the wicked shall not inhabit the earth."}, {"numero": 31, "texto": "The mouth of the just bringeth forth wisdom: but the froward tongue shall be cut out."}, {"numero": 32, "texto": "The lips of the righteous know what is acceptable: but the mouth of the wicked speaketh frowardness."}]'::jsonb, 'King James Version'),
  ('Pv', 10, 'fr', '[{"numero": 1, "texto": "Proverbes de Salomon. Un fils sage fait la joie d''''un père, Et un fils insensé le chagrin de sa mère."}, {"numero": 2, "texto": "Les trésors de la méchanceté ne profitent pas, Mais la justice délivre de la mort."}, {"numero": 3, "texto": "L''''Eternel ne laisse pas le juste souffrir de la faim, Mais il repousse l''''avidité des méchants."}, {"numero": 4, "texto": "Celui qui agit d''''une main lâche s''''appauvrit, Mais la main des diligents enrichit."}, {"numero": 5, "texto": "Celui qui amasse pendant l''''été est un fils prudent, Celui qui dort pendant la moisson est un fils qui fait honte."}, {"numero": 6, "texto": "Il y a des bénédictions sur la tête du juste, Mais la violence couvre la bouche des méchants."}, {"numero": 7, "texto": "La mémoire du juste est en bénédiction, Mais le nom des méchants tombe en pourriture."}, {"numero": 8, "texto": "Celui qui est sage de coeur reçoit les préceptes, Mais celui qui est insensé des lèvres court à sa perte."}, {"numero": 9, "texto": "Celui qui marche dans l''''intégrité marche avec assurance, Mais celui qui prend des voies tortueuses sera découvert."}, {"numero": 10, "texto": "Celui qui cligne des yeux est une cause de chagrin, Et celui qui est insensé des lèvres court à sa perte."}, {"numero": 11, "texto": "La bouche du juste est une source de vie, Mais la violence couvre la bouche des méchants."}, {"numero": 12, "texto": "La haine excite des querelles, Mais l''''amour couvre toutes les fautes."}, {"numero": 13, "texto": "Sur les lèvres de l''''homme intelligent se trouve la sagesse, Mais la verge est pour le dos de celui qui est dépourvu de sens."}, {"numero": 14, "texto": "Les sages tiennent la science en réserve, Mais la bouche de l''''insensé est une ruine prochaine."}, {"numero": 15, "texto": "La fortune est pour le riche une ville forte; La ruine des misérables, c''''est leur pauvreté."}, {"numero": 16, "texto": "L''''oeuvre du juste est pour la vie, Le gain du méchant est pour le péché."}, {"numero": 17, "texto": "Celui qui se souvient de la correction prend le chemin de la vie, Mais celui qui oublie la réprimande s''''égare."}, {"numero": 18, "texto": "Celui qui dissimule la haine a des lèvres menteuses, Et celui qui répand la calomnie est un insensé."}, {"numero": 19, "texto": "Celui qui parle beaucoup ne manque pas de pécher, Mais celui qui retient ses lèvres est un homme prudent."}, {"numero": 20, "texto": "La langue du juste est un argent de choix; Le coeur des méchants est peu de chose."}, {"numero": 21, "texto": "Les lèvres du juste dirigent beaucoup d''''hommes, Et les insensés meurent par défaut de raison."}, {"numero": 22, "texto": "C''''est la bénédiction de l''''Eternel qui enrichit, Et il ne la fait suivre d''''aucun chagrin."}, {"numero": 23, "texto": "Commettre le crime paraît un jeu à l''''insensé, Mais la sagesse appartient à l''''homme intelligent."}, {"numero": 24, "texto": "Ce que redoute le méchant, c''''est ce qui lui arrive; Et ce que désirent les justes leur est accordé."}, {"numero": 25, "texto": "Comme passe le tourbillon, ainsi disparaît le méchant; Mais le juste a des fondements éternels."}, {"numero": 26, "texto": "Ce que le vinaigre est aux dents et la fumée aux yeux, Tel est le paresseux pour celui qui l''''envoie."}, {"numero": 27, "texto": "La crainte de l''''Eternel augmente les jours, Mais les années des méchants sont abrégées."}, {"numero": 28, "texto": "L''''attente des justes n''''est que joie, Mais l''''espérance des méchants périra."}, {"numero": 29, "texto": "La voie de l''''Eternel est un rempart pour l''''intégrité, Mais elle est une ruine pour ceux qui font le mal."}, {"numero": 30, "texto": "Le juste ne chancellera jamais, Mais les méchants n''''habiteront pas le pays."}, {"numero": 31, "texto": "La bouche du juste produit la sagesse, Mais la langue perverse sera retranchée."}, {"numero": 32, "texto": "Les lèvres du juste connaissent la grâce, Et la bouche des méchants la perversité."}]'::jsonb, 'Louis Segond 1910'),
  ('Pv', 10, 'es', '[{"numero": 1, "texto": "Las sentencias de Salomón. EL hijo sabio alegra al padre; y el hijo necio es tristeza de su madre."}, {"numero": 2, "texto": "Los tesoros de maldad no serán de provecho: mas la justicia libra de muerte."}, {"numero": 3, "texto": "Jehová no dejará hambrear el alma del justo: mas la iniquidad lanzará á los impíos."}, {"numero": 4, "texto": "La mano negligente hace pobre: mas la mano de los diligentes enriquece."}, {"numero": 5, "texto": "El que recoge en el estío es hombre entendido: el que duerme en el tiempo de la siega es hombre afrentoso."}, {"numero": 6, "texto": "Bendiciones sobre la cabeza del justo: mas violencia cubrirá la boca de los impíos."}, {"numero": 7, "texto": "La memoria del justo será bendita: mas el nombre de los impíos se pudrirá."}, {"numero": 8, "texto": "El sabio de corazón recibirá los mandamientos: mas el loco de labios caerá."}, {"numero": 9, "texto": "El que camina en integridad, anda confiado: mas el que pervierte sus caminos, será quebrantado."}, {"numero": 10, "texto": "El que guiña del ojo acarrea tristeza; y el loco de labios será castigado."}, {"numero": 11, "texto": "Vena de vida es la boca del justo: mas violencia cubrirá la boca de los impíos."}, {"numero": 12, "texto": "El odio despierta rencillas: mas la caridad cubrirá todas las faltas."}, {"numero": 13, "texto": "En los labios del prudente se halla sabiduría: y vara á las espaldas del falto de cordura."}, {"numero": 14, "texto": "Los sabios guardan la sabiduría: mas la boca del loco es calamidad cercana."}, {"numero": 15, "texto": "Las riquezas del rico son su ciudad fuerte; y el desmayo de los pobres es su pobreza."}, {"numero": 16, "texto": "La obra del justo es para vida; mas el fruto del impío es para pecado."}, {"numero": 17, "texto": "Camino á la vida es guardar la corrección: mas el que deja la reprensión, yerra."}, {"numero": 18, "texto": "El que encubre el odio es de labios mentirosos; y el que echa mala fama es necio."}, {"numero": 19, "texto": "En las muchas palabras no falta pecado: mas el que refrena sus labios es prudente."}, {"numero": 20, "texto": "Plata escogida es la lengua del justo: mas el entendimiento de los impíos es como nada."}, {"numero": 21, "texto": "Los labios del justo apacientan á muchos: mas los necios por falta de entendimiento mueren."}, {"numero": 22, "texto": "La bendición de Jehová es la que enriquece, y no añade tristeza con ella."}, {"numero": 23, "texto": "Hacer abominación es como risa al insensato: mas el hombre entendido sabe."}, {"numero": 24, "texto": "Lo que el impío teme, eso le vendrá: mas á los justos les será dado lo que desean."}, {"numero": 25, "texto": "Como pasa el torbellino, así el malo no permanece: mas el justo, fundado para siempre."}, {"numero": 26, "texto": "Como el vinagre á los dientes, y como el humo á los ojos, así es el perezoso á los que lo envían."}, {"numero": 27, "texto": "El temor de Jehová aumentará los días: mas los años de los impíos serán acortados."}, {"numero": 28, "texto": "La esperanza de los justos es alegría; mas la esperanza de los impíos perecerá."}, {"numero": 29, "texto": "Fortaleza es al perfecto el camino de Jehová: mas espanto es á los que obran maldad."}, {"numero": 30, "texto": "El justo eternalmente no será removido: mas los impíos no habitarán la tierra."}, {"numero": 31, "texto": "La boca del justo producirá sabiduría: mas la lengua perversa será cortada."}, {"numero": 32, "texto": "Los labios del justo conocerán lo que agrada: mas la boca de los impíos habla perversidades."}]'::jsonb, 'Reina-Valera 1909'),
  ('Pv', 15, 'pt', '[{"numero": 1, "texto": "A resposta suave desvia o furor, mas a palavra pesada faz a ira aumentar."}, {"numero": 2, "texto": "A língua dos sábios faz bom uso da sabedoria, mas a boca dos tolos derrama loucura."}, {"numero": 3, "texto": "Os olhos do SENHOR estão em todo lugar, observando os maus e os bons."}, {"numero": 4, "texto": "Uma língua sã é árvore de vida; mas a perversidade nela é faz o espírito em pedaços."}, {"numero": 5, "texto": "O tolo despreza a correção de seu pai; mas aquele que presta atenção à repreensão age com prudência."}, {"numero": 6, "texto": "[Na] casa dos justo há um grande tesouro; mas na renda do perverso há perturbação."}, {"numero": 7, "texto": "Os lábios dos sábios derramam conhecimento; mas o coração dos tolos não [age] assim."}, {"numero": 8, "texto": "O sacrifício dos perversos é abominável ao SENHOR, mas a oração dos justos é seu agrado."}, {"numero": 9, "texto": "Abominável ao SENHOR é o caminho do perverso; porém ele ama ao que segue a justiça."}, {"numero": 10, "texto": "A correção é ruim para aquele que deixa o caminho; e quem odeia a repreensão morrerá."}, {"numero": 11, "texto": "O Xeol e a perdição estão perante o SENHOR; quanto mais os corações dos filhos dos homens!"}, {"numero": 12, "texto": "O zombador não ama quem o repreende, nem se aproximará dos sábios."}, {"numero": 13, "texto": "O coração alegre anima o rosto, mas pela dor do coração o espírito se abate."}, {"numero": 14, "texto": "O coração prudente buscará o conhecimento, mas a boca dos tolos se alimentará de loucura."}, {"numero": 15, "texto": "Todos os dias do oprimido são maus, mas o coração alegre é [como] um banquete contínuo."}, {"numero": 16, "texto": "Melhor é o pouco tendo o temor ao SENHOR, do que um grande tesouro tendo em si inquietação."}, {"numero": 17, "texto": "Melhor é a comida de hortaliças tendo amor, do que a de boi cevado tendo em si ódio."}, {"numero": 18, "texto": "O homem que fica irritado facilmente gera brigas; mas aquele que demora para se irar apaziguará o confronto."}, {"numero": 19, "texto": "O caminho do preguiçoso é como uma cerca de espinhos; mas a vereda dos corretos é bem aplanada."}, {"numero": 20, "texto": "O filho sábio alegra ao pai, mas o homem tolo despreza a sua mãe."}, {"numero": 21, "texto": "A loucura é alegria para aquele que tem falta de prudência; mas o homem de bom entendimento andará corretamente."}, {"numero": 22, "texto": "Os planos fracassam quando não há [bom] conselho; mas com abundância de conselheiros eles se confirmam."}, {"numero": 23, "texto": "O homem se alegra com a resposta de sua boca; e como é boa a palavra a seu devido tempo!"}, {"numero": 24, "texto": "Para o prudente, o caminho da vida [é] para cima, para que se afaste do Xeol, que é para baixo."}, {"numero": 25, "texto": "O SENHOR destruirá a casa dos arrogantes, mas confirmará os limites do terreno da viúva."}, {"numero": 26, "texto": "Os pensamentos do mau são abomináveis ao SENHOR, mas ele se agrada das palavras dos puros."}, {"numero": 27, "texto": "Quem pratica a ganância perturba sua [própria] casa; mas quem odeia subornos viverá."}, {"numero": 28, "texto": "O coração do justo pensa bem naquilo que vai responder, mas a boca dos perversos derrama maldades em abundância."}, {"numero": 29, "texto": "Longe está o SENHOR dos perversos, mas ele escuta a oração dos justos."}, {"numero": 30, "texto": "A luz dos olhos alegra o coração; a boa notícia fortalece os ossos."}, {"numero": 31, "texto": "Os ouvidos que escutam a repreensão da vida habitarão entre os sábios."}, {"numero": 32, "texto": "Quem rejeita correção menospreza sua [própria] alma; mas aquele que escuta a repreensão adquire entendimento."}, {"numero": 33, "texto": "O temor ao SENHOR corrige sabiamente; e antes da honra [vem] a humildade."}]'::jsonb, 'Almeida Livre'),
  ('Pv', 15, 'en', '[{"numero": 1, "texto": "A soft answer turneth away wrath: but grievous words stir up anger."}, {"numero": 2, "texto": "The tongue of the wise useth knowledge aright: but the mouth of fools poureth out foolishness."}, {"numero": 3, "texto": "The eyes of the Lord are in every place, beholding the evil and the good."}, {"numero": 4, "texto": "A wholesome tongue is a tree of life: but perverseness therein is a breach in the spirit."}, {"numero": 5, "texto": "A fool despiseth his father''s instruction: but he that regardeth reproof is prudent."}, {"numero": 6, "texto": "In the house of the righteous is much treasure: but in the revenues of the wicked is trouble."}, {"numero": 7, "texto": "The lips of the wise disperse knowledge: but the heart of the foolish doeth not so."}, {"numero": 8, "texto": "The sacrifice of the wicked is an abomination to the Lord: but the prayer of the upright is his delight."}, {"numero": 9, "texto": "The way of the wicked is an abomination unto the Lord: but he loveth him that followeth after righteousness."}, {"numero": 10, "texto": "Correction is grievous unto him that forsaketh the way: and he that hateth reproof shall die."}, {"numero": 11, "texto": "Hell and destruction are before the Lord: how much more then the hearts of the children of men?"}, {"numero": 12, "texto": "A scorner loveth not one that reproveth him: neither will he go unto the wise."}, {"numero": 13, "texto": "A merry heart maketh a cheerful countenance: but by sorrow of the heart the spirit is broken."}, {"numero": 14, "texto": "The heart of him that hath understanding seeketh knowledge: but the mouth of fools feedeth on foolishness."}, {"numero": 15, "texto": "All the days of the afflicted are evil: but he that is of a merry heart hath a continual feast."}, {"numero": 16, "texto": "Better is little with the fear of the Lord than great treasure and trouble therewith."}, {"numero": 17, "texto": "Better is a dinner of herbs where love is, than a stalled ox and hatred therewith."}, {"numero": 18, "texto": "A wrathful man stirreth up strife: but he that is slow to anger appeaseth strife."}, {"numero": 19, "texto": "The way of the slothful man is as an hedge of thorns: but the way of the righteous is made plain."}, {"numero": 20, "texto": "A wise son maketh a glad father: but a foolish man despiseth his mother."}, {"numero": 21, "texto": "Folly is joy to him that is destitute of wisdom: but a man of understanding walketh uprightly."}, {"numero": 22, "texto": "Without counsel purposes are disappointed: but in the multitude of counsellors they are established."}, {"numero": 23, "texto": "A man hath joy by the answer of his mouth: and a word spoken in due season, how good is it!"}, {"numero": 24, "texto": "The way of life is above to the wise, that he may depart from hell beneath."}, {"numero": 25, "texto": "The Lord will destroy the house of the proud: but he will establish the border of the widow."}, {"numero": 26, "texto": "The thoughts of the wicked are an abomination to the Lord: but the words of the pure are pleasant words."}, {"numero": 27, "texto": "He that is greedy of gain troubleth his own house; but he that hateth gifts shall live."}, {"numero": 28, "texto": "The heart of the righteous studieth to answer: but the mouth of the wicked poureth out evil things."}, {"numero": 29, "texto": "The Lord is far from the wicked: but he heareth the prayer of the righteous."}, {"numero": 30, "texto": "The light of the eyes rejoiceth the heart: and a good report maketh the bones fat."}, {"numero": 31, "texto": "The ear that heareth the reproof of life abideth among the wise."}, {"numero": 32, "texto": "He that refuseth instruction despiseth his own soul: but he that heareth reproof getteth understanding."}, {"numero": 33, "texto": "The fear of the Lord is the instruction of wisdom; and before honour is humility."}]'::jsonb, 'King James Version'),
  ('Pv', 15, 'fr', '[{"numero": 1, "texto": "Une réponse douce calme la fureur, Mais une parole dure excite la colère."}, {"numero": 2, "texto": "La langue des sages rend la science aimable, Et la bouche des insensés répand la folie."}, {"numero": 3, "texto": "Les yeux de l''''Eternel sont en tout lieu, Observant les méchants et les bons."}, {"numero": 4, "texto": "La langue douce est un arbre de vie, Mais la langue perverse brise l''''âme."}, {"numero": 5, "texto": "L''''insensé dédaigne l''''instruction de son père, Mais celui qui a égard à la réprimande agit avec prudence."}, {"numero": 6, "texto": "Il y a grande abondance dans la maison du juste, Mais il y a du trouble dans les profits du méchant."}, {"numero": 7, "texto": "Les lèvres des sages répandent la science, Mais le coeur des insensés n''''est pas droit."}, {"numero": 8, "texto": "Le sacrifice des méchants est en horreur à l''''Eternel, Mais la prière des hommes droits lui est agréable."}, {"numero": 9, "texto": "La voie du méchant est en horreur à l''''Eternel, Mais il aime celui qui poursuit la justice."}, {"numero": 10, "texto": "Une correction sévère menace celui qui abandonne le sentier; Celui qui hait la réprimande mourra."}, {"numero": 11, "texto": "Le séjour des morts et l''''abîme sont devant l''''Eternel; Combien plus les coeurs des fils de l''''homme!"}, {"numero": 12, "texto": "Le moqueur n''''aime pas qu''''on le reprenne, Il ne va point vers les sages."}, {"numero": 13, "texto": "Un coeur joyeux rend le visage serein; Mais quand le coeur est triste, l''''esprit est abattu."}, {"numero": 14, "texto": "Un coeur intelligent cherche la science, Mais la bouche des insensés se plaît à la folie."}, {"numero": 15, "texto": "Tous les jours du malheureux sont mauvais, Mais le coeur content est un festin perpétuel."}, {"numero": 16, "texto": "Mieux vaut peu, avec la crainte de l''''Eternel, Qu''''un grand trésor, avec le trouble."}, {"numero": 17, "texto": "Mieux vaut de l''''herbe pour nourriture, là où règne l''''amour, Qu''''un boeuf engraissé, si la haine est là."}, {"numero": 18, "texto": "Un homme violent excite des querelles, Mais celui qui est lent à la colère apaise les disputes."}, {"numero": 19, "texto": "Le chemin du paresseux est comme une haie d''''épines, Mais le sentier des hommes droits est aplani."}, {"numero": 20, "texto": "Un fils sage fait la joie de son père, Et un homme insensé méprise sa mère."}, {"numero": 21, "texto": "La folie est une joie pour celui qui est dépourvu de sens, Mais un homme intelligent va le droit chemin."}, {"numero": 22, "texto": "Les projets échouent, faute d''''une assemblée qui délibère; Mais ils réussissent quand il y a de nombreux conseillers."}, {"numero": 23, "texto": "On éprouve de la joie à donner une réponse de sa bouche; Et combien est agréable une parole dite à propos!"}, {"numero": 24, "texto": "Pour le sage, le sentier de la vie mène en haut, Afin qu''''il se détourne du séjour des morts qui est en bas."}, {"numero": 25, "texto": "L''''Eternel renverse la maison des orgueilleux, Mais il affermit les bornes de la veuve."}, {"numero": 26, "texto": "Les pensées mauvaises sont en horreur à l''''Eternel, Mais les paroles agréables sont pures à ses yeux."}, {"numero": 27, "texto": "Celui qui est avide de gain trouble sa maison, Mais celui qui hait les présents vivra."}, {"numero": 28, "texto": "Le coeur du juste médite pour répondre, Mais la bouche des méchants répand des méchancetés."}, {"numero": 29, "texto": "L''''Eternel s''''éloigne des méchants, Mais il écoute la prière des justes."}, {"numero": 30, "texto": "Ce qui plaît aux yeux réjouit le coeur; Une bonne nouvelle fortifie les membres."}, {"numero": 31, "texto": "L''''oreille attentive aux réprimandes qui mènent à la vie Fait son séjour au milieu des sages."}, {"numero": 32, "texto": "Celui qui rejette la correction méprise son âme, Mais celui qui écoute la réprimande acquiert l''''intelligence."}, {"numero": 33, "texto": "La crainte de l''''Eternel enseigne la sagesse, Et l''''humilité précède la gloire."}]'::jsonb, 'Louis Segond 1910'),
  ('Pv', 15, 'es', '[{"numero": 1, "texto": "LA blanda respuesta quita la ira: mas la palabra áspera hace subir el furor."}, {"numero": 2, "texto": "La lengua de los sabios adornará la sabiduría: mas la boca de los necios hablará sandeces."}, {"numero": 3, "texto": "Los ojos de Jehová están en todo lugar, mirando á los malos y á los buenos."}, {"numero": 4, "texto": "La sana lengua es árbol de vida: mas la perversidad en ella es quebrantamiento de espíritu."}, {"numero": 5, "texto": "El necio menosprecia el consejo de su padre: mas el que guarda la corrección, vendrá á ser cuerdo."}, {"numero": 6, "texto": "En la casa del justo hay gran provisión; empero turbación en las ganancias del impío."}, {"numero": 7, "texto": "Los labios de los sabios esparcen sabiduría: mas no así el corazón de los necios."}, {"numero": 8, "texto": "El sacrificio de los impíos es abominación á Jehová: mas la oración de los rectos es su gozo."}, {"numero": 9, "texto": "Abominación es á Jehová el camino del impío: mas él ama al que sigue justicia."}, {"numero": 10, "texto": "La reconvención es molesta al que deja el camino: y el que aborreciere la corrección, morirá."}, {"numero": 11, "texto": "El infierno y la perdición están delante de Jehová: ¡cuánto más los corazones de los hombres!"}, {"numero": 12, "texto": "El escarnecedor no ama al que le reprende; ni se allega á los sabios."}, {"numero": 13, "texto": "El corazón alegre hermosea el rostro: mas por el dolor de corazón el espíritu se abate."}, {"numero": 14, "texto": "El corazón entendido busca la sabiduría: mas la boca de los necios pace necedad."}, {"numero": 15, "texto": "Todos los días del afligido son trabajosos: mas el de corazón contento tiene un convite continuo."}, {"numero": 16, "texto": "Mejor es lo poco con el temor de Jehová, que el gran tesoro donde hay turbación."}, {"numero": 17, "texto": "Mejor es la comida de legumbres donde hay amor, que de buey engordado donde hay odio."}, {"numero": 18, "texto": "El hombre iracundo mueve contiendas: mas el que tarde se enoja, apaciguará la rencilla."}, {"numero": 19, "texto": "El camino del perezoso es como seto de espinos: mas la vereda de los rectos como una calzada."}, {"numero": 20, "texto": "El hijo sabio alegra al padre: mas el hombre necio menosprecia á su madre."}, {"numero": 21, "texto": "La necedad es alegría al falto de entendimiento: mas el hombre entendido enderezará su proceder."}, {"numero": 22, "texto": "Los pensamientos son frustrados donde no hay consejo; mas en la multitud de consejeros se afirman."}, {"numero": 23, "texto": "Alégrase el hombre con la respuesta de su boca: y la palabra á su tiempo, ¡cuán buena es!"}, {"numero": 24, "texto": "El camino de la vida es hacia arriba al entendido, para apartarse del infierno abajo."}, {"numero": 25, "texto": "Jehová asolará la casa de los soberbios: mas él afirmará el término de la viuda."}, {"numero": 26, "texto": "Abominación son á Jehová los pensamientos del malo: mas las expresiones de los limpios son limpias."}, {"numero": 27, "texto": "Alborota su casa el codicioso: mas el que aborrece las dádivas vivirá."}, {"numero": 28, "texto": "El corazón del justo piensa para responder: mas la boca de los impíos derrama malas cosas."}, {"numero": 29, "texto": "Lejos está Jehová de los impíos: mas él oye la oración de los justos."}, {"numero": 30, "texto": "La luz de los ojos alegra el corazón; y la buena fama engorda los huesos."}, {"numero": 31, "texto": "La oreja que escucha la corrección de vida, entre los sabios morará."}, {"numero": 32, "texto": "El que tiene en poco la disciplina, menosprecia su alma: mas el que escucha la corrección, tiene entendimiento."}, {"numero": 33, "texto": "El temor de Jehová es enseñanza de sabiduría: y delante de la honra está la humildad."}]'::jsonb, 'Reina-Valera 1909'),
  ('Pv', 25, 'pt', '[{"numero": 1, "texto": "Estes também são provérbios de Salomão, que foram copiados pelos homens de Ezequias, rei de Judá."}, {"numero": 2, "texto": "É glória de Deus encobrir alguma coisa; mas a glória dos Reis é investigá-la."}, {"numero": 3, "texto": "Para a altura dos céus, para a profundeza da terra, assim como para o coração dos reis, não há como serem investigados."}, {"numero": 4, "texto": "Tira as escórias da prata, e sairá um vaso para o fundidor."}, {"numero": 5, "texto": "Tira o perverso de diante do rei, e seu trono se firmará com justiça."}, {"numero": 6, "texto": "Não honres a ti mesmo perante o rei, nem te ponhas no lugar dos grandes;"}, {"numero": 7, "texto": "Porque é melhor que te digam: Sobe aqui;Do que te rebaixem perante a face do príncipe, a quem teus olhos viram."}, {"numero": 8, "texto": "Não sejas apressado para entrar numa disputa; senão, o que farás se no fim teu próximo te envergonhar?"}, {"numero": 9, "texto": "Disputa tua causa com teu próximo, mas não reveles segredo de outra pessoa."}, {"numero": 10, "texto": "Para que não te envergonhe aquele que ouvir; pois tua má fama não pode ser desfeita."}, {"numero": 11, "texto": "A palavra dita em tempo apropriado é [como] maçãs de ouro em bandejas de prata."}, {"numero": 12, "texto": "O sábio que repreende junto a um ouvido disposto a escutar é [como] pendentes de ouro e ornamentos de ouro refinado."}, {"numero": 13, "texto": "Como frio de neve no tempo da colheita, [assim] é o mensageiro fiel para aqueles que o enviam; porque ele refresca a alma de seus senhores."}, {"numero": 14, "texto": "[Como] nuvens e ventos que não trazem chuva, [assim] é o homem que se orgulha de falsos presentes."}, {"numero": 15, "texto": "Com paciência para não se irar é que se convence um líder; e a língua suave quebra ossos."}, {"numero": 16, "texto": "Achaste mel? Come o que te for suficiente; para que não venhas a ficar cheio demais, e vomites."}, {"numero": 17, "texto": "Não exagere teus pés na casa de teu próximo, para que ele não se canse de ti, e te odeie."}, {"numero": 18, "texto": "Martelo, espada e flecha afiada é o homem que fala falso testemunho contra seu próximo."}, {"numero": 19, "texto": "Confiar num infiel no tempo de angústia é [como] um dente quebrado ou um pé sem firmeza."}, {"numero": 20, "texto": "Quem canta canções ao coração aflito é como aquele que tira a roupa num dia frio, ou como vinagre sobre salitre."}, {"numero": 21, "texto": "Se aquele que te odeia tiver fome, dá-lhe pão para comer; e se tiver sede, dá-lhe água para beber;"}, {"numero": 22, "texto": "Porque [assim] amontoarás brasas sobre a cabeça dele, e o SENHOR te recompensará."}, {"numero": 23, "texto": "O vento norte traz a chuva; [assim como] a língua caluniadora [traz] a ira no rosto."}, {"numero": 24, "texto": "É melhor morar num canto do terraço do que com uma mulher briguenta numa casa espaçosa."}, {"numero": 25, "texto": "[Como] água refrescante para a alma cansada, assim são boas notícias de uma terra distante."}, {"numero": 26, "texto": "O justo que se deixa levar pelo perverso é [como] uma fonte turva e um manancial poluído."}, {"numero": 27, "texto": "Comer muito mel não é bom; assim como buscar muita glória para si."}, {"numero": 28, "texto": "O homem que não pode conter seu espírito é [como] uma cidade derrubada sem muro."}]'::jsonb, 'Almeida Livre'),
  ('Pv', 25, 'en', '[{"numero": 1, "texto": "These are also proverbs of Solomon, which the men of Hezekiah king of Judah copied out."}, {"numero": 2, "texto": "It is the glory of God to conceal a thing: but the honour of kings is to search out a matter."}, {"numero": 3, "texto": "The heaven for height, and the earth for depth, and the heart of kings is unsearchable."}, {"numero": 4, "texto": "Take away the dross from the silver, and there shall come forth a vessel for the finer."}, {"numero": 5, "texto": "Take away the wicked from before the king, and his throne shall be established in righteousness."}, {"numero": 6, "texto": "Put not forth thyself in the presence of the king, and stand not in the place of great men:"}, {"numero": 7, "texto": "For better it is that it be said unto thee, Come up hither; than that thou shouldest be put lower in the presence of the prince whom thine eyes have seen."}, {"numero": 8, "texto": "Go not forth hastily to strive, lest thou know not what to do in the end thereof, when thy neighbour hath put thee to shame."}, {"numero": 9, "texto": "Debate thy cause with thy neighbour himself; and discover not a secret to another:"}, {"numero": 10, "texto": "Lest he that heareth it put thee to shame, and thine infamy turn not away."}, {"numero": 11, "texto": "A word fitly spoken is like apples of gold in pictures of silver."}, {"numero": 12, "texto": "As an earring of gold, and an ornament of fine gold, so is a wise reprover upon an obedient ear."}, {"numero": 13, "texto": "As the cold of snow in the time of harvest, so is a faithful messenger to them that send him: for he refresheth the soul of his masters."}, {"numero": 14, "texto": "Whoso boasteth himself of a false gift is like clouds and wind without rain."}, {"numero": 15, "texto": "By long forbearing is a prince persuaded, and a soft tongue breaketh the bone."}, {"numero": 16, "texto": "Hast thou found honey? eat so much as is sufficient for thee, lest thou be filled therewith, and vomit it."}, {"numero": 17, "texto": "Withdraw thy foot from thy neighbour''s house; lest he be weary of thee, and so hate thee."}, {"numero": 18, "texto": "A man that beareth false witness against his neighbour is a maul, and a sword, and a sharp arrow."}, {"numero": 19, "texto": "Confidence in an unfaithful man in time of trouble is like a broken tooth, and a foot out of joint."}, {"numero": 20, "texto": "As he that taketh away a garment in cold weather, and as vinegar upon nitre, so is he that singeth songs to an heavy heart."}, {"numero": 21, "texto": "If thine enemy be hungry, give him bread to eat; and if he be thirsty, give him water to drink:"}, {"numero": 22, "texto": "For thou shalt heap coals of fire upon his head, and the Lord shall reward thee."}, {"numero": 23, "texto": "The north wind driveth away rain: so doth an angry countenance a backbiting tongue."}, {"numero": 24, "texto": "It is better to dwell in the corner of the housetop, than with a brawling woman and in a wide house."}, {"numero": 25, "texto": "As cold waters to a thirsty soul, so is good news from a far country."}, {"numero": 26, "texto": "A righteous man falling down before the wicked is as a troubled fountain, and a corrupt spring."}, {"numero": 27, "texto": "It is not good to eat much honey: so for men to search their own glory is not glory."}, {"numero": 28, "texto": "He that hath no rule over his own spirit is like a city that is broken down, and without walls."}]'::jsonb, 'King James Version'),
  ('Pv', 25, 'fr', '[{"numero": 1, "texto": "Voici encore des Proverbes de Salomon, recueillis par les gens d''''Ezéchias, roi de Juda."}, {"numero": 2, "texto": "La gloire de Dieu, c''''est de cacher les choses; La gloire des rois, c''''est de sonder les choses."}, {"numero": 3, "texto": "Les cieux dans leur hauteur, la terre dans sa profondeur, Et le coeur des rois, sont impénétrables."}, {"numero": 4, "texto": "Ote de l''''argent les scories, Et il en sortira un vase pour le fondeur."}, {"numero": 5, "texto": "Ote le méchant de devant le roi, Et son trône s''''affermira par la justice."}, {"numero": 6, "texto": "Ne t''''élève pas devant le roi, Et ne prends pas la place des grands;"}, {"numero": 7, "texto": "Car il vaut mieux qu''''on te dise: Monte-ici! Que si l''''on t''''abaisse devant le prince que tes yeux voient."}, {"numero": 8, "texto": "Ne te hâte pas d''''entrer en contestation, De peur qu''''à la fin tu ne saches que faire, Lorsque ton prochain t''''aura outragé."}, {"numero": 9, "texto": "Défends ta cause contre ton prochain, Mais ne révèle pas le secret d''''un autre,"}, {"numero": 10, "texto": "De peur qu''''en l''''apprenant il ne te couvre de honte, Et que ta mauvaise renommée ne s''''efface pas."}, {"numero": 11, "texto": "Comme des pommes d''''or sur des ciselures d''''argent, Ainsi est une parole dite à propos."}, {"numero": 12, "texto": "Comme un anneau d''''or et une parure d''''or fin, Ainsi pour une oreille docile est le sage qui réprimande."}, {"numero": 13, "texto": "Comme la fraîcheur de la neige au temps de la moisson, Ainsi est un messager fidèle pour celui qui l''''envoie; Il restaure l''''âme de son maître."}, {"numero": 14, "texto": "Comme des nuages et du vent sans pluie, Ainsi est un homme se glorifiant à tort de ses libéralités."}, {"numero": 15, "texto": "Par la lenteur à la colère on fléchit un prince, Et une langue douce peut briser des os."}, {"numero": 16, "texto": "Si tu trouves du miel, n''''en mange que ce qui te suffit, De peur que tu n''''en sois rassasié et que tu ne le vomisses."}, {"numero": 17, "texto": "Mets rarement le pied dans la maison de ton prochain, De peur qu''''il ne soit rassasié de toi et qu''''il ne te haïsse."}, {"numero": 18, "texto": "Comme une massue, une épée et une flèche aiguë, Ainsi est un homme qui porte un faux témoignage contre son prochain."}, {"numero": 19, "texto": "Comme une dent cassée et un pied qui chancelle, Ainsi est la confiance en un perfide au jour de la détresse."}, {"numero": 20, "texto": "Oter son vêtement dans un jour froid, Répandre du vinaigre sur du nitre, C''''est dire des chansons à un coeur attristé."}, {"numero": 21, "texto": "Si ton ennemi a faim, donne-lui du pain à manger; S''''il a soif, donne-lui de l''''eau à boire."}, {"numero": 22, "texto": "Car ce sont des charbons ardents que tu amasses sur sa tête, Et l''''Eternel te récompensera."}, {"numero": 23, "texto": "Le vent du nord enfante la pluie, Et la langue mystérieuse un visage irrité."}, {"numero": 24, "texto": "Mieux vaut habiter à l''''angle d''''un toit, Que de partager la demeure d''''une femme querelleuse."}, {"numero": 25, "texto": "Comme de l''''eau fraîche pour une personne fatiguée, Ainsi est une bonne nouvelle venant d''''une terre lointaine."}, {"numero": 26, "texto": "Comme une fontaine troublée et une source corrompue, Ainsi est le juste qui chancelle devant le méchant."}, {"numero": 27, "texto": "Il n''''est pas bon de manger beaucoup de miel, Mais rechercher la gloire des autres est un honneur."}, {"numero": 28, "texto": "Comme une ville forcée et sans murailles, Ainsi est l''''homme qui n''''est pas maître de lui-même."}]'::jsonb, 'Louis Segond 1910'),
  ('Pv', 25, 'es', '[{"numero": 1, "texto": "TAMBIÉN estos son proverbios de Salomón, los cuales copiaron los varones de Ezechîas, rey de Judá."}, {"numero": 2, "texto": "Gloria de Dios es encubrir la palabra; mas honra del rey es escudriñar la palabra."}, {"numero": 3, "texto": "Para la altura de los cielos, y para la profundidad de la tierra, y para el corazón de los reyes, no hay investigación."}, {"numero": 4, "texto": "Quita las escorias de la plata, y saldrá vaso al fundidor."}, {"numero": 5, "texto": "Aparta al impío de la presencia del rey, y su trono se afirmará en justicia."}, {"numero": 6, "texto": "No te alabes delante del rey, ni estés en el lugar de los grandes:"}, {"numero": 7, "texto": "Porque mejor es que se te diga, Sube acá, que no que seas humillado delante del príncipe que miraron tus ojos."}, {"numero": 8, "texto": "No salgas á pleito presto, no sea que no sepas qué hacer al fin, después que tu prójimo te haya dejado confuso."}, {"numero": 9, "texto": "Trata tu causa con tu compañero y no descubras el secreto á otro."}, {"numero": 10, "texto": "No sea que te deshonre el que lo oyere, y tu infamia no pueda repararse."}, {"numero": 11, "texto": "Manzana de oro con figuras de plata es la palabra dicha como conviene."}, {"numero": 12, "texto": "Como zarcillo de oro y joyel de oro fino, es el que reprende al sabio que tiene oído dócil."}, {"numero": 13, "texto": "Como frío de nieve en tiempo de la siega, así es el mensajero fiel á los que lo envían: pues al alma de su señor da refrigerio."}, {"numero": 14, "texto": "Como nubes y vientos sin lluvia, así es el hombre que se jacta de vana liberalidad."}, {"numero": 15, "texto": "Con larga paciencia se aplaca el príncipe; y la lengua blanda quebranta los huesos."}, {"numero": 16, "texto": "¿Hallaste la miel? come lo que te basta; no sea que te hartes de ella, y la vomites."}, {"numero": 17, "texto": "Detén tu pie de la casa de tu vecino, porque harto de ti no te aborrezca."}, {"numero": 18, "texto": "Martillo y cuchillo y saeta aguda, es el hombre que habla contra su prójimo falso testimonio."}, {"numero": 19, "texto": "Diente quebrado y pie resbalador, es la confianza en el prevaricador en tiempo de angustia."}, {"numero": 20, "texto": "El que canta canciones al corazón afligido, es como el que quita la ropa en tiempo de frío, ó el que sobre el jabón echa vinagre."}, {"numero": 21, "texto": "Si el que te aborrece tuviere hambre, dale de comer pan; y si tuviere sed, dale de beber agua:"}, {"numero": 22, "texto": "Porque ascuas allegas sobre su cabeza, y Jehová te lo pagará."}, {"numero": 23, "texto": "El viento del norte ahuyenta la lluvia, y el rostro airado la lengua detractora."}, {"numero": 24, "texto": "Mejor es estar en un rincón de casa, que con la mujer rencillosa en espaciosa casa."}, {"numero": 25, "texto": "Como el agua fría al alma sedienta, así son las buenas nuevas de lejanas tierras."}, {"numero": 26, "texto": "Como fuente turbia y manantial corrompido, es el justo que cae delante del impío."}, {"numero": 27, "texto": "Comer mucha miel no es bueno: ni el buscar la propia gloria es gloria."}, {"numero": 28, "texto": "Como ciudad derribada y sin muro, es el hombre cuyo espíritu no tiene rienda."}]'::jsonb, 'Reina-Valera 1909'),
  ('Pv', 31, 'pt', '[{"numero": 1, "texto": "Palavras do rei Lemuel, a profecia que sua mãe o ensinava."}, {"numero": 2, "texto": "O que [posso te dizer] ,meu filho, ó filho do meu ventre? O que [te direi] ,filho de minhas promessas?"}, {"numero": 3, "texto": "Não dês tua força às mulheres, nem teus caminhos para [coisas] que destroem reis."}, {"numero": 4, "texto": "Lemuel, não convém aos reis beber vinho; nem aos príncipes [desejar] bebida alcoólica."}, {"numero": 5, "texto": "Para não acontecer de que bebam, e se esqueçam da lei, e pervertam o direito de todos os aflitos."}, {"numero": 6, "texto": "Dai bebida alcoólica aos que estão a ponto de morrer, e vinho que têm amargura na alma,"}, {"numero": 7, "texto": "Para que bebam, e se esqueçam de sua pobreza, e não se lembrem mais de sua miséria."}, {"numero": 8, "texto": "Abre tua boca no lugar do mudo pela causa judicial de todos os que estão morrendo."}, {"numero": 9, "texto": "Abre tua boca, julga corretamente, e faze justiça aos oprimidos e necessitados."}, {"numero": 10, "texto": "Mulher virtuosa, quem a encontrará? Pois seu valor é muito maior que o de rubis."}, {"numero": 11, "texto": "O coração de seu marido confia nela, e ele não terá falta de bens."}, {"numero": 12, "texto": "Ela lhe faz bem, e não o mal, todos os dias de sua vida."}, {"numero": 13, "texto": "Ela busca lã e linho, e com prazer trabalha com suas mãos."}, {"numero": 14, "texto": "Ela é como um navio mercante; de longe traz a sua comida."}, {"numero": 15, "texto": "Ainda de noite ela se levanta, e dá alimento a sua casa; e ordens às suas servas."}, {"numero": 16, "texto": "Ela avalia um campo, e o compra; do fruto de suas mãos planta uma vinha."}, {"numero": 17, "texto": "Ela prepara seus lombos com vigor, e fortalece seus braços."}, {"numero": 18, "texto": "Ela prova que suas mercadorias são boas, [e] sua lâmpada não se apaga de noite."}, {"numero": 19, "texto": "Ela estende suas mãos ao rolo de linha, e com suas mãos prepara os fios."}, {"numero": 20, "texto": "Ela estende sua mão ao aflito, e estica os braços aos necessitados."}, {"numero": 21, "texto": "Ela não terá medo da neve por sua casa, pois todos os de sua casa estão agasalhados."}, {"numero": 22, "texto": "Ela faz cobertas para sua cama; de linho fino e de púrpura é o seu vestido."}, {"numero": 23, "texto": "Seu marido é famoso às portas [da cidade] ,quando ele se senta com os anciãos da terra."}, {"numero": 24, "texto": "Ela faz panos de linho fino, e os vende; e fornece cintos aos comerciantes."}, {"numero": 25, "texto": "Força e glória são suas roupas, e ela sorri pelo seu futuro."}, {"numero": 26, "texto": "Ela abre sua boca com sabedoria; e o ensinamento bondoso está em sua língua."}, {"numero": 27, "texto": "Ela presta atenção aos rumos de sua casa, e não come pão da preguiça."}, {"numero": 28, "texto": "Seus filhos se levantam e a chamam de bem-aventurada; seu marido também a elogia, [dizendo] :"}, {"numero": 29, "texto": "Muitas mulheres agem com virtude, mas tu és melhor que todas elas."}, {"numero": 30, "texto": "A beleza é enganosa, e a formosura é passageira; [mas] a mulher que teme ao SENHOR, essa será louvada."}, {"numero": 31, "texto": "Dai a ela conforme o fruto de suas mãos, e que suas obras a louvem às portas [da cidade] ."}]'::jsonb, 'Almeida Livre'),
  ('Pv', 31, 'en', '[{"numero": 1, "texto": "The words of king Lemuel, the prophecy that his mother taught him."}, {"numero": 2, "texto": "What, my son? and what, the son of my womb? and what, the son of my vows?"}, {"numero": 3, "texto": "Give not thy strength unto women, nor thy ways to that which destroyeth kings."}, {"numero": 4, "texto": "It is not for kings, O Lemuel, it is not for kings to drink wine; nor for princes strong drink:"}, {"numero": 5, "texto": "Lest they drink, and forget the law, and pervert the judgment of any of the afflicted."}, {"numero": 6, "texto": "Give strong drink unto him that is ready to perish, and wine unto those that be of heavy hearts."}, {"numero": 7, "texto": "Let him drink, and forget his poverty, and remember his misery no more."}, {"numero": 8, "texto": "Open thy mouth for the dumb in the cause of all such as are appointed to destruction."}, {"numero": 9, "texto": "Open thy mouth, judge righteously, and plead the cause of the poor and needy."}, {"numero": 10, "texto": "Who can find a virtuous woman? for her price is far above rubies."}, {"numero": 11, "texto": "The heart of her husband doth safely trust in her, so that he shall have no need of spoil."}, {"numero": 12, "texto": "She will do him good and not evil all the days of her life."}, {"numero": 13, "texto": "She seeketh wool, and flax, and worketh willingly with her hands."}, {"numero": 14, "texto": "She is like the merchants'' ships; she bringeth her food from afar."}, {"numero": 15, "texto": "She riseth also while it is yet night, and giveth meat to her household, and a portion to her maidens."}, {"numero": 16, "texto": "She considereth a field, and buyeth it: with the fruit of her hands she planteth a vineyard."}, {"numero": 17, "texto": "She girdeth her loins with strength, and strengtheneth her arms."}, {"numero": 18, "texto": "She perceiveth that her merchandise is good: her candle goeth not out by night."}, {"numero": 19, "texto": "She layeth her hands to the spindle, and her hands hold the distaff."}, {"numero": 20, "texto": "She stretcheth out her hand to the poor; yea, she reacheth forth her hands to the needy."}, {"numero": 21, "texto": "She is not afraid of the snow for her household: for all her household are clothed with scarlet."}, {"numero": 22, "texto": "She maketh herself coverings of tapestry; her clothing is silk and purple."}, {"numero": 23, "texto": "Her husband is known in the gates, when he sitteth among the elders of the land."}, {"numero": 24, "texto": "She maketh fine linen, and selleth it; and delivereth girdles unto the merchant."}, {"numero": 25, "texto": "Strength and honour are her clothing; and she shall rejoice in time to come."}, {"numero": 26, "texto": "She openeth her mouth with wisdom; and in her tongue is the law of kindness."}, {"numero": 27, "texto": "She looketh well to the ways of her household, and eateth not the bread of idleness."}, {"numero": 28, "texto": "Her children arise up, and call her blessed; her husband also, and he praiseth her."}, {"numero": 29, "texto": "Many daughters have done virtuously, but thou excellest them all."}, {"numero": 30, "texto": "Favour is deceitful, and beauty is vain: but a woman that feareth the Lord, she shall be praised."}, {"numero": 31, "texto": "Give her of the fruit of her hands; and let her own works praise her in the gates."}]'::jsonb, 'King James Version'),
  ('Pv', 31, 'fr', '[{"numero": 1, "texto": "Paroles du roi Lemuel. Sentences par lesquelles sa mère l''''instruisit."}, {"numero": 2, "texto": "Que te dirai-je, mon fils? que te dirai-je, fils de mes entrailles? Que te dirai-je, mon fils, objet de mes voeux?"}, {"numero": 3, "texto": "Ne livre pas ta vigueur aux femmes, Et tes voies à celles qui perdent les rois."}, {"numero": 4, "texto": "Ce n''''est point aux rois, Lemuel, Ce n''''est point aux rois de boire du vin, Ni aux princes de rechercher des liqueurs fortes,"}, {"numero": 5, "texto": "De peur qu''''en buvant ils n''''oublient la loi, Et ne méconnaissent les droits de tous les malheureux."}, {"numero": 6, "texto": "Donnez des liqueurs fortes à celui qui périt, Et du vin à celui qui a l''''amertume dans l''''âme;"}, {"numero": 7, "texto": "Qu''''il boive et oublie sa pauvreté, Et qu''''il ne se souvienne plus de ses peines."}, {"numero": 8, "texto": "Ouvre ta bouche pour le muet, Pour la cause de tous les délaissés."}, {"numero": 9, "texto": "Ouvre ta bouche, juge avec justice, Et défends le malheureux et l''''indigent."}, {"numero": 10, "texto": "Qui peut trouver une femme vertueuse? Elle a bien plus de valeur que les perles."}, {"numero": 11, "texto": "Le coeur de son mari a confiance en elle, Et les produits ne lui feront pas défaut."}, {"numero": 12, "texto": "Elle lui fait du bien, et non du mal, Tous les jours de sa vie."}, {"numero": 13, "texto": "Elle se procure de la laine et du lin, Et travaille d''''une main joyeuse."}, {"numero": 14, "texto": "Elle est comme un navire marchand, Elle amène son pain de loin."}, {"numero": 15, "texto": "Elle se lève lorsqu''''il est encore nuit, Et elle donne la nourriture à sa maison Et la tâche à ses servantes."}, {"numero": 16, "texto": "Elle pense à un champ, et elle l''''acquiert; Du fruit de son travail elle plante une vigne."}, {"numero": 17, "texto": "Elle ceint de force ses reins, Et elle affermit ses bras."}, {"numero": 18, "texto": "Elle sent que ce qu''''elle gagne est bon; Sa lampe ne s''''éteint point pendant la nuit."}, {"numero": 19, "texto": "Elle met la main à la quenouille, Et ses doigts tiennent le fuseau."}, {"numero": 20, "texto": "Elle tend la main au malheureux, Elle tend la main à l''''indigent."}, {"numero": 21, "texto": "Elle ne craint pas la neige pour sa maison, Car toute sa maison est vêtue de cramoisi."}, {"numero": 22, "texto": "Elle se fait des couvertures, Elle a des vêtements de fin lin et de pourpre."}, {"numero": 23, "texto": "Son mari est considéré aux portes, Lorsqu''''il siège avec les anciens du pays."}, {"numero": 24, "texto": "Elle fait des chemises, et les vend, Et elle livre des ceintures au marchand."}, {"numero": 25, "texto": "Elle est revêtue de force et de gloire, Et elle se rit de l''''avenir."}, {"numero": 26, "texto": "Elle ouvre la bouche avec sagesse, Et des instructions aimables sont sur sa langue."}, {"numero": 27, "texto": "Elle veille sur ce qui se passe dans sa maison, Et elle ne mange pas le pain de paresse."}, {"numero": 28, "texto": "Ses fils se lèvent, et la disent heureuse; Son mari se lève, et lui donne des louanges:"}, {"numero": 29, "texto": "Plusieurs filles ont une conduite vertueuse; Mais toi, tu les surpasses toutes."}, {"numero": 30, "texto": "La grâce est trompeuse, et la beauté est vaine; La femme qui craint l''''Eternel est celle qui sera louée."}, {"numero": 31, "texto": "Récompensez-la du fruit de son travail, Et qu''''aux portes ses oeuvres la louent."}]'::jsonb, 'Louis Segond 1910'),
  ('Pv', 31, 'es', '[{"numero": 1, "texto": "PALABRAS del rey Lemuel; la profecía con que le enseñó su madre."}, {"numero": 2, "texto": "¿Qué, hijo mío? ¿y qué, hijo de mi vientre? ¿y qué, hijo de mis deseos?"}, {"numero": 3, "texto": "No des á las mujeres tu fuerza, ni tus caminos á lo que es para destruir los reyes."}, {"numero": 4, "texto": "No es de los reyes, oh Lemuel, no es de los reyes beber vino, ni de los príncipes la cerveza."}, {"numero": 5, "texto": "No sea que bebiendo olviden la ley, y perviertan el derecho de todos los hijos afligidos."}, {"numero": 6, "texto": "Dad la cerveza al desfallecido, y el vino á los de amargo ánimo:"}, {"numero": 7, "texto": "Beban, y olvídense de su necesidad, y de su miseria no más se acuerden."}, {"numero": 8, "texto": "Abre tu boca por el mudo, en el juicio de todos los hijos de muerte."}, {"numero": 9, "texto": "Abre tu boca, juzga justicia, y el derecho del pobre y del menesteroso."}, {"numero": 10, "texto": "Mujer fuerte, ¿quién la hallará? porque su estima sobrepuja largamente á la de piedras preciosas."}, {"numero": 11, "texto": "El corazón de su marido está en ella confiado, y no tendrá necesidad de despojo."}, {"numero": 12, "texto": "Darále ella bien y no mal, todos los días de su vida."}, {"numero": 13, "texto": "Buscó lana y lino, y con voluntad labró de sus manos."}, {"numero": 14, "texto": "Fué como navío de mercader: trae su pan de lejos."}, {"numero": 15, "texto": "Levantóse aun de noche, y dió comida á su familia, y ración á sus criadas."}, {"numero": 16, "texto": "Consideró la heredad, y compróla; y plantó viña del fruto de sus manos."}, {"numero": 17, "texto": "Ciñó sus lomos de fortaleza, y esforzó sus brazos."}, {"numero": 18, "texto": "Gustó que era buena su granjería: su candela no se apagó de noche."}, {"numero": 19, "texto": "Aplicó sus manos al huso, y sus manos tomaron la rueca."}, {"numero": 20, "texto": "Alargó su mano al pobre, y extendió sus manos al menesteroso."}, {"numero": 21, "texto": "No tendrá temor de la nieve por su familia, porque toda su familia está vestida de ropas dobles."}, {"numero": 22, "texto": "Ella se hizo tapices; de lino fino y púrpura es su vestido."}, {"numero": 23, "texto": "Conocido es su marido en las puertas, cuando se sienta con los ancianos de la tierra."}, {"numero": 24, "texto": "Hizo telas, y vendió; y dió cintas al mercader."}, {"numero": 25, "texto": "Fortaleza y honor son su vestidura; y en el día postrero reirá."}, {"numero": 26, "texto": "Abrió su boca con sabiduría: y la ley de clemencia está en su lengua."}, {"numero": 27, "texto": "Considera los caminos de su casa, y no come el pan de balde."}, {"numero": 28, "texto": "Levantáronse sus hijos, y llamáronla bienaventurada; y su marido también la alabó."}, {"numero": 29, "texto": "Muchas mujeres hicieron el bien; mas tú las sobrepujaste á todas."}, {"numero": 30, "texto": "Engañosa es la gracia, y vana la hermosura: la mujer que teme á Jehová, ésa será alabada."}, {"numero": 31, "texto": "Dadle el fruto de sus manos, y alábenla en las puertas sus hechos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Rm', 1, 'pt', '[{"numero": 1, "texto": "Paulo, servo de Jesus Cristo, chamado [para ser] apóstolo, separado para o evangelho de Deus,"}, {"numero": 2, "texto": "que antes havia prometido por meio dos seus profetas nas santas Escrituras,"}, {"numero": 3, "texto": "acerca do seu Filho (que, quanto à carne, nasceu da descendência de Davi,"}, {"numero": 4, "texto": "e declarado Filho de Deus em poder, segundo o Espírito de santidade, pela ressurreição dos mortos): Jesus Cristo, nosso Senhor."}, {"numero": 5, "texto": "Por ele recebemos graça e apostolado, para a obediência da fé entre todas as nações, por causa do seu nome."}, {"numero": 6, "texto": "Entre elas sois também vós, chamados [para serdes] de Jesus Cristo."}, {"numero": 7, "texto": "A todos que estais em Roma, amados de Deus, e chamados de santos: convosco haja graça e paz da parte de Deus, nosso Pai, e do Senhor Jesus Cristo."}, {"numero": 8, "texto": "Em primeiro lugar, agradeço ao meu Deus por meio de Jesus Cristo, por todos vós, porque a vossa fé é anunciada no mundo todo."}, {"numero": 9, "texto": "Pois Deus, a quem sirvo em meu espírito no evangelho do seu Filho, é minha testemunha de como sem cessar faço menção de vós,"}, {"numero": 10, "texto": "rogando sempre em minhas orações, que agora, de alguma maneira, finalmente, tenha eu a oportunidade de, pela vontade de Deus, vir vos visitar."}, {"numero": 11, "texto": "Pois eu desejo ver-vos, para compartilhar convosco algum dom espiritual, para que sejais fortalecidos;"}, {"numero": 12, "texto": "isto é, para eu ser consolado juntamente convosco pela fé mútua, tanto a vossa, como a minha."}, {"numero": 13, "texto": "Porém, irmãos, não quero que ignoreis que muitas vezes pretendi vir à vossa presença (mas fui impedido até agora), a fim de que eu também tivesse algum fruto entre vós, como também entre os demais gentios."}, {"numero": 14, "texto": "Eu sou devedor, tanto a gregos como a bárbaros, tanto a sábios como a não sábios."}, {"numero": 15, "texto": "Portanto, quanto a mim, pronto estou para anunciar o evangelho também a vós, que estais em Roma."}, {"numero": 16, "texto": "Porque não me envergonho do Evangelho de Cristo, pois é o poder de Deus para a salvação de todo aquele que crê, primeiramente do judeu, e também do grego."}, {"numero": 17, "texto": "Pois no Evangelho se revela a justiça de Deus de fé em fé; como está escrito: O justo viverá pela fé."}, {"numero": 18, "texto": "Porque a ira de Deus se manifesta do céu contra toda irreverência e injustiça das pessoas que bloqueiam a verdade pela injustiça;"}, {"numero": 19, "texto": "pois o que se pode conhecer de Deus é evidente a eles, porque Deus lhes manifestou."}, {"numero": 20, "texto": "Pois as suas características invisíveis, inclusive o seu eterno poder e divindade, desde a criação do mundo são entendidas e claramente vistas por meio das coisas criadas, para que não tenham desculpa;"}, {"numero": 21, "texto": "Porque, ainda que tenham conhecido Deus, não o glorificaram como Deus, nem foram gratos; em vez disso, perderam o bom senso em seus pensamentos, e seus tolos corações ficaram em trevas."}, {"numero": 22, "texto": "Chamando a si mesmos de sábios, tornaram-se tolos,"}, {"numero": 23, "texto": "e trocaram a glória de Deus indestrutível por semelhança de imagem do ser humano destrutível, e de aves, de quadrúpedes, e de répteis."}, {"numero": 24, "texto": "Por isso, Deus os entregou à imundície, nos desejos dos seus corações, para desonrarem os seus corpos entre si."}, {"numero": 25, "texto": "Trocaram a verdade de Deus pela mentira, e adoraram e serviram à criatura mais do que ao Criador, que é bendito eternamente, Amém!"}, {"numero": 26, "texto": "Por isso, Deus os entregou a paixões infames. Pois até suas mulheres trocaram o hábito [sexual] natural pelo que era contra a natureza;"}, {"numero": 27, "texto": "e também, de semelhante maneira, os machos abandonaram o hábito [sexual] natural com a mulher, e acenderam sua sensualidade uns com os outros, homens com homens, praticando indecência, e recebendo em si mesmos a devida retribuição pelo seu erro."}, {"numero": 28, "texto": "E como recusaram reconhecer a Deus, [o mesmo] Deus os entregou a uma mente corrompida, para fazerem coisas impróprias."}, {"numero": 29, "texto": "[Assim, estão] cheios de toda injustiça, pecado sexual, malícia, ganância, maldade; estão repletos de inveja, homicídio, brigas, engano, malignidade;"}, {"numero": 30, "texto": "são murmuradores, difamadores, e odeiam a Deus; são insolentes, soberbos, presunçosos, inventores de males, e desobedientes aos pais;"}, {"numero": 31, "texto": "não têm entendimento, quebram acordos, são insensíveis, e recusam-se a perdoar ou a mostrar misericórdia."}, {"numero": 32, "texto": "Apesar de conhecerem o juízo de Deus (de que os que fazem tais coisas merecem a morte), não somente as fazem, como também aprovam os que as praticam."}]'::jsonb, 'Almeida Livre'),
  ('Rm', 1, 'en', '[{"numero": 1, "texto": "Paul, a servant of Jesus Christ, called to be an apostle, separated unto the gospel of God,"}, {"numero": 2, "texto": "(Which he had promised afore by his prophets in the holy scriptures,)"}, {"numero": 3, "texto": "Concerning his Son Jesus Christ our Lord, which was made of the seed of David according to the flesh;"}, {"numero": 4, "texto": "And declared to be the Son of God with power, according to the spirit of holiness, by the resurrection from the dead:"}, {"numero": 5, "texto": "By whom we have received grace and apostleship, for obedience to the faith among all nations, for his name:"}, {"numero": 6, "texto": "Among whom are ye also the called of Jesus Christ:"}, {"numero": 7, "texto": "To all that be in Rome, beloved of God, called to be saints: Grace to you and peace from God our Father, and the Lord Jesus Christ."}, {"numero": 8, "texto": "First, I thank my God through Jesus Christ for you all, that your faith is spoken of throughout the whole world."}, {"numero": 9, "texto": "For God is my witness, whom I serve with my spirit in the gospel of his Son, that without ceasing I make mention of you always in my prayers;"}, {"numero": 10, "texto": "Making request, if by any means now at length I might have a prosperous journey by the will of God to come unto you."}, {"numero": 11, "texto": "For I long to see you, that I may impart unto you some spiritual gift, to the end ye may be established;"}, {"numero": 12, "texto": "That is, that I may be comforted together with you by the mutual faith both of you and me."}, {"numero": 13, "texto": "Now I would not have you ignorant, brethren, that oftentimes I purposed to come unto you, (but was let hitherto,) that I might have some fruit among you also, even as among other Gentiles."}, {"numero": 14, "texto": "I am debtor both to the Greeks, and to the Barbarians; both to the wise, and to the unwise."}, {"numero": 15, "texto": "So, as much as in me is, I am ready to preach the gospel to you that are at Rome also."}, {"numero": 16, "texto": "For I am not ashamed of the gospel of Christ: for it is the power of God unto salvation to every one that believeth; to the Jew first, and also to the Greek."}, {"numero": 17, "texto": "For therein is the righteousness of God revealed from faith to faith: as it is written, The just shall live by faith."}, {"numero": 18, "texto": "For the wrath of God is revealed from heaven against all ungodliness and unrighteousness of men, who hold the truth in unrighteousness;"}, {"numero": 19, "texto": "Because that which may be known of God is manifest in them; for God hath shewed it unto them."}, {"numero": 20, "texto": "For the invisible things of him from the creation of the world are clearly seen, being understood by the things that are made, even his eternal power and Godhead; so that they are without excuse:"}, {"numero": 21, "texto": "Because that, when they knew God, they glorified him not as God, neither were thankful; but became vain in their imaginations, and their foolish heart was darkened."}, {"numero": 22, "texto": "Professing themselves to be wise, they became fools,"}, {"numero": 23, "texto": "And changed the glory of the uncorruptible God into an image made like to corruptible man, and to birds, and fourfooted beasts, and creeping things."}, {"numero": 24, "texto": "Wherefore God also gave them up to uncleanness through the lusts of their own hearts, to dishonour their own bodies between themselves:"}, {"numero": 25, "texto": "Who changed the truth of God into a lie, and worshipped and served the creature more than the Creator, who is blessed for ever. Amen."}, {"numero": 26, "texto": "For this cause God gave them up unto vile affections: for even their women did change the natural use into that which is against nature:"}, {"numero": 27, "texto": "And likewise also the men, leaving the natural use of the woman, burned in their lust one toward another; men with men working that which is unseemly, and receiving in themselves that recompence of their error which was meet."}, {"numero": 28, "texto": "And even as they did not like to retain God in their knowledge, God gave them over to a reprobate mind, to do those things which are not convenient;"}, {"numero": 29, "texto": "Being filled with all unrighteousness, fornication, wickedness, covetousness, maliciousness; full of envy, murder, debate, deceit, malignity; whisperers,"}, {"numero": 30, "texto": "Backbiters, haters of God, despiteful, proud, boasters, inventors of evil things, disobedient to parents,"}, {"numero": 31, "texto": "Without understanding, covenantbreakers, without natural affection, implacable, unmerciful:"}, {"numero": 32, "texto": "Who knowing the judgment of God, that they which commit such things are worthy of death, not only do the same, but have pleasure in them that do them."}]'::jsonb, 'King James Version'),
  ('Rm', 1, 'fr', '[{"numero": 1, "texto": "Paul, serviteur de Jésus-Christ, appelé à être apôtre, mis à part pour annoncer l''''Evangile de Dieu, -"}, {"numero": 2, "texto": "qui avait été promis auparavant de la part de Dieu par ses prophètes dans les saintes Ecritures,"}, {"numero": 3, "texto": "et qui concerne son Fils né de la postérité de David, selon la chair,"}, {"numero": 4, "texto": "et déclaré Fils de Dieu avec puissance, selon l''''Esprit de sainteté, par sa résurrection d''''entre les morts, Jésus-Christ notre Seigneur,"}, {"numero": 5, "texto": "par qui nous avons reçu la grâce et l''''apostolat, pour amener en son nom à l''''obéissance de la foi tous les païens,"}, {"numero": 6, "texto": "parmi lesquels vous êtes aussi, vous qui avez été appelés par Jésus-Christ, -"}, {"numero": 7, "texto": "tous ceux qui, à Rome, sont bien-aimés de Dieu, appelés à être saints: que la grâce et la paix vous soient données de la part de Dieu notre Père et du Seigneur Jésus-Christ!"}, {"numero": 8, "texto": "Je rends d''''abord grâces à mon Dieu par Jésus-Christ, au sujet de vous tous, de ce que votre foi est renommée dans le monde entier."}, {"numero": 9, "texto": "Dieu, que je sers en mon esprit dans l''''Evangile de son Fils, m''''est témoin que je fais sans cesse mention de vous,"}, {"numero": 10, "texto": "demandant continuellement dans mes prières d''''avoir enfin, par sa volonté, le bonheur d''''aller vers vous."}, {"numero": 11, "texto": "Car je désire vous voir, pour vous communiquer quelque don spirituel, afin que vous soyez affermis,"}, {"numero": 12, "texto": "ou plutôt, afin que nous soyons encouragés ensemble au milieu de vous par la foi qui nous est commune, à vous et à moi."}, {"numero": 13, "texto": "Je ne veux pas vous laisser ignorer, frères, que j''''ai souvent formé le projet d''''aller vous voir, afin de recueillir quelque fruit parmi vous, comme parmi les autres nations; mais j''''en ai été empêché jusqu''''ici."}, {"numero": 14, "texto": "Je me dois aux Grecs et aux barbares, aux savants et aux ignorants."}, {"numero": 15, "texto": "Ainsi j''''ai un vif désir de vous annoncer aussi l''''Evangile, à vous qui êtes à Rome."}, {"numero": 16, "texto": "Car je n''''ai point honte de l''''Evangile: c''''est une puissance de Dieu pour le salut de quiconque croit, du Juif premièrement, puis du Grec,"}, {"numero": 17, "texto": "parce qu''''en lui est révélée la justice de Dieu par la foi et pour la foi, selon qu''''il est écrit: Le juste vivra par la foi."}, {"numero": 18, "texto": "La colère de Dieu se révèle du ciel contre toute impiété et toute injustice des hommes qui retiennent injustement la vérité captive,"}, {"numero": 19, "texto": "car ce qu''''on peut connaître de Dieu est manifeste pour eux, Dieu le leur ayant fait connaître."}, {"numero": 20, "texto": "En effet, les perfections invisibles de Dieu, sa puissance éternelle et sa divinité, se voient comme à l''''oeil, depuis la création du monde, quand on les considère dans ses ouvrages. Ils sont donc inexcusables,"}, {"numero": 21, "texto": "puisque ayant connu Dieu, ils ne l''''ont point glorifié comme Dieu, et ne lui ont point rendu grâces; mais ils se sont égarés dans leurs pensées, et leur coeur sans intelligence a été plongé dans les ténèbres."}, {"numero": 22, "texto": "Se vantant d''''être sages, ils sont devenus fous;"}, {"numero": 23, "texto": "et ils ont changé la gloire du Dieu incorruptible en images représentant l''''homme corruptible, des oiseaux, des quadrupèdes, et des reptiles."}, {"numero": 24, "texto": "C''''est pourquoi Dieu les a livrés à l''''impureté, selon les convoitises de leurs coeurs; en sorte qu''''ils déshonorent eux-mêmes leurs propres corps;"}, {"numero": 25, "texto": "eux qui ont changé la vérité de Dieu en mensonge, et qui ont adoré et servi la créature au lieu du Créateur, qui est béni éternellement. Amen!"}, {"numero": 26, "texto": "C''''est pourquoi Dieu les a livrés à des passions infâmes: car leurs femmes ont changé l''''usage naturel en celui qui est contre nature;"}, {"numero": 27, "texto": "et de même les hommes, abandonnant l''''usage naturel de la femme, se sont enflammés dans leurs désirs les uns pour les autres, commettant homme avec homme des choses infâmes, et recevant en eux-mêmes le salaire que méritait leur égarement."}, {"numero": 28, "texto": "Comme ils ne se sont pas souciés de connaître Dieu, Dieu les a livrés à leur sens réprouvé, pour commettre des choses indignes,"}, {"numero": 29, "texto": "tant remplis de toute espèce d''''injustice, de méchanceté, de cupidité, de malice; pleins d''''envie, de meurtre, de querelle, de ruse, de malignité; rapporteurs,"}, {"numero": 30, "texto": "médisants, impies, arrogants, hautains, fanfarons, ingénieux au mal, rebelles à leurs parents,"}, {"numero": 31, "texto": "dépourvus d''''intelligence, de loyauté, d''''affection naturelle, de miséricorde."}, {"numero": 32, "texto": "Et, bien qu''''ils connaissent le jugement de Dieu, déclarant dignes de mort ceux qui commettent de telles choses, non seulement ils les font, mais ils approuvent ceux qui les font."}]'::jsonb, 'Louis Segond 1910'),
  ('Rm', 1, 'es', '[{"numero": 1, "texto": "PABLO, siervo de Jesucristo, llamado á ser apóstol, apartado para el evangelio de Dios,"}, {"numero": 2, "texto": "Que él había antes prometido por sus profetas en las santas Escrituras,"}, {"numero": 3, "texto": "Acerca de su Hijo, (que fué hecho de la simiente de David según la carne;"}, {"numero": 4, "texto": "El cual fué declarado Hijo de Dios con potencia, según el espíritu de santidad, por la resurrección de los muertos), de Jesucristo Señor nuestro,"}, {"numero": 5, "texto": "Por el cual recibimos la gracia y el apostolado, para la obediencia de la fe en todas las naciones en su nombre,"}, {"numero": 6, "texto": "Entre las cuales sois también vosotros, llamados de Jesucristo:"}, {"numero": 7, "texto": "A todos los que estáis en Roma, amados de Dios, llamados santos: Gracia y paz tengáis de Dios nuestro Padre, y del Señor Jesucristo."}, {"numero": 8, "texto": "Primeramente, doy gracias á mi Dios por Jesucristo acerca de todos vosotros, de que vuestra fe es predicada en todo el mundo."}, {"numero": 9, "texto": "Porque testigo me es Dios, al cual sirvo en mi espíritu en el evangelio de su Hijo, que sin cesar me acuerdo de vosotros siempre en mis oraciones,"}, {"numero": 10, "texto": "Rogando, si al fin algún tiempo haya de tener, por la voluntad de Dios, próspero viaje para ir á vosotros."}, {"numero": 11, "texto": "Porque os deseo ver, para repartir con vosotros algún don espiritual, para confirmaros;"}, {"numero": 12, "texto": "Es á saber, para ser juntamente consolado con vosotros por la común fe vuestra y juntamente mía."}, {"numero": 13, "texto": "Mas no quiero, hermanos, que ignoréis que muchas veces me he propuesto ir á vosotros (empero hasta ahora he sido estorbado), para tener también entre vosotros algún fruto, como entre los demás Gentiles."}, {"numero": 14, "texto": "A Griegos y á bárbaros, á sabios y á no sabios soy deudor."}, {"numero": 15, "texto": "Así que, cuanto á mí, presto estoy á anunciar el evangelio también á vosotros que estáis en Roma."}, {"numero": 16, "texto": "Porque no me avergüenzo del evangelio: porque es potencia de Dios para salud á todo aquel que cree; al Judío primeramente y también al Griego."}, {"numero": 17, "texto": "Porque en él la justicia de Dios se descubre de fe en fe; como está escrito: Mas el justo vivirá por la fe."}, {"numero": 18, "texto": "Porque manifiesta es la ira de Dios del cielo contra toda impiedad é injusticia de los hombres, que detienen la verdad con injusticia:"}, {"numero": 19, "texto": "Porque lo que de Dios se conoce, á ellos es manifiesto; porque Dios se lo manifestó."}, {"numero": 20, "texto": "Porque las cosas invisibles de él, su eterna potencia y divinidad, se echan de ver desde la creación del mundo, siendo entendidas por las cosas que son hechas; de modo que son inexcusables:"}, {"numero": 21, "texto": "Porque habiendo conocido á Dios, no le glorificaron como á Dios, ni dieron gracias; antes se desvanecieron en sus discursos, y el necio corazón de ellos fué entenebrecido."}, {"numero": 22, "texto": "Diciéndose ser sabios, se hicieron fatuos,"}, {"numero": 23, "texto": "Y trocaron la gloria del Dios incorruptible en semejanza de imagen de hombre corruptible, y de aves, y de animales de cuatro pies, y de serpientes."}, {"numero": 24, "texto": "Por lo cual también Dios los entregó á inmundicia, en las concupiscencias de sus corazones, de suerte que contaminaron sus cuerpos entre sí mismos:"}, {"numero": 25, "texto": "Los cuales mudaron la verdad de Dios en mentira, honrando y sirviendo á las criaturas antes que al Criador, el cual es bendito por los siglos. Amén."}, {"numero": 26, "texto": "Por esto Dios los entregó á afectos vergonzosos; pues aun sus mujeres mudaron el natural uso en el uso que es contra naturaleza:"}, {"numero": 27, "texto": "Y del mismo modo también los hombres, dejando el uso natural de las mujeres, se encendieron en sus concupiscencias los unos con los otros, cometiendo cosas nefandas hombres con hombres, y recibiendo en sí mismos la recompensa que convino á su extravío."}, {"numero": 28, "texto": "Y como á ellos no les pareció tener á Dios en su noticia, Dios los entregó á una mente depravada, para hacer lo que no conviene,"}, {"numero": 29, "texto": "Estando atestados de toda iniquidad, de fornicación, de malicia, de avaricia, de maldad; llenos de envidia, de homicidios, de contiendas, de engaños, de malignidades;"}, {"numero": 30, "texto": "Murmuradores, detractores, aborrecedores de Dios, injuriosos, soberbios, altivos, inventores de males, desobedientes á los padres,"}, {"numero": 31, "texto": "Necios, desleales, sin afecto natural, implacables, sin misericordia:"}, {"numero": 32, "texto": "Que, habiendo entendido el juicio de Dios que los que hacen tales cosas son dignos de muerte, no sólo las hacen, mas aun consienten á los que las hacen."}]'::jsonb, 'Reina-Valera 1909'),
  ('Rm', 3, 'pt', '[{"numero": 1, "texto": "Qual, pois, é a vantagem do judeu? Ou qual é a utilidade da circuncisão?"}, {"numero": 2, "texto": "Muita, em toda maneira. Pois, em primeiro lugar, as palavras de Deus lhes foram confiadas."}, {"numero": 3, "texto": "Então, quê? Se alguns foram infiéis, a infidelidade deles anulará a fidelidade de Deus?"}, {"numero": 4, "texto": "De maneira nenhuma! Antes seja Deus verdadeiro, e todo ser humano mentiroso, como está escrito: “Para que sejas justificado em tuas palavras, e prevaleças quando julgares”."}, {"numero": 5, "texto": "E, se a nossa injustiça evidencia a justiça de Deus, que diremos? Acaso Deus é injusto em impor [a sua] ira? (Falo na lógica humana)."}, {"numero": 6, "texto": "De maneira nenhuma! De outro modo, como Deus julgará o mundo?"}, {"numero": 7, "texto": "Pois se, através da minha mentira, a verdade de Deus foi mais abundante para a sua glória, por que ainda sou também julgado como pecador?"}, {"numero": 8, "texto": "E por que não [dizer] : “Façamos o mal, para que venha o bem”, como alguns nos caluniam, afirmando que nós dizemos isto? (A condenação destes é justa)."}, {"numero": 9, "texto": "Então, quê? Somos nós melhores? Não, de maneira nenhuma. Pois já delatamos que todos, tanto judeus como gregos, estão debaixo do pecado,"}, {"numero": 10, "texto": "como está escrito: Não há justo, nem um sequer."}, {"numero": 11, "texto": "Ninguém há que entenda, ninguém há que busque a Deus."}, {"numero": 12, "texto": "Todos se desviaram, e juntamente se tornaram inúteis. “Não há quem faça o bem, não há um sequer”."}, {"numero": 13, "texto": "“Suas gargantas são sepulcro aberto; com suas línguas enganam”; “veneno de serpentes está sob seus lábios”."}, {"numero": 14, "texto": "“Suas bocas estão cheias de maldição e amargura”."}, {"numero": 15, "texto": "“Seus pés são velozes para derramar sangue."}, {"numero": 16, "texto": "Destruição e miséria há em seus caminhos,"}, {"numero": 17, "texto": "e não conheceram o caminho da paz”."}, {"numero": 18, "texto": "“Diante dos seus olhos não há temor a Deus”."}, {"numero": 19, "texto": "Ora, sabemos que tudo o que a Lei diz, diz aos que estão na Lei, para que toda boca se cale, e todo o mundo seja condenável perante Deus."}, {"numero": 20, "texto": "Assim, ninguém será justificado diante dele pelas obras da Lei, porque o que vem pela Lei é o conhecimento do pecado."}, {"numero": 21, "texto": "Mas agora, independentemente da Lei, a justiça de Deus se manifestou, tendo testemunho da Lei e dos Profetas;"}, {"numero": 22, "texto": "isto é, a justiça de Deus por meio da fé em Jesus Cristo, para todos e sobre todos os que creem; pois não há diferença;"}, {"numero": 23, "texto": "porque todos pecaram, e estão destituídos da glória de Deus;"}, {"numero": 24, "texto": "e são justificados gratuitamente pela sua graça, por meio da redenção que há em Cristo Jesus."}, {"numero": 25, "texto": "Deus propôs Jesus por sacrifício de reconciliação, pela fé em seu sangue, para demonstrar a sua justiça. Ele deixou de considerar os pecados antes cometidos, sob a paciência de Deus,"}, {"numero": 26, "texto": "para demonstrar a sua justiça neste presente tempo, a fim de que ele seja justo, e justificador daquele que tem fé em Jesus."}, {"numero": 27, "texto": "Onde, pois, está o orgulho? Este é excluído. Por qual lei? A das obras? Não, mas sim, pela Lei da fé."}, {"numero": 28, "texto": "Concluímos, portanto, que o ser humano é justificado pela fé, independentemente das obras da Lei."}, {"numero": 29, "texto": "Por acaso Deus é somente dos judeus, e não também dos gentios? Certamente que dos gentios também;"}, {"numero": 30, "texto": "já que há um só Deus, que justificará pela fé os circuncisos, e por meio da fé os incircuncisos."}, {"numero": 31, "texto": "Por acaso anulamos a Lei pela fé? De maneira nenhuma. Pelo contrário, confirmamos a Lei."}]'::jsonb, 'Almeida Livre'),
  ('Rm', 3, 'en', '[{"numero": 1, "texto": "What advantage then hath the Jew? or what profit is there of circumcision?"}, {"numero": 2, "texto": "Much every way: chiefly, because that unto them were committed the oracles of God."}, {"numero": 3, "texto": "For what if some did not believe? shall their unbelief make the faith of God without effect?"}, {"numero": 4, "texto": "God forbid: yea, let God be true, but every man a liar; as it is written, That thou mightest be justified in thy sayings, and mightest overcome when thou art judged."}, {"numero": 5, "texto": "But if our unrighteousness commend the righteousness of God, what shall we say? Is God unrighteous who taketh vengeance? (I speak as a man)"}, {"numero": 6, "texto": "God forbid: for then how shall God judge the world?"}, {"numero": 7, "texto": "For if the truth of God hath more abounded through my lie unto his glory; why yet am I also judged as a sinner?"}, {"numero": 8, "texto": "And not rather, (as we be slanderously reported, and as some affirm that we say,) Let us do evil, that good may come? whose damnation is just."}, {"numero": 9, "texto": "What then? are we better than they? No, in no wise: for we have before proved both Jews and Gentiles, that they are all under sin;"}, {"numero": 10, "texto": "As it is written, There is none righteous, no, not one:"}, {"numero": 11, "texto": "There is none that understandeth, there is none that seeketh after God."}, {"numero": 12, "texto": "They are all gone out of the way, they are together become unprofitable; there is none that doeth good, no, not one."}, {"numero": 13, "texto": "Their throat is an open sepulchre; with their tongues they have used deceit; the poison of asps is under their lips:"}, {"numero": 14, "texto": "Whose mouth is full of cursing and bitterness:"}, {"numero": 15, "texto": "Their feet are swift to shed blood:"}, {"numero": 16, "texto": "Destruction and misery are in their ways:"}, {"numero": 17, "texto": "And the way of peace have they not known:"}, {"numero": 18, "texto": "There is no fear of God before their eyes."}, {"numero": 19, "texto": "Now we know that what things soever the law saith, it saith to them who are under the law: that every mouth may be stopped, and all the world may become guilty before God."}, {"numero": 20, "texto": "Therefore by the deeds of the law there shall no flesh be justified in his sight: for by the law is the knowledge of sin."}, {"numero": 21, "texto": "But now the righteousness of God without the law is manifested, being witnessed by the law and the prophets;"}, {"numero": 22, "texto": "Even the righteousness of God which is by faith of Jesus Christ unto all and upon all them that believe: for there is no difference:"}, {"numero": 23, "texto": "For all have sinned, and come short of the glory of God;"}, {"numero": 24, "texto": "Being justified freely by his grace through the redemption that is in Christ Jesus:"}, {"numero": 25, "texto": "Whom God hath set forth to be a propitiation through faith in his blood, to declare his righteousness for the remission of sins that are past, through the forbearance of God;"}, {"numero": 26, "texto": "To declare, I say, at this time his righteousness: that he might be just, and the justifier of him which believeth in Jesus."}, {"numero": 27, "texto": "Where is boasting then? It is excluded. By what law? of works? Nay: but by the law of faith."}, {"numero": 28, "texto": "Therefore we conclude that a man is justified by faith without the deeds of the law."}, {"numero": 29, "texto": "Is he the God of the Jews only? is he not also of the Gentiles? Yes, of the Gentiles also:"}, {"numero": 30, "texto": "Seeing it is one God, which shall justify the circumcision by faith, and uncircumcision through faith."}, {"numero": 31, "texto": "Do we then make void the law through faith? God forbid: yea, we establish the law."}]'::jsonb, 'King James Version'),
  ('Rm', 3, 'fr', '[{"numero": 1, "texto": "Quel est donc l''''avantage des Juifs, ou quelle est l''''utilité de la circoncision?"}, {"numero": 2, "texto": "Il est grand de toute manière, et tout d''''abord en ce que les oracles de Dieu leur ont été confiés."}, {"numero": 3, "texto": "Eh quoi! si quelques-uns n''''ont pas cru, leur incrédulité anéantira-t-elle la fidélité de Dieu?"}, {"numero": 4, "texto": "Loin de là! Que Dieu, au contraire, soit reconnu pour vrai, et tout homme pour menteur, selon qu''''il est écrit: Afin que tu sois trouvé juste dans tes paroles, Et que tu triomphes lorsqu''''on te juge."}, {"numero": 5, "texto": "Mais si notre injustice établit la justice de Dieu, que dirons-nous? Dieu est-il injuste quand il déchaîne sa colère? Je parle à la manière des hommes."}, {"numero": 6, "texto": "Loin de là! Autrement, comment Dieu jugerait-il le monde?"}, {"numero": 7, "texto": "Et si, par mon mensonge, la vérité de Dieu éclate davantage pour sa gloire, pourquoi suis-je moi-même encore jugé comme pécheur?"}, {"numero": 8, "texto": "Et pourquoi ne ferions-nous pas le mal afin qu''''il en arrive du bien, comme quelques-uns, qui nous calomnient, prétendent que nous le disons? La condamnation de ces gens est juste."}, {"numero": 9, "texto": "Quoi donc! sommes-nous plus excellents? Nullement. Car nous avons déjà prouvé que tous, Juifs et Grecs, sont sous l''''empire du péché,"}, {"numero": 10, "texto": "selon qu''''il est écrit: Il n''''y a point de juste, Pas même un seul;"}, {"numero": 11, "texto": "Nul n''''est intelligent, Nul ne cherche Dieu;"}, {"numero": 12, "texto": "Tous sont égarés, tous sont pervertis; Il n''''en est aucun qui fasse le bien, Pas même un seul;"}, {"numero": 13, "texto": "Leur gosier est un sépulcre ouvert; Ils se servent de leurs langues pour tromper; Ils ont sous leurs lèvres un venin d''''aspic;"}, {"numero": 14, "texto": "Leur bouche est pleine de malédiction et d''''amertume;"}, {"numero": 15, "texto": "Ils ont les pieds légers pour répandre le sang;"}, {"numero": 16, "texto": "La destruction et le malheur sont sur leur route;"}, {"numero": 17, "texto": "Ils ne connaissent pas le chemin de la paix;"}, {"numero": 18, "texto": "La crainte de Dieu n''''est pas devant leurs yeux."}, {"numero": 19, "texto": "Or, nous savons que tout ce que dit la loi, elle le dit à ceux qui sont sous la loi, afin que toute bouche soit fermée, et que tout le monde soit reconnu coupable devant Dieu."}, {"numero": 20, "texto": "Car nul ne sera justifié devant lui par les oeuvres de la loi, puisque c''''est par la loi que vient la connaissance du péché."}, {"numero": 21, "texto": "Mais maintenant, sans la loi est manifestée la justice de Dieu, à laquelle rendent témoignage la loi et les prophètes,"}, {"numero": 22, "texto": "justice de Dieu par la foi en Jésus-Christ pour tous ceux qui croient. Il n''''y a point de distinction."}, {"numero": 23, "texto": "Car tous ont péché et sont privés de la gloire de Dieu;"}, {"numero": 24, "texto": "et ils sont gratuitement justifiés par sa grâce, par le moyen de la rédemption qui est en Jésus-Christ."}, {"numero": 25, "texto": "C''''est lui que Dieu a destiné, par son sang, à être, pour ceux qui croiraient victime propitiatoire, afin de montrer sa justice, parce qu''''il avait laissé impunis les péchés commis auparavant, au temps de sa patience, afin, dis-je,"}, {"numero": 26, "texto": "de montrer sa justice dans le temps présent, de manière à être juste tout en justifiant celui qui a la foi en Jésus."}, {"numero": 27, "texto": "Où donc est le sujet de se glorifier? Il est exclu. Par quelle loi? Par la loi des oeuvres? Non, mais par la loi de la foi."}, {"numero": 28, "texto": "Car nous pensons que l''''homme est justifié par la foi, sans les oeuvres de la loi."}, {"numero": 29, "texto": "Ou bien Dieu est-il seulement le Dieu des Juifs? Ne l''''est-il pas aussi des païens? Oui, il l''''est aussi des païens,"}, {"numero": 30, "texto": "puisqu''''il y a un seul Dieu, qui justifiera par la foi les circoncis, et par la foi les incirconcis."}, {"numero": 31, "texto": "Anéantissons-nous donc la loi par la foi? Loin de là! Au contraire, nous confirmons la loi."}]'::jsonb, 'Louis Segond 1910'),
  ('Rm', 3, 'es', '[{"numero": 1, "texto": "¿QUÉ, pues, tiene más el Judío? ¿ó qué aprovecha la circuncisión?"}, {"numero": 2, "texto": "Mucho en todas maneras. Lo primero ciertamente, que la palabra de Dios les ha sido confiada."}, {"numero": 3, "texto": "¿Pues qué si algunos de ellos han sido incrédulos? ¿la incredulidad de ellos habrá hecho vana la verdad de Dios?"}, {"numero": 4, "texto": "En ninguna manera; antes bien sea Dios verdadero, mas todo hombre mentiroso; como está escrito: Para que seas justificado en tus dichos, y venzas cuando de ti se juzgare."}, {"numero": 5, "texto": "Y si nuestra iniquidad encarece la justicia de Dios, ¿qué diremos? ¿Será injusto Dios que da castigo? (hablo como hombre.)"}, {"numero": 6, "texto": "En ninguna manera: de otra suerte ¿cómo juzgaría Dios el mundo?"}, {"numero": 7, "texto": "Empero si la verdad de Dios por mi mentira creció á gloria suya, ¿por qué aun así yo soy juzgado como pecador?"}, {"numero": 8, "texto": "¿Y por qué no decir (como somos blasfemados, y como algunos dicen que nosotros decimos): Hagamos males para que vengan bienes? la condenación de los cuales es justa."}, {"numero": 9, "texto": "¿Qué pues? ¿Somos mejores que ellos? En ninguna manera: porque ya hemos acusado á Judíos y á Gentiles, que todos están debajo de pecado."}, {"numero": 10, "texto": "Como está escrito: No hay justo, ni aun uno;"}, {"numero": 11, "texto": "No hay quien entienda, no hay quien busque á Dios;"}, {"numero": 12, "texto": "Todos se apartaron, á una fueron hechos inútiles; no hay quien haga lo bueno, no hay ni aun uno:"}, {"numero": 13, "texto": "Sepulcro abierto es su garganta; con sus lenguas tratan engañosamente; veneno de áspides está debajo de sus labios;"}, {"numero": 14, "texto": "Cuya boca está llena de maledicencia y de amargura;"}, {"numero": 15, "texto": "Sus pies son ligeros á derramar sangre;"}, {"numero": 16, "texto": "Quebrantamiento y desventura hay en sus caminos;"}, {"numero": 17, "texto": "Y camino de paz no conocieron:"}, {"numero": 18, "texto": "No hay temor de Dios delante de sus ojos."}, {"numero": 19, "texto": "Empero sabemos que todo lo que la ley dice, á los que están en la ley lo dice, para que toda boca se tape, y que todo el mundo se sujete á Dios:"}, {"numero": 20, "texto": "Porque por las obras de la ley ninguna carne se justificará delante de él; porque por la ley es el conocimiento del pecado."}, {"numero": 21, "texto": "Mas ahora, sin la ley, la justicia de Dios se ha manifestado, testificada por la ley y por los profetas:"}, {"numero": 22, "texto": "La justicia de Dios por la fe de Jesucristo, para todos los que creen en él; porque no hay diferencia;"}, {"numero": 23, "texto": "Por cuanto todos pecaron, y están destituídos de la gloria de Dios;"}, {"numero": 24, "texto": "Siendo justificados gratuitamente por su gracia, por la redención que es en Cristo Jesús;"}, {"numero": 25, "texto": "Al cual Dios ha propuesto en propiciación por la fe en su sangre, para manifestación de su justicia, atento á haber pasado por alto, en su paciencia, los pecados pasados,"}, {"numero": 26, "texto": "Con la mira de manifestar su justicia en este tiempo: para que él sea el justo, y el que justifica al que es de la fe de Jesús."}, {"numero": 27, "texto": "¿Dónde pues está la jactancia? Es excluída. ¿Por cuál ley? ¿de las obras? No; mas por la ley de la fe."}, {"numero": 28, "texto": "Así que, concluímos ser el hombre justificado por fe sin las obras de la ley."}, {"numero": 29, "texto": "¿Es Dios solamente Dios de los Judíos? ¿No es también Dios de los Gentiles? Cierto, también de los Gentiles."}, {"numero": 30, "texto": "Porque uno es Dios, el cual justificará por la fe la circuncisión, y por medio de la fe la incircuncisión."}, {"numero": 31, "texto": "¿Luego deshacemos la ley por la fe? En ninguna manera; antes establecemos la ley."}]'::jsonb, 'Reina-Valera 1909'),
  ('Rm', 5, 'pt', '[{"numero": 1, "texto": "Portanto, agora que somos justificados pela fé, temos paz com Deus por meio do nosso Senhor Jesus Cristo."}, {"numero": 2, "texto": "Por meio dele também temos acesso pela fé a esta graça, na qual estamos firmes, e nos alegramos na esperança da glória de Deus."}, {"numero": 3, "texto": "E não somente [isso] , mas também nos alegramos nas tribulações, sabendo que a tribulação produz paciência;"}, {"numero": 4, "texto": "a paciência [produz] experiência, e a experiência [produz] esperança."}, {"numero": 5, "texto": "E a esperança não frustra, porque o amor de Deus está derramado em nossos corações pelo Espírito Santo que nos foi dado."}, {"numero": 6, "texto": "Pois quando ainda éramos fracos, Cristo morreu a seu tempo pelos ímpios."}, {"numero": 7, "texto": "Ora, dificilmente alguém morre por um justo, ainda que talvez alguém possa ousar morrer por uma boa pessoa."}, {"numero": 8, "texto": "Mas Deus prova o seu amor por nós através de Cristo haver morrido por nós, quando ainda éramos pecadores."}, {"numero": 9, "texto": "Por isso, muito mais agora, que já somos justificados por seu sangue, seremos por ele salvos da ira."}, {"numero": 10, "texto": "Pois, se quando éramos inimigos, fomos reconciliados com Deus pela morte do seu Filho, muito mais, tendo sido reconciliados, seremos salvos pela sua vida."}, {"numero": 11, "texto": "E não somente [isso] , mas também nos alegramos em Deus por meio do nosso Senhor Jesus Cristo, por quem agora recebemos a reconciliação."}, {"numero": 12, "texto": "Portanto, assim como por um homem o pecado entrou no mundo, e pelo pecado a morte, assim também a morte passou a todos os seres humanos, porque todos pecaram."}, {"numero": 13, "texto": "Pois, antes da Lei, o pecado [já] existia no mundo; porém, quando não há Lei, o pecado não é considerado."}, {"numero": 14, "texto": "Mas a morte reinou desde Adão até Moisés, até sobre aqueles que não pecaram à semelhança da transgressão de Adão, o qual era uma figura daquele que estava para vir."}, {"numero": 15, "texto": "Mas o dom gratuito não é como a transgressão; porque, se pela transgressão de um, muitos morreram, muito mais a graça de Deus, e o dom pela graça de um homem, Jesus Cristo, têm sido abundantes sobre muitos."}, {"numero": 16, "texto": "E o dom não é como [a transgressão] de um que pecou; porque o julgamento de uma só [transgressão] trouxe condenação, mas o dom gratuito, de muitas transgressões, trouxe justificação."}, {"numero": 17, "texto": "Pois, se pela transgressão de um, a morte reinou por causa desse, muito mais os que recebem a abundância da graça, e do dom da justiça reinarão em vida por um só, Jesus Cristo."}, {"numero": 18, "texto": "Portanto, assim como uma transgressão resultou em condenação sobre todos os seres humanos, assim também um ato de justiça resultou em justificação da vida sobre todos os seres humanos."}, {"numero": 19, "texto": "Pois, assim como pela desobediência de um só homem muitos foram feitos pecadores, assim também, pela obediência de um só, muitos serão justificados."}, {"numero": 20, "texto": "A Lei veio para que a transgressão aumentasse; mas onde o pecado aumentou, a graça superabundou;"}, {"numero": 21, "texto": "a fim de que, assim como o pecado reinou para a morte, também a graça reine pela justiça para a vida eterna, por meio de Jesus Cristo, nosso Senhor."}]'::jsonb, 'Almeida Livre'),
  ('Rm', 5, 'en', '[{"numero": 1, "texto": "Therefore being justified by faith, we have peace with God through our Lord Jesus Christ:"}, {"numero": 2, "texto": "By whom also we have access by faith into this grace wherein we stand, and rejoice in hope of the glory of God."}, {"numero": 3, "texto": "And not only so, but we glory in tribulations also: knowing that tribulation worketh patience;"}, {"numero": 4, "texto": "And patience, experience; and experience, hope:"}, {"numero": 5, "texto": "And hope maketh not ashamed; because the love of God is shed abroad in our hearts by the Holy Ghost which is given unto us."}, {"numero": 6, "texto": "For when we were yet without strength, in due time Christ died for the ungodly."}, {"numero": 7, "texto": "For scarcely for a righteous man will one die: yet peradventure for a good man some would even dare to die."}, {"numero": 8, "texto": "But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us."}, {"numero": 9, "texto": "Much more then, being now justified by his blood, we shall be saved from wrath through him."}, {"numero": 10, "texto": "For if, when we were enemies, we were reconciled to God by the death of his Son, much more, being reconciled, we shall be saved by his life."}, {"numero": 11, "texto": "And not only so, but we also joy in God through our Lord Jesus Christ, by whom we have now received the atonement."}, {"numero": 12, "texto": "Wherefore, as by one man sin entered into the world, and death by sin; and so death passed upon all men, for that all have sinned:"}, {"numero": 13, "texto": "(For until the law sin was in the world: but sin is not imputed when there is no law."}, {"numero": 14, "texto": "Nevertheless death reigned from Adam to Moses, even over them that had not sinned after the similitude of Adam''s transgression, who is the figure of him that was to come."}, {"numero": 15, "texto": "But not as the offence, so also is the free gift. For if through the offence of one many be dead, much more the grace of God, and the gift by grace, which is by one man, Jesus Christ, hath abounded unto many."}, {"numero": 16, "texto": "And not as it was by one that sinned, so is the gift: for the judgment was by one to condemnation, but the free gift is of many offences unto justification."}, {"numero": 17, "texto": "For if by one man''s offence death reigned by one; much more they which receive abundance of grace and of the gift of righteousness shall reign in life by one, Jesus Christ.)"}, {"numero": 18, "texto": "Therefore as by the offence of one judgment came upon all men to condemnation; even so by the righteousness of one the free gift came upon all men unto justification of life."}, {"numero": 19, "texto": "For as by one man''s disobedience many were made sinners, so by the obedience of one shall many be made righteous."}, {"numero": 20, "texto": "Moreover the law entered, that the offence might abound. But where sin abounded, grace did much more abound:"}, {"numero": 21, "texto": "That as sin hath reigned unto death, even so might grace reign through righteousness unto eternal life by Jesus Christ our Lord."}]'::jsonb, 'King James Version'),
  ('Rm', 5, 'fr', '[{"numero": 1, "texto": "Etant donc justifiés par la foi, nous avons la paix avec Dieu par notre Seigneur Jésus-Christ,"}, {"numero": 2, "texto": "qui nous devons d''''avoir eu par la foi accès à cette grâce, dans laquelle nous demeurons fermes, et nous nous glorifions dans l''''espérance de la gloire de Dieu."}, {"numero": 3, "texto": "Bien plus, nous nous glorifions même des afflictions, sachant que l''''affliction produit la persévérance,"}, {"numero": 4, "texto": "la persévérance la victoire dans l''''épreuve, et cette victoire l''''espérance."}, {"numero": 5, "texto": "Or, l''''espérance ne trompe point, parce que l''''amour de Dieu est répandu dans nos coeurs par le Saint-Esprit qui nous a été donné."}, {"numero": 6, "texto": "Car, lorsque nous étions encore sans force, Christ, au temps marqué, est mort pour des impies."}, {"numero": 7, "texto": "A peine mourrait-on pour un juste; quelqu''''un peut-être mourrait-il pour un homme de bien."}, {"numero": 8, "texto": "Mais Dieu prouve son amour envers nous, en ce que, lorsque nous étions encore des pécheurs, Christ est mort pour nous."}, {"numero": 9, "texto": "A plus forte raison donc, maintenant que nous sommes justifiés par son sang, serons-nous sauvés par lui de la colère."}, {"numero": 10, "texto": "Car si, lorsque nous étions ennemis, nous avons été réconciliés avec Dieu par la mort de son Fils, à plus forte raison, étant réconciliés, serons-nous sauvés par sa vie."}, {"numero": 11, "texto": "Et non seulement cela, mais encore nous nous glorifions en Dieu par notre Seigneur Jésus-Christ, par qui maintenant nous avons obtenu la réconciliation."}, {"numero": 12, "texto": "C''''est pourquoi, comme par un seul homme le péché est entré dans le monde, et par le péché la mort, et qu''''ainsi la mort s''''est étendue sur tous les hommes, parce que tous ont péché,..."}, {"numero": 13, "texto": "car jusqu''''à la loi le péché était dans le monde. Or, le péché n''''est pas imputé, quand il n''''y a point de loi."}, {"numero": 14, "texto": "Cependant la mort a régné depuis Adam jusqu''''à Moïse, même sur ceux qui n''''avaient pas péché par une transgression semblable à celle d''''Adam, lequel est la figure de celui qui devait venir."}, {"numero": 15, "texto": "Mais il n''''en est pas du don gratuit comme de l''''offense; car, si par l''''offense d''''un seul il en est beaucoup qui sont morts, à plus forte raison la grâce de Dieu et le don de la grâce venant d''''un seul homme, Jésus-Christ, ont-ils été abondamment répandus sur beaucoup."}, {"numero": 16, "texto": "Et il n''''en est pas du don comme de ce qui est arrivé par un seul qui a péché; car c''''est après une seule offense que le jugement est devenu condamnation, tandis que le don gratuit devient justification après plusieurs offenses."}, {"numero": 17, "texto": "Si par l''''offense d''''un seul la mort a régné par lui seul, à plus forte raison ceux qui reçoivent l''''abondance de la grâce et du don de la justice régneront-ils dans la vie par Jésus-Christ lui seul."}, {"numero": 18, "texto": "Ainsi donc, comme par une seule offense la condamnation a atteint tous les hommes, de même par un seul acte de justice la justification qui donne la vie s''''étend à tous les hommes."}, {"numero": 19, "texto": "Car, comme par la désobéissance d''''un seul homme beaucoup ont été rendus pécheurs, de même par l''''obéissance d''''un seul beaucoup seront rendus justes."}, {"numero": 20, "texto": "Or, la loi est intervenue pour que l''''offense abondât, mais là où le péché a abondé, la grâce a surabondé,"}, {"numero": 21, "texto": "afin que, comme le péché a régné par la mort, ainsi la grâce régnât par la justice pour la vie éternelle, par Jésus-Christ notre Seigneur."}]'::jsonb, 'Louis Segond 1910'),
  ('Rm', 5, 'es', '[{"numero": 1, "texto": "JUSTIFICADOS pues por la fe, tenemos paz para con Dios por medio de nuestro Señor Jesucristo:"}, {"numero": 2, "texto": "Por el cual también tenemos entrada por la fe á esta gracia en la cual estamos firmes, y nos gloriamos en la esperanza de la gloria de Dios."}, {"numero": 3, "texto": "Y no sólo esto, mas aun nos gloriamos en las tribulaciones, sabiendo que la tribulación produce paciencia;"}, {"numero": 4, "texto": "Y la paciencia, prueba; y la prueba, esperanza;"}, {"numero": 5, "texto": "Y la esperanza no avergüenza; porque el amor de Dios está derramado en nuestros corazones por el Espíritu Santo que nos es dado."}, {"numero": 6, "texto": "Porque Cristo, cuando aun éramos flacos, á su tiempo murió por los impíos."}, {"numero": 7, "texto": "Ciertamente apenas muere alguno por un justo: con todo podrá ser que alguno osara morir por el bueno."}, {"numero": 8, "texto": "Mas Dios encarece su caridad para con nosotros, porque siendo aún pecadores, Cristo murió por nosotros."}, {"numero": 9, "texto": "Luego mucho más ahora, justificados en su sangre, por él seremos salvos de la ira."}, {"numero": 10, "texto": "Porque si siendo enemigos, fuimos reconciliados con Dios por la muerte de su Hijo, mucho más, estando reconciliados, seremos salvos por su vida."}, {"numero": 11, "texto": "Y no sólo esto, mas aun nos gloriamos en Dios por el Señor nuestro Jesucristo, por el cual hemos ahora recibido la reconciliación."}, {"numero": 12, "texto": "De consiguiente, vino la reconciliación por uno, así como el pecado entró en el mundo por un hombre, y por el pecado la muerte, y la muerte así pasó á todos los hombres, pues que todos pecaron."}, {"numero": 13, "texto": "Porque hasta la ley, el pecado estaba en el mundo; pero no se imputa pecado no habiendo ley."}, {"numero": 14, "texto": "No obstante, reinó la muerte desde Adam hasta Moisés, aun en los que no pecaron á la manera de la rebelión de Adam; el cual es figura del que había de venir."}, {"numero": 15, "texto": "Mas no como el delito, tal fué el don: porque si por el delito de aquel uno murieron los muchos, mucho más abundó la gracia de Dios á los muchos, y el don por la gracia de un hombre, Jesucristo."}, {"numero": 16, "texto": "Ni tampoco de la manera que por un pecado, así también el don: porque el juicio á la verdad vino de un pecado para condenación, mas la gracia vino de muchos delitos para justificación."}, {"numero": 17, "texto": "Porque, si por un delito reinó la muerte por uno, mucho más reinarán en vida por un Jesucristo los que reciben la abundancia de la gracia, y del don de la justicia."}, {"numero": 18, "texto": "Así que, de la manera que por un delito vino la culpa á todos los hombres para condenación, así por una justicia vino la gracia á todos los hombres para justificación de vida."}, {"numero": 19, "texto": "Porque como por la desobediencia de un hombre los muchos fueron constituídos pecadores, así por la obediencia de uno los muchos serán constituídos justos."}, {"numero": 20, "texto": "La ley empero entró para que el pecado creciese; mas cuando el pecado creció, sobrepujó la gracia;"}, {"numero": 21, "texto": "Para que, de la manera que el pecado reinó para muerte, así también la gracia reine por la justicia para vida eterna por Jesucristo Señor nuestro."}]'::jsonb, 'Reina-Valera 1909'),
  ('Rm', 6, 'pt', '[{"numero": 1, "texto": "Que diremos, pois? Continuaremos no pecado, para que a graça aumente?"}, {"numero": 2, "texto": "De maneira nenhuma! Nós, que morremos para o pecado, como ainda viveremos nele?"}, {"numero": 3, "texto": "Ou não sabeis que todos os que somos batizados em Cristo Jesus, somos batizados em sua morte?"}, {"numero": 4, "texto": "Por isso, estamos sepultados com ele pelo batismo na morte; para que, assim como Cristo ressuscitou dos mortos para a glória do Pai, assim também nós andemos em novidade de vida."}, {"numero": 5, "texto": "Pois, se fomos unidos [a ele] na semelhança de sua morte, também o seremos na da [sua] ressurreição."}, {"numero": 6, "texto": "E sabemos isto: que o nosso velho ser foi crucificado com [ele] , para que o corpo do pecado seja extinto, a fim de que não mais sirvamos ao pecado;"}, {"numero": 7, "texto": "pois o que está morto já está absolvido do pecado."}, {"numero": 8, "texto": "Ora, se já morremos com Cristo, cremos que também com ele viveremos."}, {"numero": 9, "texto": "Porque sabemos que, depois que Cristo foi ressuscitado dos mortos, já não morre mais; a morte já não mais o domina."}, {"numero": 10, "texto": "Pois, ao morrer, ele morreu para o pecado de uma vez por todas; mas, ao viver, vive para Deus."}, {"numero": 11, "texto": "Assim também vós, considerai que estais mortos para o pecado, mas vivendo para Deus, em Cristo Jesus, nosso Senhor."}, {"numero": 12, "texto": "Portanto, não reine o pecado em vosso corpo mortal, para obedecer a ele em seus maus desejos."}, {"numero": 13, "texto": "Nem apresenteis os membros do vosso corpo ao pecado como instrumentos de injustiça; em vez disso, apresentai-vos a Deus, como vivos dentre os mortos, e vossos membros como instrumentos de justiça para Deus."}, {"numero": 14, "texto": "Pois o pecado não vos dominará, porque não estais sob a Lei, mas sim, sob a graça."}, {"numero": 15, "texto": "Então, quê? Pecaremos, já que não estamos sob a Lei, mas sob a graça? De maneira nenhuma!"}, {"numero": 16, "texto": "Não sabeis vós, que a quem vos apresentardes por servos para obedecer, sois servos daquele a quem obedeceis? Ou do pecado para a morte, ou da obediência para a justiça."}, {"numero": 17, "texto": "Porém, graças a Deus que vós éreis servos do pecado, mas [agora] , de coração obedeceis à forma de doutrina a que vós fostes entregues;"}, {"numero": 18, "texto": "e, sendo libertos do pecado, vos tornastes servos da justiça."}, {"numero": 19, "texto": "Estou falando na lógica humana, pela fraqueza de vossa carne. Pois, assim como apresentastes os membros do vosso corpo como servos da impureza e da maldade para a maldade, assim também apresentai agora os vossos membros como servos da justiça para a santificação."}, {"numero": 20, "texto": "Porque quando éreis servos do pecado, estáveis livres da justiça."}, {"numero": 21, "texto": "Afinal, que fruto obtivestes das coisas de que agora vos envergonhais? Pois o fim delas é a morte."}, {"numero": 22, "texto": "Mas agora, libertos do pecado, e feitos servos de Deus, tendes o vosso fruto para a santificação, e por fim a vida eterna;"}, {"numero": 23, "texto": "porque o salário do pecado é a morte, mas o dom gratuito de Deus é a vida eterna em Cristo Jesus nosso Senhor."}]'::jsonb, 'Almeida Livre'),
  ('Rm', 6, 'en', '[{"numero": 1, "texto": "What shall we say then? Shall we continue in sin, that grace may abound?"}, {"numero": 2, "texto": "God forbid. How shall we, that are dead to sin, live any longer therein?"}, {"numero": 3, "texto": "Know ye not, that so many of us as were baptized into Jesus Christ were baptized into his death?"}, {"numero": 4, "texto": "Therefore we are buried with him by baptism into death: that like as Christ was raised up from the dead by the glory of the Father, even so we also should walk in newness of life."}, {"numero": 5, "texto": "For if we have been planted together in the likeness of his death, we shall be also in the likeness of his resurrection:"}, {"numero": 6, "texto": "Knowing this, that our old man is crucified with him, that the body of sin might be destroyed, that henceforth we should not serve sin."}, {"numero": 7, "texto": "For he that is dead is freed from sin."}, {"numero": 8, "texto": "Now if we be dead with Christ, we believe that we shall also live with him:"}, {"numero": 9, "texto": "Knowing that Christ being raised from the dead dieth no more; death hath no more dominion over him."}, {"numero": 10, "texto": "For in that he died, he died unto sin once: but in that he liveth, he liveth unto God."}, {"numero": 11, "texto": "Likewise reckon ye also yourselves to be dead indeed unto sin, but alive unto God through Jesus Christ our Lord."}, {"numero": 12, "texto": "Let not sin therefore reign in your mortal body, that ye should obey it in the lusts thereof."}, {"numero": 13, "texto": "Neither yield ye your members as instruments of unrighteousness unto sin: but yield yourselves unto God, as those that are alive from the dead, and your members as instruments of righteousness unto God."}, {"numero": 14, "texto": "For sin shall not have dominion over you: for ye are not under the law, but under grace."}, {"numero": 15, "texto": "What then? shall we sin, because we are not under the law, but under grace? God forbid."}, {"numero": 16, "texto": "Know ye not, that to whom ye yield yourselves servants to obey, his servants ye are to whom ye obey; whether of sin unto death, or of obedience unto righteousness?"}, {"numero": 17, "texto": "But God be thanked, that ye were the servants of sin, but ye have obeyed from the heart that form of doctrine which was delivered you."}, {"numero": 18, "texto": "Being then made free from sin, ye became the servants of righteousness."}, {"numero": 19, "texto": "I speak after the manner of men because of the infirmity of your flesh: for as ye have yielded your members servants to uncleanness and to iniquity unto iniquity; even so now yield your members servants to righteousness unto holiness."}, {"numero": 20, "texto": "For when ye were the servants of sin, ye were free from righteousness."}, {"numero": 21, "texto": "What fruit had ye then in those things whereof ye are now ashamed? for the end of those things is death."}, {"numero": 22, "texto": "But now being made free from sin, and become servants to God, ye have your fruit unto holiness, and the end everlasting life."}, {"numero": 23, "texto": "For the wages of sin is death; but the gift of God is eternal life through Jesus Christ our Lord."}]'::jsonb, 'King James Version'),
  ('Rm', 6, 'fr', '[{"numero": 1, "texto": "Que dirons-nous donc? Demeurerions-nous dans le péché, afin que la grâce abonde?"}, {"numero": 2, "texto": "Loin de là! Nous qui sommes morts au péché, comment vivrions-nous encore dans le péché?"}, {"numero": 3, "texto": "Ignorez-vous que nous tous qui avons été baptisés en Jésus-Christ, c''''est en sa mort que nous avons été baptisés?"}, {"numero": 4, "texto": "Nous avons donc été ensevelis avec lui par le baptême en sa mort, afin que, comme Christ est ressuscité des morts par la gloire du Père, de même nous aussi nous marchions en nouveauté de vie."}, {"numero": 5, "texto": "En effet, si nous sommes devenus une même plante avec lui par la conformité à sa mort, nous le serons aussi par la conformité à sa résurrection,"}, {"numero": 6, "texto": "sachant que notre vieil homme a été crucifié avec lui, afin que le corps du péché fût détruit, pour que nous ne soyons plus esclaves du péché;"}, {"numero": 7, "texto": "car celui qui est mort est libre du péché."}, {"numero": 8, "texto": "Or, si nous sommes morts avec Christ, nous croyons que nous vivrons aussi avec lui,"}, {"numero": 9, "texto": "sachant que Christ ressuscité des morts ne meurt plus; la mort n''''a plus de pouvoir sur lui."}, {"numero": 10, "texto": "Car il est mort, et c''''est pour le péché qu''''il est mort une fois pour toutes; il est revenu à la vie, et c''''est pour Dieu qu''''il vit."}, {"numero": 11, "texto": "Ainsi vous-mêmes, regardez-vous comme morts au péché, et comme vivants pour Dieu en Jésus-Christ."}, {"numero": 12, "texto": "Que le péché ne règne donc point dans votre corps mortel, et n''''obéissez pas à ses convoitises."}, {"numero": 13, "texto": "Ne livrez pas vos membres au péché, comme des instruments d''''iniquité; mais donnez-vous vous-mêmes à Dieu, comme étant vivants de morts que vous étiez, et offrez à Dieu vos membres, comme des instruments de justice."}, {"numero": 14, "texto": "Car le péché n''''aura point de pouvoir sur vous, puisque vous êtes, non sous la loi, mais sous la grâce."}, {"numero": 15, "texto": "Quoi donc! Pécherions-nous, parce que nous sommes, non sous la loi, mais sous la grâce? Loin de là!"}, {"numero": 16, "texto": "Ne savez-vous pas qu''''en vous livrant à quelqu''''un comme esclaves pour lui obéir, vous êtes esclaves de celui à qui vous obéissez, soit du péché qui conduit à la mort, soit de l''''obéissance qui conduit à la justice?"}, {"numero": 17, "texto": "Mais grâces soient rendues à Dieu de ce que, après avoir été esclaves du péché, vous avez obéi de coeur à la règle de doctrine dans laquelle vous avez été instruits."}, {"numero": 18, "texto": "Ayant été affranchis du péché, vous êtes devenus esclaves de la justice. -"}, {"numero": 19, "texto": "Je parle à la manière des hommes, à cause de la faiblesse de votre chair. -De même donc que vous avez livré vos membres comme esclaves à l''''impureté et à l''''iniquité, pour arriver à l''''iniquité, ainsi maintenant livrez vos membres comme esclaves à la justice, pour arriver à la sainteté."}, {"numero": 20, "texto": "Car, lorsque vous étiez esclaves du péché, vous étiez libres à l''''égard de la justice."}, {"numero": 21, "texto": "Quels fruits portiez-vous alors? Des fruits dont vous rougissez aujourd''''hui. Car la fin de ces choses, c''''est la mort."}, {"numero": 22, "texto": "Mais maintenant, étant affranchis du péché et devenus esclaves de Dieu, vous avez pour fruit la sainteté et pour fin la vie éternelle."}, {"numero": 23, "texto": "Car le salaire du péché, c''''est la mort; mais le don gratuit de Dieu, c''''est la vie éternelle en Jésus-Christ notre Seigneur."}]'::jsonb, 'Louis Segond 1910'),
  ('Rm', 6, 'es', '[{"numero": 1, "texto": "¿PUES qué diremos? Perseveraremos en pecado para que la gracia crezca?"}, {"numero": 2, "texto": "En ninguna manera. Porque los que somos muertos al pecado, ¿cómo viviremos aún en él?"}, {"numero": 3, "texto": "¿O no sabéis que todos los que somos bautizados en Cristo Jesús, somos bautizados en su muerte?"}, {"numero": 4, "texto": "Porque somos sepultados juntamente con él á muerte por el bautismo; para que como Cristo resucitó de los muertos por la gloria del Padre, así también nosotros andemos en novedad de vida."}, {"numero": 5, "texto": "Porque si fuimos plantados juntamente en él á la semejanza de su muerte, así también lo seremos á la de su resurrección:"}, {"numero": 6, "texto": "Sabiendo esto, que nuestro viejo hombre juntamente fué crucificado con él, para que el cuerpo del pecado sea deshecho, á fin de que no sirvamos más al pecado."}, {"numero": 7, "texto": "Porque el que es muerto, justificado es del pecado."}, {"numero": 8, "texto": "Y si morimos con Cristo, creemos que también viviremos con él;"}, {"numero": 9, "texto": "Sabiendo que Cristo, habiendo resucitado de entre los muertos, ya no muere: la muerte no se enseñoreará más de él."}, {"numero": 10, "texto": "Porque el haber muerto, al pecado murió una vez; mas el vivir, á Dios vive."}, {"numero": 11, "texto": "Así también vosotros, pensad que de cierto estáis muertos al pecado, mas vivos á Dios en Cristo Jesús Señor nuestro."}, {"numero": 12, "texto": "No reine, pues, el pecado en vuestro cuerpo mortal, para que le obedezcáis en sus concupiscencias;"}, {"numero": 13, "texto": "Ni tampoco presentéis vuestros miembros al pecado por instrumentos de iniquidad; antes presentaos á Dios como vivos de los muertos, y vuestros miembros á Dios por instrumentos de justicia."}, {"numero": 14, "texto": "Porque el pecado no se enseñoreará de vosotros; pues no estáis bajo la ley, sino bajo la gracia."}, {"numero": 15, "texto": "¿Pues qué? ¿Pecaremos, porque no estamos bajo de la ley, sino bajo de la gracia? En ninguna manera."}, {"numero": 16, "texto": "¿No sabéis que á quien os prestáis vosotros mismos por siervos para obedecerle, sois siervos de aquel á quien obedecéis, ó del pecado para muerte, ó de la obediencia para justicia?"}, {"numero": 17, "texto": "Empero gracias á Dios, que aunque fuisteis siervos del pecado, habéis obedecido de corazón á aquella forma de doctrina á la cual sois entregados;"}, {"numero": 18, "texto": "Y libertados del pecado, sois hechos siervos de la justicia."}, {"numero": 19, "texto": "Humana cosa digo, por la flaqueza de vuestra carne: que como para iniquidad presentasteis vuestros miembros á servir á la inmundicia y á la iniquidad, así ahora para santidad presentéis vuestros miembros á servir á la justicia."}, {"numero": 20, "texto": "Porque cuando fuisteis siervos del pecado, erais libres acerca de la justicia."}, {"numero": 21, "texto": "¿Qué fruto, pues, teníais de aquellas cosas de las cuales ahora os avergonzáis? porque el fin de ellas es muerte."}, {"numero": 22, "texto": "Mas ahora, librados del pecado, y hechos siervos á Dios, tenéis por vuestro fruto la santificación, y por fin la vida eterna."}, {"numero": 23, "texto": "Porque la paga del pecado es muerte: mas la dádiva de Dios es vida eterna en Cristo Jesús Señor nuestro."}]'::jsonb, 'Reina-Valera 1909'),
  ('Rm', 8, 'pt', '[{"numero": 1, "texto": "Portanto, agora, nenhuma condenação há para os que estão em Cristo Jesus, que não andam segundo a carne, mas sim segundo o Espírito."}, {"numero": 2, "texto": "Porque a Lei do Espírito de vida, em Cristo Jesus, me livrou da lei do pecado e da morte."}, {"numero": 3, "texto": "Pois o que era impossível para a lei, porque estava enferma pela carne, Deus, ao enviar o seu próprio Filho em semelhança da carne pecadora, e por causa do pecado, condenou o pecado na carne,"}, {"numero": 4, "texto": "para que a exigência da lei se cumprisse em nós, que andamos, não segundo a carne, mas sim, segundo o Espírito."}, {"numero": 5, "texto": "Pois os que são segundo a carne voltam sua mentalidade para as coisas da carne, mas os que são segundo o Espírito, para as coisas do Espírito."}, {"numero": 6, "texto": "Pois a mentalidade da carne é morte, mas a mentalidade do Espírito é vida e paz."}, {"numero": 7, "texto": "Pois a mentalidade da carne é inimizade contra Deus, pois não se sujeita à Lei de Deus, porque nem sequer pode."}, {"numero": 8, "texto": "Portanto, os que permanecem na carne não podem agradar a Deus."}, {"numero": 9, "texto": "Porém vós não permaneceis na carne, mas sim, no Espírito, se é que o Espírito de Deus habita em vós. Porém, se alguém não tem o Espírito de Cristo, esse não lhe pertence."}, {"numero": 10, "texto": "E se Cristo está em vós, apesar do corpo estar morto por causa do pecado, o Espírito é vida por causa da justiça."}, {"numero": 11, "texto": "E se o Espírito daquele que dos mortos ressuscitou a Jesus habita em vós, aquele que dos mortos ressuscitou a Cristo também dará vida aos vossos corpos mortais por meio do seu Espírito, que habita em vós."}, {"numero": 12, "texto": "Por isso, irmãos, somos devedores, não à carne, para vivermos segundo a carne;"}, {"numero": 13, "texto": "porque, se viverdes segundo a carne, morrereis; mas se, pelo Espírito, fizerdes morrer as ações do corpo, vivereis."}, {"numero": 14, "texto": "Pois todos quantos são guiados pelo Espírito de Deus são filhos de Deus."}, {"numero": 15, "texto": "Pois não recebestes o espírito de escravidão, para voltardes ao medo; mas recebestes o Espírito de adoção como filhos, pelo qual clamamos: Aba, Pai!"}, {"numero": 16, "texto": "O próprio Espírito dá testemunho com o nosso espírito de que somos filhos de Deus."}, {"numero": 17, "texto": "E, se somos filhos, logo somos também herdeiros; herdeiros de Deus, e coerdeiros de Cristo; se sofremos com ele, é para que também com ele sejamos glorificados."}, {"numero": 18, "texto": "Pois considero que as aflições deste tempo presente nem se comparam com a glória que nos será revelada."}, {"numero": 19, "texto": "Pois a criação espera ansiosamente a revelação dos filhos de Deus;"}, {"numero": 20, "texto": "porque a criação ficou sujeita à futilidade (não por vontade própria, mas sim por causa daquele que a sujeitou),"}, {"numero": 21, "texto": "na esperança de que também a mesma criação seja liberta da escravidão da degradação para a liberdade da glória dos filhos de Deus."}, {"numero": 22, "texto": "Pois sabemos que toda a criação geme e sofre dores como as de parto até agora."}, {"numero": 23, "texto": "E não somente [isso] , mas também nós, que temos os primeiros frutos do Espírito, gememos em nós mesmos, esperando a [adoção] , [isto é] , a redenção do nosso corpo."}, {"numero": 24, "texto": "Pois fomos salvos na esperança. Ora, a esperança que se vê não é esperança; afinal, por que alguém ainda espera o que já vê?"}, {"numero": 25, "texto": "Mas, se esperamos o que não vemos, com paciência esperamos."}, {"numero": 26, "texto": "E da mesma maneira também o Espírito ajuda em nossas fraquezas. Pois não sabemos orar como se deve, mas o próprio Espírito intercede por nós com gemidos inexprimíveis."}, {"numero": 27, "texto": "E aquele que examina os corações sabe qual é a intenção do Espírito, pois ele intercede pelos santos, segundo [a vontade] de Deus."}, {"numero": 28, "texto": "E sabemos que todas as coisas juntamente contribuem para o bem daqueles que amam a Deus, dos que são chamados segundo o seu propósito."}, {"numero": 29, "texto": "Pois aos que desde antes conheceu, também os predestinou para serem conformes à imagem do seu Filho, para que ele seja o primogênito entre muitos irmãos."}, {"numero": 30, "texto": "E aos que predestinou, a esses também chamou; e aos que chamou, a esses também justificou; e aos que justificou, a esses também glorificou."}, {"numero": 31, "texto": "Então, que diremos acerca dessas coisas? Se Deus é por nós, quem será contra nós?"}, {"numero": 32, "texto": "Aquele que nem mesmo ao seu próprio Filho poupou, como não nos dará também com ele todas as coisas?"}, {"numero": 33, "texto": "Quem fará acusação contra os escolhidos de Deus? Deus é quem justifica."}, {"numero": 34, "texto": "Quem [os] condenará? Cristo é o que morreu; além disto é o que também ressuscitou; o que também está à direita de Deus, e que intercede por nós."}, {"numero": 35, "texto": "Quem nos separará do amor de Cristo? A aflição, a angústia, a perseguição, a fome, a nudez, o perigo, ou a espada?"}, {"numero": 36, "texto": "Como está escrito: “Pois por causa de ti somos entreges à morte o dia todo; somos contados como ovelhas para o matadouro”."}, {"numero": 37, "texto": "Mas em todas estas coisas somos mais que vencedores, por meio daquele que nos amou."}, {"numero": 38, "texto": "Pois tenho certeza que nem a morte, nem a vida, nem anjos, nem principados, nem poderes, nem o presente, nem o futuro,"}, {"numero": 39, "texto": "nem altura, nem profundeza, nem qualquer outra criatura poderá nos separar do amor de Deus, que está em Cristo Jesus, nosso Senhor."}]'::jsonb, 'Almeida Livre'),
  ('Rm', 8, 'en', '[{"numero": 1, "texto": "There is therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit."}, {"numero": 2, "texto": "For the law of the Spirit of life in Christ Jesus hath made me free from the law of sin and death."}, {"numero": 3, "texto": "For what the law could not do, in that it was weak through the flesh, God sending his own Son in the likeness of sinful flesh, and for sin, condemned sin in the flesh:"}, {"numero": 4, "texto": "That the righteousness of the law might be fulfilled in us, who walk not after the flesh, but after the Spirit."}, {"numero": 5, "texto": "For they that are after the flesh do mind the things of the flesh; but they that are after the Spirit the things of the Spirit."}, {"numero": 6, "texto": "For to be carnally minded is death; but to be spiritually minded is life and peace."}, {"numero": 7, "texto": "Because the carnal mind is enmity against God: for it is not subject to the law of God, neither indeed can be."}, {"numero": 8, "texto": "So then they that are in the flesh cannot please God."}, {"numero": 9, "texto": "But ye are not in the flesh, but in the Spirit, if so be that the Spirit of God dwell in you. Now if any man have not the Spirit of Christ, he is none of his."}, {"numero": 10, "texto": "And if Christ be in you, the body is dead because of sin; but the Spirit is life because of righteousness."}, {"numero": 11, "texto": "But if the Spirit of him that raised up Jesus from the dead dwell in you, he that raised up Christ from the dead shall also quicken your mortal bodies by his Spirit that dwelleth in you."}, {"numero": 12, "texto": "Therefore, brethren, we are debtors, not to the flesh, to live after the flesh."}, {"numero": 13, "texto": "For if ye live after the flesh, ye shall die: but if ye through the Spirit do mortify the deeds of the body, ye shall live."}, {"numero": 14, "texto": "For as many as are led by the Spirit of God, they are the sons of God."}, {"numero": 15, "texto": "For ye have not received the spirit of bondage again to fear; but ye have received the Spirit of adoption, whereby we cry, Abba, Father."}, {"numero": 16, "texto": "The Spirit itself beareth witness with our spirit, that we are the children of God:"}, {"numero": 17, "texto": "And if children, then heirs; heirs of God, and joint-heirs with Christ; if so be that we suffer with him, that we may be also glorified together."}, {"numero": 18, "texto": "For I reckon that the sufferings of this present time are not worthy to be compared with the glory which shall be revealed in us."}, {"numero": 19, "texto": "For the earnest expectation of the creature waiteth for the manifestation of the sons of God."}, {"numero": 20, "texto": "For the creature was made subject to vanity, not willingly, but by reason of him who hath subjected the same in hope,"}, {"numero": 21, "texto": "Because the creature itself also shall be delivered from the bondage of corruption into the glorious liberty of the children of God."}, {"numero": 22, "texto": "For we know that the whole creation groaneth and travaileth in pain together until now."}, {"numero": 23, "texto": "And not only they, but ourselves also, which have the firstfruits of the Spirit, even we ourselves groan within ourselves, waiting for the adoption, to wit, the redemption of our body."}, {"numero": 24, "texto": "For we are saved by hope: but hope that is seen is not hope: for what a man seeth, why doth he yet hope for?"}, {"numero": 25, "texto": "But if we hope for that we see not, then do we with patience wait for it."}, {"numero": 26, "texto": "Likewise the Spirit also helpeth our infirmities: for we know not what we should pray for as we ought: but the Spirit itself maketh intercession for us with groanings which cannot be uttered."}, {"numero": 27, "texto": "And he that searcheth the hearts knoweth what is the mind of the Spirit, because he maketh intercession for the saints according to the will of God."}, {"numero": 28, "texto": "And we know that all things work together for good to them that love God, to them who are the called according to his purpose."}, {"numero": 29, "texto": "For whom he did foreknow, he also did predestinate to be conformed to the image of his Son, that he might be the firstborn among many brethren."}, {"numero": 30, "texto": "Moreover whom he did predestinate, them he also called: and whom he called, them he also justified: and whom he justified, them he also glorified."}, {"numero": 31, "texto": "What shall we then say to these things? If God be for us, who can be against us?"}, {"numero": 32, "texto": "He that spared not his own Son, but delivered him up for us all, how shall he not with him also freely give us all things?"}, {"numero": 33, "texto": "Who shall lay any thing to the charge of God''s elect? It is God that justifieth."}, {"numero": 34, "texto": "Who is he that condemneth? It is Christ that died, yea rather, that is risen again, who is even at the right hand of God, who also maketh intercession for us."}, {"numero": 35, "texto": "Who shall separate us from the love of Christ? shall tribulation, or distress, or persecution, or famine, or nakedness, or peril, or sword?"}, {"numero": 36, "texto": "As it is written, For thy sake we are killed all the day long; we are accounted as sheep for the slaughter."}, {"numero": 37, "texto": "Nay, in all these things we are more than conquerors through him that loved us."}, {"numero": 38, "texto": "For I am persuaded, that neither death, nor life, nor angels, nor principalities, nor powers, nor things present, nor things to come,"}, {"numero": 39, "texto": "Nor height, nor depth, nor any other creature, shall be able to separate us from the love of God, which is in Christ Jesus our Lord."}]'::jsonb, 'King James Version'),
  ('Rm', 8, 'fr', '[{"numero": 1, "texto": "Il n''''y a donc maintenant aucune condamnation pour ceux qui sont en Jésus-Christ."}, {"numero": 2, "texto": "En effet, la loi de l''''esprit de vie en Jésus-Christ m''''a affranchi de la loi du péché et de la mort."}, {"numero": 3, "texto": "Car chose impossible à la loi, parce que la chair la rendait sans force, -Dieu a condamné le péché dans la chair, en envoyant, à cause du péché, son propre Fils dans une chair semblable à celle du péché,"}, {"numero": 4, "texto": "et cela afin que la justice de la loi fût accomplie en nous, qui marchons, non selon la chair, mais selon l''''esprit."}, {"numero": 5, "texto": "Ceux, en effet, qui vivent selon la chair, s''''affectionnent aux choses de la chair, tandis que ceux qui vivent selon l''''esprit s''''affectionnent aux choses de l''''esprit."}, {"numero": 6, "texto": "Et l''''affection de la chair, c''''est la mort, tandis que l''''affection de l''''esprit, c''''est la vie et la paix;"}, {"numero": 7, "texto": "car l''''affection de la chair est inimitié contre Dieu, parce qu''''elle ne se soumet pas à la loi de Dieu, et qu''''elle ne le peut même pas."}, {"numero": 8, "texto": "Or ceux qui vivent selon la chair ne sauraient plaire à Dieu."}, {"numero": 9, "texto": "Pour vous, vous ne vivez pas selon la chair, mais selon l''''esprit, si du moins l''''Esprit de Dieu habite en vous. Si quelqu''''un n''''a pas l''''Esprit de Christ, il ne lui appartient pas."}, {"numero": 10, "texto": "Et si Christ est en vous, le corps, il est vrai, est mort à cause du péché, mais l''''esprit est vie à cause de la justice."}, {"numero": 11, "texto": "Et si l''''Esprit de celui qui a ressuscité Jésus d''''entre les morts habite en vous, celui qui a ressuscité Christ d''''entre les morts rendra aussi la vie à vos corps mortels par son Esprit qui habite en vous."}, {"numero": 12, "texto": "Ainsi donc, frères, nous ne sommes point redevables à la chair, pour vivre selon la chair."}, {"numero": 13, "texto": "Si vous vivez selon la chair, vous mourrez; mais si par l''''Esprit vous faites mourir les actions du corps, vous vivrez,"}, {"numero": 14, "texto": "car tous ceux qui sont conduits par l''''Esprit de Dieu sont fils de Dieu."}, {"numero": 15, "texto": "Et vous n''''avez point reçu un esprit de servitude, pour être encore dans la crainte; mais vous avez reçu un Esprit d''''adoption, par lequel nous crions: Abba! Père!"}, {"numero": 16, "texto": "L''''Esprit lui-même rend témoignage à notre esprit que nous sommes enfants de Dieu."}, {"numero": 17, "texto": "Or, si nous sommes enfants, nous sommes aussi héritiers: héritiers de Dieu, et cohéritiers de Christ, si toutefois nous souffrons avec lui, afin d''''être glorifiés avec lui."}, {"numero": 18, "texto": "J''''estime que les souffrances du temps présent ne sauraient être comparées à la gloire à venir qui sera révélée pour nous."}, {"numero": 19, "texto": "Aussi la création attend-elle avec un ardent désir la révélation des fils de Dieu."}, {"numero": 20, "texto": "Car la création a été soumise à la vanité, -non de son gré, mais à cause de celui qui l''''y a soumise, avec l''''espérance"}, {"numero": 21, "texto": "qu''''elle aussi sera affranchie de la servitude de la corruption, pour avoir part à la liberté de la gloire des enfants de Dieu."}, {"numero": 22, "texto": "Or, nous savons que, jusqu''''à ce jour, la création tout entière soupire et souffre les douleurs de l''''enfantement."}, {"numero": 23, "texto": "Et ce n''''est pas elle seulement; mais nous aussi, qui avons les prémices de l''''Esprit, nous aussi nous soupirons en nous-mêmes, en attendant l''''adoption, la rédemption de notre corps."}, {"numero": 24, "texto": "Car c''''est en espérance que nous sommes sauvés. Or, l''''espérance qu''''on voit n''''est plus espérance: ce qu''''on voit, peut-on l''''espérer encore?"}, {"numero": 25, "texto": "Mais si nous espérons ce que nous ne voyons pas, nous l''''attendons avec persévérance."}, {"numero": 26, "texto": "De même aussi l''''Esprit nous aide dans notre faiblesse, car nous ne savons pas ce qu''''il nous convient de demander dans nos prières. Mais l''''Esprit lui-même intercède par des soupirs inexprimables;"}, {"numero": 27, "texto": "et celui qui sonde les coeurs connaît quelle est la pensée de l''''Esprit, parce que c''''est selon Dieu qu''''il intercède en faveur des saints."}, {"numero": 28, "texto": "Nous savons, du reste, que toutes choses concourent au bien de ceux qui aiment Dieu, de ceux qui sont appelés selon son dessein."}, {"numero": 29, "texto": "Car ceux qu''''il a connus d''''avance, il les a aussi prédestinés à être semblables à l''''image de son Fils, afin que son Fils fût le premier-né entre plusieurs frères."}, {"numero": 30, "texto": "Et ceux qu''''il a prédestinés, il les a aussi appelés; et ceux qu''''il a appelés, il les a aussi justifiés; et ceux qu''''il a justifiés, il les a aussi glorifiés."}, {"numero": 31, "texto": "Que dirons-nous donc à l''''égard de ces choses? Si Dieu est pour nous, qui sera contre nous?"}, {"numero": 32, "texto": "Lui, qui n''''a point épargné son propre Fils, mais qui l''''a livré pour nous tous, comment ne nous donnera-t-il pas aussi toutes choses avec lui?"}, {"numero": 33, "texto": "Qui accusera les élus de Dieu? C''''est Dieu qui justifie!"}, {"numero": 34, "texto": "Qui les condamnera? Christ est mort; bien plus, il est ressuscité, il est à la droite de Dieu, et il intercède pour nous!"}, {"numero": 35, "texto": "Qui nous séparera de l''''amour de Christ? Sera-ce la tribulation, ou l''''angoisse, ou la persécution, ou la faim, ou la nudité, ou le péril, ou l''''épée?"}, {"numero": 36, "texto": "selon qu''''il est écrit: C''''est à cause de toi qu''''on nous met à mort tout le jour, Qu''''on nous regarde comme des brebis destinées à la boucherie."}, {"numero": 37, "texto": "Mais dans toutes ces choses nous sommes plus que vainqueurs par celui qui nous a aimés."}, {"numero": 38, "texto": "Car j''''ai l''''assurance que ni la mort ni la vie, ni les anges ni les dominations, ni les choses présentes ni les choses à venir, ni les puissances,"}, {"numero": 39, "texto": "ni la hauteur, ni la profondeur, ni aucune autre créature ne pourra nous séparer de l''''amour de Dieu manifesté en Jésus-Christ notre Seigneur."}]'::jsonb, 'Louis Segond 1910'),
  ('Rm', 8, 'es', '[{"numero": 1, "texto": "AHORA pues, ninguna condenación hay para los que están en Cristo Jesús, los que no andan conforme á la carne, mas conforme al espíritu."}, {"numero": 2, "texto": "Porque la ley del Espíritu de vida en Cristo Jesús me ha librado de la ley del pecado y de la muerte."}, {"numero": 3, "texto": "Porque lo que era imposible á la ley, por cuanto era débil por la carne, Dios enviando á su Hijo en semejanza de carne de pecado, y á causa del pecado, condenó al pecado en la carne;"}, {"numero": 4, "texto": "Para que la justicia de la ley fuese cumplida en nosotros, que no andamos conforme á la carne, mas conforme al espíritu."}, {"numero": 5, "texto": "Porque los que viven conforme á la carne, de las cosas que son de la carne se ocupan; mas los que conforme al espíritu, de las cosas del espíritu."}, {"numero": 6, "texto": "Porque la intención de la carne es muerte; mas la intención del espíritu, vida y paz:"}, {"numero": 7, "texto": "Por cuanto la intención de la carne es enemistad contra Dios; porque no se sujeta á la ley de Dios, ni tampoco puede."}, {"numero": 8, "texto": "Así que, los que están en la carne no pueden agradar á Dios."}, {"numero": 9, "texto": "Mas vosotros no estáis en la carne, sino en el espíritu, si es que el Espíritu de Dios mora en vosotros. Y si alguno no tiene el Espíritu de Cristo, el tal no es de él."}, {"numero": 10, "texto": "Empero si Cristo está en vosotros, el cuerpo á la verdad está muerto á causa del pecado; mas el espíritu vive á causa de la justicia."}, {"numero": 11, "texto": "Y si el Espíritu de aquel que levantó de los muertos á Jesús mora en vosotros, el que levantó á Cristo Jesús de los muertos, vivificará también vuestros cuerpos mortales por su Espíritu que mora en vosotros."}, {"numero": 12, "texto": "Así que, hermanos, deudores somos, no á la carne, para que vivamos conforme á la carne:"}, {"numero": 13, "texto": "Porque si viviereis conforme á la carne, moriréis; mas si por el espíritu mortificáis las obras de la carne, viviréis."}, {"numero": 14, "texto": "Porque todos los que son guiados por el Espíritu de Dios, los tales son hijos de Dios."}, {"numero": 15, "texto": "Porque no habéis recibido el espíritu de servidumbre para estar otra vez en temor; mas habéis recibido el espíritu de adopción, por el cual clamamos, Abba, Padre."}, {"numero": 16, "texto": "Porque el mismo Espíritu da testimonio á nuestro espíritu que somos hijos de Dios."}, {"numero": 17, "texto": "Y si hijos, también herederos; herederos de Dios, y coherederos de Cristo; si empero padecemos juntamente con él, para que juntamente con él seamos glorificados."}, {"numero": 18, "texto": "Porque tengo por cierto que lo que en este tiempo se padece, no es de comparar con la gloria venidera que en nosotros ha de ser manifestada."}, {"numero": 19, "texto": "Porque el continuo anhelar de las criaturas espera la manifestación de los hijos de Dios."}, {"numero": 20, "texto": "Porque las criaturas sujetas fueron á vanidad, no de grado, mas por causa del que las sujetó con esperanza,"}, {"numero": 21, "texto": "Que también las mismas criaturas serán libradas de la servidumbre de corrupción en la libertad gloriosa de los hijos de Dios."}, {"numero": 22, "texto": "Porque sabemos que todas las criaturas gimen á una, y á una están de parto hasta ahora."}, {"numero": 23, "texto": "Y no sólo ellas, mas también nosotros mismos, que tenemos las primicias del Espíritu, nosotros también gemimos dentro de nosotros mismos, esperando la adopción, es á saber, la redención de nuestro cuerpo."}, {"numero": 24, "texto": "Porque en esperanza somos salvos; mas la esperanza que se ve, no es esperanza; porque lo que alguno ve, ¿á qué esperarlo?"}, {"numero": 25, "texto": "Empero si lo que no vemos esperamos, por paciencia esperamos."}, {"numero": 26, "texto": "Y asimismo también el Espíritu ayuda nuestra flaqueza: porque qué hemos de pedir como conviene, no lo sabemos; sino que el mismo Espíritu pide por nosotros con gemidos indecibles."}, {"numero": 27, "texto": "Mas el que escudriña los corazones, sabe cuál es el intento del Espíritu, porque conforme á la voluntad de Dios, demanda por los santos."}, {"numero": 28, "texto": "Y sabemos que á los que á Dios aman, todas las cosas les ayudan á bien, es á saber, á los que conforme al propósito son llamados."}, {"numero": 29, "texto": "Porque á los que antes conoció, también predestinó para que fuesen hechos conformes á la imagen de su Hijo, para que él sea el primogénito entre muchos hermanos;"}, {"numero": 30, "texto": "Y á los que predestinó, á éstos también llamó; y á los que llamó, á éstos también justificó; y á los que justificó, á éstos también glorificó."}, {"numero": 31, "texto": "¿Pues qué diremos á esto? Si Dios por nosotros, ¿quién contra nosotros?"}, {"numero": 32, "texto": "El que aun á su propio Hijo no perdonó, antes le entregó por todos nosotros, ¿cómo no nos dará también con él todas las cosas?"}, {"numero": 33, "texto": "¿Quién acusará á los escogidos de Dios? Dios es el que justifica."}, {"numero": 34, "texto": "¿Quién es el que condenará? Cristo es el que murió; más aún, el que también resucitó, quien además está á la diestra de Dios, el que también intercede por nosotros."}, {"numero": 35, "texto": "¿Quién nos apartará del amor de Cristo? tribulación? ó angustia? ó persecución? ó hambre? ó desnudez? ó peligro? ó cuchillo?"}, {"numero": 36, "texto": "Como está escrito: Por causa de ti somos muertos todo el tiempo: somos estimados como ovejas de matadero."}, {"numero": 37, "texto": "Antes, en todas estas cosas hacemos más que vencer por medio de aquel que nos amó."}, {"numero": 38, "texto": "Por lo cual estoy cierto que ni la muerte, ni la vida, ni ángeles, ni principados, ni potestades, ni lo presente, ni lo por venir,"}, {"numero": 39, "texto": "Ni lo alto, ni lo bajo, ni ninguna criatura nos podrá apartar del amor de Dios, que es en Cristo Jesús Señor nuestro."}]'::jsonb, 'Reina-Valera 1909'),
  ('Rm', 12, 'pt', '[{"numero": 1, "texto": "Rogo-vos, pois, irmãos, pelas misericórdias de Deus, que apresenteis os vossos corpos como sacrifício vivo, santo e agradável a Deus, [que é] o vosso culto racional."}, {"numero": 2, "texto": "E não vos conformeis com a presente era; mas transformai-vos pela renovação da vossa mentalidade, para que experimenteis qual seja a boa, agradável, e perfeita vontade de Deus."}, {"numero": 3, "texto": "Pois, pela graça que me foi dada, digo a cada um dentre vós que não se estime mais do que convém se estimar; em vez disso, cada um estime a si mesmo com bom senso, conforme a medida de fé que Deus repartiu a cada um."}, {"numero": 4, "texto": "Porque assim como em um corpo temos muitos membros, e nem todos os membros têm a mesma função,"}, {"numero": 5, "texto": "assim também nós, [ainda que] muitos, somos um único corpo em Cristo; porém, individualmente, membros uns dos outros."}, {"numero": 6, "texto": "Temos, contudo, diferentes dons, segundo a graça que nos foi dada: se é o de profecia, seja segundo a medida da fé;"}, {"numero": 7, "texto": "se é o de serviço, seja em servir; se é o de ensino, seja em ensinar;"}, {"numero": 8, "texto": "se é o de exortação, seja em exortar; o que reparte, [reparta] com generosidade; o que lidera, [lidere] com empenho, o que usa de misericórdia, [faça-o] com alegria."}, {"numero": 9, "texto": "O amor seja sem hipocrisia. Odiai o mal, e apegai-vos ao bem."}, {"numero": 10, "texto": "Amai-vos cordialmente uns aos outros com amor de irmãos, preferindo honrar uns aos outros."}, {"numero": 11, "texto": "Não sejais vagarosos em mostrardes empenho. Sede fervorosos de espírito. Servi ao Senhor."}, {"numero": 12, "texto": "Alegrai-vos na esperança. Sede pacientes na aflição. Perseverai na oração."}, {"numero": 13, "texto": "Compartilhai com os santos em suas necessidades. Buscai ser hospitaleiros."}, {"numero": 14, "texto": "Abençoai os que vos perseguem; abençoai, e não amaldiçoeis."}, {"numero": 15, "texto": "Alegrai-vos com os que se alegram, e chorai com os que choram."}, {"numero": 16, "texto": "Estimai-vos uns aos outros como semelhantes. Não fiqueis pensando com soberba; em vez disso, acompanhai-vos dos humildes. Não sejais sábios em vós mesmos."}, {"numero": 17, "texto": "A ninguém pagueis o mal com o mal; buscai fazer o que é certo diante de todos."}, {"numero": 18, "texto": "No que for possível de vossa parte, tende paz com todos."}, {"numero": 19, "texto": "Não vos vingueis por vós mesmos, amados. Em vez disso, dai lugar à ira [divina] ,porque está escrito: A mim pertence a vingança, eu retribuirei, diz o Senhor."}, {"numero": 20, "texto": "Portanto, se o teu inimigo tiver fome, dá-lhe de comer; se tiver sede, dá-lhe de beber. Pois, quando fizeres isto, estarás amontoando brasas de fogo sobre a cabeça dele."}, {"numero": 21, "texto": "Não sejas vencido pelo mal, mas vence o mal com o bem."}]'::jsonb, 'Almeida Livre'),
  ('Rm', 12, 'en', '[{"numero": 1, "texto": "I beseech you therefore, brethren, by the mercies of God, that ye present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service."}, {"numero": 2, "texto": "And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God."}, {"numero": 3, "texto": "For I say, through the grace given unto me, to every man that is among you, not to think of himself more highly than he ought to think; but to think soberly, according as God hath dealt to every man the measure of faith."}, {"numero": 4, "texto": "For as we have many members in one body, and all members have not the same office:"}, {"numero": 5, "texto": "So we, being many, are one body in Christ, and every one members one of another."}, {"numero": 6, "texto": "Having then gifts differing according to the grace that is given to us, whether prophecy, let us prophesy according to the proportion of faith;"}, {"numero": 7, "texto": "Or ministry, let us wait on our ministering: or he that teacheth, on teaching;"}, {"numero": 8, "texto": "Or he that exhorteth, on exhortation: he that giveth, let him do it with simplicity; he that ruleth, with diligence; he that sheweth mercy, with cheerfulness."}, {"numero": 9, "texto": "Let love be without dissimulation. Abhor that which is evil; cleave to that which is good."}, {"numero": 10, "texto": "Be kindly affectioned one to another with brotherly love; in honour preferring one another;"}, {"numero": 11, "texto": "Not slothful in business; fervent in spirit; serving the Lord;"}, {"numero": 12, "texto": "Rejoicing in hope; patient in tribulation; continuing instant in prayer;"}, {"numero": 13, "texto": "Distributing to the necessity of saints; given to hospitality."}, {"numero": 14, "texto": "Bless them which persecute you: bless, and curse not."}, {"numero": 15, "texto": "Rejoice with them that do rejoice, and weep with them that weep."}, {"numero": 16, "texto": "Be of the same mind one toward another. Mind not high things, but condescend to men of low estate. Be not wise in your own conceits."}, {"numero": 17, "texto": "Recompense to no man evil for evil. Provide things honest in the sight of all men."}, {"numero": 18, "texto": "If it be possible, as much as lieth in you, live peaceably with all men."}, {"numero": 19, "texto": "Dearly beloved, avenge not yourselves, but rather give place unto wrath: for it is written, Vengeance is mine; I will repay, saith the Lord."}, {"numero": 20, "texto": "Therefore if thine enemy hunger, feed him; if he thirst, give him drink: for in so doing thou shalt heap coals of fire on his head."}, {"numero": 21, "texto": "Be not overcome of evil, but overcome evil with good."}]'::jsonb, 'King James Version'),
  ('Rm', 12, 'fr', '[{"numero": 1, "texto": "Je vous exhorte donc, frères, par les compassions de Dieu, à offrir vos corps comme un sacrifice vivant, saint, agréable à Dieu, ce qui sera de votre part un culte raisonnable."}, {"numero": 2, "texto": "Ne vous conformez pas au siècle présent, mais soyez transformés par le renouvellement de l''''intelligence, afin que vous discerniez quelle est la volonté de Dieu, ce qui est bon, agréable et parfait."}, {"numero": 3, "texto": "Par la grâce qui m''''a été donnée, je dis à chacun de vous de n''''avoir pas de lui-même une trop haute opinion, mais de revêtir des sentiments modestes, selon la mesure de foi que Dieu a départie à chacun."}, {"numero": 4, "texto": "Car, comme nous avons plusieurs membres dans un seul corps, et que tous les membres n''''ont pas la même fonction,"}, {"numero": 5, "texto": "ainsi, nous qui sommes plusieurs, nous formons un seul corps en Christ, et nous sommes tous membres les uns des autres."}, {"numero": 6, "texto": "Puisque nous avons des dons différents, selon la grâce qui nous a été accordée, que celui qui a le don de prophétie l''''exerce selon l''''analogie de la foi;"}, {"numero": 7, "texto": "que celui qui est appelé au ministère s''''attache à son ministère; que celui qui enseigne s''''attache à son enseignement,"}, {"numero": 8, "texto": "et celui qui exhorte à l''''exhortation. Que celui qui donne le fasse avec libéralité; que celui qui préside le fasse avec zèle; que celui qui pratique la miséricorde le fasse avec joie."}, {"numero": 9, "texto": "Que la charité soit sans hypocrisie. Ayez le mal en horreur; attachez-vous fortement au bien."}, {"numero": 10, "texto": "Par amour fraternel, soyez pleins d''''affection les uns pour les autres; par honneur, usez de prévenances réciproques."}, {"numero": 11, "texto": "Ayez du zèle, et non de la paresse. Soyez fervents d''''esprit. Servez le Seigneur."}, {"numero": 12, "texto": "Réjouissez-vous en espérance. Soyez patients dans l''''affliction. Persévérez dans la prière."}, {"numero": 13, "texto": "Pourvoyez aux besoins des saints. Exercez l''''hospitalité."}, {"numero": 14, "texto": "Bénissez ceux qui vous persécutent, bénissez et ne maudissez pas."}, {"numero": 15, "texto": "Réjouissez-vous avec ceux qui se réjouissent; pleurez avec ceux qui pleurent."}, {"numero": 16, "texto": "Ayez les mêmes sentiments les uns envers les autres. N''''aspirez pas à ce qui est élevé, mais laissez-vous attirer par ce qui est humble. Ne soyez point sages à vos propres yeux."}, {"numero": 17, "texto": "Ne rendez à personne le mal pour le mal. Recherchez ce qui est bien devant tous les hommes."}, {"numero": 18, "texto": "S''''il est possible, autant que cela dépend de vous, soyez en paix avec tous les hommes."}, {"numero": 19, "texto": "Ne vous vengez point vous-mêmes, bien-aimés, mais laissez agir la colère; car il est écrit: A moi la vengeance, à moi la rétribution, dit le Seigneur."}, {"numero": 20, "texto": "Mais si ton ennemi a faim, donne-lui à manger; s''''il a soif, donne-lui à boire; car en agissant ainsi, ce sont des charbons ardents que tu amasseras sur sa tête."}, {"numero": 21, "texto": "Ne te laisse pas vaincre par le mal, mais surmonte le mal par le bien."}]'::jsonb, 'Louis Segond 1910'),
  ('Rm', 12, 'es', '[{"numero": 1, "texto": "ASÍ que, hermanos, os ruego por las misericordias de Dios, que presentéis vuestros cuerpos en sacrificio vivo, santo, agradable á Dios, que es vuestro racional culto."}, {"numero": 2, "texto": "Y no os conforméis á este siglo; mas reformaos por la renovación de vuestro entendimiento, para que experimentéis cuál sea la buena voluntad de Dios, agradable y perfecta."}, {"numero": 3, "texto": "Digo pues por la gracia que me es dada, á cada cual que está entre vosotros, que no tenga más alto concepto de sí que el que debe tener, sino que piense de sí con templanza, conforme á la medida de fe que Dios repartió á cada uno."}, {"numero": 4, "texto": "Porque de la manera que en un cuerpo tenemos muchos miembros, empero todos los miembros no tienen la misma operación;"}, {"numero": 5, "texto": "Así muchos somos un cuerpo en Cristo, mas todos miembros los unos de los otros."}, {"numero": 6, "texto": "De manera que, teniendo diferentes dones según la gracia que nos es dada, si el de profecía, úsese conforme á la medida de la fe;"}, {"numero": 7, "texto": "O si ministerio, en servir; ó el que enseña, en doctrina;"}, {"numero": 8, "texto": "El que exhorta, en exhortar; el que reparte, hágalo en simplicidad; el que preside, con solicitud; el que hace misericordia, con alegría."}, {"numero": 9, "texto": "El amor sea sin fingimiento: aborreciendo lo malo, llegándoos á lo bueno;"}, {"numero": 10, "texto": "Amándoos los unos á los otros con caridad fraternal; previniéndoos con honra los unos á los otros;"}, {"numero": 11, "texto": "En el cuidado no perezosos; ardientes en espíritu; sirviendo al Señor;"}, {"numero": 12, "texto": "Gozosos en la esperanza; sufridos en la tribulación; constantes en la oración;"}, {"numero": 13, "texto": "Comunicando á las necesidades de los santos; siguiendo la hospitalidad."}, {"numero": 14, "texto": "Bendecid á los que os persiguen: bendecid, y no maldigáis."}, {"numero": 15, "texto": "Gozaos con los que se gozan: llorad con los que lloran."}, {"numero": 16, "texto": "Unánimes entre vosotros: no altivos, mas acomodándoos á los humildes. No seáis sabios en vuestra opinión."}, {"numero": 17, "texto": "No paguéis á nadie mal por mal; procurad lo bueno delante de todos los hombres."}, {"numero": 18, "texto": "Si se puede hacer, cuanto está en vosotros, tened paz con todos los hombres."}, {"numero": 19, "texto": "No os venguéis vosotros mismos, amados míos; antes dad lugar á la ira; porque escrito está: Mía es la venganza: yo pagaré, dice el Señor."}, {"numero": 20, "texto": "Así que, si tu enemigo tuviere hambre, dale de comer; si tuviere sed, dale de beber: que haciendo esto, ascuas de fuego amontonas sobre su cabeza."}, {"numero": 21, "texto": "No seas vencido de lo malo; mas vence con el bien el mal."}]'::jsonb, 'Reina-Valera 1909'),
  ('Rt', 1, 'pt', '[{"numero": 1, "texto": "E aconteceu nos dias que governavam os juízes, que houve fome na terra. E um homem de Belém de Judá, foi a peregrinar nos campos de Moabe, ele e sua mulher, e dois filhos seus."}, {"numero": 2, "texto": "O nome daquele homem era Elimeleque, e o de sua mulher Noemi; e os nomes de seus dois filhos eram Malom e Quiliom, efrateus de Belém de Judá. Chegaram, pois, aos campos de Moabe, e assentaram ali."}, {"numero": 3, "texto": "E morreu Elimeleque, marido de Noemi, e restou ela com seus dois filhos;"}, {"numero": 4, "texto": "Os quais tomaram para si mulheres de Moabe, o nome da uma Orfa, e o nome da outra Rute; e habitaram ali uns dez anos."}, {"numero": 5, "texto": "E morreram também os dois, Malom e Quiliom, restando assim a mulher desamparada de seus dois filhos e de seu marido."}, {"numero": 6, "texto": "Então se levantou com suas noras, e voltou-se dos campos de Moabe: porque ouviu no campo de Moabe que o SENHOR havia visitado a seu povo para dar-lhes pão."}, {"numero": 7, "texto": "Saiu, pois, do lugar de onde havia estado, e com ela suas duas noras, e começaram em caminhar para voltar-se à terra de Judá."}, {"numero": 8, "texto": "E Noemi disse a suas duas noras: Andai, voltai-vos cada uma à casa de sua mãe: o SENHOR faça convosco misericórdia, como a fizestes com os mortos e comigo."}, {"numero": 9, "texto": "Dê-vos o SENHOR que acheis descanso, cada uma em casa de seu marido: beijou-as logo, e elas choraram a voz em grito."}, {"numero": 10, "texto": "E disseram-lhe: Certamente nós voltaremos contigo a teu povo."}, {"numero": 11, "texto": "E Noemi respondeu: Voltai, filhas minhas; para que ireis comigo? Tenho eu mais filhos no ventre, que possam ser vossos maridos?"}, {"numero": 12, "texto": "Voltai, filhas minhas, e ide; que eu já sou velha para ser para me casar com homem. E ainda que dissesse: Tenho esperança; e esta noite me casasse com um homem, e ainda desse à luz filhos;"}, {"numero": 13, "texto": "Teríeis vós de esperá-los até que fossem grandes? Ficaríeis vós sem se casar por causa deles? Não, filhas minhas; que maior amargura tenho eu que vós, pois a mão do SENHOR saiu contra mim."}, {"numero": 14, "texto": "Mas elas levantando outra vez sua voz, choraram: e Orfa beijou à sua sogra, mas Rute se ficou com ela."}, {"numero": 15, "texto": "E Noemi disse: Eis que tua cunhada se voltou a seu povo e a seus deuses; volta-te atrás dela."}, {"numero": 16, "texto": "E Rute respondeu: Não me rogues que te deixe, e que me aparte de ti: porque de onde quer que tu fores, irei eu; e de onde quer que viveres, viverei. Teu povo será meu povo, e teu Deus meu Deus."}, {"numero": 17, "texto": "Onde tu morreres, morrerei eu, e ali serei sepultada: assim me faça o SENHOR, e assim me dê, que somente a morte fará separação entre mim e ti."}, {"numero": 18, "texto": "E vendo Noemi que estava tão decidida a ir com ela, deixou de falar-lhe."}, {"numero": 19, "texto": "Andaram, pois, elas duas até que chegaram a Belém: e aconteceu que entrando em Belém, toda a cidade se comoveu por razão delas, e diziam: Não é esta Noemi?"}, {"numero": 20, "texto": "E ela lhes respondia: Não me chameis Noemi, mas sim me chamai Mara: porque em grande amargura me pôs o Todo-Poderoso."}, {"numero": 21, "texto": "Eu me fui cheia, mas vazia me fez voltar o SENHOR. Por que me chamareis Noemi, já que o SENHOR deu testemunho contra mim, e o Todo-Poderoso me afligiu?"}, {"numero": 22, "texto": "Assim voltou Noemi e Rute moabita sua nora com ela; voltou dos campos de Moabe, e chegaram a Belém no princípio da colheita das cevadas."}]'::jsonb, 'Almeida Livre'),
  ('Rt', 1, 'en', '[{"numero": 1, "texto": "Now it came to pass in the days when the judges ruled, that there was a famine in the land. And a certain man of Bethlehemjudah went to sojourn in the country of Moab, he, and his wife, and his two sons."}, {"numero": 2, "texto": "And the name of the man was Elimelech, and the name of his wife Naomi, and the name of his two sons Mahlon and Chilion, Ephrathites of Bethlehemjudah. And they came into the country of Moab, and continued there."}, {"numero": 3, "texto": "And Elimelech Naomi''s husband died; and she was left, and her two sons."}, {"numero": 4, "texto": "And they took them wives of the women of Moab; the name of the one was Orpah, and the name of the other Ruth: and they dwelled there about ten years."}, {"numero": 5, "texto": "And Mahlon and Chilion died also both of them; and the woman was left of her two sons and her husband."}, {"numero": 6, "texto": "Then she arose with her daughters in law, that she might return from the country of Moab: for she had heard in the country of Moab how that the Lord had visited his people in giving them bread."}, {"numero": 7, "texto": "Wherefore she went forth out of the place where she was, and her two daughters in law with her; and they went on the way to return unto the land of Judah."}, {"numero": 8, "texto": "And Naomi said unto her two daughters in law, Go, return each to her mother''s house: the Lord deal kindly with you, as ye have dealt with the dead, and with me."}, {"numero": 9, "texto": "The Lord grant you that ye may find rest, each of you in the house of her husband. Then she kissed them; and they lifted up their voice, and wept."}, {"numero": 10, "texto": "And they said unto her, Surely we will return with thee unto thy people."}, {"numero": 11, "texto": "And Naomi said, Turn again, my daughters: why will ye go with me? are there yet any more sons in my womb, that they may be your husbands?"}, {"numero": 12, "texto": "Turn again, my daughters, go your way; for I am too old to have an husband. If I should say, I have hope, if I should have an husband also to night, and should also bear sons;"}, {"numero": 13, "texto": "Would ye tarry for them till they were grown? would ye stay for them from having husbands? nay, my daughters; for it grieveth me much for your sakes that the hand of the Lord is gone out against me."}, {"numero": 14, "texto": "And they lifted up their voice, and wept again: and Orpah kissed her mother in law; but Ruth clave unto her."}, {"numero": 15, "texto": "And she said, Behold, thy sister in law is gone back unto her people, and unto her gods: return thou after thy sister in law."}, {"numero": 16, "texto": "And Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God:"}, {"numero": 17, "texto": "Where thou diest, will I die, and there will I be buried: the Lord do so to me, and more also, if ought but death part thee and me."}, {"numero": 18, "texto": "When she saw that she was stedfastly minded to go with her, then she left speaking unto her."}, {"numero": 19, "texto": "So they two went until they came to Bethlehem. And it came to pass, when they were come to Bethlehem, that all the city was moved about them, and they said, Is this Naomi?"}, {"numero": 20, "texto": "And she said unto them, Call me not Naomi, call me Mara: for the Almighty hath dealt very bitterly with me."}, {"numero": 21, "texto": "I went out full and the Lord hath brought me home again empty: why then call ye me Naomi, seeing the Lord hath testified against me, and the Almighty hath afflicted me?"}, {"numero": 22, "texto": "So Naomi returned, and Ruth the Moabitess, her daughter in law, with her, which returned out of the country of Moab: and they came to Bethlehem in the beginning of barley harvest."}]'::jsonb, 'King James Version'),
  ('Rt', 1, 'fr', '[{"numero": 1, "texto": "Du temps des juges, il y eut une famine dans le pays. Un homme de Bethléhem de Juda partit, avec sa femme et ses deux fils, pour faire un séjour dans le pays de Moab."}, {"numero": 2, "texto": "Le nom de cet homme était Elimélec, celui de sa femme Naomi, et ses deux fils s''''appelaient Machlon et Kiljon; ils étaient Ephratiens, de Bethléhem de Juda. Arrivés au pays de Moab, ils y fixèrent leur demeure."}, {"numero": 3, "texto": "Elimélec, mari de Naomi, mourut, et elle resta avec ses deux fils."}, {"numero": 4, "texto": "Ils prirent des femmes Moabites, dont l''''une se nommait Orpa, et l''''autre Ruth, et ils habitèrent là environ dix ans."}, {"numero": 5, "texto": "Machlon et Kiljon moururent aussi tous les deux, et Naomi resta privée de ses deux fils et de son mari."}, {"numero": 6, "texto": "Puis elle se leva, elle et ses belles-filles, afin de quitter le pays de Moab, car elle apprit au pays de Moab que l''''Eternel avait visité son peuple et lui avait donné du pain."}, {"numero": 7, "texto": "Elle sortit du lieu qu''''elle habitait, accompagnée de ses deux belles-filles, et elle se mit en route pour retourner dans le pays de Juda."}, {"numero": 8, "texto": "Naomi dit alors à ses deux belles-filles: Allez, retournez chacune à la maison de sa mère! Que l''''Eternel use de bonté envers vous, comme vous l''''avez fait envers ceux qui sont morts et envers moi!"}, {"numero": 9, "texto": "Que l''''Eternel vous fasse trouver à chacune du repos dans la maison d''''un mari! Et elle les baisa. Elles élevèrent la voix, et pleurèrent;"}, {"numero": 10, "texto": "et elles lui dirent: Non, nous irons avec toi vers ton peuple."}, {"numero": 11, "texto": "Naomi, dit: Retournez, mes filles! Pourquoi viendriez-vous avec moi? Ai-je encore dans mon sein des fils qui puissent devenir vos maris?"}, {"numero": 12, "texto": "Retournez, mes filles, allez! Je suis trop vieille pour me remarier. Et quand je dirais: J''''ai de l''''espérance; quand cette nuit même je serais avec un mari, et que j''''enfanterais des fils,"}, {"numero": 13, "texto": "attendriez-vous pour cela qu''''ils eussent grandi, refuseriez-vous pour cela de vous marier? Non, mes filles! car à cause de vous je suis dans une grande affliction de ce que la main de l''''Eternel s''''est étendue contre moi."}, {"numero": 14, "texto": "Et elles élevèrent la voix, et pleurèrent encore. Orpa baisa sa belle-mère, mais Ruth s''''attacha à elle."}, {"numero": 15, "texto": "Naomi dit à Ruth: Voici, ta belle-soeur est retournée vers son peuple et vers ses dieux; retourne, comme ta belle-soeur."}, {"numero": 16, "texto": "Ruth répondit: Ne me presse pas de te laisser, de retourner loin de toi! Où tu iras j''''irai, où tu demeureras je demeurerai; ton peuple sera mon peuple, et ton Dieu sera mon Dieu;"}, {"numero": 17, "texto": "où tu mourras je mourrai, et j''''y serai enterrée. Que l''''Eternel me traite dans toute sa rigueur, si autre chose que la mort vient à me séparer de toi!"}, {"numero": 18, "texto": "Naomi, la voyant décidée à aller avec elle, cessa ses instances."}, {"numero": 19, "texto": "Elles firent ensemble le voyage jusqu''''à leur arrivée à Bethléhem. Et lorsqu''''elles entrèrent dans Bethléhem, toute la ville fut émue à cause d''''elles, et les femmes disaient: Est-ce là Naomi?"}, {"numero": 20, "texto": "Elle leur dit: Ne m''''appelez pas Naomi; appelez-moi Mara, car le Tout-Puissant m''''a remplie d''''amertume."}, {"numero": 21, "texto": "J''''étais dans l''''abondance à mon départ, et l''''Eternel me ramène les mains vides. Pourquoi m''''appelleriez-vous Naomi, après que l''''Eternel s''''est prononcé contre moi, et que le Tout-Puissant m''''a affligée?"}, {"numero": 22, "texto": "Ainsi revinrent du pays de Moab Naomi et sa belle-fille, Ruth la Moabite. Elles arrivèrent à Bethléhem au commencement de la moisson des orges."}]'::jsonb, 'Louis Segond 1910'),
  ('Rt', 1, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ en los días que gobernaban los jueces, que hubo hambre en la tierra. Y un varón de Beth-lehem de Judá, fué á peregrinar en los campos de Moab, él y su mujer, y dos hijos suyos."}, {"numero": 2, "texto": "El nombre de aquel varón era Elimelech, y el de su mujer Noemi; y los nombres de sus dos hijos eran, Mahalón y Chelión, Ephrateos de Beth-lehem de Judá. Llegaron pues á los campos de Moab, y asentaron allí."}, {"numero": 3, "texto": "Y murió Elimelech, marido de Noemi, y quedó ella con sus dos hijos;"}, {"numero": 4, "texto": "Los cuales tomaron para sí mujeres de Moab, el nombre de la una Orpha, y el nombre de la otra Ruth; y habitaron allí unos diez años."}, {"numero": 5, "texto": "Y murieron también los dos, Mahalón y Chelión, quedando así la mujer desamparada de sus dos hijos y de su marido."}, {"numero": 6, "texto": "Entonces se levantó con sus nueras, y volvióse de los campos de Moab: porque oyó en el campo de Moab que Jehová había visitado á su pueblo para darles pan."}, {"numero": 7, "texto": "Salió pues del lugar donde había estado, y con ella sus dos nueras, y comenzaron á caminar para volverse á la tierra de Judá."}, {"numero": 8, "texto": "Y Noemi dijo á sus dos nueras: Andad, volveos cada una á la casa de su madre: Jehová haga con vosotras misericordia, como la habéis hecho con los muertos y conmigo."}, {"numero": 9, "texto": "Déos Jehová que halléis descanso, cada una en casa de su marido: besólas luego, y ellas lloraron á voz en grito."}, {"numero": 10, "texto": "Y dijéronle: Ciertamente nosotras volveremos contigo á tu pueblo."}, {"numero": 11, "texto": "Y Noemi respondió: Volveos, hijas mías: ¿para qué habéis de ir conmigo? ¿tengo yo más hijos en el vientre, que puedan ser vuestros maridos?"}, {"numero": 12, "texto": "Volveos, hijas mías, é idos; que yo ya soy vieja para ser para varón. Y aunque dijese: Esperanza tengo; y esta noche fuese con varón, y aun pariese hijos;"}, {"numero": 13, "texto": "¿Habíais vosotras de esperarlos hasta que fuesen grandes? ¿habías vosotras de quedaros sin casar por amor de ellos? No, hijas mías; que mayor amargura tengo yo que vosotras, pues la mano de Jehová ha salido contra mí."}, {"numero": 14, "texto": "Mas ellas alzando otra vez su voz, lloraron: y Orpha besó á su suegra, mas Ruth se quedó con ella."}, {"numero": 15, "texto": "Y Noemi dijo: He aquí tu cuñada se ha vuelto á su pueblo y á sus dioses; vuélvete tú tras ella."}, {"numero": 16, "texto": "Y Ruth respondió: No me ruegues que te deje, y me aparte de ti: porque donde quiera que tú fueres, iré yo; y donde quiera que vivieres, viviré. Tu pueblo será mi pueblo, y tu Dios mi Dios."}, {"numero": 17, "texto": "Donde tú murieres, moriré yo, y allí seré sepultada: así me haga Jehová, y así me dé, que sólo la muerte hará separación entre mí y ti."}, {"numero": 18, "texto": "Y viendo Noemi que estaba tan resuelta á ir con ella, dejó de hablarle."}, {"numero": 19, "texto": "Anduvieron pues ellas dos hasta que llegaron á Beth-lehem: y aconteció que entrando en Beth-lehem, toda la ciudad se conmovió por razón de ellas, y decían: ¿No es ésta Noemi?"}, {"numero": 20, "texto": "Y ella les respondía: No me llaméis Noemi, sino llamadme Mara: porque en grande amargura me ha puesto el Todopoderoso."}, {"numero": 21, "texto": "Yo me fuí llena, mas vacía me ha vuelto Jehová. ¿Por qué me llamaréis Noemi, ya que Jehová ha dado testimonio contra mí, y el Todopoderoso me ha afligido?"}, {"numero": 22, "texto": "Así volvió Noemi y Ruth Moabita su nuera con ella; volvió de los campos de Moab, y llegaron á Beth-lehem en el principio de la siega de las cebadas."}]'::jsonb, 'Reina-Valera 1909'),
  ('Rt', 2, 'pt', '[{"numero": 1, "texto": "E tinha Noemi um parente de seu marido, homem poderoso e rico, da família de Elimeleque, o qual se chamava Boaz."}, {"numero": 2, "texto": "E Rute a moabita disse a Noemi: Rogo-te que me deixes ir ao campo, e colherei espigas atrás daquele a cujos olhos achar favor. E ela lhe respondeu: Vai, filha minha."}, {"numero": 3, "texto": "Foi, pois, e chegando, tirou espigas no campo atrás dos ceifeiros: e aconteceu porventura, que o terreno era de Boaz, o qual era da parentela de Elimeleque."}, {"numero": 4, "texto": "E eis que Boaz veio de Belém, e disse aos ceifeiros: O SENHOR seja convosco. E eles responderam: O SENHOR te abençoe."}, {"numero": 5, "texto": "E Boaz disse a seu criado o supervisor dos ceifeiros: De quem é esta moça?"}, {"numero": 6, "texto": "E o criado, supervisor dos ceifeiros, respondeu e disse: É a moça de Moabe, que voltou com Noemi dos campos de Moabe;"}, {"numero": 7, "texto": "E disse: Rogo-te que me deixes colher e juntar atrás dos ceifeiros entre os feixes; entrou, pois, e está desde pela manhã até agora, menos um pouco que se deteve em casa."}, {"numero": 8, "texto": "Então Boaz disse á Rute: Ouve, filha minha, não vás a tirar espigas em outro campo, nem passes daqui: e aqui estarás com minhas moças."}, {"numero": 9, "texto": "Olha bem o campo que colherem, e segue-as: porque eu mandei aos moços que não te toquem. E se tiveres sede, vai aos vasos, e bebe da água que os moços tirarem."}, {"numero": 10, "texto": "Ela então baixando seu rosto inclinou-se à terra, e disse-lhe: Por que achei favor em teus olhos para que tu me reconheças, sendo eu estrangeira?"}, {"numero": 11, "texto": "E respondendo Boaz, disse-lhe: Por certo se me declarou tudo o que fizeste com tua sogra depois da morte de teu marido, e que deixando teu pai e tua mãe e a terra de onde nasceste, vieste a um povo que não conheceste antes."}, {"numero": 12, "texto": "O SENHOR recompense tua obra, e tua remuneração seja cheia pelo SENHOR Deus de Israel, que vieste para cobrir-te debaixo de suas asas."}, {"numero": 13, "texto": "E ela disse: Senhor meu, ache eu favor diante de teus olhos; porque me consolaste, e porque falaste ao coração de tua serva, não sendo eu como uma de tuas criadas."}, {"numero": 14, "texto": "E Boaz lhe disse à hora de comer: Achega-te aqui, e come do pão, e molha teu bocado no vinagre. E sentou-se ela junto aos ceifeiros, e ele lhe deu grãos tostados, e comeu até que se fartou e lhe sobrou."}, {"numero": 15, "texto": "Levantou-se logo para tirar espigas. E Boaz mandou a seus criados, dizendo: Colha também espigas entre os feixes, e não a envergonheis;"}, {"numero": 16, "texto": "Antes lançareis de propósito dos feixes, e a deixareis que colha, e não a repreendais."}, {"numero": 17, "texto": "E tirou espigas no campo até à tarde, e debulhou o que havia colhido, e foi como um efa de cevada."}, {"numero": 18, "texto": "E tomou-o, e veio à cidade; e sua sogra viu o que havia colhido. Tirou também logo o que lhe havia sobrado depois de farta, e deu-lhe."}, {"numero": 19, "texto": "E disse-lhe sua sogra: Onde tiraste espigas hoje? e onde trabalhaste? Bendito seja o que te reconheceu. E ela declarou à sua sogra o que lhe havia acontecido com aquele, e disse: O nome do homem com quem hoje trabalhei é Boaz."}, {"numero": 20, "texto": "E disse Noemi à sua nora: Seja ele bendito do SENHOR, pois que não recusou aos vivos a benevolência que teve para com os finados. Disse-lhe depois Noemi: Nosso parente é aquele homem, e de nossos remidores é."}, {"numero": 21, "texto": "E Rute moabita disse: a mais disto me disse: Junta-te com meus criados, até que tenham acabado toda minha colheita."}, {"numero": 22, "texto": "E Noemi respondeu a Rute sua nora: Melhor é, filha minha, que saias com suas criadas, que não que te encontrem em outro campo."}, {"numero": 23, "texto": "Esteve, pois, junto com as moças de Boaz tirando espigas, até que a colheita das cevadas e a dos trigos foi acabada; mas com sua sogra habitou."}]'::jsonb, 'Almeida Livre'),
  ('Rt', 2, 'en', '[{"numero": 1, "texto": "And Naomi had a kinsman of her husband''s, a mighty man of wealth, of the family of Elimelech; and his name was Boaz."}, {"numero": 2, "texto": "And Ruth the Moabitess said unto Naomi, Let me now go to the field, and glean ears of corn after him in whose sight I shall find grace. And she said unto her, Go, my daughter."}, {"numero": 3, "texto": "And she went, and came, and gleaned in the field after the reapers: and her hap was to light on a part of the field belonging unto Boaz, who was of the kindred of Elimelech."}, {"numero": 4, "texto": "And, behold, Boaz came from Bethlehem, and said unto the reapers, The Lord be with you. And they answered him, The Lord bless thee."}, {"numero": 5, "texto": "Then said Boaz unto his servant that was set over the reapers, Whose damsel is this?"}, {"numero": 6, "texto": "And the servant that was set over the reapers answered and said, It is the Moabitish damsel that came back with Naomi out of the country of Moab:"}, {"numero": 7, "texto": "And she said, I pray you, let me glean and gather after the reapers among the sheaves: so she came, and hath continued even from the morning until now, that she tarried a little in the house."}, {"numero": 8, "texto": "Then said Boaz unto Ruth, Hearest thou not, my daughter? Go not to glean in another field, neither go from hence, but abide here fast by my maidens:"}, {"numero": 9, "texto": "Let thine eyes be on the field that they do reap, and go thou after them: have I not charged the young men that they shall not touch thee? and when thou art athirst, go unto the vessels, and drink of that which the young men have drawn."}, {"numero": 10, "texto": "Then she fell on her face, and bowed herself to the ground, and said unto him, Why have I found grace in thine eyes, that thou shouldest take knowledge of me, seeing I am a stranger?"}, {"numero": 11, "texto": "And Boaz answered and said unto her, It hath fully been shewed me, all that thou hast done unto thy mother in law since the death of thine husband: and how thou hast left thy father and thy mother, and the land of thy nativity, and art come unto a people which thou knewest not heretofore."}, {"numero": 12, "texto": "The Lord recompense thy work, and a full reward be given thee of the Lord God of Israel, under whose wings thou art come to trust."}, {"numero": 13, "texto": "Then she said, Let me find favour in thy sight, my lord; for that thou hast comforted me, and for that thou hast spoken friendly unto thine handmaid, though I be not like unto one of thine handmaidens."}, {"numero": 14, "texto": "And Boaz said unto her, At mealtime come thou hither, and eat of the bread, and dip thy morsel in the vinegar. And she sat beside the reapers: and he reached her parched corn, and she did eat, and was sufficed, and left."}, {"numero": 15, "texto": "And when she was risen up to glean, Boaz commanded his young men, saying, Let her glean even among the sheaves, and reproach her not:"}, {"numero": 16, "texto": "And let fall also some of the handfuls of purpose for her, and leave them, that she may glean them, and rebuke her not."}, {"numero": 17, "texto": "So she gleaned in the field until even, and beat out that she had gleaned: and it was about an ephah of barley."}, {"numero": 18, "texto": "And she took it up, and went into the city: and her mother in law saw what she had gleaned: and she brought forth, and gave to her that she had reserved after she was sufficed."}, {"numero": 19, "texto": "And her mother in law said unto her, Where hast thou gleaned to day? and where wroughtest thou? blessed be he that did take knowledge of thee. And she shewed her mother in law with whom she had wrought, and said, The man''s name with whom I wrought to day is Boaz."}, {"numero": 20, "texto": "And Naomi said unto her daughter in law, Blessed be he of the Lord, who hath not left off his kindness to the living and to the dead. And Naomi said unto her, The man is near of kin unto us, one of our next kinsmen."}, {"numero": 21, "texto": "And Ruth the Moabitess said, He said unto me also, Thou shalt keep fast by my young men, until they have ended all my harvest."}, {"numero": 22, "texto": "And Naomi said unto Ruth her daughter in law, It is good, my daughter, that thou go out with his maidens, that they meet thee not in any other field."}, {"numero": 23, "texto": "So she kept fast by the maidens of Boaz to glean unto the end of barley harvest and of wheat harvest; and dwelt with her mother in law."}]'::jsonb, 'King James Version'),
  ('Rt', 2, 'fr', '[{"numero": 1, "texto": "Naomi avait un parent de son mari. C''''était un homme puissant et riche, de la famille d''''Elimélec, et qui se nommait Boaz."}, {"numero": 2, "texto": "Ruth la Moabite dit à Naomi: Laisse-moi, je te prie, aller glaner des épis dans le champ de celui aux yeux duquel je trouverai grâce. Elle lui répondit: Va, ma fille."}, {"numero": 3, "texto": "Elle alla glaner dans un champ, derrière les moissonneurs. Et il se trouva par hasard que la pièce de terre appartenait à Boaz, qui était de la famille d''''Elimélec."}, {"numero": 4, "texto": "Et voici, Boaz vint de Bethléhem, et il dit aux moissonneurs: Que l''''Eternel soit avec vous! Ils lui répondirent: Que l''''Eternel te bénisse!"}, {"numero": 5, "texto": "Et Boaz dit à son serviteur chargé de surveiller les moissonneurs: A qui est cette jeune femme?"}, {"numero": 6, "texto": "Le serviteur chargé de surveiller les moissonneurs répondit: C''''est une jeune femme Moabite, qui est revenue avec Naomi du pays de Moab."}, {"numero": 7, "texto": "Elle a dit: Permettez-moi de glaner et de ramasser des épis entre les gerbes, derrière les moissonneurs. Et depuis ce matin qu''''elle est venue, elle a été debout jusqu''''à présent, et ne s''''est reposée qu''''un moment dans la maison."}, {"numero": 8, "texto": "Boaz dit à Ruth: Ecoute, ma fille, ne va pas glaner dans un autre champ; ne t''''éloigne pas d''''ici, et reste avec mes servantes."}, {"numero": 9, "texto": "Regarde où l''''on moissonne dans le champ, et va après elles. J''''ai défendu à mes serviteurs de te toucher. Et quand tu auras soif, tu iras aux vases, et tu boiras de ce que les serviteurs auront puisé."}, {"numero": 10, "texto": "Alors elle tomba sur sa face et se prosterna contre terre, et elle lui dit: Comment ai-je trouvé grâce à tes yeux, pour que tu t''''intéresses à moi, à moi qui suis une étrangère?"}, {"numero": 11, "texto": "Boaz lui répondit: On m''''a rapporté tout ce que tu as fait pour ta belle-mère depuis la mort de ton mari, et comment tu as quitté ton père et ta mère et le pays de ta naissance, pour aller vers un peuple que tu ne connaissais point auparavant."}, {"numero": 12, "texto": "Que l''''Eternel te rende ce que tu as fait, et que ta récompense soit entière de la part de l''''Eternel, le Dieu d''''Israël, sous les ailes duquel tu es venue te réfugier!"}, {"numero": 13, "texto": "Et elle dit: Oh! que je trouve grâce à tes yeux, mon seigneur! Car tu m''''as consolée, et tu as parlé au coeur de ta servante. Et pourtant je ne suis pas, moi, comme l''''une de tes servantes."}, {"numero": 14, "texto": "Au moment du repas, Boaz dit à Ruth: Approche, mange du pain, et trempe ton morceau dans le vinaigre. Elle s''''assit à côté des moissonneurs. On lui donna du grain rôti; elle mangea et se rassasia, et elle garda le reste."}, {"numero": 15, "texto": "Puis elle se leva pour glaner. Boaz donna cet ordre à ses serviteurs: Qu''''elle glane aussi entre les gerbes, et ne l''''inquiétez pas,"}, {"numero": 16, "texto": "et même vous ôterez pour elle des gerbes quelques épis, que vous la laisserez glaner, sans lui faire de reproches."}, {"numero": 17, "texto": "Elle glana dans le champ jusqu''''au soir, et elle battit ce qu''''elle avait glané. Il y eut environ un épha d''''orge."}, {"numero": 18, "texto": "Elle l''''emporta et rentra dans la ville, et sa belle-mère vit ce qu''''elle avait glané. Elle sortit aussi les restes de son repas, et les lui donna."}, {"numero": 19, "texto": "Sa belle-mère lui dit: Où as-tu glané aujourd''''hui, et où as-tu travaillé? Béni soit celui qui s''''est intéressé à toi! Et Ruth fit connaître à sa belle-mère chez qui elle avait travaillé: L''''homme chez qui j''''ai travaillé aujourd''''hui, dit-elle, s''''appelle Boaz."}, {"numero": 20, "texto": "Naomi dit à sa belle-fille: Qu''''il soit béni de l''''Eternel, qui se montre miséricordieux pour les vivants comme il le fut pour ceux qui sont morts! Cet homme est notre parent, lui dit encore Naomi, il est de ceux qui ont sur nous droit de rachat."}, {"numero": 21, "texto": "Ruth la Moabite ajouta: Il m''''a dit aussi: Reste avec mes serviteurs, jusqu''''à ce qu''''ils aient achevé toute ma moisson."}, {"numero": 22, "texto": "Et Naomi dit à Ruth, sa belle-fille: Il est bon, ma fille, que tu sortes avec ses servantes, et qu''''on ne te rencontre pas dans un autre champ."}, {"numero": 23, "texto": "Elle resta donc avec les servantes de Boaz, pour glaner, jusqu''''à la fin de la moisson des orges et de la moisson du froment. Et elle demeurait avec sa belle-mère."}]'::jsonb, 'Louis Segond 1910'),
  ('Rt', 2, 'es', '[{"numero": 1, "texto": "Y TENÍA Noemi un pariente de su marido, varón poderoso y de hecho, de la familia de Elimelech, el cual se llamaba Booz."}, {"numero": 2, "texto": "Y Ruth la Moabita dijo á Noemi: Ruégote que me dejes ir al campo, y cogeré espigas en pos de aquel á cuyos ojos hallare gracia. Y ella le respondió: Ve, hija mía."}, {"numero": 3, "texto": "Fué pues, y llegando, espigó en el campo en pos de los segadores: y aconteció por ventura, que la suerte del campo era de Booz, el cual era de la parentela de Elimelech."}, {"numero": 4, "texto": "Y he aquí que Booz vino de Beth-lehem, y dijo á los segadores: Jehová sea con vosotros. Y ellos respondieron: Jehová te bendiga."}, {"numero": 5, "texto": "Y Booz dijo á su criado el sobrestante de los segadores: ¿Cúya es esta moza?"}, {"numero": 6, "texto": "Y el criado, sobrestante de los segadores, respondió y dijo: Es la moza de Moab, que volvió con Noemi de los campos de Moab;"}, {"numero": 7, "texto": "Y ha dicho: Ruégote que me dejes coger y juntar tras los segadores entre las gavillas: entró pues, y está desde por la mañana hasta ahora, menos un poco que se detuvo en casa."}, {"numero": 8, "texto": "Entonces Booz dijo á Ruth: Oye, hija mía, no vayas á espigar á otro campo, ni pases de aquí: y aquí estarás con mis mozas."}, {"numero": 9, "texto": "Mira bien al campo que segaren, y síguelas: porque yo he mandado á los mozos que no te toquen. Y si tuvieres sed, ve á los vasos, y bebe del agua que sacaren los mozos."}, {"numero": 10, "texto": "Ella entonces bajando su rostro inclinóse á tierra, y díjole: ¿Por qué he hallado gracia en tus ojos para que tú me reconozcas, siendo yo extranjera?"}, {"numero": 11, "texto": "Y respondiendo Booz, díjole: Por cierto se me ha declarado todo lo que has hecho con tu suegra después de la muerte de tu marido, y que dejando á tu padre y á tu madre y la tierra donde naciste, has venido á pueblo que no conociste antes."}, {"numero": 12, "texto": "Jehová galardone tu obra, y tu remuneración sea llena por Jehová Dios de Israel, que has venido para cubrirte debajo de sus alas."}, {"numero": 13, "texto": "Y ella dijo: Señor mío, halle yo gracia delante de tus ojos; porque me has consolado, y porque has hablado al corazón de tu sierva, no siendo yo como una de tus criadas."}, {"numero": 14, "texto": "Y Booz le dijo á la hora de comer: Allégate aquí, y come del pan, y moja tu bocado en el vinagre. Y sentóse ella junto á los segadores, y él le dió del potaje, y comió hasta que se hartó y le sobró."}, {"numero": 15, "texto": "Levantóse luego para espigar. Y Booz mandó á sus criados, diciendo: Coja también espigas entre las gavillas, y no la avergoncéis;"}, {"numero": 16, "texto": "Antes echaréis á sabiendas de los manojos, y la dejaréis que coja, y no la reprendáis."}, {"numero": 17, "texto": "Y espigó en el campo hasta la tarde, y desgranó lo que había cogido, y fué como un epha de cebada."}, {"numero": 18, "texto": "Y tomólo, y vínose á la ciudad; y su suegra vió lo que había cogido. Sacó también luego lo que le había sobrado después de harta, y dióselo."}, {"numero": 19, "texto": "Y díjole su suegra: ¿Dónde has espigado hoy? ¿y dónde has trabajado? bendito sea el que te ha reconocido. Y ella declaró á su suegra lo que le había acontecido con aquél, y dijo: El nombre del varón con quien hoy he trabajado es Booz."}, {"numero": 20, "texto": "Y dijo Noemi á su nuera: Sea él bendito de Jehová, pues que no ha rehusado á los vivos la benevolencia que tuvo para con los finados. Díjole después Noemi: Nuestro pariente es aquel varón, y de nuestros redentores es."}, {"numero": 21, "texto": "Y Ruth Moabita dijo: A más de esto me ha dicho: Júntate con mis criados, hasta que hayan acabado toda mi siega."}, {"numero": 22, "texto": "Y Noemi respondió á Ruth su nuera: Mejor es, hija mía, que salgas con sus criadas, que no que te encuentren en otro campo."}, {"numero": 23, "texto": "Estuvo pues junta con las mozas de Booz espigando, hasta que la siega de las cebadas y la de los trigos fué acabada; mas con su suegra habitó."}]'::jsonb, 'Reina-Valera 1909')
